/* TỰ SINH bởi tools/build-zh-game.mjs từ data/curriculum (giáo trình HSK của app ATLAS), đừng sửa tay. */
var G = window.G || (window.G = {});
G.ROOMS = G.ROOMS || {};
G.ROOMS["zh-l098"] = {"id":"zh-l098","lang":"zh","level":4,"no":98,"teacher":"wang","title":"HSK4 · Bài 98 · 人的性格 Tính cách con người","intro":["你觉得他的性格怎么样？","Bài 98: Mở đầu HSK 4 bằng bộ từ tả tính người — năm trên mười từ trùng khít tiếng Việt. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ juéde tā de xìnggé zěnmeyàng?","gram":{"t":"Chào mừng tới HSK 4 — từ trừu tượng bắt đầu chiếm ưu thế","b":"性格 · 活泼 · 诚实 · 骄傲 · 勇敢","d":"Từ HSK 4 trở đi, phần lớn từ mới là từ HAI ÂM TIẾT trừu tượng — và đó chính là kho từ Hán Việt của tiếng Việt. Chiến thuật học hiệu quả nhất: gặp từ hai chữ, đọc âm Hán Việt lên trước, rất nhiều lần bạn sẽ tự đoán ra nghĩa mà không cần tra.","ex":[["性格 · 活泼 · 诚实","tính cách · hoạt bát · thành thực","xìnggé · huópō · chéngshí"],["骄傲 · 勇敢","kiêu ngạo · dũng cảm","jiāo'ào · yǒnggǎn"]]},"grams":[{"t":"Chào mừng tới HSK 4 — từ trừu tượng bắt đầu chiếm ưu thế","b":"性格 · 活泼 · 诚实 · 骄傲 · 勇敢","d":"Từ HSK 4 trở đi, phần lớn từ mới là từ HAI ÂM TIẾT trừu tượng — và đó chính là kho từ Hán Việt của tiếng Việt. Chiến thuật học hiệu quả nhất: gặp từ hai chữ, đọc âm Hán Việt lên trước, rất nhiều lần bạn sẽ tự đoán ra nghĩa mà không cần tra.","ex":[["性格 · 活泼 · 诚实","tính cách · hoạt bát · thành thực","xìnggé · huópō · chéngshí"],["骄傲 · 勇敢","kiêu ngạo · dũng cảm","jiāo'ào · yǒnggǎn"]]},{"t":"骄傲 — một từ hai sắc thái trái ngược","b":"对…骄傲 (tự hào) · 太骄傲了 (kiêu ngạo)","d":"Khác tiếng Việt chỉ hiểu \"kiêu ngạo\" theo nghĩa xấu, tiếng Trung dùng 骄傲 cho cả niềm TỰ HÀO chính đáng. Nhìn ngữ cảnh mà đoán: có 为/对 đi kèm thì thường là nghĩa tốt.","ex":[["父母为孩子的成绩骄傲。","Cha mẹ tự hào về thành tích của con.","Fùmǔ wèi háizi de chéngjì jiāo'ào."],["他有点儿骄傲，不太听别人的话。","Cậu ấy hơi kiêu, không mấy khi nghe người khác.","Tā yǒudiǎnr jiāo'ào, bú tài tīng biéren de huà."]]},{"t":"Khen người: dùng từ nào cho ai","b":"帅 (nam) · 漂亮 / 美丽 (nữ) · 可爱 (trẻ con) · 活泼 (trẻ, người trẻ)","d":"Tiếng Trung phân biệt khá rạch ròi. Khen một người đàn ông là 漂亮 nghe rất lạ tai. Người Việt cũng phân biệt \"đẹp trai\" với \"xinh\" nên nắm rất nhanh.","ex":[["你儿子真帅！","Con trai bạn đẹp trai thật!","Nǐ érzi zhēn shuài!"],["你女儿又漂亮又活泼。","Con gái bạn vừa xinh vừa lanh lợi.","Nǐ nǚ'ér yòu piàoliang yòu huópō."]]}],"items":[{"zh":"性格","py":"xìnggé","vi":"tính cách","hv":"tính cách","note":"Chính là \"tính cách\" tiếng Việt: 性 (tính, có bộ 忄) + 格 (cách). Không sai một ly.","ex":"你觉得他的性格怎么样？","exPy":"Nǐ juéde tā de xìnggé zěnmeyàng?","exVi":"Bạn thấy tính cách anh ấy thế nào?","w":"你 觉得 他 的 性格 怎么样？"},{"zh":"活泼","py":"huópō","vi":"hoạt bát, lanh lợi","hv":"hoạt bát","note":"Chính là \"hoạt bát\" tiếng Việt: 活 (sống động) + 泼 (bộ 氵). Thường khen trẻ con và người trẻ.","ex":"她性格活泼，朋友很多。","exPy":"Tā xìnggé huópō, péngyou hěn duō.","exVi":"Cô ấy tính hoạt bát nên nhiều bạn.","w":"她 性格 活泼， 朋友 很 多。"},{"zh":"幽默","py":"yōumò","vi":"hài hước","hv":"u mặc","note":"Thú vị: đây là từ MƯỢN ÂM tiếng Anh \"humour\", người Trung Quốc chọn hai chữ 幽默 cho gần âm. Tiếng Việt mượn thẳng \"hài hước\" từ gốc khác.","ex":"他说话很幽默，大家都爱听。","exPy":"Tā shuōhuà hěn yōumò, dàjiā dōu ài tīng.","exVi":"Anh ấy nói chuyện hài hước, ai cũng thích nghe.","w":"他 说话 很 幽默， 大家 都 爱 听。"},{"zh":"诚实","py":"chéngshí","vi":"thành thật, trung thực","hv":"thành thực","note":"Chính là \"thành thực\" tiếng Việt: 诚 (thành, có bộ 讠) + 实 (thực).","ex":"诚实比聪明更重要。","exPy":"Chéngshí bǐ cōngming gèng zhòngyào.","exVi":"Thành thật quan trọng hơn thông minh.","w":"诚实 比 聪明 更 重要。"},{"zh":"骄傲","py":"jiāo'ào","vi":"kiêu ngạo; tự hào","hv":"kiêu ngạo","note":"Chính là \"kiêu ngạo\" tiếng Việt, nhưng tiếng Trung có CẢ NGHĨA TỐT: 为你骄傲 = tự hào về bạn.","ex":"爸爸妈妈都为你骄傲。","exPy":"Bàba māma dōu wèi nǐ jiāo'ào.","exVi":"Bố mẹ đều tự hào về con.","w":"爸爸 妈妈 都 为 你 骄傲。"},{"zh":"懒","py":"lǎn","vi":"lười","hv":"lãn","note":"Bộ 忄 (tim) — lười là chuyện của lòng dạ. Tiếng Việt: \"lãn công\" (đình công kiểu lười làm).","ex":"他这个人有点儿懒。","exPy":"Tā zhège rén yǒudiǎnr lǎn.","exVi":"Người này hơi lười.","w":"他 这个 人 有点儿 懒。"},{"zh":"笨","py":"bèn","vi":"ngốc, vụng","hv":"bổn","note":"Bộ 竹 (tre) trên 本 (gốc) — như khúc tre thô chưa gọt. Trái nghĩa với 聪明 (bài 52). Lời chê nặng, dùng cẩn thận.","ex":"我又做错了，真笨。","exPy":"Wǒ yòu zuò cuò le, zhēn bèn.","exVi":"Tôi lại làm sai rồi, ngốc thật.","w":"我 又 做 错 了， 真 笨。"},{"zh":"帅","py":"shuài","vi":"đẹp trai","hv":"soái","note":"Tiếng Việt: \"nguyên soái\", \"thống soái\" — nghĩa gốc là vị tướng oai phong. Khen nam giới; khen nữ thì dùng 漂亮 hoặc 美丽.","ex":"你今天穿得真帅！","exPy":"Nǐ jīntiān chuān de zhēn shuài!","exVi":"Hôm nay bạn mặc đẹp trai thật!","w":"你 今天 穿 得 真 帅！"},{"zh":"冷静","py":"lěngjìng","vi":"bình tĩnh","hv":"lãnh tĩnh","note":"冷 (lạnh, bài 15) + 静 (tĩnh, bài 60 trong 安静) — đầu lạnh mà lòng yên. Lời khuyên hay dùng: 冷静一点儿！","ex":"遇到问题要冷静。","exPy":"Yù dào wèntí yào lěngjìng.","exVi":"Gặp vấn đề phải bình tĩnh.","w":"遇到 问题 要 冷静。"},{"zh":"勇敢","py":"yǒnggǎn","vi":"dũng cảm","hv":"dũng cảm","note":"Chính là \"dũng cảm\" tiếng Việt: 勇 (dũng) + 敢 (dám).","ex":"他很勇敢，一个人去了那么远的地方。","exPy":"Tā hěn yǒnggǎn, yí ge rén qù le nàme yuǎn de dìfang.","exVi":"Anh ấy rất dũng cảm, một mình đi tới nơi xa như thế.","w":"他 很 勇敢， 一 个人 去 了 那么 远 的 地方。"}],"newChars":["格","泼","幽","默","诚","骄","傲","懒","笨","帅","勇","敢"],"outro":"很好！Xong bài 98."};
G.ROOMS["zh-l099"] = {"id":"zh-l099","lang":"zh","level":4,"no":99,"teacher":"wang","title":"HSK4 · Bài 99 · 高兴的心情 Niềm vui","intro":["听到这个好消息，我特别激动。","Bài 99: Diễn tả các sắc thái vui khác nhau — bảy trên mười từ là từ Hán Việt bạn đã dùng. Bấm 1 · Học để bắt đầu."],"introPy":"Tīng dào zhège hǎo xiāoxi, wǒ tèbié jīdòng.","gram":{"t":"Thang niềm vui — chọn từ đúng sắc thái","b":"开心 (thân mật) < 高兴 (chung) < 愉快 (trang trọng) < 幸福 (lâu dài)","d":"开心 dùng với bạn bè. 高兴 dùng được mọi lúc. 愉快 dùng trong lời chúc và văn viết. 幸福 chỉ dùng cho hạnh phúc cuộc đời, không nói 今天很幸福 khi vừa ăn xong bữa ngon.","ex":[["今天真开心！","Hôm nay vui thật!","Jīntiān zhēn kāixīn!"],["祝你生日愉快！","Chúc bạn sinh nhật vui vẻ!","Zhù nǐ shēngrì yúkuài!"],["有家人在身边就是幸福。","Có người thân bên cạnh chính là hạnh phúc.","Yǒu jiārén zài shēnbiān jiù shì xìngfú."]]},"grams":[{"t":"Thang niềm vui — chọn từ đúng sắc thái","b":"开心 (thân mật) < 高兴 (chung) < 愉快 (trang trọng) < 幸福 (lâu dài)","d":"开心 dùng với bạn bè. 高兴 dùng được mọi lúc. 愉快 dùng trong lời chúc và văn viết. 幸福 chỉ dùng cho hạnh phúc cuộc đời, không nói 今天很幸福 khi vừa ăn xong bữa ngon.","ex":[["今天真开心！","Hôm nay vui thật!","Jīntiān zhēn kāixīn!"],["祝你生日愉快！","Chúc bạn sinh nhật vui vẻ!","Zhù nǐ shēngrì yúkuài!"],["有家人在身边就是幸福。","Có người thân bên cạnh chính là hạnh phúc.","Yǒu jiārén zài shēnbiān jiù shì xìngfú."]]},{"t":"让 + người + cảm xúc","b":"A + 让 + người + tính từ cảm xúc","d":"Nhắc lại 让 ở bài 20, nay dùng với cảm xúc: 这件事让我很感动 (việc này khiến tôi rất cảm động). Cấu trúc cực kỳ thông dụng để nói nguyên nhân của cảm xúc.","ex":[["这个消息让大家很兴奋。","Tin này làm mọi người rất háo hức.","Zhège xiāoxi ràng dàjiā hěn xīngfèn."],["他的话让我很感动。","Lời anh ấy khiến tôi cảm động.","Tā de huà ràng wǒ hěn gǎndòng."]]},{"t":"祝 — mở đầu mọi lời chúc","b":"祝 + người + điều chúc","d":"祝你生日快乐, 祝你旅途愉快, 祝你身体健康, 祝你工作顺利. Đây là mẫu câu bạn sẽ dùng suốt đời khi nhắn tin cho bạn bè Trung Quốc.","ex":[["祝你一切顺利！","Chúc bạn mọi sự thuận lợi!","Zhù nǐ yíqiè shùnlì!"],["祝你们幸福！","Chúc hai bạn hạnh phúc!","Zhù nǐmen xìngfú!"]]}],"items":[{"zh":"激动","py":"jīdòng","vi":"xúc động, phấn khích","hv":"kích động","note":"Chính là \"kích động\" tiếng Việt, nhưng tiếng Trung thiên về nghĩa TỐT: xúc động vì vui, vì cảm kích.","ex":"听到这个好消息，我特别激动。","exPy":"Tīng dào zhège hǎo xiāoxi, wǒ tèbié jīdòng.","exVi":"Nghe tin vui này tôi đặc biệt xúc động.","w":"听 到 这个 好 消息， 我 特别 激动。"},{"zh":"兴奋","py":"xīngfèn","vi":"hưng phấn, háo hức","hv":"hưng phấn","note":"Chính là \"hưng phấn\" tiếng Việt. Chú ý 兴 ở đây đọc xīng, khác 高兴 gāoxìng (thanh 4).","ex":"明天要去旅游，孩子们很兴奋。","exPy":"Míngtiān yào qù lǚyóu, háizimen hěn xīngfèn.","exVi":"Mai đi du lịch nên bọn trẻ rất háo hức.","w":"明天 要 去 旅游， 孩子 们 很 兴奋。"},{"zh":"感动","py":"gǎndòng","vi":"cảm động","hv":"cảm động","note":"Chính là \"cảm động\" tiếng Việt: 感 (cảm) + 动 (động).","ex":"这部电影让我很感动。","exPy":"Zhè bù diànyǐng ràng wǒ hěn gǎndòng.","exVi":"Bộ phim này làm tôi rất cảm động.","w":"这 部 电影 让 我 很 感动。"},{"zh":"开心","py":"kāixīn","vi":"vui, vui vẻ","hv":"khai tâm","note":"开 (mở) + 心 (lòng) — mở lòng ra thì vui. Thân mật hơn 高兴, hay dùng trong khẩu ngữ.","ex":"跟朋友在一起总是很开心。","exPy":"Gēn péngyou zài yìqǐ zǒngshì hěn kāixīn.","exVi":"Ở cùng bạn bè lúc nào cũng vui.","w":"跟 朋友 在 一起 总是 很 开心。"},{"zh":"愉快","py":"yúkuài","vi":"vui vẻ, dễ chịu","hv":"du khoái","note":"Trang trọng hơn 开心. Hay dùng trong lời chúc: 祝你旅途愉快 (chúc chuyến đi vui vẻ).","ex":"祝你旅途愉快！","exPy":"Zhù nǐ lǚtú yúkuài!","exVi":"Chúc bạn chuyến đi vui vẻ!","w":"祝 你 旅途 愉快！"},{"zh":"幸福","py":"xìngfú","vi":"hạnh phúc","hv":"hạnh phúc","note":"Chính là \"hạnh phúc\" tiếng Việt. Nói về trạng thái sống lâu dài, không dùng cho niềm vui nhất thời.","ex":"有健康的身体才有幸福的生活。","exPy":"Yǒu jiànkāng de shēntǐ cái yǒu xìngfú de shēnghuó.","exVi":"Có sức khoẻ mới có cuộc sống hạnh phúc.","w":"有 健康 的 身体 才 有幸 福 的 生活。"},{"zh":"得意","py":"déyì","vi":"đắc ý, hài lòng về mình","hv":"đắc ý","note":"Chính là \"đắc ý\" tiếng Việt: 得 (được) + 意 (ý) — được như ý. Hơi mang sắc thái vênh váo.","ex":"别太得意，还有很多要学的。","exPy":"Bié tài déyì, hái yǒu hěn duō yào xué de.","exVi":"Đừng đắc ý quá, còn nhiều thứ phải học.","w":"别 太 得意， 还 有 很 多 要 学 的。"},{"zh":"惊喜","py":"jīngxǐ","vi":"bất ngờ vui, món quà bất ngờ","hv":"kinh hỉ","note":"惊 (kinh ngạc) + 喜 (mừng) — vừa bất ngờ vừa mừng. Đúng nghĩa \"surprise\" trong tiếng Anh.","ex":"他给了我一个大惊喜。","exPy":"Tā gěi le wǒ yí ge dà jīngxǐ.","exVi":"Anh ấy dành cho tôi một bất ngờ lớn.","w":"他 给 了 我 一 个 大 惊喜。"},{"zh":"精神","py":"jīngshen","vi":"tinh thần; tươi tắn","hv":"tinh thần","note":"Chính là \"tinh thần\" tiếng Việt. Đọc jīngshén (đủ thanh) là danh từ; đọc jīngshen (nhẹ) là tính từ nghĩa \"trông tươi tỉnh\".","ex":"睡好了人就有精神。","exPy":"Shuì hǎo le rén jiù yǒu jīngshen.","exVi":"Ngủ đủ thì người mới tỉnh táo.","w":"睡 好 了 人 就 有 精神。"},{"zh":"轻松","py":"qīngsōng","vi":"nhẹ nhõm, thoải mái","hv":"khinh tùng","note":"轻 (nhẹ, bài 97) + 松 (lỏng, bộ 木). Nghĩa đen: nhẹ và lỏng — không căng thẳng.","ex":"考完试，心情轻松多了。","exPy":"Kǎo wán shì, xīnqíng qīngsōng duō le.","exVi":"Thi xong rồi, tâm trạng nhẹ hẳn.","w":"考 完 试， 心情 轻松 多 了。"}],"newChars":["激","奋","愉","幸","福","惊","神"],"outro":"很好！Xong bài 99."};
G.ROOMS["zh-l100"] = {"id":"zh-l100","lang":"zh","level":4,"no":100,"teacher":"wang","title":"HSK4 · Bài 100 · 不好的心情 Nỗi buồn và lo lắng","intro":["我很后悔没有早点儿开始学汉语。","Bài 100: Nói về cảm xúc tiêu cực — kèm một bẫy Hán Việt rất dễ hiểu ngược. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ hěn hòuhuǐ méiyǒu zǎo diǎnr kāishǐ xué Hànyǔ.","gram":{"t":"Bẫy Hán Việt: 紧张 KHÔNG phải \"khẩn trương\"","b":"紧张 = hồi hộp, căng thẳng","d":"Tiếng Việt hiện đại dùng \"khẩn trương\" với nghĩa \"nhanh lên\", nhưng nghĩa gốc Hán là CĂNG. Trong tiếng Trung 紧张 luôn là hồi hộp, lo lắng, hoặc tình hình căng thẳng. Muốn nói \"nhanh lên\" phải dùng 快点儿.","ex":[["第一次上台，我很紧张。","Lần đầu lên sân khấu, tôi rất hồi hộp.","Dì-yī cì shàngtái, wǒ hěn jǐnzhāng."],["快点儿，来不及了！","Nhanh lên, không kịp mất!","Kuài diǎnr, láibují le!"]]},"grams":[{"t":"Bẫy Hán Việt: 紧张 KHÔNG phải \"khẩn trương\"","b":"紧张 = hồi hộp, căng thẳng","d":"Tiếng Việt hiện đại dùng \"khẩn trương\" với nghĩa \"nhanh lên\", nhưng nghĩa gốc Hán là CĂNG. Trong tiếng Trung 紧张 luôn là hồi hộp, lo lắng, hoặc tình hình căng thẳng. Muốn nói \"nhanh lên\" phải dùng 快点儿.","ex":[["第一次上台，我很紧张。","Lần đầu lên sân khấu, tôi rất hồi hộp.","Dì-yī cì shàngtái, wǒ hěn jǐnzhāng."],["快点儿，来不及了！","Nhanh lên, không kịp mất!","Kuài diǎnr, láibují le!"]]},{"t":"后悔 + việc đã làm hoặc chưa làm","b":"后悔 + (没) + động từ","d":"后悔来了 (hối vì đã đến) và 后悔没来 (hối vì đã không đến). Chỉ khác một chữ 没 mà nghĩa ngược hẳn — chú ý khi nghe.","ex":[["我后悔买了这个。","Tôi hối vì đã mua cái này.","Wǒ hòuhuǐ mǎi le zhège."],["我后悔没听你的话。","Tôi hối vì đã không nghe lời bạn.","Wǒ hòuhuǐ méi tīng nǐ de huà."]]},{"t":"Ba mức buồn: 难过 < 伤心 < 痛苦","b":"难过 (buồn) · 伤心 (đau lòng) · 痛苦 (đau khổ)","d":"难过 (bài 34) là buồn thường ngày. 伤心 nặng hơn, thường kèm nước mắt. Chọn đúng mức để lời nói không quá nhẹ hay quá nặng.","ex":[["考得不好，我有点儿难过。","Thi không tốt, tôi hơi buồn.","Kǎo de bù hǎo, wǒ yǒudiǎnr nánguò."],["听到那个消息，她非常伤心。","Nghe tin đó, cô ấy vô cùng đau lòng.","Tīng dào nàge xiāoxi, tā fēicháng shāngxīn."]]}],"items":[{"zh":"后悔","py":"hòuhuǐ","vi":"hối hận","hv":"hậu hối","note":"后 (sau) + 悔 (hối, có bộ 忄). Tiếng Việt nói \"hối hận\", cùng chữ 悔.","ex":"我很后悔没有早点儿开始学汉语。","exPy":"Wǒ hěn hòuhuǐ méiyǒu zǎo diǎnr kāishǐ xué Hànyǔ.","exVi":"Tôi rất tiếc vì đã không học tiếng Trung sớm hơn.","w":"我 很 后悔 没有 早 点 儿 开始 学 汉语。"},{"zh":"失望","py":"shīwàng","vi":"thất vọng","hv":"thất vọng","note":"Chính là \"thất vọng\" tiếng Việt: 失 (mất) + 望 (hy vọng).","ex":"这次的结果让大家都很失望。","exPy":"Zhè cì de jiéguǒ ràng dàjiā dōu hěn shīwàng.","exVi":"Kết quả lần này khiến ai cũng thất vọng.","w":"这 次 的 结果 让 大家 都 很 失望。"},{"zh":"伤心","py":"shāngxīn","vi":"đau lòng, buồn","hv":"thương tâm","note":"Chính là \"thương tâm\" tiếng Việt: 伤 (thương tổn) + 心 (tim). Nặng hơn 难过 (bài 34).","ex":"她因为这件事伤心了很久。","exPy":"Tā yīnwèi zhè jiàn shì shāngxīn le hěn jiǔ.","exVi":"Cô ấy buồn vì chuyện này rất lâu.","w":"她 因为 这 件 事 伤心 了 很 久。"},{"zh":"讨厌","py":"tǎoyàn","vi":"ghét; đáng ghét","hv":"thảo yếm","note":"Vừa là động từ (ghét ai) vừa là tính từ (đáng ghét). Mạnh hơn 不喜欢 nhiều.","ex":"我讨厌下雨天出门。","exPy":"Wǒ tǎoyàn xiàyǔ tiān chūmén.","exVi":"Tôi ghét ra ngoài vào ngày mưa.","w":"我 讨厌 下雨 天 出门。"},{"zh":"烦恼","py":"fánnǎo","vi":"phiền muộn, buồn phiền","hv":"phiền não","note":"Chính là \"phiền não\" tiếng Việt — từ nhà Phật, cả hai ngôn ngữ đều mượn.","ex":"工作上的烦恼别带回家。","exPy":"Gōngzuò shàng de fánnǎo bié dài huí jiā.","exVi":"Phiền muộn công việc đừng mang về nhà.","w":"工作 上 的 烦恼 别 带 回 家。"},{"zh":"紧张","py":"jǐnzhāng","vi":"hồi hộp, căng thẳng","hv":"khẩn trương","note":"BẪY HÁN VIỆT: âm là \"khẩn trương\" nhưng nghĩa tiếng Trung là HỒI HỘP, CĂNG THẲNG — không phải \"nhanh lên\" như tiếng Việt hiện đại.","ex":"面试的时候不要太紧张。","exPy":"Miànshì de shíhou búyào tài jǐnzhāng.","exVi":"Lúc phỏng vấn đừng quá hồi hộp.","w":"面试 的 时候 不要 太 紧张。"},{"zh":"难受","py":"nánshòu","vi":"khó chịu (trong người hoặc trong lòng)","hv":"nan thụ","note":"难 (khó) + 受 (chịu). Dùng cho cả khó chịu về thân thể lẫn về tinh thần.","ex":"吃得太多，肚子很难受。","exPy":"Chī de tài duō, dùzi hěn nánshòu.","exVi":"Ăn nhiều quá, bụng khó chịu.","w":"吃 得 太 多， 肚子 很 难受。"},{"zh":"无聊","py":"wúliáo","vi":"buồn chán, vô vị","hv":"vô liêu","note":"无 (không) + 聊 (trò chuyện, bài 49) — không có gì để nói. Tả cả người lẫn việc.","ex":"一个人在家很无聊。","exPy":"Yí ge rén zài jiā hěn wúliáo.","exVi":"Ở nhà một mình chán lắm.","w":"一 个人 在 家 很 无聊。"},{"zh":"可怜","py":"kělián","vi":"đáng thương, tội nghiệp","hv":"khả liên","note":"可 (đáng) + 怜 (thương, có bộ 忄). Cùng lối ghép với 可爱, 可怕 ở bài 52.","ex":"他一个人生活，真可怜。","exPy":"Tā yí ge rén shēnghuó, zhēn kělián.","exVi":"Anh ấy sống một mình, thật tội.","w":"他 一 个人 生活， 真 可怜。"},{"zh":"害羞","py":"hàixiū","vi":"ngại ngùng, mắc cỡ","hv":"hại tu","note":"羞 = \"tu\" trong \"tu sỉ\" (xấu hổ). Cùng chữ 害 với 害怕 (bài 34).","ex":"小朋友第一次见老师会害羞。","exPy":"Xiǎopéngyǒu dì-yī cì jiàn lǎoshī huì hàixiū.","exVi":"Trẻ con lần đầu gặp cô giáo hay ngại.","w":"小朋友 第一 次 见 老师 会 害羞。"}],"newChars":["悔","失","伤","讨","厌","恼","紧","受","怜","羞"],"outro":"很好！Xong bài 100."};
G.ROOMS["zh-l101"] = {"id":"zh-l101","lang":"zh","level":4,"no":101,"teacher":"wang","title":"HSK4 · Bài 101 · 对别人的态度 Thái độ với người khác","intro":["我很羡慕你能去中国留学。","Bài 101: Đồng ý, phản đối, xin lỗi và cảm ơn ở mức trang trọng hơn HSK 1. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ hěn xiànmù nǐ néng qù Zhōngguó liúxué.","gram":{"t":"Hai bẫy Hán Việt trong một bài","b":"同情 = thông cảm (không phải \"đồng tình\") · 紧张 = hồi hộp (bài 63)","d":"Âm Hán Việt là người bạn tốt nhưng đôi khi đánh lừa, vì tiếng Việt đã dịch chuyển nghĩa qua nhiều thế kỷ. Gặp từ nào nghĩa nghe \"hơi lệch\", hãy tra lại thay vì đoán bừa.","ex":[["我同情他，但是不同意他的做法。","Tôi thương anh ấy, nhưng không tán thành cách anh ấy làm.","Wǒ tóngqíng tā, dànshì bù tóngyì tā de zuòfǎ."]]},"grams":[{"t":"Hai bẫy Hán Việt trong một bài","b":"同情 = thông cảm (không phải \"đồng tình\") · 紧张 = hồi hộp (bài 63)","d":"Âm Hán Việt là người bạn tốt nhưng đôi khi đánh lừa, vì tiếng Việt đã dịch chuyển nghĩa qua nhiều thế kỷ. Gặp từ nào nghĩa nghe \"hơi lệch\", hãy tra lại thay vì đoán bừa.","ex":[["我同情他，但是不同意他的做法。","Tôi thương anh ấy, nhưng không tán thành cách anh ấy làm.","Wǒ tóngqíng tā, dànshì bù tóngyì tā de zuòfǎ."]]},{"t":"向 + người + động từ nói năng","b":"向 + người + 道歉 / 学习 / 借","d":"向 xiàng (bài 53) nêu ĐỐI TƯỢNG hướng tới. Các động từ ly hợp như 道歉 bắt buộc dùng cấu trúc này: 向他道歉, không nói 道歉他.","ex":[["我向老师道歉了。","Tôi đã xin lỗi thầy.","Wǒ xiàng lǎoshī dàoqiàn le."],["我们要向他学习。","Chúng ta phải học tập anh ấy.","Wǒmen yào xiàng tā xuéxí."]]},{"t":"Thang xin lỗi và cảm ơn theo mức trang trọng","b":"对不起 < 抱歉 < 道歉 · 谢谢 < 感谢","d":"对不起 dùng hằng ngày. 抱歉 lịch sự, hay dùng trong email và công việc. 道歉 là hành động xin lỗi chính thức. Tương tự 谢谢 thường ngày, 感谢 trang trọng.","ex":[["很抱歉，给您添麻烦了。","Rất xin lỗi đã làm phiền ngài.","Hěn bàoqiàn, gěi nín tiān máfan le."],["衷心感谢大家的支持。","Chân thành cảm ơn sự ủng hộ của mọi người.","Zhōngxīn gǎnxiè dàjiā de zhīchí."]]}],"items":[{"zh":"羡慕","py":"xiànmù","vi":"ngưỡng mộ, thèm được như","hv":"tiện mộ","note":"慕 = \"mộ\" trong \"ái mộ\", \"ngưỡng mộ\". Mang sắc thái tích cực, khác với ghen tị.","ex":"我很羡慕你能去中国留学。","exPy":"Wǒ hěn xiànmù nǐ néng qù Zhōngguó liúxué.","exVi":"Tôi ngưỡng mộ bạn được đi du học Trung Quốc.","w":"我 很 羡慕 你 能 去 中国 留学。"},{"zh":"怀疑","py":"huáiyí","vi":"nghi ngờ","hv":"hoài nghi","note":"Chính là \"hoài nghi\" tiếng Việt: 怀 (ôm trong lòng) + 疑 (nghi).","ex":"我怀疑这个消息是假的。","exPy":"Wǒ huáiyí zhège xiāoxi shì jiǎ de.","exVi":"Tôi nghi tin này là giả.","w":"我 怀疑 这个 消息 是 假 的。"},{"zh":"同情","py":"tóngqíng","vi":"thông cảm, thương cảm","hv":"đồng tình","note":"BẪY HÁN VIỆT: âm là \"đồng tình\" nhưng nghĩa tiếng Trung là THÔNG CẢM, THƯƠNG XÓT — không phải \"tán thành\". Tán thành là 同意 (bài 34).","ex":"听了她的故事，大家都很同情。","exPy":"Tīng le tā de gùshi, dàjiā dōu hěn tóngqíng.","exVi":"Nghe chuyện của cô ấy, ai cũng thương cảm.","w":"听 了 她 的 故事， 大家 都 很 同情。"},{"zh":"吃惊","py":"chījīng","vi":"kinh ngạc, giật mình","hv":"cật kinh","note":"吃 (ăn) + 惊 (kinh sợ) — nghĩa đen \"nuốt phải cú giật mình\". Là động từ ly hợp: 吃了一惊.","ex":"他的话让我很吃惊。","exPy":"Tā de huà ràng wǒ hěn chījīng.","exVi":"Lời anh ấy làm tôi kinh ngạc.","w":"他 的话 让 我 很 吃惊。"},{"zh":"反对","py":"fǎnduì","vi":"phản đối","hv":"phản đối","note":"Chính là \"phản đối\" tiếng Việt: 反 (ngược) + 对 (đối). Trái nghĩa với 同意.","ex":"父母反对他一个人去那么远。","exPy":"Fùmǔ fǎnduì tā yí ge rén qù nàme yuǎn.","exVi":"Bố mẹ phản đối việc cậu ấy đi xa một mình.","w":"父母 反对 他 一 个人 去 那么 远。"},{"zh":"拒绝","py":"jùjué","vi":"từ chối","hv":"cự tuyệt","note":"Chính là \"cự tuyệt\" tiếng Việt: 拒 (chống lại, bộ 扌) + 绝 (dứt).","ex":"他很客气地拒绝了。","exPy":"Tā hěn kèqi de jùjué le.","exVi":"Anh ấy từ chối rất lịch sự.","w":"他 很 客气 地 拒绝 了。"},{"zh":"原谅","py":"yuánliàng","vi":"tha thứ, lượng thứ","hv":"nguyên lượng","note":"Tiếng Việt có \"lượng thứ\", \"khoan dung\". 谅 có bộ 讠 (lời nói) — tha thứ bằng lời.","ex":"希望你能原谅我这一次。","exPy":"Xīwàng nǐ néng yuánliàng wǒ zhè yí cì.","exVi":"Mong bạn tha thứ cho tôi lần này.","w":"希望 你 能 原谅 我 这 一 次。"},{"zh":"道歉","py":"dàoqiàn","vi":"xin lỗi (chính thức)","hv":"đạo khiểm","note":"道 (nói) + 歉 (áy náy). Là động từ ly hợp: 向他道歉 (xin lỗi anh ấy), KHÔNG nói 道歉他.","ex":"做错了就应该道歉。","exPy":"Zuò cuò le jiù yīnggāi dàoqiàn.","exVi":"Làm sai thì nên xin lỗi.","w":"做 错 了 就 应该 道歉。"},{"zh":"抱歉","py":"bàoqiàn","vi":"áy náy, rất tiếc","hv":"bão khiểm","note":"Nhẹ và lịch sự hơn 对不起, hay dùng trong công việc và văn viết: 很抱歉，我不能参加.","ex":"很抱歉，明天的会议我不能参加。","exPy":"Hěn bàoqiàn, míngtiān de huìyì wǒ bù néng cānjiā.","exVi":"Rất tiếc, cuộc họp mai tôi không dự được.","w":"很 抱歉， 明天 的 会议 我 不 能 参加。"},{"zh":"感谢","py":"gǎnxiè","vi":"cảm tạ, cảm ơn","hv":"cảm tạ","note":"Chính là \"cảm tạ\" tiếng Việt. Trang trọng hơn 谢谢 (bài 1) — dùng khi biết ơn thật sự.","ex":"感谢你这段时间的照顾。","exPy":"Gǎnxiè nǐ zhè duàn shíjiān de zhàogù.","exVi":"Cảm ơn bạn đã chăm sóc thời gian qua.","w":"感谢 你 这 段 时间 的 照顾。"}],"newChars":["羡","慕","怀","疑","拒","绝","谅","歉","抱"],"outro":"很好！Xong bài 101."};
G.ROOMS["zh-l102"] = {"id":"zh-l102","lang":"zh","level":4,"no":102,"teacher":"wang","title":"HSK4 · Bài 102 · 优点和缺点 Ưu điểm và khuyết điểm","intro":["说说你自己的优点和缺点。","Bài 102: Nhận xét con người và cách làm việc — bài đầy từ Hán Việt, kèm một bẫy nữa. Bấm 1 · Học để bắt đầu."],"introPy":"Shuōshuo nǐ zìjǐ de yōudiǎn hé quēdiǎn.","gram":{"t":"Bẫy Hán Việt: 仔细 là KỸ LƯỠNG","b":"仔细 = tỉ mỉ, cẩn thận · 善良 = tử tế, tốt bụng","d":"Người Việt gặp 仔细 rất dễ hiểu thành \"tử tế, tốt bụng\". Thực ra nó nói về cách LÀM VIỆC, không phải về lòng dạ. Nhớ cặp trái nghĩa: 仔细 ↔ 马虎.","ex":[["他工作很仔细。","Anh ấy làm việc rất tỉ mỉ.","Tā gōngzuò hěn zǐxì."],["他是个善良的人。","Anh ấy là người tốt bụng.","Tā shì ge shànliáng de rén."]]},"grams":[{"t":"Bẫy Hán Việt: 仔细 là KỸ LƯỠNG","b":"仔细 = tỉ mỉ, cẩn thận · 善良 = tử tế, tốt bụng","d":"Người Việt gặp 仔细 rất dễ hiểu thành \"tử tế, tốt bụng\". Thực ra nó nói về cách LÀM VIỆC, không phải về lòng dạ. Nhớ cặp trái nghĩa: 仔细 ↔ 马虎.","ex":[["他工作很仔细。","Anh ấy làm việc rất tỉ mỉ.","Tā gōngzuò hěn zǐxì."],["他是个善良的人。","Anh ấy là người tốt bụng.","Tā shì ge shànliáng de rén."]]},{"t":"对 … 严格 / 有耐心 — thái độ hướng tới ai","b":"对 + đối tượng + tính từ / 有 + danh từ","d":"Nhắc lại mẫu 对 từ bài 34 và 39. Rất nhiều từ trong bài này đi với 对: 对学生严格, 对孩子有耐心, 对工作认真.","ex":[["老师对我们很严格。","Thầy rất nghiêm khắc với chúng tôi.","Lǎoshī duì wǒmen hěn yángé."],["他对客人的态度很好。","Thái độ của anh ấy với khách rất tốt.","Tā duì kèrén de tàidu hěn hǎo."]]},{"t":"Cặp trái nghĩa cần thuộc theo cặp","b":"优点 ↔ 缺点 · 仔细 ↔ 马虎 · 优秀 ↔ 一般","d":"Học từ theo CẶP TRÁI NGHĨA hiệu quả gấp đôi học từng từ một, vì não ghi nhớ bằng đối chiếu. Từ HSK 4 trở đi, hãy tự lập bảng cặp trái nghĩa cho mỗi bài.","ex":[["他的优点是认真，缺点是太慢。","Ưu điểm của anh ấy là nghiêm túc, khuyết điểm là quá chậm.","Tā de yōudiǎn shì rènzhēn, quēdiǎn shì tài màn."]]}],"items":[{"zh":"优点","py":"yōudiǎn","vi":"ưu điểm","hv":"ưu điểm","note":"Chính là \"ưu điểm\" tiếng Việt: 优 (ưu) + 点 (điểm).","ex":"说说你自己的优点和缺点。","exPy":"Shuōshuo nǐ zìjǐ de yōudiǎn hé quēdiǎn.","exVi":"Hãy nói về ưu điểm và khuyết điểm của bạn.","w":"说 说 你 自己 的 优点 和 缺点。"},{"zh":"缺点","py":"quēdiǎn","vi":"khuyết điểm, nhược điểm","hv":"khuyết điểm","note":"Chính là \"khuyết điểm\" tiếng Việt: 缺 (thiếu) + 点 (điểm). Cặp đối với 优点.","ex":"他最大的缺点是太懒。","exPy":"Tā zuì dà de quēdiǎn shì tài lǎn.","exVi":"Khuyết điểm lớn nhất của cậu ấy là quá lười.","w":"他 最 大 的 缺点 是 太 懒。"},{"zh":"优秀","py":"yōuxiù","vi":"ưu tú, xuất sắc","hv":"ưu tú","note":"Chính là \"ưu tú\" tiếng Việt. Lời khen mạnh, dùng cho học sinh, nhân viên, tác phẩm.","ex":"他是我们班最优秀的学生。","exPy":"Tā shì wǒmen bān zuì yōuxiù de xuésheng.","exVi":"Cậu ấy là học sinh xuất sắc nhất lớp tôi.","w":"他 是 我们 班 最 优秀 的 学生。"},{"zh":"良好","py":"liánghǎo","vi":"tốt, khá tốt","hv":"lương hảo","note":"良 = \"lương\" trong \"lương thiện\", \"cải lương\". Trang trọng, hay gặp trên giấy tờ: 成绩良好.","ex":"他这次考试成绩良好。","exPy":"Tā zhè cì kǎoshì chéngjì liánghǎo.","exVi":"Kỳ thi này kết quả của cậu ấy khá tốt.","w":"他 这 次 考试 成绩 良好。"},{"zh":"严格","py":"yángé","vi":"nghiêm khắc","hv":"nghiêm cách","note":"Tiếng Việt nói \"nghiêm khắc\", \"nghiêm túc\" — cùng chữ 严. Dùng với 对: 对学生很严格.","ex":"爸爸对我很严格。","exPy":"Bàba duì wǒ hěn yángé.","exVi":"Bố rất nghiêm khắc với tôi.","w":"爸爸 对 我 很 严格。"},{"zh":"马虎","py":"mǎhu","vi":"cẩu thả, qua loa","hv":"mã hổ","note":"Nghĩa đen là \"ngựa hổ\" — có điển tích về người vẽ con vật nửa ngựa nửa hổ vì làm ẩu. Trái nghĩa với 仔细.","ex":"他做事有点儿马虎。","exPy":"Tā zuòshì yǒudiǎnr mǎhu.","exVi":"Cậu ấy làm việc hơi cẩu thả.","w":"他 做 事 有点儿 马虎。"},{"zh":"粗心","py":"cūxīn","vi":"bất cẩn, sơ ý","hv":"thô tâm","note":"粗 (thô) + 心 (lòng) — lòng dạ thô, không tỉ mỉ. Gần nghĩa 马虎 nhưng nhấn vào sự sơ ý.","ex":"因为粗心，我又做错了一道题。","exPy":"Yīnwèi cūxīn, wǒ yòu zuò cuò le yí dào tí.","exVi":"Vì sơ ý, tôi lại làm sai một bài.","w":"因为 粗心， 我 又 做 错 了 一道 题。"},{"zh":"仔细","py":"zǐxì","vi":"kỹ lưỡng, tỉ mỉ","hv":"tử tế","note":"BẪY HÁN VIỆT: âm là \"tử tế\" nhưng nghĩa tiếng Trung là KỸ LƯỠNG, không phải \"tốt bụng\". Tốt bụng là 善良 hoặc 好.","ex":"考试的时候要仔细检查。","exPy":"Kǎoshì de shíhou yào zǐxì jiǎnchá.","exVi":"Lúc thi phải kiểm tra kỹ.","w":"考试 的 时候 要 仔细 检查。"},{"zh":"耐心","py":"nàixīn","vi":"kiên nhẫn","hv":"nại tâm","note":"耐 = \"nại\" trong \"nhẫn nại\". Lại một thành viên gia đình chữ 心.","ex":"学外语一定要有耐心。","exPy":"Xué wàiyǔ yídìng yào yǒu nàixīn.","exVi":"Học ngoại ngữ nhất định phải kiên nhẫn.","w":"学 外语 一定 要 有 耐心。"},{"zh":"态度","py":"tàidu","vi":"thái độ","hv":"thái độ","note":"Chính là \"thái độ\" tiếng Việt: 态 (thái) + 度 (độ).","ex":"工作态度比能力更重要。","exPy":"Gōngzuò tàidu bǐ nénglì gèng zhòngyào.","exVi":"Thái độ làm việc quan trọng hơn năng lực.","w":"工作 态度 比 能力 更 重要。"}],"newChars":["优","缺","秀","良","虎","粗","仔","细","耐","态"],"outro":"很好！Xong bài 102."};
G.ROOMS["zh-l103"] = {"id":"zh-l103","lang":"zh","level":4,"no":103,"teacher":"wang","title":"HSK4 · Bài 103 · 看法和记忆 Ý kiến và trí nhớ","intro":["关于这件事，你有什么看法？","Bài 103: Nêu quan điểm, phỏng đoán và nhớ lại — nhóm động từ tư duy của HSK 4. Bấm 1 · Học để bắt đầu."],"introPy":"Guānyú zhè jiàn shì, nǐ yǒu shénme kànfǎ?","gram":{"t":"Ba mức phỏng đoán: 猜 < 估计 < 判断","b":"猜 = đoán mò · 估计 = ước chừng có cơ sở · 判断 = nhận định có phân tích","d":"猜谜语 (đoán câu đố), 估计有一百人 (ước chừng trăm người), 判断这个消息是假的 (nhận định tin này là giả). Chọn đúng mức thể hiện bạn nắm sắc thái.","ex":[["我猜他今年三十岁。","Tôi đoán năm nay anh ấy ba mươi.","Wǒ cāi tā jīnnián sānshí suì."],["估计明天会下雨。","Ước chừng mai sẽ mưa.","Gūjì míngtiān huì xiàyǔ."]]},"grams":[{"t":"Ba mức phỏng đoán: 猜 < 估计 < 判断","b":"猜 = đoán mò · 估计 = ước chừng có cơ sở · 判断 = nhận định có phân tích","d":"猜谜语 (đoán câu đố), 估计有一百人 (ước chừng trăm người), 判断这个消息是假的 (nhận định tin này là giả). Chọn đúng mức thể hiện bạn nắm sắc thái.","ex":[["我猜他今年三十岁。","Tôi đoán năm nay anh ấy ba mươi.","Wǒ cāi tā jīnnián sānshí suì."],["估计明天会下雨。","Ước chừng mai sẽ mưa.","Gūjì míngtiān huì xiàyǔ."]]},{"t":"Đuôi 法 — biến động từ thành \"cách làm\"","b":"看法 · 想法 · 做法 · 说法 · 用法","d":"Ghép 法 (pháp, cách) vào sau động từ là ra danh từ chỉ cách thức. Quy tắc cực kỳ sinh lợi: biết một động từ là có thêm một danh từ.","ex":[["我的想法跟你不一样。","Cách nghĩ của tôi khác bạn.","Wǒ de xiǎngfǎ gēn nǐ bù yíyàng."],["这个词的用法很特别。","Cách dùng từ này rất đặc biệt.","Zhège cí de yòngfǎ hěn tèbié."]]},{"t":"对 … 有意见 — cẩn thận nghĩa kép","b":"有意见 = có ý kiến · 对…有意见 = bất mãn với ai","d":"Nói 我对他有意见 không phải là \"tôi có ý kiến về anh ấy\" mà là \"tôi bất mãn với anh ấy\". Muốn xin ý kiến trung tính thì dùng 听听你的意见.","ex":[["大家对这个安排有意见。","Mọi người không hài lòng với sắp xếp này.","Dàjiā duì zhège ānpái yǒu yìjiàn."],["我想听听大家的意见。","Tôi muốn nghe ý kiến của mọi người.","Wǒ xiǎng tīngting dàjiā de yìjiàn."]]}],"items":[{"zh":"看法","py":"kànfǎ","vi":"cách nhìn, quan điểm","hv":"khán pháp","note":"看 (nhìn) + 法 (cách). Đuôi 法 rất hay gặp: 想法 (cách nghĩ), 做法 (cách làm), 说法 (cách nói).","ex":"关于这件事，你有什么看法？","exPy":"Guānyú zhè jiàn shì, nǐ yǒu shénme kànfǎ?","exVi":"Về việc này, bạn nghĩ sao?","w":"关于 这 件 事， 你 有 什么 看法？"},{"zh":"意见","py":"yìjiàn","vi":"ý kiến; ý kiến phản đối","hv":"ý kiến","note":"Chính là \"ý kiến\" tiếng Việt. Lưu ý: 对…有意见 nghĩa là BẤT MÃN với ai, không phải chỉ \"có ý kiến\".","ex":"会上大家提了很多意见。","exPy":"Huì shàng dàjiā tí le hěn duō yìjiàn.","exVi":"Trong cuộc họp mọi người nêu nhiều ý kiến.","w":"会 上 大家 提 了 很 多 意见。"},{"zh":"主意","py":"zhǔyi","vi":"ý tưởng, chủ ý","hv":"chủ ý","note":"Chính là \"chủ ý\" tiếng Việt. Khen ý tưởng hay: 好主意！","ex":"去海边过周末，好主意！","exPy":"Qù hǎibiān guò zhōumò, hǎo zhǔyi!","exVi":"Cuối tuần ra biển, ý hay đấy!","w":"去 海 边 过 周末， 好 主意！"},{"zh":"想念","py":"xiǎngniàn","vi":"nhớ nhung","hv":"tưởng niệm","note":"BẪY HÁN VIỆT: âm là \"tưởng niệm\" nhưng nghĩa tiếng Trung là NHỚ người còn sống ở xa, không liên quan tới tang lễ.","ex":"离开家以后，我很想念妈妈做的菜。","exPy":"Líkāi jiā yǐhòu, wǒ hěn xiǎngniàn māma zuò de cài.","exVi":"Xa nhà rồi tôi rất nhớ món mẹ nấu.","w":"离开 家 以后， 我 很 想念 妈妈 做 的 菜。"},{"zh":"回忆","py":"huíyì","vi":"hồi ức; nhớ lại","hv":"hồi ức","note":"Chính là \"hồi ức\" tiếng Việt: 回 (quay lại) + 忆 (nhớ, bộ 忄).","ex":"那次旅行留下了美好的回忆。","exPy":"Nà cì lǚxíng liú xià le měihǎo de huíyì.","exVi":"Chuyến đi đó để lại hồi ức đẹp.","w":"那 次 旅行 留下 了 美好 的 回忆。"},{"zh":"印象","py":"yìnxiàng","vi":"ấn tượng","hv":"ấn tượng","note":"Chính là \"ấn tượng\" tiếng Việt: 印 (in dấu) + 象 (hình). Dùng với 对: 对他印象很好.","ex":"第一印象很重要。","exPy":"Dì-yī yìnxiàng hěn zhòngyào.","exVi":"Ấn tượng đầu tiên rất quan trọng.","w":"第一 印象 很 重要。"},{"zh":"考虑","py":"kǎolǜ","vi":"cân nhắc, suy xét","hv":"khảo lự","note":"考 (khảo, xét) + 虑 (lo nghĩ, bộ 心). Nặng hơn 想 — là suy xét có cân đo.","ex":"这件事我需要考虑几天。","exPy":"Zhè jiàn shì wǒ xūyào kǎolǜ jǐ tiān.","exVi":"Việc này tôi cần cân nhắc vài ngày.","w":"这 件 事 我 需要 考虑 几 天。"},{"zh":"估计","py":"gūjì","vi":"ước tính, đoán chừng","hv":"cổ kế","note":"Dựa vào thông tin mà đoán con số hoặc khả năng: 估计他不来了.","ex":"估计这本书要两百块。","exPy":"Gūjì zhè běn shū yào liǎngbǎi kuài.","exVi":"Ước chừng quyển sách này hai trăm đồng.","w":"估计 这 本 书 要 两 百 块。"},{"zh":"判断","py":"pànduàn","vi":"phán đoán, nhận định","hv":"phán đoán","note":"Chính là \"phán đoán\" tiếng Việt: 判 (phán) + 断 (đoán, dứt khoát).","ex":"根据经验，我判断他会同意。","exPy":"Gēnjù jīngyàn, wǒ pànduàn tā huì tóngyì.","exVi":"Theo kinh nghiệm, tôi nhận định anh ấy sẽ đồng ý.","w":"根据 经验， 我 判断 他 会 同意。"},{"zh":"猜","py":"cāi","vi":"đoán","hv":"sai","note":"Bộ 犭 bên trái. Đoán mò không có căn cứ, nhẹ hơn 估计 và 判断.","ex":"你猜猜这是谁送的？","exPy":"Nǐ cāicai zhè shì shéi sòng de?","exVi":"Bạn đoán xem ai tặng cái này?","w":"你 猜 猜 这 是 谁 送 的？"}],"newChars":["念","忆","印","象","虑","估","计","判","猜"],"outro":"很好！Xong bài 103."};
G.ROOMS["zh-l104"] = {"id":"zh-l104","lang":"zh","level":4,"no":104,"teacher":"wang","title":"HSK4 · Bài 104 · 身体和打扮 Cơ thể và vẻ ngoài","intro":["打篮球的时候我的胳膊受伤了。","Bài 104: Mở rộng từ về thân thể và chuyện chăm chút bề ngoài. Bấm 1 · Học để bắt đầu."],"introPy":"Dǎ lánqiú de shíhou wǒ de gēbo shòushāng le.","gram":{"t":"眼睛 và 眼镜 — hai chữ chỉ khác một nét","b":"眼睛 yǎnjing = con mắt · 眼镜 yǎnjìng = cái kính","d":"Đây là cặp dễ nhầm nhất khi VIẾT. Mẹo: 镜 có bộ 钅 (kim loại) vì kính là đồ vật; 睛 có bộ 目 (mắt) vì đó là bộ phận cơ thể. Nhìn bộ thủ là phân biệt được ngay.","ex":[["我的眼睛不太好，要戴眼镜。","Mắt tôi không tốt lắm, phải đeo kính.","Wǒ de yǎnjing bú tài hǎo, yào dài yǎnjìng."]]},"grams":[{"t":"眼睛 và 眼镜 — hai chữ chỉ khác một nét","b":"眼睛 yǎnjing = con mắt · 眼镜 yǎnjìng = cái kính","d":"Đây là cặp dễ nhầm nhất khi VIẾT. Mẹo: 镜 có bộ 钅 (kim loại) vì kính là đồ vật; 睛 có bộ 目 (mắt) vì đó là bộ phận cơ thể. Nhìn bộ thủ là phân biệt được ngay.","ex":[["我的眼睛不太好，要戴眼镜。","Mắt tôi không tốt lắm, phải đeo kính.","Wǒ de yǎnjing bú tài hǎo, yào dài yǎnjìng."]]},{"t":"看样子 — trông có vẻ","b":"看样子 + nhận định","d":"Dùng để phỏng đoán dựa vào vẻ ngoài quan sát được. Gần nghĩa 好像 (bài 101) nhưng nhấn vào chuyện MẮT THẤY.","ex":[["看样子要下雨了。","Trông có vẻ sắp mưa rồi.","Kàn yàngzi yào xiàyǔ le."],["看他的样子，好像很不高兴。","Nhìn dáng anh ấy, hình như không vui.","Kàn tā de yàngzi, hǎoxiàng hěn bù gāoxìng."]]},{"t":"一点儿 … 也/都 没有 — phủ định tuyệt đối","b":"一点儿 + danh từ + 也/都 + 没有","d":"Cấu trúc nhấn mạnh \"chẳng có chút nào\". Với động từ dùng 一点儿也不: 我一点儿也不累.","ex":[["我一点儿力气也没有。","Tôi chẳng còn chút sức nào.","Wǒ yìdiǎnr lìqi yě méiyǒu."],["他一点儿都不害羞。","Cậu ấy chẳng ngại chút nào.","Tā yìdiǎnr dōu bú hàixiū."]]}],"items":[{"zh":"胳膊","py":"gēbo","vi":"cánh tay","hv":"cách bác","note":"Cả hai chữ đều có bộ 月 (thịt) — dấu hiệu chữ về cơ thể, đúng như bài 32.","ex":"打篮球的时候我的胳膊受伤了。","exPy":"Dǎ lánqiú de shíhou wǒ de gēbo shòushāng le.","exVi":"Lúc chơi bóng rổ tay tôi bị thương.","w":"打篮球 的 时候 我 的 胳膊 受伤 了。"},{"zh":"皮肤","py":"pífū","vi":"làn da","hv":"bì phu","note":"Tiếng Việt: \"bì\" trong \"da bì\", \"phu\" trong \"phu thê\"? Không — \"phu\" ở đây là da thịt, như trong \"cốt nhục bì phu\".","ex":"夏天要保护好皮肤。","exPy":"Xiàtiān yào bǎohù hǎo pífū.","exVi":"Mùa hè phải bảo vệ làn da.","w":"夏天 要 保护 好 皮肤。"},{"zh":"肚子","py":"dùzi","vi":"cái bụng","hv":"đỗ tử","note":"Cũng có bộ 月 (thịt). 肚子疼 (đau bụng), 肚子饿 (bụng đói).","ex":"吃太多了，肚子有点儿难受。","exPy":"Chī tài duō le, dùzi yǒudiǎnr nánshòu.","exVi":"Ăn nhiều quá, bụng hơi khó chịu.","w":"吃 太 多 了， 肚子 有点儿 难受。"},{"zh":"眼镜","py":"yǎnjìng","vi":"cái kính (mắt)","hv":"nhãn kính","note":"CẨN THẬN: 眼镜 yǎnjìng (kính) và 眼睛 yǎnjing (mắt, bài 17) chỉ khác chữ cuối. 镜 có bộ 钅 vì kính xưa mài từ kim loại.","ex":"他新买了一副眼镜。","exPy":"Tā xīn mǎi le yí fù yǎnjìng.","exVi":"Anh ấy mới mua một cái kính.","w":"他 新 买 了 一 副 眼镜。"},{"zh":"牙膏","py":"yágāo","vi":"kem đánh răng","hv":"nha cao","note":"牙 (răng, bài 51 trong 刷牙) + 膏 (chất sệt). Tiếng Việt: \"nha khoa\", \"cao dán\".","ex":"牙膏和毛巾都在洗手间。","exPy":"Yágāo hé máojīn dōu zài xǐshǒujiān.","exVi":"Kem đánh răng và khăn đều ở nhà tắm.","w":"牙膏 和 毛巾 都 在 洗手间。"},{"zh":"汗","py":"hàn","vi":"mồ hôi","hv":"hãn","note":"Bộ 氵 (nước) — mồ hôi là nước của cơ thể. Ra mồ hôi là 出汗.","ex":"天太热了，一动就出汗。","exPy":"Tiān tài rè le, yí dòng jiù chū hàn.","exVi":"Trời nóng quá, hễ động là ra mồ hôi.","w":"天 太 热 了， 一 动 就 出 汗。"},{"zh":"力气","py":"lìqi","vi":"sức lực","hv":"lực khí","note":"力 (lực, bộ thủ) + 气 (khí). Chỉ sức mạnh cơ bắp: 没力气 (không còn sức).","ex":"搬这个箱子需要很大力气。","exPy":"Bān zhège xiāngzi xūyào hěn dà lìqi.","exVi":"Khiêng cái thùng này cần rất nhiều sức.","w":"搬 这个 箱子 需要 很 大力 气。"},{"zh":"样子","py":"yàngzi","vi":"dáng vẻ, kiểu dáng","hv":"dạng tử","note":"样 = \"dạng\" trong \"hình dạng\", \"đa dạng\" (đã gặp ở 一样, bài 56).","ex":"他看样子很累。","exPy":"Tā kàn yàngzi hěn lèi.","exVi":"Trông dáng anh ấy có vẻ mệt.","w":"他 看 样子 很 累。"},{"zh":"打扮","py":"dǎban","vi":"trang điểm, ăn diện","hv":"đả ban","note":"打 (làm) + 扮 (hoá trang, bộ 扌). Chỉ việc chăm chút quần áo đầu tóc trước khi ra ngoài.","ex":"参加聚会前她打扮了很久。","exPy":"Cānjiā jùhuì qián tā dǎban le hěn jiǔ.","exVi":"Trước khi dự tiệc cô ấy trang điểm rất lâu.","w":"参加 聚会 前 她 打扮 了 很 久。"},{"zh":"理发","py":"lǐfà","vi":"cắt tóc","hv":"lý phát","note":"理 (sửa sang) + 发 (tóc, bài 32 trong 头发). Là động từ ly hợp: 理了一次发.","ex":"头发太长了，明天去理发。","exPy":"Tóufa tài cháng le, míngtiān qù lǐfà.","exVi":"Tóc dài quá rồi, mai đi cắt.","w":"头发 太 长 了， 明天 去 理发。"}],"newChars":["胳","膊","皮","肤","肚","镜","膏","汗","扮"],"outro":"很好！Xong bài 104."};
G.ROOMS["zh-l105"] = {"id":"zh-l105","lang":"zh","level":4,"no":105,"teacher":"wang","title":"HSK4 · Bài 105 · 安全和生命 An toàn và tính mạng","intro":["他咳嗽得厉害，应该去看医生。","Bài 105: Nói về nguy hiểm, bảo vệ, và những giới hạn chịu đựng. Bấm 1 · Học để bắt đầu."],"introPy":"Tā késou de lìhai, yīnggāi qù kàn yīshēng.","gram":{"t":"Động từ + 得 + 厉害 / 死了 — nhấn mạnh cực độ","b":"tính từ + 死了 · động từ + 得厉害","d":"累死了, 饿死了, 热死了 — cách nói cực kỳ thông dụng trong khẩu ngữ, tương đương \"…chết đi được\" của tiếng Việt. 疼得厉害 = đau dữ dội.","ex":[["今天热死了！","Hôm nay nóng chết đi được!","Jīntiān rè sǐ le!"],["他咳嗽得很厉害。","Anh ấy ho dữ lắm.","Tā késou de hěn lìhai."]]},"grams":[{"t":"Động từ + 得 + 厉害 / 死了 — nhấn mạnh cực độ","b":"tính từ + 死了 · động từ + 得厉害","d":"累死了, 饿死了, 热死了 — cách nói cực kỳ thông dụng trong khẩu ngữ, tương đương \"…chết đi được\" của tiếng Việt. 疼得厉害 = đau dữ dội.","ex":[["今天热死了！","Hôm nay nóng chết đi được!","Jīntiān rè sǐ le!"],["他咳嗽得很厉害。","Anh ấy ho dữ lắm.","Tā késou de hěn lìhai."]]},{"t":"Động từ + 不了 — không làm nổi","b":"động từ + 得了 (làm nổi) / 不了 (không nổi)","d":"了 ở đây đọc liǎo. 受不了 (chịu không nổi), 吃不了 (ăn không hết), 去不了 (không đi được). Khác với 不能 (không được phép) — 不了 là KHÔNG ĐỦ KHẢ NĂNG.","ex":[["菜太多了，我吃不了。","Nhiều món quá, tôi ăn không hết.","Cài tài duō le, wǒ chī bu liǎo."],["明天我去不了了。","Mai tôi không đi được rồi.","Míngtiān wǒ qù bu liǎo le."]]},{"t":"恐怕 — nói điều xấu cho nhẹ đi","b":"恐怕 + điều không hay","d":"Khi phải báo tin không vui hoặc từ chối, người Trung Quốc mở đầu bằng 恐怕 cho lịch sự. Khác 可能 (có thể) ở chỗ 恐怕 luôn kèm sắc thái tiếc nuối.","ex":[["恐怕我帮不了你。","E rằng tôi không giúp được bạn.","Kǒngpà wǒ bāng bu liǎo nǐ."],["恐怕来不及了。","E là không kịp mất.","Kǒngpà láibují le."]]}],"items":[{"zh":"咳嗽","py":"késou","vi":"ho","hv":"khái thấu","note":"Cả hai chữ đều có bộ 口 (miệng). Là động từ: 我咳嗽了三天.","ex":"他咳嗽得厉害，应该去看医生。","exPy":"Tā késou de lìhai, yīnggāi qù kàn yīshēng.","exVi":"Anh ấy ho dữ lắm, nên đi khám.","w":"他 咳嗽 得 厉害， 应该 去 看 医生。"},{"zh":"减肥","py":"jiǎnféi","vi":"giảm cân","hv":"giảm phì","note":"减 (giảm, bài 79) + 肥 (béo, bộ 月 thịt). Tiếng Việt: \"giảm\", \"phì nhiêu\". Động từ ly hợp: 减了五公斤肥.","ex":"为了减肥，她每天跑步。","exPy":"Wèile jiǎnféi, tā měi tiān pǎobù.","exVi":"Để giảm cân, ngày nào cô ấy cũng chạy bộ.","w":"为了 减肥， 她 每 天 跑步。"},{"zh":"厉害","py":"lìhai","vi":"giỏi, ghê gớm; nặng","hv":"lệ hại","note":"Hai nghĩa trái chiều: khen ai giỏi (你真厉害！) và tả mức độ nặng (疼得厉害). Nhìn ngữ cảnh mà đoán.","ex":"你的汉语真厉害！","exPy":"Nǐ de Hànyǔ zhēn lìhai!","exVi":"Tiếng Trung của bạn giỏi thật!","w":"你 的 汉语 真 厉害！"},{"zh":"死","py":"sǐ","vi":"chết","hv":"tử","note":"Chính là \"tử\" tiếng Việt (\"tử vong\", \"sinh tử\"). Cũng dùng làm bổ ngữ cực cấp: 累死了 (mệt chết đi được).","ex":"走了一天，累死我了。","exPy":"Zǒu le yì tiān, lèi sǐ wǒ le.","exVi":"Đi cả ngày, mệt chết đi được.","w":"走 了 一 天， 累 死 我 了。"},{"zh":"危险","py":"wēixiǎn","vi":"nguy hiểm","hv":"nguy hiểm","note":"Chính là \"nguy hiểm\" tiếng Việt: 危 (nguy) + 险 (hiểm).","ex":"晚上一个人走这条路很危险。","exPy":"Wǎnshang yí ge rén zǒu zhè tiáo lù hěn wēixiǎn.","exVi":"Tối đi một mình con đường này rất nguy hiểm.","w":"晚上 一 个人 走 这 条 路 很 危险。"},{"zh":"安全","py":"ānquán","vi":"an toàn","hv":"an toàn","note":"Chính là \"an toàn\" tiếng Việt: 安 (an) + 全 (toàn). Trái nghĩa với 危险.","ex":"开车的时候一定要注意安全。","exPy":"Kāichē de shíhou yídìng yào zhùyì ānquán.","exVi":"Khi lái xe nhất định phải chú ý an toàn.","w":"开车 的 时候 一定 要 注意 安全。"},{"zh":"保护","py":"bǎohù","vi":"bảo vệ","hv":"bảo hộ","note":"Chính là \"bảo hộ\" tiếng Việt (nay hay nói \"bảo vệ\"). 护 cũng nằm trong 护照 (bài 60), 护士 (bài 76).","ex":"保护环境就是保护我们自己。","exPy":"Bǎohù huánjìng jiù shì bǎohù wǒmen zìjǐ.","exVi":"Bảo vệ môi trường chính là bảo vệ chính mình.","w":"保护 环境 就是 保护 我们 自己。"},{"zh":"生命","py":"shēngmìng","vi":"sinh mệnh, tính mạng","hv":"sinh mệnh","note":"Chính là \"sinh mệnh\" tiếng Việt: 生 (sinh) + 命 (mệnh).","ex":"健康和生命最重要。","exPy":"Jiànkāng hé shēngmìng zuì zhòngyào.","exVi":"Sức khoẻ và tính mạng là quan trọng nhất.","w":"健康 和 生命 最 重要。"},{"zh":"恐怕","py":"kǒngpà","vi":"e rằng, sợ là","hv":"khủng phạ","note":"恐 (sợ, có bộ 心) + 怕 (sợ, bộ 忄). Dùng để nói điều KHÔNG HAY một cách nhẹ nhàng.","ex":"恐怕今天的会要推迟了。","exPy":"Kǒngpà jīntiān de huì yào tuīchí le.","exVi":"E là cuộc họp hôm nay phải hoãn.","w":"恐怕 今天 的 会 要 推迟 了。"},{"zh":"受不了","py":"shòu bu liǎo","vi":"không chịu nổi","hv":"thụ bất liễu","note":"受 (chịu) + 不了 (không nổi). Cấu trúc \"động từ + 不了\" nghĩa là không làm nổi: 吃不了 (ăn không hết).","ex":"外面太吵，我受不了。","exPy":"Wàimiàn tài chǎo, wǒ shòu bu liǎo.","exVi":"Bên ngoài ồn quá, tôi chịu không nổi.","w":"外面 太 吵， 我 受不了。"}],"newChars":["咳","嗽","减","肥","厉","死","危","险","全","保","命","恐"],"outro":"很好！Xong bài 105."};
G.ROOMS["zh-l106"] = {"id":"zh-l106","lang":"zh","level":4,"no":106,"teacher":"wang","title":"HSK4 · Bài 106 · 亲人和朋友 Người thân và bạn hữu","intro":["春节的时候，所有的亲戚都会来。","Bài 106: Mở rộng cách gọi người thân, và dùng 咱们 — đại từ \"chúng ta\" thân mật. Bấm 1 · Học để bắt đầu."],"introPy":"Chūnjié de shíhou, suǒyǒu de qīnqi dōu huì lái.","gram":{"t":"咱们 và 我们 — sự khác biệt tinh tế","b":"咱们 = tôi + BẠN · 我们 = tôi + người khác (có thể không có bạn)","d":"Nói với một người bạn: 咱们去吃饭吧 (mình với cậu đi ăn) nghe thân thiết hơn hẳn 我们去吃饭吧. Tiếng Việt cũng có sắc thái này giữa \"chúng ta\" và \"chúng tôi\" — nên người Việt nắm rất nhanh.","ex":[["咱们是好朋友。","Mình với cậu là bạn tốt.","Zánmen shì hǎo péngyou."],["我们公司在北京。","Công ty chúng tôi ở Bắc Kinh. (không gồm người nghe)","Wǒmen gōngsī zài Běijīng."]]},"grams":[{"t":"咱们 và 我们 — sự khác biệt tinh tế","b":"咱们 = tôi + BẠN · 我们 = tôi + người khác (có thể không có bạn)","d":"Nói với một người bạn: 咱们去吃饭吧 (mình với cậu đi ăn) nghe thân thiết hơn hẳn 我们去吃饭吧. Tiếng Việt cũng có sắc thái này giữa \"chúng ta\" và \"chúng tôi\" — nên người Việt nắm rất nhanh.","ex":[["咱们是好朋友。","Mình với cậu là bạn tốt.","Zánmen shì hǎo péngyou."],["我们公司在北京。","Công ty chúng tôi ở Bắc Kinh. (không gồm người nghe)","Wǒmen gōngsī zài Běijīng."]]},{"t":"俩 và 仨 — số đã gộp sẵn lượng từ","b":"俩 = 两个 · 仨 = 三个","d":"Hai chữ khẩu ngữ này đã chứa sẵn lượng từ 个, nên tuyệt đối KHÔNG thêm lượng từ nữa. 我们俩 đúng, 我们俩个 sai.","ex":[["他们俩认识很久了。","Hai người họ quen nhau lâu rồi.","Tāmen liǎ rènshi hěn jiǔ le."]]},{"t":"Từ trang trọng và từ thường ngày","b":"妈妈 / 母亲 · 孩子 / 儿童 · 朋友 / 友谊","d":"Từ HSK 4 trở đi bạn học song song hai lớp từ vựng: lớp khẩu ngữ và lớp văn viết. Trong bài thi HSK và báo chí, lớp trang trọng xuất hiện rất nhiều — và nó chính là lớp gần tiếng Việt Hán Việt nhất.","ex":[["妈妈 → 母亲","mẹ → mẫu thân","māma → mǔqīn"],["孩子 → 儿童","đứa trẻ → nhi đồng","háizi → értóng"]]}],"items":[{"zh":"亲戚","py":"qīnqi","vi":"họ hàng, thân thích","hv":"thân thích","note":"Chính là \"thân thích\" tiếng Việt. Chỉ họ hàng ngoài gia đình hạt nhân.","ex":"春节的时候，所有的亲戚都会来。","exPy":"Chūnjié de shíhou, suǒyǒu de qīnqi dōu huì lái.","exVi":"Dịp Tết tất cả họ hàng đều đến.","w":"春 节 的 时候， 所有 的 亲戚 都会 来。"},{"zh":"孙子","py":"sūnzi","vi":"cháu trai (nội)","hv":"tôn tử","note":"Chính là \"tôn\" trong \"tử tôn\", \"con cháu\". Cháu gái là 孙女.","ex":"爷爷奶奶最喜欢的就是孙子。","exPy":"Yéye nǎinai zuì xǐhuan de jiù shì sūnzi.","exVi":"Ông bà thích nhất là cháu trai.","w":"爷爷 奶奶 最 喜欢 的 就是 孙子。"},{"zh":"母亲","py":"mǔqīn","vi":"mẹ (trang trọng)","hv":"mẫu thân","note":"Chính là \"mẫu thân\" tiếng Việt. Trang trọng hơn 妈妈 — dùng trong văn viết. Cha là 父亲 (phụ thân).","ex":"他把第一份工资给了母亲。","exPy":"Tā bǎ dì-yī fèn gōngzī gěi le mǔqīn.","exVi":"Anh ấy đưa tháng lương đầu tiên cho mẹ.","w":"他 把 第一 份 工资 给 了 母亲。"},{"zh":"儿童","py":"értóng","vi":"nhi đồng, trẻ em","hv":"nhi đồng","note":"Chính là \"nhi đồng\" tiếng Việt. Trang trọng hơn 孩子 — dùng trong văn bản, biển báo: 儿童节 (Tết thiếu nhi).","ex":"这本书是给儿童看的。","exPy":"Zhè běn shū shì gěi értóng kàn de.","exVi":"Quyển sách này dành cho trẻ em.","w":"这 本 书 是 给 儿童 看 的。"},{"zh":"小伙子","py":"xiǎohuǒzi","vi":"chàng trai trẻ","hv":"tiểu hoả tử","note":"Cách gọi thân mật của người lớn tuổi dành cho thanh niên nam. Nữ thì gọi là 姑娘.","ex":"那个小伙子帮我搬了行李。","exPy":"Nàge xiǎohuǒzi bāng wǒ bān le xíngli.","exVi":"Cậu thanh niên đó giúp tôi khiêng hành lý.","w":"那个 小伙子 帮 我 搬 了 行李。"},{"zh":"咱们","py":"zánmen","vi":"chúng ta (gồm cả người nghe)","hv":"cha môn","note":"Khác 我们: 咱们 CHẮC CHẮN bao gồm người nghe, còn 我们 có thể không. Rất thân mật, đặc trưng miền Bắc.","ex":"咱们下班以后去喝一杯吧。","exPy":"Zánmen xiàbān yǐhòu qù hē yì bēi ba.","exVi":"Tan làm mình đi làm ly nhé.","w":"咱们 下班 以后 去 喝 一 杯 吧。"},{"zh":"俩","py":"liǎ","vi":"hai người, cả hai","hv":"lưỡng","note":"Là 两个 gộp lại thành một chữ. Vì đã chứa \"个\" nên KHÔNG được thêm lượng từ: nói 我们俩, không nói 我们俩个.","ex":"我们俩从小就认识。","exPy":"Wǒmen liǎ cóngxiǎo jiù rènshi.","exVi":"Hai chúng tôi quen nhau từ nhỏ.","w":"我们 俩 从小 就 认识。"},{"zh":"友谊","py":"yǒuyì","vi":"tình bạn, hữu nghị","hv":"hữu nghị","note":"Chính là \"hữu nghị\" tiếng Việt: 友 (bạn) + 谊 (tình nghĩa).","ex":"友谊比什么都重要。","exPy":"Yǒuyì bǐ shénme dōu zhòngyào.","exVi":"Tình bạn quan trọng hơn mọi thứ.","w":"友谊 比 什么 都 重要。"},{"zh":"友好","py":"yǒuhǎo","vi":"thân thiện, hữu hảo","hv":"hữu hảo","note":"Chính là \"hữu hảo\" tiếng Việt. Dùng cho cả người lẫn quan hệ giữa hai nước.","ex":"越南人对客人特别友好。","exPy":"Yuènán rén duì kèrén tèbié yǒuhǎo.","exVi":"Người Việt Nam đặc biệt thân thiện với khách.","w":"越 南 人 对 客人 特别 友好。"},{"zh":"尊重","py":"zūnzhòng","vi":"tôn trọng","hv":"tôn trọng","note":"Chính là \"tôn trọng\" tiếng Việt: 尊 (tôn) + 重 (trọng).","ex":"互相尊重才能长久。","exPy":"Hùxiāng zūnzhòng cái néng chángjiǔ.","exVi":"Tôn trọng lẫn nhau mới bền lâu.","w":"互相 尊重 才能 长久。"}],"newChars":["亲","戚","孙","母","童","伙","咱","俩","谊","尊"],"outro":"很好！Xong bài 106."};
G.ROOMS["zh-l107"] = {"id":"zh-l107","lang":"zh","level":4,"no":107,"teacher":"wang","title":"HSK4 · Bài 107 · 社会生活 Xã hội và cộng đồng","intro":["毕业以后就要走进社会了。","Bài 107: Nói về xã hội, dân tộc, pháp luật — lớp từ trừu tượng gần tiếng Việt nhất. Bấm 1 · Học để bắt đầu."],"introPy":"Bìyè yǐhòu jiù yào zǒu jìn shèhuì le.","gram":{"t":"Bài này gần như là tiếng Việt viết bằng chữ Hán","b":"社会 · 民族 · 国籍 · 法律 · 责任 · 世纪","d":"Sáu từ trùng khít hoàn toàn. Đây là lý do người Việt đọc báo tiếng Trung dễ hơn nói tiếng Trung: lớp từ chính luận, học thuật gần như dùng chung kho Hán Việt.","ex":[["社会 · 民族 · 国籍","xã hội · dân tộc · quốc tịch","shèhuì · mínzú · guójí"],["法律 · 责任 · 世纪","pháp luật · trách nhiệm · thế kỷ","fǎlǜ · zérèn · shìjì"]]},"grams":[{"t":"Bài này gần như là tiếng Việt viết bằng chữ Hán","b":"社会 · 民族 · 国籍 · 法律 · 责任 · 世纪","d":"Sáu từ trùng khít hoàn toàn. Đây là lý do người Việt đọc báo tiếng Trung dễ hơn nói tiếng Trung: lớp từ chính luận, học thuật gần như dùng chung kho Hán Việt.","ex":[["社会 · 民族 · 国籍","xã hội · dân tộc · quốc tịch","shèhuì · mínzú · guójí"],["法律 · 责任 · 世纪","pháp luật · trách nhiệm · thế kỷ","fǎlǜ · zérèn · shìjì"]]},{"t":"各 + lượng từ — mỗi, các","b":"各 + lượng từ + danh từ","d":"各 luôn đi kèm lượng từ hoặc danh từ đơn âm: 各个 (mỗi cái), 各种 (các loại), 各国 (các nước). Khác 每 (bài 18) ở chỗ 各 nhấn vào sự KHÁC BIỆT giữa các cá thể, còn 每 nhấn vào sự lặp lại đều đặn.","ex":[["商店里有各种水果。","Trong cửa hàng có đủ loại hoa quả.","Shāngdiàn lǐ yǒu gè zhǒng shuǐguǒ."],["各位好！","Chào quý vị!","Gè wèi hǎo!"]]},{"t":"Lượng từ 群 và các lượng từ tập thể","b":"一群人 · 一群鸟 · 一批货 · 一堆书","d":"群 dùng cho nhóm sinh vật sống di chuyển cùng nhau. Tiếng Việt cũng nói \"một đàn chim\", \"một đám người\" — cùng tư duy phân loại theo tập thể.","ex":[["天上飞过一群鸟。","Trên trời bay qua một đàn chim.","Tiān shàng fēi guò yì qún niǎo."]]}],"items":[{"zh":"社会","py":"shèhuì","vi":"xã hội","hv":"xã hội","note":"Chính là \"xã hội\" tiếng Việt: 社 (xã) + 会 (hội).","ex":"毕业以后就要走进社会了。","exPy":"Bìyè yǐhòu jiù yào zǒu jìn shèhuì le.","exVi":"Tốt nghiệp rồi là bước vào xã hội.","w":"毕业 以后 就 要 走 进 社会 了。"},{"zh":"民族","py":"mínzú","vi":"dân tộc","hv":"dân tộc","note":"Chính là \"dân tộc\" tiếng Việt: 民 (dân) + 族 (tộc). Trung Quốc có 56 dân tộc.","ex":"每个民族都有自己的文化。","exPy":"Měi ge mínzú dōu yǒu zìjǐ de wénhuà.","exVi":"Mỗi dân tộc đều có văn hoá riêng.","w":"每 个 民族 都 有 自己 的 文化。"},{"zh":"国籍","py":"guójí","vi":"quốc tịch","hv":"quốc tịch","note":"Chính là \"quốc tịch\" tiếng Việt: 国 (quốc) + 籍 (tịch, sổ sách).","ex":"办签证要填国籍和地址。","exPy":"Bàn qiānzhèng yào tián guójí hé dìzhǐ.","exVi":"Làm visa phải điền quốc tịch và địa chỉ.","w":"办 签证 要 填 国籍 和 地址。"},{"zh":"法律","py":"fǎlǜ","vi":"pháp luật","hv":"pháp luật","note":"Chính là \"pháp luật\" tiếng Việt: 法 (pháp) + 律 (luật).","ex":"开车不能喝酒，这是法律。","exPy":"Kāichē bù néng hē jiǔ, zhè shì fǎlǜ.","exVi":"Lái xe không được uống rượu, đó là luật.","w":"开车 不 能 喝 酒， 这 是 法律。"},{"zh":"责任","py":"zérèn","vi":"trách nhiệm","hv":"trách nhiệm","note":"Chính là \"trách nhiệm\" tiếng Việt: 责 (trách) + 任 (nhiệm).","ex":"照顾好家人是我们的责任。","exPy":"Zhàogù hǎo jiārén shì wǒmen de zérèn.","exVi":"Chăm lo cho gia đình là trách nhiệm của chúng ta.","w":"照顾 好 家人 是 我们 的 责任。"},{"zh":"世纪","py":"shìjì","vi":"thế kỷ","hv":"thế kỷ","note":"Chính là \"thế kỷ\" tiếng Việt: 世 (thế, bài 38 trong 世界) + 纪 (kỷ).","ex":"这座桥是上个世纪建的。","exPy":"Zhè zuò qiáo shì shàng ge shìjì jiàn de.","exVi":"Cây cầu này xây từ thế kỷ trước.","w":"这 座 桥 是 上 个 世纪 建 的。"},{"zh":"生活","py":"shēnghuó","vi":"cuộc sống; sinh sống","hv":"sinh hoạt","note":"Chính là \"sinh hoạt\" tiếng Việt, nhưng nghĩa rộng hơn — là cả CUỘC SỐNG chứ không chỉ hoạt động hằng ngày.","ex":"城市生活很方便，但是也很累。","exPy":"Chéngshì shēnghuó hěn fāngbiàn, dànshì yě hěn lèi.","exVi":"Cuộc sống thành phố tiện nhưng cũng mệt.","w":"城市 生活 很 方便， 但是 也 很 累。"},{"zh":"观众","py":"guānzhòng","vi":"khán giả","hv":"quan chúng","note":"观 (xem) + 众 (đám đông — ba chữ 人 chồng lên nhau!). 观 đọc là \"quan\" như trong \"quan sát\", \"tham quan\". Chữ \"khán\" trong \"khán giả\" là chữ khác: 看.","ex":"演出结束时观众都鼓掌了。","exPy":"Yǎnchū jiéshù shí guānzhòng dōu gǔzhǎng le.","exVi":"Khi diễn xong khán giả đều vỗ tay.","w":"演出 结束 时 观众 都 鼓掌 了。"},{"zh":"群","py":"qún","vi":"đám, nhóm (lượng từ)","hv":"quần","note":"Tiếng Việt: \"quần chúng\", \"quần thể\". Đếm nhóm người hay động vật: 一群人, 一群鸟.","ex":"公园里有一群孩子在玩。","exPy":"Gōngyuán lǐ yǒu yì qún háizi zài wán.","exVi":"Trong công viên có một nhóm trẻ đang chơi.","w":"公园 里 有 一 群 孩子 在 玩。"},{"zh":"各","py":"gè","vi":"các, mỗi","hv":"các","note":"Chính là \"các\" tiếng Việt. Đứng trước lượng từ: 各个国家, 各种颜色.","ex":"各位朋友，欢迎大家！","exPy":"Gè wèi péngyou, huānyíng dàjiā!","exVi":"Thưa các bạn, hoan nghênh mọi người!","w":"各位 朋友， 欢迎 大家！"}],"newChars":["社","族","籍","律","责","纪","观","众","群","各"],"outro":"很好！Xong bài 107."};
G.ROOMS["zh-l108"] = {"id":"zh-l108","lang":"zh","level":4,"no":108,"teacher":"wang","title":"HSK4 · Bài 108 · 交往 Giao thiệp","intro":["到了以后请跟我联系。","Bài 108: Liên lạc, bàn bạc, mời mọc — bộ động từ giao tiếp xã hội. Bấm 1 · Học để bắt đầu."],"introPy":"Dào le yǐhòu qǐng gēn wǒ liánxì.","gram":{"t":"跟 / 和 + người + 联系 · 商量 · 谈","b":"跟 + người + động từ giao tiếp","d":"Các động từ hai chiều đều cần nêu đối tượng bằng 跟 hoặc 和 đặt TRƯỚC động từ. Nói 联系我 được, nhưng trang trọng thì dùng 跟我联系.","ex":[["有问题请跟我联系。","Có vấn đề xin liên hệ với tôi.","Yǒu wèntí qǐng gēn wǒ liánxì."],["我想跟你商量一件事。","Tôi muốn bàn với bạn một việc.","Wǒ xiǎng gēn nǐ shāngliang yí jiàn shì."]]},"grams":[{"t":"跟 / 和 + người + 联系 · 商量 · 谈","b":"跟 + người + động từ giao tiếp","d":"Các động từ hai chiều đều cần nêu đối tượng bằng 跟 hoặc 和 đặt TRƯỚC động từ. Nói 联系我 được, nhưng trang trọng thì dùng 跟我联系.","ex":[["有问题请跟我联系。","Có vấn đề xin liên hệ với tôi.","Yǒu wèntí qǐng gēn wǒ liánxì."],["我想跟你商量一件事。","Tôi muốn bàn với bạn một việc.","Wǒ xiǎng gēn nǐ shāngliang yí jiàn shì."]]},{"t":"互相 — chỉ dùng với hành động HAI CHIỀU","b":"互相 + động từ hai âm tiết","d":"互相帮助, 互相学习, 互相尊重, 互相理解 — đều là việc cả hai bên cùng làm cho nhau. Không nói 互相吃饭 vì ăn cơm không phải hành động qua lại.","ex":[["同学之间要互相帮助。","Bạn học phải giúp nhau.","Tóngxué zhījiān yào hùxiāng bāngzhù."],["夫妻要互相理解。","Vợ chồng phải hiểu nhau.","Fūqī yào hùxiāng lǐjiě."]]},{"t":"关键是 … — điều mấu chốt là…","b":"关键是 + mệnh đề","d":"Mẫu câu rất hay dùng khi tổng kết hoặc khuyên nhủ. Tương đương \"vấn đề mấu chốt là…\" của tiếng Việt.","ex":[["关键是要每天练习。","Mấu chốt là phải luyện mỗi ngày.","Guānjiàn shì yào měi tiān liànxí."],["学好汉语的关键是什么？","Mấu chốt để học giỏi tiếng Trung là gì?","Xué hǎo Hànyǔ de guānjiàn shì shénme?"]]}],"items":[{"zh":"联系","py":"liánxì","vi":"liên hệ, liên lạc","hv":"liên hệ","note":"Chính là \"liên hệ\" tiếng Việt: 联 (liên) + 系 (hệ).","ex":"到了以后请跟我联系。","exPy":"Dào le yǐhòu qǐng gēn wǒ liánxì.","exVi":"Đến nơi rồi xin liên hệ với tôi.","w":"到 了 以后 请 跟 我 联系。"},{"zh":"交流","py":"jiāoliú","vi":"giao lưu, trao đổi","hv":"giao lưu","note":"Chính là \"giao lưu\" tiếng Việt: 交 (giao) + 流 (lưu, chảy).","ex":"留学生和本地学生经常交流。","exPy":"Liúxuéshēng hé běndì xuésheng jīngcháng jiāoliú.","exVi":"Du học sinh và sinh viên bản địa thường giao lưu.","w":"留学生 和 本地 学生 经常 交流。"},{"zh":"互相","py":"hùxiāng","vi":"lẫn nhau","hv":"hỗ tương","note":"Chính là \"hỗ tương\" tiếng Việt (\"hỗ trợ\", \"tương trợ\"). Đứng trước động từ: 互相帮助.","ex":"我们互相学习，互相进步。","exPy":"Wǒmen hùxiāng xuéxí, hùxiāng jìnbù.","exVi":"Chúng ta học lẫn nhau, cùng tiến bộ.","w":"我们 互相 学习， 互相 进步。"},{"zh":"共同","py":"gòngtóng","vi":"chung, cùng nhau","hv":"cộng đồng","note":"Chính là \"cộng đồng\" tiếng Việt, nhưng tiếng Trung dùng như tính từ \"chung\": 共同的爱好 (sở thích chung).","ex":"这是我们共同的目标。","exPy":"Zhè shì wǒmen gòngtóng de mùbiāo.","exVi":"Đây là mục tiêu chung của chúng ta.","w":"这 是 我们 共同 的 目标。"},{"zh":"关键","py":"guānjiàn","vi":"then chốt, mấu chốt","hv":"quan kiện","note":"关 (then cửa) + 键 (chốt, bộ 钅) — nghĩa đen là cái then chốt. Tiếng Việt cũng nói \"then chốt\".","ex":"成功的关键是坚持。","exPy":"Chénggōng de guānjiàn shì jiānchí.","exVi":"Mấu chốt của thành công là kiên trì.","w":"成功 的 关键 是 坚持。"},{"zh":"陪","py":"péi","vi":"đi cùng, bầu bạn","hv":"bồi","note":"Tiếng Việt: \"bồi\" trong \"bồi bàn\", \"bồi dưỡng\". Bộ 阝 bên trái.","ex":"周末我陪妈妈去买东西。","exPy":"Zhōumò wǒ péi māma qù mǎi dōngxi.","exVi":"Cuối tuần tôi đi mua sắm cùng mẹ.","w":"周末 我 陪 妈妈 去 买 东西。"},{"zh":"谈","py":"tán","vi":"bàn, nói chuyện","hv":"đàm","note":"Chính là \"đàm\" tiếng Việt (\"đàm phán\", \"hội đàm\"). Bộ 讠 (lời nói). Trang trọng hơn 聊天.","ex":"经理想跟你谈一谈。","exPy":"Jīnglǐ xiǎng gēn nǐ tán yi tán.","exVi":"Giám đốc muốn nói chuyện với bạn.","w":"经理 想 跟 你 谈 一 谈。"},{"zh":"商量","py":"shāngliang","vi":"bàn bạc, thương lượng","hv":"thương lượng","note":"Chính là \"thương lượng\" tiếng Việt. 商 cũng nằm trong 商店 (bài 10).","ex":"买房子这么大的事要商量。","exPy":"Mǎi fángzi zhème dà de shì yào shāngliang.","exVi":"Việc lớn như mua nhà thì phải bàn bạc.","w":"买 房子 这么 大 的 事 要 商量。"},{"zh":"邀请","py":"yāoqǐng","vi":"mời","hv":"yêu thỉnh","note":"邀 (mời, bộ 辶) + 请 (thỉnh, bài 2). Trang trọng hơn 请 dùng một mình.","ex":"他邀请我去他家吃饭。","exPy":"Tā yāoqǐng wǒ qù tā jiā chīfàn.","exVi":"Anh ấy mời tôi đến nhà ăn cơm.","w":"他 邀请 我 去 他 家 吃 饭。"},{"zh":"聚会","py":"jùhuì","vi":"buổi tụ họp, tiệc","hv":"tụ hội","note":"Chính là \"tụ hội\" tiếng Việt: 聚 (tụ) + 会 (hội).","ex":"今晚的聚会你去不去？","exPy":"Jīnwǎn de jùhuì nǐ qù bu qù?","exVi":"Buổi tụ họp tối nay bạn có đi không?","w":"今 晚 的 聚会 你 去 不 去？"}],"newChars":["联","互","键","陪","谈","量","邀","聚"],"outro":"很好！Xong bài 108."};
G.ROOMS["zh-l109"] = {"id":"zh-l109","lang":"zh","level":4,"no":109,"teacher":"wang","title":"HSK4 · Bài 109 · 大学生活 Trường đại học","intro":["这个学期的课程很紧张。","Bài 109: Từ vựng bậc đại học: ngành học, bằng cấp, đăng ký, nghỉ hè. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège xuéqī de kèchéng hěn jǐnzhāng.","gram":{"t":"Bẫy Hán Việt: 博士 là TIẾN SĨ","b":"博士 = tiến sĩ · 医生 / 大夫 = bác sĩ","d":"Đây là cái bẫy nguy hiểm vì cả hai đều là nghề nghiệp. Nhớ: 博 nghĩa là UYÊN BÁC (như \"bác học\", \"uyên bác\") — người học rộng, tức tiến sĩ. Người chữa bệnh là 医生.","ex":[["他是医学博士。","Anh ấy là tiến sĩ y học.","Tā shì yīxué bóshì."],["我要去看医生。","Tôi phải đi khám bác sĩ.","Wǒ yào qù kàn yīshēng."]]},"grams":[{"t":"Bẫy Hán Việt: 博士 là TIẾN SĨ","b":"博士 = tiến sĩ · 医生 / 大夫 = bác sĩ","d":"Đây là cái bẫy nguy hiểm vì cả hai đều là nghề nghiệp. Nhớ: 博 nghĩa là UYÊN BÁC (như \"bác học\", \"uyên bác\") — người học rộng, tức tiến sĩ. Người chữa bệnh là 医生.","ex":[["他是医学博士。","Anh ấy là tiến sĩ y học.","Tā shì yīxué bóshì."],["我要去看医生。","Tôi phải đi khám bác sĩ.","Wǒ yào qù kàn yīshēng."]]},{"t":"Thang bằng cấp","b":"本科 → 硕士 → 博士","d":"本科 (cử nhân) → 硕士 (thạc sĩ) → 博士 (tiến sĩ). Ba từ này giống hệt hệ thống bằng cấp Việt Nam vì cùng gốc Hán. Người dạy là 教授 (giáo sư).","ex":[["他硕士毕业以后去读博士了。","Anh ấy tốt nghiệp thạc sĩ rồi đi học tiến sĩ.","Tā shuòshì bìyè yǐhòu qù dú bóshì le."]]},{"t":"报名 và 申请 — đăng ký hay nộp đơn?","b":"报名 = ghi tên tham gia · 申请 = nộp đơn xin xét duyệt","d":"报名参加比赛 (ghi tên dự thi — ai cũng vào được). 申请奖学金 (xin học bổng — phải được duyệt). Mức trang trọng và tính cạnh tranh khác nhau.","ex":[["我报名参加了汉语比赛。","Tôi đăng ký dự thi tiếng Trung.","Wǒ bàomíng cānjiā le Hànyǔ bǐsài."],["他申请了三所大学。","Cậu ấy nộp đơn vào ba trường đại học.","Tā shēnqǐng le sān suǒ dàxué."]]}],"items":[{"zh":"学期","py":"xuéqī","vi":"học kỳ","hv":"học kỳ","note":"Chính là \"học kỳ\" tiếng Việt: 学 (học) + 期 (kỳ).","ex":"这个学期的课程很紧张。","exPy":"Zhège xuéqī de kèchéng hěn jǐnzhāng.","exVi":"Chương trình học kỳ này rất căng.","w":"这个 学期 的 课程 很 紧张。"},{"zh":"专业","py":"zhuānyè","vi":"chuyên ngành","hv":"chuyên nghiệp","note":"Âm là \"chuyên nghiệp\" nhưng nghĩa chính trong tiếng Trung là CHUYÊN NGÀNH học. Nghĩa \"chuyên nghiệp\" cũng có nhưng phụ.","ex":"你大学学的什么专业？","exPy":"Nǐ dàxué xué de shénme zhuānyè?","exVi":"Đại học bạn học ngành gì?","w":"你 大学 学 的 什么 专业？"},{"zh":"硕士","py":"shuòshì","vi":"thạc sĩ","hv":"thạc sĩ","note":"Chính là \"thạc sĩ\" tiếng Việt: 硕 (thạc, to lớn) + 士 (sĩ).","ex":"读硕士需要两三年。","exPy":"Dú shuòshì xūyào liǎng sān nián.","exVi":"Học thạc sĩ cần hai ba năm.","w":"读 硕士 需要 两 三 年。"},{"zh":"博士","py":"bóshì","vi":"tiến sĩ","hv":"bác sĩ","note":"BẪY HÁN VIỆT: âm là \"bác sĩ\" nhưng nghĩa là TIẾN SĨ. Bác sĩ chữa bệnh là 医生 hoặc 大夫.","ex":"他是这个专业最年轻的博士。","exPy":"Tā shì zhège zhuānyè zuì niánqīng de bóshì.","exVi":"Anh ấy là tiến sĩ trẻ nhất ngành này.","w":"他 是 这个 专业 最 年轻 的 博士。"},{"zh":"教授","py":"jiàoshòu","vi":"giáo sư","hv":"giáo thụ","note":"Tiếng Việt gọi là \"giáo sư\"; âm Hán Việt của 教授 là \"giáo thụ\" — nghĩa đen: người truyền dạy.","ex":"李教授的课很受欢迎。","exPy":"Lǐ jiàoshòu de kè hěn shòu huānyíng.","exVi":"Lớp của giáo sư Lý rất được ưa thích.","w":"李 教授 的 课 很 受 欢迎。"},{"zh":"毕业","py":"bìyè","vi":"tốt nghiệp","hv":"tốt nghiệp","note":"Âm Hán Việt là \"tất nghiệp\" — chính là \"tốt nghiệp\" trong tiếng Việt. Là động từ ly hợp: 毕了业.","ex":"毕业以后你有什么打算？","exPy":"Bìyè yǐhòu nǐ yǒu shénme dǎsuàn?","exVi":"Tốt nghiệp xong bạn dự định gì?","w":"毕业 以后 你 有 什么 打算？"},{"zh":"报名","py":"bàomíng","vi":"đăng ký, ghi danh","hv":"báo danh","note":"Chính là \"báo danh\" tiếng Việt: 报 (báo) + 名 (danh). Động từ ly hợp: 报了名.","ex":"报名时间只有三天。","exPy":"Bàomíng shíjiān zhǐ yǒu sān tiān.","exVi":"Thời gian đăng ký chỉ có ba ngày.","w":"报名 时间 只有 三 天。"},{"zh":"申请","py":"shēnqǐng","vi":"xin, nộp đơn","hv":"thân thỉnh","note":"申 (trình bày) + 请 (xin). Dùng cho việc chính thức: 申请签证, 申请奖学金.","ex":"他申请了中国的奖学金。","exPy":"Tā shēnqǐng le Zhōngguó de jiǎngxuéjīn.","exVi":"Cậu ấy xin học bổng của Trung Quốc.","w":"他 申请 了 中国 的 奖学金。"},{"zh":"寒假","py":"hánjià","vi":"nghỉ đông, nghỉ Tết","hv":"hàn giả","note":"寒 (lạnh) + 假 (nghỉ, đọc jià). Ở Trung Quốc nghỉ đông trùng dịp Tết Nguyên Đán.","ex":"寒假一般有一个月。","exPy":"Hánjià yìbān yǒu yí ge yuè.","exVi":"Nghỉ đông thường được một tháng.","w":"寒假 一般 有 一 个 月。"},{"zh":"放暑假","py":"fàng shǔjià","vi":"nghỉ hè","hv":"phóng thử giả","note":"放 (thả, bài 60) + 暑 (nắng nóng) + 假 (nghỉ). 放假 = được nghỉ; 暑假 = kỳ nghỉ hè.","ex":"放暑假我打算去打工。","exPy":"Fàng shǔjià wǒ dǎsuàn qù dǎgōng.","exVi":"Nghỉ hè tôi định đi làm thêm.","w":"放暑假 我 打算 去 打工。"}],"newChars":["硕","士","博","授","毕","申","寒","暑"],"outro":"很好！Xong bài 109."};
G.ROOMS["zh-l110"] = {"id":"zh-l110","lang":"zh","level":4,"no":110,"teacher":"wang","title":"HSK4 · Bài 110 · 作业和考试 Bài vở và kiểm tra","intro":["老师让我们回家预习第五课。","Bài 110: Từ vựng phòng thi: đề bài, đáp án, chuẩn mực, chứng minh. Bấm 1 · Học để bắt đầu."],"introPy":"Lǎoshī ràng wǒmen huí jiā yùxí dì-wǔ kè.","gram":{"t":"预 — tiền tố \"trước\"","b":"预习 · 预报 · 预订 · 预计","d":"预 nghĩa là \"trước, dự\". Ghép vào trước động từ là ra nghĩa \"làm sẵn trước\": 预习 (học trước), 天气预报 (dự báo thời tiết), 预订房间 (đặt phòng trước).","ex":[["我预订了两个座位。","Tôi đã đặt trước hai chỗ.","Wǒ yùdìng le liǎng ge zuòwèi."],["天气预报说明天有雨。","Dự báo nói mai có mưa.","Tiānqì yùbào shuō míngtiān yǒu yǔ."]]},"grams":[{"t":"预 — tiền tố \"trước\"","b":"预习 · 预报 · 预订 · 预计","d":"预 nghĩa là \"trước, dự\". Ghép vào trước động từ là ra nghĩa \"làm sẵn trước\": 预习 (học trước), 天气预报 (dự báo thời tiết), 预订房间 (đặt phòng trước).","ex":[["我预订了两个座位。","Tôi đã đặt trước hai chỗ.","Wǒ yùdìng le liǎng ge zuòwèi."],["天气预报说明天有雨。","Dự báo nói mai có mưa.","Tiānqì yùbào shuō míngtiān yǒu yǔ."]]},{"t":"Bốn kỹ năng trong bài thi HSK","b":"听力 · 阅读 · 书写 · 口语","d":"听力 (nghe), 阅读 (đọc), 书写 (viết), 口语 (nói). Bài thi HSK 4 gồm ba phần đầu. Biết tên bốn kỹ năng giúp bạn đọc hiểu đề thi và tài liệu ôn.","ex":[["我的听力比阅读好。","Nghe của tôi tốt hơn đọc.","Wǒ de tīnglì bǐ yuèdú hǎo."]]},{"t":"错 và 错误 — khẩu ngữ và văn viết","b":"错 (tính từ, khẩu ngữ) · 错误 (danh từ, trang trọng)","d":"我写错了 (tôi viết sai — dùng 错). 这是一个错误 (đây là một lỗi — dùng 错误 làm danh từ). Cặp này minh hoạ quy luật chung: từ một âm thiên khẩu ngữ, từ hai âm thiên văn viết.","ex":[["你说错了。","Bạn nói sai rồi.","Nǐ shuō cuò le."],["请改正这些错误。","Xin sửa những lỗi này.","Qǐng gǎizhèng zhèxiē cuòwù."]]}],"items":[{"zh":"预习","py":"yùxí","vi":"chuẩn bị bài trước","hv":"dự tập","note":"预 = \"dự\" trong \"dự báo\", \"dự đoán\". Cặp với 复习 (ôn lại, bài 36): học trước và học lại.","ex":"老师让我们回家预习第五课。","exPy":"Lǎoshī ràng wǒmen huí jiā yùxí dì-wǔ kè.","exVi":"Thầy bảo về nhà chuẩn bị bài 5.","w":"老师 让 我们 回 家 预习 第 五 课。"},{"zh":"阅读","py":"yuèdú","vi":"đọc hiểu","hv":"duyệt độc","note":"阅 = \"duyệt\" trong \"duyệt binh\", \"kiểm duyệt\". Trang trọng hơn 看书 — là kỹ năng đọc hiểu trong thi cử.","ex":"多阅读能提高词汇量。","exPy":"Duō yuèdú néng tígāo cíhuìliàng.","exVi":"Đọc nhiều giúp tăng vốn từ.","w":"多 阅读 能 提高 词汇 量。"},{"zh":"语法","py":"yǔfǎ","vi":"ngữ pháp","hv":"ngữ pháp","note":"Chính là \"ngữ pháp\" tiếng Việt: 语 (ngữ) + 法 (pháp).","ex":"这个语法点我还不太懂。","exPy":"Zhège yǔfǎ diǎn wǒ hái bú tài dǒng.","exVi":"Điểm ngữ pháp này tôi vẫn chưa hiểu lắm.","w":"这个 语法 点 我 还 不 太 懂。"},{"zh":"试卷","py":"shìjuàn","vi":"bài thi, đề thi","hv":"thí quyển","note":"试 (thi, bài 45) + 卷 (cuộn giấy). Nghĩa đen: tờ giấy thi.","ex":"试卷一共有五十道题。","exPy":"Shìjuàn yígòng yǒu wǔshí dào tí.","exVi":"Đề thi tất cả năm mươi câu.","w":"试卷 一共 有 五 十 道 题。"},{"zh":"填空","py":"tiánkòng","vi":"điền vào chỗ trống","hv":"điền không","note":"填 (điền vào) + 空 (chỗ trống). Tiếng Việt cũng nói \"điền vào chỗ trống\" — dịch sát từng chữ.","ex":"填空题最容易丢分。","exPy":"Tiánkòng tí zuì róngyì diū fēn.","exVi":"Câu điền khuyết dễ mất điểm nhất.","w":"填空 题 最 容易 丢 分。"},{"zh":"答案","py":"dá'àn","vi":"đáp án","hv":"đáp án","note":"Chính là \"đáp án\" tiếng Việt: 答 (đáp, bài 37 trong 回答) + 案 (án).","ex":"做完以后请对一下答案。","exPy":"Zuò wán yǐhòu qǐng duì yíxià dá'àn.","exVi":"Làm xong rồi xin đối chiếu đáp án.","w":"做 完 以后 请 对 一下 答案。"},{"zh":"错误","py":"cuòwù","vi":"sai lầm, lỗi","hv":"thác ngộ","note":"错 (sai, bài 30) + 误 (nhầm, bài 106 trong 误会). Trang trọng hơn 错 dùng một mình.","ex":"从错误中学习最有效。","exPy":"Cóng cuòwù zhōng xuéxí zuì yǒuxiào.","exVi":"Học từ sai lầm là hiệu quả nhất.","w":"从 错误 中学 习 最 有效。"},{"zh":"标准","py":"biāozhǔn","vi":"tiêu chuẩn; chuẩn","hv":"tiêu chuẩn","note":"Chính là \"tiêu chuẩn\" tiếng Việt: 标 (tiêu) + 准 (chuẩn). Khen phát âm: 你的发音很标准.","ex":"他的普通话非常标准。","exPy":"Tā de pǔtōnghuà fēicháng biāozhǔn.","exVi":"Tiếng phổ thông của anh ấy cực chuẩn.","w":"他 的 普通话 非常 标准。"},{"zh":"合格","py":"hégé","vi":"đạt yêu cầu, đủ tiêu chuẩn","hv":"hợp cách","note":"合 (hợp) + 格 (cách, quy cách). Tiếng Việt: \"hợp cách\", \"đủ tư cách\". Thi đạt là 考试合格.","ex":"六十分以上才算合格。","exPy":"Liùshí fēn yǐshàng cái suàn hégé.","exVi":"Từ sáu mươi điểm trở lên mới coi là đạt.","w":"六 十分 以上 才 算 合格。"},{"zh":"证明","py":"zhèngmíng","vi":"chứng minh; giấy chứng nhận","hv":"chứng minh","note":"Chính là \"chứng minh\" tiếng Việt: 证 (chứng) + 明 (minh). Cũng là danh từ: 学生证明 (giấy xác nhận sinh viên).","ex":"请出示您的身份证明。","exPy":"Qǐng chūshì nín de shēnfèn zhèngmíng.","exVi":"Xin xuất trình giấy tờ tuỳ thân.","w":"请 出示 您 的 身份证 明。"}],"newChars":["预","阅","卷","填","案","标","证"],"outro":"很好！Xong bài 110."};
G.ROOMS["zh-l111"] = {"id":"zh-l111","lang":"zh","level":4,"no":111,"teacher":"wang","title":"HSK4 · Bài 111 · 知识和研究 Kiến thức và nghiên cứu","intro":["学好语法是打好基础的关键。","Bài 111: Bộ động từ tư duy học thuật — nền tảng để đọc bài viết tiếng Trung. Bấm 1 · Học để bắt đầu."],"introPy":"Xué hǎo yǔfǎ shì dǎ hǎo jīchǔ de guānjiàn.","gram":{"t":"Cả bài là mười từ Hán Việt trùng khít","b":"基础 · 经验 · 理解 · 研究 · 讨论 · 解释 · 说明 · 总结 · 内容 · 文章","d":"Đây là bài có mật độ Hán Việt cao nhất toàn giáo trình — MƯỜI TRÊN MƯỜI. Lớp từ học thuật của tiếng Việt gần như mượn nguyên khối từ chữ Hán, nên người Việt đọc văn bản chính luận tiếng Trung dễ hơn nghe hội thoại đời thường.","ex":[["基础 · 经验 · 理解","cơ sở · kinh nghiệm · lý giải","jīchǔ · jīngyàn · lǐjiě"],["研究 · 讨论 · 总结","nghiên cứu · thảo luận · tổng kết","yánjiū · tǎolùn · zǒngjié"]]},"grams":[{"t":"Cả bài là mười từ Hán Việt trùng khít","b":"基础 · 经验 · 理解 · 研究 · 讨论 · 解释 · 说明 · 总结 · 内容 · 文章","d":"Đây là bài có mật độ Hán Việt cao nhất toàn giáo trình — MƯỜI TRÊN MƯỜI. Lớp từ học thuật của tiếng Việt gần như mượn nguyên khối từ chữ Hán, nên người Việt đọc văn bản chính luận tiếng Trung dễ hơn nghe hội thoại đời thường.","ex":[["基础 · 经验 · 理解","cơ sở · kinh nghiệm · lý giải","jīchǔ · jīngyàn · lǐjiě"],["研究 · 讨论 · 总结","nghiên cứu · thảo luận · tổng kết","yánjiū · tǎolùn · zǒngjié"]]},{"t":"Lượng từ 篇 cho bài viết","b":"一篇文章 · 一篇日记 · 一篇论文","d":"篇 (bài 100) dùng riêng cho văn bản thành bài. Sách dùng 本, tờ giấy dùng 张, còn bài viết dùng 篇. Tiếng Việt cũng nói \"một bài văn\", \"một thiên truyện\".","ex":[["我写了一篇日记。","Tôi viết một bài nhật ký.","Wǒ xiě le yì piān rìjì."]]},{"t":"解释 và 说明 — giải thích hay trình bày?","b":"解释 = làm cho hiểu điều khó · 说明 = trình bày rõ sự việc","d":"解释 dùng khi có điều khó hiểu hoặc hiểu lầm cần gỡ. 说明 trung tính hơn, là trình bày thông tin. 说明书 (sách hướng dẫn) không bao giờ gọi là 解释书.","ex":[["他解释了迟到的原因。","Anh ấy giải thích lý do đến muộn.","Tā jiěshì le chídào de yuányīn."],["这说明他很努力。","Điều này cho thấy cậu ấy rất cố gắng.","Zhè shuōmíng tā hěn nǔlì."]]}],"items":[{"zh":"基础","py":"jīchǔ","vi":"cơ sở, nền tảng","hv":"cơ sở","note":"Chính là \"cơ sở\" tiếng Việt: 基 (cơ) + 础 (sở, đá tảng chân cột). Nghĩa đen: nền móng.","ex":"学好语法是打好基础的关键。","exPy":"Xué hǎo yǔfǎ shì dǎ hǎo jīchǔ de guānjiàn.","exVi":"Học chắc ngữ pháp là mấu chốt để có nền tảng tốt.","w":"学 好 语法 是 打 好 基础 的 关键。"},{"zh":"经验","py":"jīngyàn","vi":"kinh nghiệm","hv":"kinh nghiệm","note":"Chính là \"kinh nghiệm\" tiếng Việt: 经 (kinh, trải qua) + 验 (nghiệm).","ex":"这份工作需要三年以上的经验。","exPy":"Zhè fèn gōngzuò xūyào sān nián yǐshàng de jīngyàn.","exVi":"Công việc này cần trên ba năm kinh nghiệm.","w":"这 份 工作 需要 三 年 以上 的 经验。"},{"zh":"理解","py":"lǐjiě","vi":"hiểu, lĩnh hội","hv":"lý giải","note":"Chính là \"lý giải\" tiếng Việt: 理 (lý) + 解 (giải). Sâu hơn 明白 — là hiểu được cái lý bên trong.","ex":"谢谢你的理解和支持。","exPy":"Xièxie nǐ de lǐjiě hé zhīchí.","exVi":"Cảm ơn sự thấu hiểu và ủng hộ của bạn.","w":"谢谢 你 的 理解 和 支持。"},{"zh":"研究","py":"yánjiū","vi":"nghiên cứu","hv":"nghiên cứu","note":"Chính là \"nghiên cứu\" tiếng Việt: 研 (nghiên, mài) + 究 (cứu, xét tận cùng).","ex":"他花了十年研究这个问题。","exPy":"Tā huā le shí nián yánjiū zhège wèntí.","exVi":"Anh ấy dành mười năm nghiên cứu vấn đề này.","w":"他 花 了 十 年 研究 这个 问题。"},{"zh":"讨论","py":"tǎolùn","vi":"thảo luận","hv":"thảo luận","note":"Chính là \"thảo luận\" tiếng Việt: 讨 (thảo) + 论 (luận). Cả hai chữ đều có bộ 讠 (lời nói).","ex":"这个问题值得好好讨论。","exPy":"Zhège wèntí zhíde hǎohǎo tǎolùn.","exVi":"Vấn đề này đáng để thảo luận kỹ.","w":"这个 问题 值得 好好 讨论。"},{"zh":"解释","py":"jiěshì","vi":"giải thích","hv":"giải thích","note":"Chính là \"giải thích\" tiếng Việt: 解 (giải) + 释 (thích).","ex":"能不能再解释一遍？","exPy":"Néng bu néng zài jiěshì yí biàn?","exVi":"Có thể giải thích lại một lần nữa không?","w":"能 不 能 再 解释 一 遍？"},{"zh":"说明","py":"shuōmíng","vi":"thuyết minh, nói rõ","hv":"thuyết minh","note":"Chính là \"thuyết minh\" tiếng Việt: 说 (thuyết) + 明 (minh). 说明书 = bản hướng dẫn sử dụng.","ex":"使用前请仔细阅读说明书。","exPy":"Shǐyòng qián qǐng zǐxì yuèdú shuōmíngshū.","exVi":"Trước khi dùng xin đọc kỹ hướng dẫn.","w":"使用 前 请 仔细 阅读 说明书。"},{"zh":"总结","py":"zǒngjié","vi":"tổng kết","hv":"tổng kết","note":"Chính là \"tổng kết\" tiếng Việt: 总 (tổng) + 结 (kết).","ex":"每个学期末都要写总结。","exPy":"Měi ge xuéqī mò dōu yào xiě zǒngjié.","exVi":"Cuối mỗi học kỳ đều phải viết tổng kết.","w":"每 个 学期 末 都 要 写 总结。"},{"zh":"内容","py":"nèiróng","vi":"nội dung","hv":"nội dung","note":"Chính là \"nội dung\" tiếng Việt: 内 (nội, trong) + 容 (dung, chứa).","ex":"这本书的内容对我很有用。","exPy":"Zhè běn shū de nèiróng duì wǒ hěn yǒuyòng.","exVi":"Nội dung sách này rất hữu ích với tôi.","w":"这 本 书 的 内容 对 我 很 有用。"},{"zh":"文章","py":"wénzhāng","vi":"bài viết, bài văn","hv":"văn chương","note":"Chính là \"văn chương\" tiếng Việt, nhưng tiếng Trung dùng cho MỌI bài viết, kể cả bài báo — không chỉ văn nghệ thuật.","ex":"我在报纸上读到一篇好文章。","exPy":"Wǒ zài bàozhǐ shàng dú dào yì piān hǎo wénzhāng.","exVi":"Tôi đọc được một bài hay trên báo.","w":"我 在 报纸 上 读 到 一 篇 好 文章。"}],"newChars":["基","础","验","研","究","释","章"],"outro":"很好！Xong bài 111."};
G.ROOMS["zh-l112"] = {"id":"zh-l112","lang":"zh","level":4,"no":112,"teacher":"wang","title":"HSK4 · Bài 112 · 科技和网络 Khoa học và mạng","intro":["科学技术改变了我们的生活。","Bài 112: Từ vựng công nghệ — thấy rõ cách tiếng Trung ghép chữ cũ để đặt tên thứ mới. Bấm 1 · Học để bắt đầu."],"introPy":"Kēxué jìshù gǎibiàn le wǒmen de shēnghuó.","gram":{"t":"Tiếng Trung DỊCH NGHĨA thay vì mượn âm","b":"互联网 · 网站 · 传真 · 电脑 · 手机","d":"Internet → 互联网 (lưới nối nhau), website → 网站 (trạm mạng), fax → 传真 (truyền hình thật), computer → 电脑 (não điện). Nhờ vậy người biết chữ Hán đoán được nghĩa từ mới. Tiếng Việt thì mượn âm nhiều hơn (in-tơ-nét, fax) nên mất lợi thế này.","ex":[["网站 = 网 + 站","mạng + trạm","wǎngzhàn"],["打印机 = 打印 + 机","in + máy = máy in","dǎyìnjī"]]},"grams":[{"t":"Tiếng Trung DỊCH NGHĨA thay vì mượn âm","b":"互联网 · 网站 · 传真 · 电脑 · 手机","d":"Internet → 互联网 (lưới nối nhau), website → 网站 (trạm mạng), fax → 传真 (truyền hình thật), computer → 电脑 (não điện). Nhờ vậy người biết chữ Hán đoán được nghĩa từ mới. Tiếng Việt thì mượn âm nhiều hơn (in-tơ-nét, fax) nên mất lợi thế này.","ex":[["网站 = 网 + 站","mạng + trạm","wǎngzhàn"],["打印机 = 打印 + 机","in + máy = máy in","dǎyìnjī"]]},{"t":"复印 và 打印 — hai kiểu \"in\"","b":"复印 = chụp lại bản giấy · 打印 = in từ máy tính","d":"Đưa tờ giấy vào máy photo là 复印. Bấm nút in từ file trên máy tính là 打印. Máy tương ứng là 复印机 và 打印机.","ex":[["请把护照复印一份。","Xin photo hộ chiếu một bản.","Qǐng bǎ hùzhào fùyìn yí fèn."],["文件已经打印好了。","Tài liệu đã in xong rồi.","Wénjiàn yǐjīng dǎyìn hǎo le."]]},{"t":"发 — động từ \"gửi đi\" của thời đại số","b":"发短信 · 发邮件 · 发消息 · 发照片","d":"发 fā nghĩa là phát ra, gửi đi. Đây là động từ bạn dùng nhiều nhất khi nhắn tin với bạn Trung Quốc.","ex":[["我给你发了三条短信。","Tôi đã nhắn cho bạn ba tin.","Wǒ gěi nǐ fā le sān tiáo duǎnxìn."],["照片我发到你邮箱了。","Ảnh tôi gửi vào hòm thư bạn rồi.","Zhàopiàn wǒ fā dào nǐ yóuxiāng le."]]}],"items":[{"zh":"科学","py":"kēxué","vi":"khoa học","hv":"khoa học","note":"Chính là \"khoa học\" tiếng Việt: 科 (khoa) + 学 (học). Cũng là tính từ: 这个方法很科学.","ex":"科学技术改变了我们的生活。","exPy":"Kēxué jìshù gǎibiàn le wǒmen de shēnghuó.","exVi":"Khoa học kỹ thuật đã thay đổi cuộc sống chúng ta.","w":"科学 技术 改变 了 我们 的 生活。"},{"zh":"技术","py":"jìshù","vi":"kỹ thuật","hv":"kỹ thuật","note":"Chính là \"kỹ thuật\" tiếng Việt: 技 (kỹ, bộ 扌) + 术 (thuật).","ex":"他在一家技术公司工作。","exPy":"Tā zài yì jiā jìshù gōngsī gōngzuò.","exVi":"Anh ấy làm ở một công ty công nghệ.","w":"他 在 一 家 技术 公司 工作。"},{"zh":"机器","py":"jīqì","vi":"cỗ máy","hv":"cơ khí","note":"Âm Hán Việt là \"cơ khí\" nhưng nghĩa là CÁI MÁY cụ thể. 机 cũng nằm trong 飞机, 手机, 机会.","ex":"这家工厂的机器都很新。","exPy":"Zhè jiā gōngchǎng de jīqì dōu hěn xīn.","exVi":"Máy móc nhà máy này đều rất mới.","w":"这 家 工厂 的 机器 都 很 新。"},{"zh":"互联网","py":"hùliánwǎng","vi":"Internet","hv":"hỗ liên võng","note":"互 (lẫn nhau) + 联 (nối) + 网 (lưới) = \"lưới nối lẫn nhau\". Dịch nghĩa chứ không mượn âm — rất đúng bản chất Internet.","ex":"没有互联网我真受不了。","exPy":"Méiyǒu hùliánwǎng wǒ zhēn shòu bu liǎo.","exVi":"Không có Internet tôi chịu không nổi.","w":"没有 互联网 我 真 受不了。"},{"zh":"网站","py":"wǎngzhàn","vi":"trang web","hv":"võng trạm","note":"网 (lưới, mạng) + 站 (trạm, bài 41) = \"trạm trên mạng\". Cách ghép rất gọn.","ex":"学校网站上有考试安排。","exPy":"Xuéxiào wǎngzhàn shàng yǒu kǎoshì ānpái.","exVi":"Trên web trường có lịch thi.","w":"学校 网站 上 有 考试 安排。"},{"zh":"密码","py":"mìmǎ","vi":"mật khẩu","hv":"mật mã","note":"Chính là \"mật mã\" tiếng Việt: 密 (mật) + 码 (mã).","ex":"密码最好不要太简单。","exPy":"Mìmǎ zuì hǎo búyào tài jiǎndān.","exVi":"Mật khẩu tốt nhất đừng quá đơn giản.","w":"密码 最好 不要 太 简单。"},{"zh":"短信","py":"duǎnxìn","vi":"tin nhắn","hv":"đoản tín","note":"短 (ngắn, bài 52) + 信 (thư tín) = \"thư ngắn\". Gửi tin nhắn là 发短信.","ex":"到了给我发个短信。","exPy":"Dào le gěi wǒ fā ge duǎnxìn.","exVi":"Tới nơi nhắn tin cho tôi.","w":"到 了 给 我 发 个 短信。"},{"zh":"传真","py":"chuánzhēn","vi":"máy fax, bản fax","hv":"truyền chân","note":"传 (truyền) + 真 (thật) — truyền hình ảnh thật đi xa. Lại là dịch nghĩa thay vì mượn âm \"fax\".","ex":"现在很少有人用传真了。","exPy":"Xiànzài hěn shǎo yǒu rén yòng chuánzhēn le.","exVi":"Bây giờ ít người dùng fax rồi.","w":"现在 很 少 有 人 用 传真 了。"},{"zh":"复印","py":"fùyìn","vi":"photo, sao chụp","hv":"phức ấn","note":"复 ở đây là chữ 複 (phức, nhân ra nhiều bản, như \"phức tạp\") + 印 (in). Nghĩa đen: in ra thêm bản. Khác 复 trong 复习 (bài 36), vốn là chữ 復 (phục, làm lại).","ex":"办签证要复印护照。","exPy":"Bàn qiānzhèng yào fùyìn hùzhào.","exVi":"Làm visa phải photo hộ chiếu.","w":"办 签证 要 复印 护照。"},{"zh":"打印","py":"dǎyìn","vi":"in (từ máy tính)","hv":"đả ấn","note":"打 (làm) + 印 (in). Khác 复印: 打印 là in từ máy tính ra, 复印 là chụp lại bản đã có.","ex":"打印机没纸了。","exPy":"Dǎyìnjī méi zhǐ le.","exVi":"Máy in hết giấy rồi.","w":"打印机 没 纸 了。"}],"newChars":["科","技","器","密","码","传"],"outro":"很好！Xong bài 112."};
G.ROOMS["zh-l113"] = {"id":"zh-l113","lang":"zh","level":4,"no":113,"teacher":"wang","title":"HSK4 · Bài 113 · 各种职业 Nghề nghiệp","intro":["遇到法律问题最好找律师。","Bài 113: Gọi tên nghề nghiệp và hiểu ba đuôi tạo tên nghề trong tiếng Trung. Bấm 1 · Học để bắt đầu."],"introPy":"Yù dào fǎlǜ wèntí zuì hǎo zhǎo lǜshī.","gram":{"t":"Ba đuôi tạo tên nghề: 员 · 者 · 家","b":"员 = nhân viên · 者 = người làm · 家 = chuyên gia","d":"服务员, 售货员, 演员 (nhân viên). 记者, 作者, 读者 (người làm việc đó). 作家, 画家, 音乐家, 科学家 (bậc chuyên gia). Tiếng Việt cũng có \"viên\", \"giả\", \"gia\" — cùng ba đuôi này. Biết quy luật là đoán được hàng chục nghề.","ex":[["运动员 · 服务员","vận động viên · phục vụ viên","yùndòngyuán · fúwùyuán"],["记者 · 作者 · 读者","ký giả · tác giả · độc giả","jìzhě · zuòzhě · dúzhě"],["作家 · 画家 · 科学家","tác gia · hoạ gia · khoa học gia","zuòjiā · huàjiā · kēxuéjiā"]]},"grams":[{"t":"Ba đuôi tạo tên nghề: 员 · 者 · 家","b":"员 = nhân viên · 者 = người làm · 家 = chuyên gia","d":"服务员, 售货员, 演员 (nhân viên). 记者, 作者, 读者 (người làm việc đó). 作家, 画家, 音乐家, 科学家 (bậc chuyên gia). Tiếng Việt cũng có \"viên\", \"giả\", \"gia\" — cùng ba đuôi này. Biết quy luật là đoán được hàng chục nghề.","ex":[["运动员 · 服务员","vận động viên · phục vụ viên","yùndòngyuán · fúwùyuán"],["记者 · 作者 · 读者","ký giả · tác giả · độc giả","jìzhě · zuòzhě · dúzhě"],["作家 · 画家 · 科学家","tác gia · hoạ gia · khoa học gia","zuòjiā · huàjiā · kēxuéjiā"]]},{"t":"师傅 — cách gọi lịch sự người lao động","b":"师傅 + câu hỏi","d":"Gọi tài xế taxi, thợ sửa xe, bảo vệ đều dùng 师傅 — vừa lịch sự vừa thân thiện, không phân biệt tuổi. Tương đương \"bác\", \"chú\" khi người Việt gọi bác tài.","ex":[["师傅，请问洗手间在哪儿？","Bác ơi, cho hỏi nhà vệ sinh ở đâu?","Shīfu, qǐngwèn xǐshǒujiān zài nǎr?"]]},{"t":"医生 và 大夫 — cùng nghĩa, khác giọng","b":"医生 (chung, văn viết) · 大夫 dàifu (khẩu ngữ, miền Bắc)","d":"Hai từ hoàn toàn đồng nghĩa. 大夫 nghe gần gũi hơn và rất phổ biến ở Bắc Kinh. Nhớ đọc là dàifu chứ không phải dàfū — đọc sai nghĩa thành \"quan đại phu\" thời cổ.","ex":[["我要去看大夫。","Tôi phải đi khám bác sĩ.","Wǒ yào qù kàn dàifu."]]}],"items":[{"zh":"律师","py":"lǜshī","vi":"luật sư","hv":"luật sư","note":"Chính là \"luật sư\" tiếng Việt: 律 (luật) + 师 (sư).","ex":"遇到法律问题最好找律师。","exPy":"Yù dào fǎlǜ wèntí zuì hǎo zhǎo lǜshī.","exVi":"Gặp vấn đề pháp lý tốt nhất tìm luật sư.","w":"遇到 法律 问题 最好 找 律师。"},{"zh":"护士","py":"hùshi","vi":"y tá, điều dưỡng","hv":"hộ sĩ","note":"护 (bảo hộ, bài 68) + 士 (sĩ). Nghĩa đen: người chăm sóc. Đuôi 士 giống 硕士, 博士.","ex":"医院里的护士都很忙。","exPy":"Yīyuàn lǐ de hùshi dōu hěn máng.","exVi":"Y tá trong bệnh viện đều rất bận.","w":"医院 里 的 护士 都 很 忙。"},{"zh":"记者","py":"jìzhě","vi":"nhà báo, phóng viên","hv":"ký giả","note":"Chính là \"ký giả\" tiếng Việt: 记 (ghi) + 者 (người). Đuôi 者 như 作者 (bài 58).","ex":"他从大学毕业后当了记者。","exPy":"Tā cóng dàxué bìyè hòu dāng le jìzhě.","exVi":"Tốt nghiệp đại học xong anh ấy làm phóng viên.","w":"他 从 大学 毕业 后 当 了 记者。"},{"zh":"售货员","py":"shòuhuòyuán","vi":"nhân viên bán hàng","hv":"thụ hoá viên","note":"售 (bán) + 货 (hàng) + 员 (viên). Đuôi 员 như 服务员 (bài 29), 演员.","ex":"请问售货员，这个多少钱？","exPy":"Qǐngwèn shòuhuòyuán, zhège duōshao qián?","exVi":"Xin hỏi nhân viên, cái này bao nhiêu tiền?","w":"请问 售货员， 这个 多少 钱？"},{"zh":"师傅","py":"shīfu","vi":"bác tài, thợ, sư phụ","hv":"sư phó","note":"Cách gọi lịch sự dành cho người lao động có tay nghề: tài xế, thợ sửa, đầu bếp. Gọi bác tài taxi là 师傅.","ex":"师傅，麻烦开快一点儿。","exPy":"Shīfu, máfan kāi kuài yìdiǎnr.","exVi":"Bác tài, làm ơn chạy nhanh chút.","w":"师傅， 麻烦 开 快 一点儿。"},{"zh":"大夫","py":"dàifu","vi":"bác sĩ (khẩu ngữ)","hv":"đại phu","note":"Chính là \"đại phu\" trong truyện cổ tiếng Việt. Chú ý đọc dàifu, KHÔNG phải dàfū. Đồng nghĩa 医生 nhưng thân mật hơn.","ex":"大夫，我最近总是咳嗽。","exPy":"Dàifu, wǒ zuìjìn zǒngshì késou.","exVi":"Bác sĩ ơi, dạo này tôi ho suốt.","w":"大夫， 我 最近 总是 咳嗽。"},{"zh":"导游","py":"dǎoyóu","vi":"hướng dẫn viên du lịch","hv":"đạo du","note":"导 (dẫn dắt) + 游 (đi chơi, bài 49 trong 游戏). Tiếng Việt: \"đạo diễn\", \"chỉ đạo\" cùng chữ 导.","ex":"我们的导游会说三种语言。","exPy":"Wǒmen de dǎoyóu huì shuō sān zhǒng yǔyán.","exVi":"Hướng dẫn viên của chúng tôi nói được ba thứ tiếng.","w":"我们 的 导游 会 说 三 种 语言。"},{"zh":"演员","py":"yǎnyuán","vi":"diễn viên","hv":"diễn viên","note":"Chính là \"diễn viên\" tiếng Việt: 演 (diễn) + 员 (viên).","ex":"这部电影的演员都很有名。","exPy":"Zhè bù diànyǐng de yǎnyuán dōu hěn yǒumíng.","exVi":"Diễn viên phim này đều nổi tiếng.","w":"这 部 电影 的 演员 都 很 有名。"},{"zh":"作家","py":"zuòjiā","vi":"nhà văn","hv":"tác gia","note":"Chính là \"tác gia\" tiếng Việt: 作 (sáng tác) + 家 (nhà). Đuôi 家 chỉ chuyên gia: 画家, 音乐家, 科学家.","ex":"这位作家写了二十多本小说。","exPy":"Zhè wèi zuòjiā xiě le èrshí duō běn xiǎoshuō.","exVi":"Nhà văn này viết hơn hai mươi cuốn tiểu thuyết.","w":"这 位 作家 写 了 二 十 多 本 小说。"},{"zh":"教育","py":"jiàoyù","vi":"giáo dục","hv":"giáo dục","note":"Chính là \"giáo dục\" tiếng Việt: 教 (giáo, bài 37) + 育 (dục, nuôi dạy).","ex":"父母的教育对孩子影响很大。","exPy":"Fùmǔ de jiàoyù duì háizi yǐngxiǎng hěn dà.","exVi":"Giáo dục của cha mẹ ảnh hưởng lớn tới con.","w":"父母 的 教育 对 孩子 影响 很 大。"}],"newChars":["售","货","傅","导"],"outro":"很好！Xong bài 113."};
G.ROOMS["zh-l114"] = {"id":"zh-l114","lang":"zh","level":4,"no":114,"teacher":"wang","title":"HSK4 · Bài 114 · 找工作和上班 Xin việc và đi làm","intro":["我下周去应聘，有点儿紧张。","Bài 114: Toàn bộ vòng đời một công việc: ứng tuyển, lương thưởng, áp lực, quản lý. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xià zhōu qù yìngpìn, yǒudiǎnr jǐnzhāng.","gram":{"t":"应聘 và 招聘 — hai đầu của một việc","b":"应聘 = phía người xin việc · 招聘 = phía công ty tuyển","d":"Cả hai đều chứa 聘 (mời làm việc). Nhìn chữ đầu mà phân biệt: 应 là ĐÁP LẠI lời mời (ứng viên), 招 là VẪY GỌI (nhà tuyển dụng). Bảng tin việc làm ghi 招聘启事.","ex":[["他去应聘销售的工作。","Anh ấy đi ứng tuyển vị trí bán hàng.","Tā qù yìngpìn xiāoshòu de gōngzuò."],["我们公司在招聘新人。","Công ty chúng tôi đang tuyển người mới.","Wǒmen gōngsī zài zhāopìn xīnrén."]]},"grams":[{"t":"应聘 và 招聘 — hai đầu của một việc","b":"应聘 = phía người xin việc · 招聘 = phía công ty tuyển","d":"Cả hai đều chứa 聘 (mời làm việc). Nhìn chữ đầu mà phân biệt: 应 là ĐÁP LẠI lời mời (ứng viên), 招 là VẪY GỌI (nhà tuyển dụng). Bảng tin việc làm ghi 招聘启事.","ex":[["他去应聘销售的工作。","Anh ấy đi ứng tuyển vị trí bán hàng.","Tā qù yìngpìn xiāoshòu de gōngzuò."],["我们公司在招聘新人。","Công ty chúng tôi đang tuyển người mới.","Wǒmen gōngsī zài zhāopìn xīnrén."]]},{"t":"Động từ ly hợp nơi công sở","b":"加班 · 出差 · 上班 · 请假 · 帮忙","d":"Muốn thêm thời lượng phải chèn vào GIỮA: 加了两个小时班, 出了三天差. Đây là nhóm động từ ly hợp bạn dùng nhiều nhất khi đi làm.","ex":[["昨天我加了三个小时班。","Hôm qua tôi tăng ca ba tiếng.","Zuótiān wǒ jiā le sān ge xiǎoshí bān."],["他出了一个星期差。","Anh ấy đi công tác một tuần.","Tā chū le yí ge xīngqī chāi."]]},{"t":"压力大 / 能力强 — cặp danh từ + tính từ cố định","b":"压力大 · 能力强 · 责任重","d":"Một số danh từ trừu tượng đi với tính từ cố định. 压力 luôn dùng 大/小 (không dùng 多/少). 能力 dùng 强/弱. Học nguyên cụm sẽ nói tự nhiên hơn ghép rời.","ex":[["最近我压力很大。","Dạo này tôi áp lực lớn.","Zuìjìn wǒ yālì hěn dà."],["她的学习能力很强。","Khả năng học của cô ấy rất mạnh.","Tā de xuéxí nénglì hěn qiáng."]]}],"items":[{"zh":"应聘","py":"yìngpìn","vi":"ứng tuyển, xin việc","hv":"ứng sính","note":"应 (đáp lại) + 聘 (mời làm). Người XIN việc dùng 应聘; công ty TÌM người dùng 招聘.","ex":"我下周去应聘，有点儿紧张。","exPy":"Wǒ xià zhōu qù yìngpìn, yǒudiǎnr jǐnzhāng.","exVi":"Tuần sau tôi đi phỏng vấn, hơi hồi hộp.","w":"我 下 周 去 应聘， 有点儿 紧张。"},{"zh":"招聘","py":"zhāopìn","vi":"tuyển dụng","hv":"chiêu sính","note":"招 (vẫy gọi, bộ 扌) + 聘 (mời). Tiếng Việt: \"chiêu mộ\", \"chiêu sinh\".","ex":"网站上有很多招聘信息。","exPy":"Wǎngzhàn shàng yǒu hěn duō zhāopìn xìnxī.","exVi":"Trên web có nhiều thông tin tuyển dụng.","w":"网站 上 有 很 多 招聘 信息。"},{"zh":"工资","py":"gōngzī","vi":"tiền lương","hv":"công tư","note":"工 (công việc) + 资 (tiền của). Tiếng Việt: \"tư bản\", \"đầu tư\" cùng chữ 资.","ex":"每个月十号发工资。","exPy":"Měi ge yuè shí hào fā gōngzī.","exVi":"Mùng mười hàng tháng phát lương.","w":"每 个 月 十 号 发 工资。"},{"zh":"奖金","py":"jiǎngjīn","vi":"tiền thưởng","hv":"thưởng kim","note":"奖 (thưởng) + 金 (tiền vàng). Tiếng Việt: \"giải thưởng\", \"học bổng\" (奖学金).","ex":"今年的奖金比去年多。","exPy":"Jīnnián de jiǎngjīn bǐ qùnián duō.","exVi":"Thưởng năm nay nhiều hơn năm ngoái.","w":"今年 的 奖金 比 去年 多。"},{"zh":"加班","py":"jiābān","vi":"làm thêm giờ","hv":"gia ban","note":"加 (thêm) + 班 (ca làm, bài 36). Động từ ly hợp: 加了三个小时班.","ex":"今天我又要加班。","exPy":"Jīntiān wǒ yòu yào jiābān.","exVi":"Hôm nay tôi lại phải tăng ca.","w":"今天 我 又 要 加班。"},{"zh":"出差","py":"chūchāi","vi":"đi công tác","hv":"xuất sai","note":"出 (ra) + 差 (việc được phái đi — đọc chāi, khác 差 chà ở bài 54). Động từ ly hợp: 出了一个星期差.","ex":"经理经常出差，很少在办公室。","exPy":"Jīnglǐ jīngcháng chūchāi, hěn shǎo zài bàngōngshì.","exVi":"Giám đốc hay đi công tác, ít khi ở văn phòng.","w":"经理 经常 出差， 很 少 在 办公室。"},{"zh":"任务","py":"rènwu","vi":"nhiệm vụ","hv":"nhiệm vụ","note":"Chính là \"nhiệm vụ\" tiếng Việt: 任 (nhiệm) + 务 (vụ).","ex":"为了完成任务，我们加了三天班。","exPy":"Wèile wánchéng rènwu, wǒmen jiā le sān tiān bān.","exVi":"Để hoàn thành nhiệm vụ, chúng tôi tăng ca ba ngày.","w":"为了 完成 任务， 我们 加 了 三 天 班。"},{"zh":"能力","py":"nénglì","vi":"năng lực","hv":"năng lực","note":"Chính là \"năng lực\" tiếng Việt: 能 (năng, bài 8) + 力 (lực).","ex":"公司很重视员工的能力。","exPy":"Gōngsī hěn zhòngshì yuángōng de nénglì.","exVi":"Công ty rất coi trọng năng lực nhân viên.","w":"公司 很 重视 员工 的 能力。"},{"zh":"压力","py":"yālì","vi":"áp lực","hv":"áp lực","note":"Chính là \"áp lực\" tiếng Việt: 压 (áp, đè) + 力 (lực).","ex":"压力太大对身体不好。","exPy":"Yālì tài dà duì shēntǐ bù hǎo.","exVi":"Áp lực lớn quá không tốt cho sức khoẻ.","w":"压力 太 大 对 身体 不 好。"},{"zh":"管理","py":"guǎnlǐ","vi":"quản lý","hv":"quản lý","note":"Chính là \"quản lý\" tiếng Việt: 管 (quản, bộ 竹) + 理 (lý).","ex":"他学的是企业管理。","exPy":"Tā xué de shì qǐyè guǎnlǐ.","exVi":"Anh ấy học ngành quản trị doanh nghiệp.","w":"他 学 的 是 企业 管理。"}],"newChars":["聘","招","资","奖","金","压"],"outro":"很好！Xong bài 114."};
G.ROOMS["zh-l115"] = {"id":"zh-l115","lang":"zh","level":4,"no":115,"teacher":"wang","title":"HSK4 · Bài 115 · 钱的事 Chuyện tiền bạc","intro":["最近经济不太好，工作难找。","Bài 115: Nói về thu nhập, giá cả, thanh toán — và phân biệt 赚 / 挣 / 存. Bấm 1 · Học để bắt đầu."],"introPy":"Zuìjìn jīngjì bú tài hǎo, gōngzuò nán zhǎo.","gram":{"t":"打折 — con số ngược với tiếng Việt","b":"打八折 = bán 80% giá gốc = giảm 20%","d":"Đây là chỗ người Việt hay hiểu ngược và mua hớ. 打折 nêu TỶ LỆ CÒN PHẢI TRẢ, không phải tỷ lệ giảm. 打五折 = giảm nửa giá. 打九折 = giảm 10%. Nhớ: số càng NHỎ thì càng RẺ.","ex":[["全场打五折！","Toàn bộ giảm 50%!","Quán chǎng dǎ wǔ zhé!"],["打九折，便宜不了多少。","Giảm 10% thôi, chẳng rẻ được bao nhiêu.","Dǎ jiǔ zhé, piányi bu liǎo duōshao."]]},"grams":[{"t":"打折 — con số ngược với tiếng Việt","b":"打八折 = bán 80% giá gốc = giảm 20%","d":"Đây là chỗ người Việt hay hiểu ngược và mua hớ. 打折 nêu TỶ LỆ CÒN PHẢI TRẢ, không phải tỷ lệ giảm. 打五折 = giảm nửa giá. 打九折 = giảm 10%. Nhớ: số càng NHỎ thì càng RẺ.","ex":[["全场打五折！","Toàn bộ giảm 50%!","Quán chǎng dǎ wǔ zhé!"],["打九折，便宜不了多少。","Giảm 10% thôi, chẳng rẻ được bao nhiêu.","Dǎ jiǔ zhé, piányi bu liǎo duōshao."]]},{"t":"Bộ 贝 — nhìn là biết chữ về tiền","b":"赚 · 贵 · 买 · 费 · 账 · 贷","d":"Nhắc lại bài bộ thủ: 贝 vốn là vỏ sò, tiền tệ đầu tiên của Trung Quốc cổ. Chữ nào mang bộ này gần như chắc chắn liên quan tới tiền bạc, mua bán, giá trị.","ex":[["赚 · 贵 · 费","kiếm tiền · đắt · phí","zhuàn · guì · fèi"]]},{"t":"租 dùng được cả hai chiều","b":"我租房子 (tôi thuê) · 他把房子租给我 (anh ấy cho tôi thuê)","d":"Giống 借 (bài 42), chữ 租 không tự phân biệt chiều. Nhìn giới từ 给 hoặc ngữ cảnh mà đoán. Muốn rõ ràng thì dùng 出租 (cho thuê) và 租用 (đi thuê).","ex":[["这套房子出租吗？","Căn nhà này có cho thuê không?","Zhè tào fángzi chūzū ma?"]]}],"items":[{"zh":"经济","py":"jīngjì","vi":"kinh tế","hv":"kinh tế","note":"Chính là \"kinh tế\" tiếng Việt: 经 (kinh) + 济 (tế). Cũng là tính từ nghĩa \"tiết kiệm\": 很经济.","ex":"最近经济不太好，工作难找。","exPy":"Zuìjìn jīngjì bú tài hǎo, gōngzuò nán zhǎo.","exVi":"Dạo này kinh tế không tốt, việc khó tìm.","w":"最近 经济 不 太 好， 工作 难 找。"},{"zh":"收入","py":"shōurù","vi":"thu nhập","hv":"thu nhập","note":"Chính là \"thu nhập\" tiếng Việt: 收 (thu, bài 84) + 入 (nhập, vào).","ex":"他的收入比以前高了很多。","exPy":"Tā de shōurù bǐ yǐqián gāo le hěn duō.","exVi":"Thu nhập của anh ấy cao hơn trước nhiều.","w":"他 的 收入 比 以前 高 了 很 多。"},{"zh":"价格","py":"jiàgé","vi":"giá cả","hv":"giá cách","note":"价 (giá) + 格 (cách, mức). Trang trọng hơn 多少钱 — dùng trên bảng giá và trong đàm phán.","ex":"这两家店的价格差不多。","exPy":"Zhè liǎng jiā diàn de jiàgé chàbuduō.","exVi":"Giá hai cửa hàng này gần như nhau.","w":"这 两 家 店 的 价格 差不多。"},{"zh":"现金","py":"xiànjīn","vi":"tiền mặt","hv":"hiện kim","note":"Chính là \"hiện kim\" tiếng Việt: 现 (hiện) + 金 (kim, tiền). Đối lại với thẻ và ví điện tử.","ex":"现在很多店不收现金了。","exPy":"Xiànzài hěn duō diàn bù shōu xiànjīn le.","exVi":"Bây giờ nhiều cửa hàng không nhận tiền mặt nữa.","w":"现在 很 多 店 不 收 现金 了。"},{"zh":"付款","py":"fùkuǎn","vi":"thanh toán, trả tiền","hv":"phó khoản","note":"付 (trả) + 款 (khoản tiền). Tiếng Việt: \"khoản\", \"chi khoản\". Động từ ly hợp: 付了款.","ex":"可以用手机付款吗？","exPy":"Kěyǐ yòng shǒujī fùkuǎn ma?","exVi":"Có thể thanh toán bằng điện thoại không?","w":"可以 用 手机 付款 吗？"},{"zh":"打折","py":"dǎzhé","vi":"giảm giá","hv":"đả chiết","note":"QUAN TRỌNG: 打八折 nghĩa là bán 80% giá gốc, tức GIẢM 20% — ngược với cách hiểu của người Việt!","ex":"这个季节衣服都打折。","exPy":"Zhège jìjié yīfu dōu dǎzhé.","exVi":"Mùa này quần áo đều giảm giá.","w":"这个 季节 衣服 都 打折。"},{"zh":"赚","py":"zhuàn","vi":"kiếm được (tiền), lãi","hv":"trám","note":"Bộ 贝 (vỏ sò = tiền) bên trái — nhìn bộ là biết chữ về tiền. Trái nghĩa là 赔 (lỗ).","ex":"做生意不一定能赚钱。","exPy":"Zuò shēngyi bù yídìng néng zhuànqián.","exVi":"Làm ăn chưa chắc kiếm được tiền.","w":"做 生意 不 一定 能 赚 钱。"},{"zh":"租","py":"zū","vi":"thuê; cho thuê","hv":"tô","note":"Bộ 禾 (lúa) — thời xưa nộp tô bằng thóc. Đã gặp trong 出租车 (bài 12). Dùng được cả hai chiều.","ex":"在北京租房子很贵。","exPy":"Zài Běijīng zū fángzi hěn guì.","exVi":"Thuê nhà ở Bắc Kinh rất đắt.","w":"在 北京 租 房子 很 贵。"},{"zh":"存","py":"cún","vi":"gửi (tiền), cất giữ","hv":"tồn","note":"Chính là \"tồn\" tiếng Việt (\"tồn tại\", \"lưu tồn\"). 存钱 = gửi tiết kiệm, 存包 = gửi túi.","ex":"每个月我都存一点儿钱。","exPy":"Měi ge yuè wǒ dōu cún yìdiǎnr qián.","exVi":"Tháng nào tôi cũng để dành một ít.","w":"每 个 月 我 都 存 一点儿 钱。"},{"zh":"富","py":"fù","vi":"giàu","hv":"phú","note":"Chính là \"phú\" tiếng Việt (\"phú quý\", \"giàu có\"). Bộ 宀 (mái nhà). Trái nghĩa là 穷 (bài 97).","ex":"他不富，但是生活得很幸福。","exPy":"Tā bú fù, dànshì shēnghuó de hěn xìngfú.","exVi":"Anh ấy không giàu nhưng sống rất hạnh phúc.","w":"他 不 富， 但是 生活 得 很 幸福。"}],"newChars":["济","收","入","价","付","款","折","赚","存"],"outro":"很好！Xong bài 115."};
G.ROOMS["zh-l116"] = {"id":"zh-l116","lang":"zh","level":4,"no":116,"teacher":"wang","title":"HSK4 · Bài 116 · 数量和质量 Số lượng và chất lượng","intro":["这个广告做得很有意思。","Bài 116: Nói tăng giảm, vượt trội, thiếu đủ — bộ từ dùng khi bàn về số liệu. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège guǎnggào zuò de hěn yǒu yìsi.","gram":{"t":"质量 và 数量 — cặp đối kinh điển","b":"质量 = tốt hay xấu · 数量 = nhiều hay ít","d":"Hai từ này luôn đi cùng nhau khi đánh giá bất cứ thứ gì. Cả hai đều kết thúc bằng 量, và tiếng Việt cũng có đủ cặp \"chất lượng / số lượng\".","ex":[["我们要重视质量，不只是数量。","Chúng ta phải coi trọng chất lượng, không chỉ số lượng.","Wǒmen yào zhòngshì zhìliàng, bù zhǐ shì shùliàng."]]},"grams":[{"t":"质量 và 数量 — cặp đối kinh điển","b":"质量 = tốt hay xấu · 数量 = nhiều hay ít","d":"Hai từ này luôn đi cùng nhau khi đánh giá bất cứ thứ gì. Cả hai đều kết thúc bằng 量, và tiếng Việt cũng có đủ cặp \"chất lượng / số lượng\".","ex":[["我们要重视质量，不只是数量。","Chúng ta phải coi trọng chất lượng, không chỉ số lượng.","Wǒmen yào zhòngshì zhìliàng, bù zhǐ shì shùliàng."]]},{"t":"够 đứng SAU danh từ","b":"danh từ + 够 / 不够","d":"Khác tiếng Việt nói \"đủ tiền\", tiếng Trung nói \"钱够\" (tiền đủ). Phủ định: 钱不够. Đặt trước tính từ thì nghĩa khác: 够大 (đủ to rồi).","ex":[["钱不够，买不了。","Không đủ tiền, mua không nổi.","Qián bú gòu, mǎi bu liǎo."],["这个房间够大了。","Căn phòng này đủ rộng rồi.","Zhège fángjiān gòu dà le."]]},{"t":"Bộ từ nói về thay đổi số liệu","b":"增加 ↔ 减少 · 提高 ↔ 降低 · 超过","d":"增加/减少 dùng cho SỐ LƯỢNG (người, tiền, hàng). 提高/降低 dùng cho MỨC ĐỘ (trình độ, giá, nhiệt độ). Chọn sai cặp là câu nghe lạ ngay.","ex":[["学生的数量增加了。","Số lượng học sinh tăng lên.","Xuésheng de shùliàng zēngjiā le."],["价格降低了百分之十。","Giá giảm mười phần trăm.","Jiàgé jiàngdī le bǎi fēn zhī shí."]]}],"items":[{"zh":"广告","py":"guǎnggào","vi":"quảng cáo","hv":"quảng cáo","note":"Chính là \"quảng cáo\" tiếng Việt: 广 (quảng, rộng) + 告 (cáo, báo).","ex":"这个广告做得很有意思。","exPy":"Zhège guǎnggào zuò de hěn yǒu yìsi.","exVi":"Quảng cáo này làm rất thú vị.","w":"这个 广告 做 得 很 有意思。"},{"zh":"质量","py":"zhìliàng","vi":"chất lượng","hv":"chất lượng","note":"Chính là \"chất lượng\" tiếng Việt: 质 (chất) + 量 (lượng).","ex":"买东西要看质量，不能只看价格。","exPy":"Mǎi dōngxi yào kàn zhìliàng, bù néng zhǐ kàn jiàgé.","exVi":"Mua đồ phải xem chất lượng, không chỉ nhìn giá.","w":"买 东西 要 看 质量， 不 能 只 看 价格。"},{"zh":"数量","py":"shùliàng","vi":"số lượng","hv":"số lượng","note":"Chính là \"số lượng\" tiếng Việt: 数 (số) + 量 (lượng). Cặp đối với 质量.","ex":"今年参加的人数量比去年多。","exPy":"Jīnnián cānjiā de rén shùliàng bǐ qùnián duō.","exVi":"Số người tham gia năm nay nhiều hơn năm ngoái.","w":"今年 参加 的 人数 量 比 去年 多。"},{"zh":"全部","py":"quánbù","vi":"toàn bộ, tất cả","hv":"toàn bộ","note":"Chính là \"toàn bộ\" tiếng Việt: 全 (toàn) + 部 (bộ).","ex":"这些书全部都是他的。","exPy":"Zhèxiē shū quánbù dōu shì tā de.","exVi":"Toàn bộ sách này đều của anh ấy.","w":"这些 书 全部 都 是 他 的。"},{"zh":"部分","py":"bùfen","vi":"một phần, bộ phận","hv":"bộ phận","note":"Chính là \"bộ phận\" tiếng Việt. Cặp đối với 全部: 大部分 (phần lớn), 一部分 (một phần).","ex":"一部分同学已经毕业了。","exPy":"Yí bùfen tóngxué yǐjīng bìyè le.","exVi":"Một bộ phận bạn học đã tốt nghiệp.","w":"一 部分 同学 已经 毕业 了。"},{"zh":"增加","py":"zēngjiā","vi":"tăng thêm","hv":"tăng gia","note":"Chính là \"tăng gia\" tiếng Việt (\"tăng gia sản xuất\"): 增 (tăng) + 加 (thêm).","ex":"为了增加收入，他晚上还去打工。","exPy":"Wèile zēngjiā shōurù, tā wǎnshang hái qù dǎgōng.","exVi":"Để tăng thu nhập, tối anh ấy còn đi làm thêm.","w":"为了 增加 收入， 他 晚上 还 去 打工。"},{"zh":"减少","py":"jiǎnshǎo","vi":"giảm bớt","hv":"giảm thiểu","note":"Chính là \"giảm thiểu\" tiếng Việt: 减 (giảm) + 少 (thiểu, ít). Cặp đối với 增加.","ex":"医生让他减少工作时间。","exPy":"Yīshēng ràng tā jiǎnshǎo gōngzuò shíjiān.","exVi":"Bác sĩ bảo anh ấy giảm giờ làm.","w":"医生 让 他 减少 工作 时间。"},{"zh":"超过","py":"chāoguò","vi":"vượt quá","hv":"siêu quá","note":"超 (siêu, vượt — như 超市 bài 40) + 过 (qua). Dùng cho con số và tốc độ.","ex":"这里的温度很少超过三十度。","exPy":"Zhèlǐ de wēndù hěn shǎo chāoguò sānshí dù.","exVi":"Nhiệt độ ở đây ít khi vượt ba mươi độ.","w":"这里 的 温度 很 少 超过 三 十 度。"},{"zh":"够","py":"gòu","vi":"đủ","hv":"cấu","note":"Đặt SAU danh từ: 钱不够 (không đủ tiền). Cũng đặt trước tính từ nghĩa \"khá\": 够大了.","ex":"带的钱够不够？","exPy":"Dài de qián gòu bu gòu?","exVi":"Tiền mang theo có đủ không?","w":"带 的 钱 够 不够？"},{"zh":"缺少","py":"quēshǎo","vi":"thiếu","hv":"khuyết thiểu","note":"缺 (khuyết, thiếu — như 缺点 bài 65) + 少 (ít). Trang trọng hơn 没有.","ex":"我最缺少的是时间。","exPy":"Wǒ zuì quēshǎo de shì shíjiān.","exVi":"Thứ tôi thiếu nhất là thời gian.","w":"我 最 缺少 的 是 时间。"}],"newChars":["质","部","增","够"],"outro":"很好！Xong bài 116."};
G.ROOMS["zh-l117"] = {"id":"zh-l117","lang":"zh","level":4,"no":117,"teacher":"wang","title":"HSK4 · Bài 117 · 家里的房间 Trong căn nhà","intro":["我们家的厨房不太大。","Bài 117: Gọi tên các phòng và đồ đạc — từ vựng thuê nhà và sinh hoạt. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒmen jiā de chúfáng bú tài dà.","gram":{"t":"Đuôi 间 và 房 và 厅 — cách gọi tên phòng","b":"房间 · 卫生间 · 厨房 · 客厅","d":"间 (gian) dùng cho phòng chức năng nhỏ, 房 (phòng) cho phòng ở, 厅 (sảnh) cho không gian rộng tiếp khách. Ba đuôi này ghép được với hầu hết tên phòng trong nhà.","ex":[["卧室 · 书房 · 餐厅","phòng ngủ · phòng sách · phòng ăn","wòshì · shūfáng · cāntīng"]]},"grams":[{"t":"Đuôi 间 và 房 và 厅 — cách gọi tên phòng","b":"房间 · 卫生间 · 厨房 · 客厅","d":"间 (gian) dùng cho phòng chức năng nhỏ, 房 (phòng) cho phòng ở, 厅 (sảnh) cho không gian rộng tiếp khách. Ba đuôi này ghép được với hầu hết tên phòng trong nhà.","ex":[["卧室 · 书房 · 餐厅","phòng ngủ · phòng sách · phòng ăn","wòshì · shūfáng · cāntīng"]]},{"t":"Câu 把 với đồ vật trong nhà","b":"把 + đồ vật + động từ + 上/进/好","d":"Nhắc lại bài 44. Trong sinh hoạt hằng ngày, câu 把 xuất hiện liên tục vì ta luôn TÁC ĐỘNG lên đồ vật: 把窗户关上, 把垃圾扔进垃圾桶, 把钥匙放好.","ex":[["请把门关好。","Xin đóng cửa cho kỹ.","Qǐng bǎ mén guān hǎo."],["他把家具都搬走了。","Anh ấy khiêng hết đồ đạc đi rồi.","Tā bǎ jiājù dōu bān zǒu le."]]},{"t":"Lượng từ 套 cho bộ đồ","b":"一套家具 · 一套房子 · 一套衣服","d":"套 tào dùng cho thứ gồm nhiều món hợp thành một BỘ. Tiếng Việt cũng nói \"một bộ bàn ghế\", \"một căn hộ\".","ex":[["他买了一套新家具。","Anh ấy mua một bộ nội thất mới.","Tā mǎi le yí tào xīn jiājù."]]}],"items":[{"zh":"厨房","py":"chúfáng","vi":"nhà bếp","hv":"trù phòng","note":"厨 (bếp) + 房 (phòng, bài 25). Tiếng Việt: \"trù phòng\" trong từ cổ, nay nói \"nhà bếp\".","ex":"我们家的厨房不太大。","exPy":"Wǒmen jiā de chúfáng bú tài dà.","exVi":"Bếp nhà tôi không lớn lắm.","w":"我们 家 的 厨房 不 太 大。"},{"zh":"客厅","py":"kètīng","vi":"phòng khách","hv":"khách sảnh","note":"客 (khách, bài 69 trong 客人) + 厅 (sảnh). Tiếng Việt: \"khách sảnh\", \"đại sảnh\".","ex":"晚上全家人都在客厅看电视。","exPy":"Wǎnshang quánjiā rén dōu zài kètīng kàn diànshì.","exVi":"Buổi tối cả nhà xem tivi ở phòng khách.","w":"晚上 全 家人 都 在 客厅 看 电视。"},{"zh":"卫生间","py":"wèishēngjiān","vi":"nhà vệ sinh","hv":"vệ sinh gian","note":"卫生 chính là \"vệ sinh\" tiếng Việt + 间 (gian phòng). Đồng nghĩa 洗手间 (bài 40).","ex":"请问卫生间在几楼？","exPy":"Qǐngwèn wèishēngjiān zài jǐ lóu?","exVi":"Xin hỏi nhà vệ sinh ở tầng mấy?","w":"请问 卫生间 在 几 楼？"},{"zh":"窗户","py":"chuānghu","vi":"cửa sổ","hv":"song hộ","note":"窗 (song cửa) + 户 (hộ, cửa). Tiếng Việt: \"song cửa\", \"hộ khẩu\".","ex":"打开窗户，让空气进来。","exPy":"Dǎkāi chuānghu, ràng kōngqì jìnlai.","exVi":"Mở cửa sổ cho không khí vào.","w":"打开 窗户， 让 空气 进来。"},{"zh":"沙发","py":"shāfā","vi":"ghế sofa","hv":"sa phát","note":"Từ MƯỢN ÂM tiếng Anh \"sofa\". Tiếng Việt cũng mượn thẳng \"sofa\" — hiếm khi hai bên mượn giống nhau như vậy.","ex":"这个沙发坐着很舒服。","exPy":"Zhège shāfā zuò zhe hěn shūfu.","exVi":"Cái sofa này ngồi rất thoải mái.","w":"这个 沙发 坐 着 很 舒服。"},{"zh":"家具","py":"jiājù","vi":"đồ nội thất","hv":"gia cụ","note":"家 (nhà) + 具 (dụng cụ). Tiếng Việt: \"gia cụ\", \"dụng cụ\", \"công cụ\".","ex":"搬家最麻烦的是家具。","exPy":"Bānjiā zuì máfan de shì jiājù.","exVi":"Chuyển nhà phiền nhất là đồ đạc.","w":"搬家 最 麻烦 的 是 家具。"},{"zh":"房东","py":"fángdōng","vi":"chủ nhà (cho thuê)","hv":"phòng đông","note":"房 (nhà) + 东 (chủ). Chữ 东 ở đây nghĩa là CHỦ, như trong 股东 (cổ đông). Người thuê là 房客.","ex":"房东人很好，房租也不贵。","exPy":"Fángdōng rén hěn hǎo, fángzū yě bú guì.","exVi":"Chủ nhà tốt tính, tiền thuê cũng không đắt.","w":"房东 人 很 好， 房租 也 不 贵。"},{"zh":"钥匙","py":"yàoshi","vi":"chìa khoá","hv":"thược thi","note":"Cả hai chữ đều có bộ 钅 (kim loại). Chú ý 匙 ở đây đọc nhẹ shi, khác 勺子 (thìa).","ex":"我的钥匙找不到了。","exPy":"Wǒ de yàoshi zhǎo bu dào le.","exVi":"Tôi không tìm thấy chìa khoá.","w":"我 的 钥匙 找 不 到 了。"},{"zh":"垃圾桶","py":"lājītǒng","vi":"thùng rác","hv":"lạp cấp dũng","note":"垃圾 (rác) + 桶 (thùng, bộ 木). Vứt rác là 扔垃圾.","ex":"垃圾桶满了，该倒了。","exPy":"Lājītǒng mǎn le, gāi dào le.","exVi":"Thùng rác đầy rồi, phải đổ thôi.","w":"垃圾桶 满 了， 该 倒 了。"},{"zh":"毛巾","py":"máojīn","vi":"khăn mặt","hv":"mao cân","note":"毛 (lông, bài 115) + 巾 (khăn — bộ thủ đã học). Nghĩa đen: khăn có lông.","ex":"洗完澡记得把毛巾挂好。","exPy":"Xǐ wán zǎo jìde bǎ máojīn guà hǎo.","exVi":"Tắm xong nhớ treo khăn lại.","w":"洗 完 澡 记得 把 毛巾 挂 好。"}],"newChars":["厨","厅","卫","窗","户","沙","具","钥","匙","垃","圾","桶","巾"],"outro":"很好！Xong bài 117."};
G.ROOMS["zh-l118"] = {"id":"zh-l118","lang":"zh","level":4,"no":118,"teacher":"wang","title":"HSK4 · Bài 118 · 办公用品 Đồ dùng văn phòng","intro":["礼物我放在一个红盒子里。","Bài 118: Gọi tên giấy tờ, đồ dùng và học thêm hai lượng từ hay gặp. Bấm 1 · Học để bắt đầu."],"introPy":"Lǐwù wǒ fàng zài yí ge hóng hézi lǐ.","gram":{"t":"Lượng từ 台 và 把","b":"台 cho máy móc · 把 cho vật có tay cầm","d":"一台电脑, 一台机器, 一台电视 (máy móc). 一把刀, 一把伞, 一把椅子 (vật cầm được bằng tay). Nhớ: 把 vốn nghĩa là \"nắm lấy\" nên dùng cho thứ có chỗ nắm.","ex":[["他家有两台空调。","Nhà anh ấy có hai cái điều hoà.","Tā jiā yǒu liǎng tái kōngtiáo."],["请给我一把刀。","Cho tôi xin một con dao.","Qǐng gěi wǒ yì bǎ dāo."]]},"grams":[{"t":"Lượng từ 台 và 把","b":"台 cho máy móc · 把 cho vật có tay cầm","d":"一台电脑, 一台机器, 一台电视 (máy móc). 一把刀, 一把伞, 一把椅子 (vật cầm được bằng tay). Nhớ: 把 vốn nghĩa là \"nắm lấy\" nên dùng cho thứ có chỗ nắm.","ex":[["他家有两台空调。","Nhà anh ấy có hai cái điều hoà.","Tā jiā yǒu liǎng tái kōngtiáo."],["请给我一把刀。","Cho tôi xin một con dao.","Qǐng gěi wǒ yì bǎ dāo."]]},{"t":"封 vừa là danh từ vừa là lượng từ","b":"一封信 · 信封","d":"封 nghĩa gốc là niêm phong. Làm lượng từ thì đếm thư: 一封信 (một lá thư). Ghép với 信 thì thành cái phong bì. Cùng một chữ, hai vai trò.","ex":[["我收到了三封信。","Tôi nhận được ba lá thư.","Wǒ shōu dào le sān fēng xìn."]]},{"t":"Từ vựng làm giấy tờ","b":"填表格 · 准备材料 · 复印证明 · 交申请","d":"Bốn cụm này bạn sẽ dùng khi xin visa, nhập học hoặc xin việc ở Trung Quốc. Học nguyên cụm sẽ hiệu quả hơn học rời từng từ.","ex":[["办签证要填表格、交材料。","Làm visa phải điền tờ khai, nộp hồ sơ.","Bàn qiānzhèng yào tián biǎogé, jiāo cáiliào."]]}],"items":[{"zh":"盒子","py":"hézi","vi":"cái hộp","hv":"hạp tử","note":"Tiếng Việt: \"hộp\" chính là chữ 盒 này. Bộ 皿 (đồ đựng) ở dưới.","ex":"礼物我放在一个红盒子里。","exPy":"Lǐwù wǒ fàng zài yí ge hóng hézi lǐ.","exVi":"Quà tôi để trong một cái hộp đỏ.","w":"礼物 我 放 在 一 个 红 盒子 里。"},{"zh":"刀","py":"dāo","vi":"con dao","hv":"đao","note":"Bộ thủ đã học ở phần bộ thủ. Tiếng Việt: \"đao\", \"đao kiếm\". Lượng từ là 把: 一把刀.","ex":"厨房的刀要放好，别让孩子拿到。","exPy":"Chúfáng de dāo yào fàng hǎo, bié ràng háizi ná dào.","exVi":"Dao trong bếp phải cất kỹ, đừng để trẻ lấy được.","w":"厨房 的 刀 要 放 好， 别 让 孩子 拿 到。"},{"zh":"塑料袋","py":"sùliàodài","vi":"túi ni lông","hv":"tố liệu đại","note":"塑料 (nhựa) + 袋 (túi). 料 là \"liệu\" trong \"nguyên liệu\", \"tài liệu\".","ex":"超市现在不免费提供塑料袋了。","exPy":"Chāoshì xiànzài bù miǎnfèi tígōng sùliàodài le.","exVi":"Siêu thị giờ không phát túi ni lông miễn phí nữa.","w":"超市 现在 不免 费 提供 塑料袋 了。"},{"zh":"信封","py":"xìnfēng","vi":"phong bì","hv":"tín phong","note":"信 (thư tín) + 封 (phong, niêm). Tiếng Việt gọi \"phong bì\" — cùng chữ 封. Cũng là lượng từ: 一封信.","ex":"信封上要写清楚地址。","exPy":"Xìnfēng shàng yào xiě qīngchu dìzhǐ.","exVi":"Trên phong bì phải ghi rõ địa chỉ.","w":"信封 上 要 写 清楚 地址。"},{"zh":"表格","py":"biǎogé","vi":"biểu mẫu, tờ khai","hv":"biểu cách","note":"表 (bảng biểu) + 格 (ô, cách). Điền tờ khai là 填表格.","ex":"这张表格有点儿复杂。","exPy":"Zhè zhāng biǎogé yǒudiǎnr fùzá.","exVi":"Tờ khai này hơi phức tạp.","w":"这 张 表格 有点儿 复杂。"},{"zh":"材料","py":"cáiliào","vi":"tài liệu; vật liệu","hv":"tài liệu","note":"Chính là \"tài liệu\" tiếng Việt, nhưng tiếng Trung còn nghĩa VẬT LIỆU xây dựng, nấu ăn.","ex":"开会前请准备好材料。","exPy":"Kāihuì qián qǐng zhǔnbèi hǎo cáiliào.","exVi":"Trước khi họp xin chuẩn bị tài liệu.","w":"开会 前 请 准备 好 材料。"},{"zh":"页","py":"yè","vi":"trang (sách)","hv":"hiệt","note":"Chính là bộ thủ 页 (hiệt, cái đầu). Nay dùng đếm trang giấy: 第一页, 三页.","ex":"这本书一共三百页。","exPy":"Zhè běn shū yígòng sānbǎi yè.","exVi":"Quyển sách này tất cả ba trăm trang.","w":"这 本 书 一共 三 百 页。"},{"zh":"台","py":"tái","vi":"chiếc (lượng từ cho máy móc)","hv":"đài","note":"Chính là \"đài\" tiếng Việt (\"đài truyền hình\"). Làm lượng từ thì đếm máy móc: 一台电脑, 一台机器.","ex":"我们办公室新买了两台打印机。","exPy":"Wǒmen bàngōngshì xīn mǎi le liǎng tái dǎyìnjī.","exVi":"Văn phòng tôi mới mua hai máy in.","w":"我们 办公室 新 买 了 两 台 打印机。"},{"zh":"杂志","py":"zázhì","vi":"tạp chí","hv":"tạp chí","note":"Chính là \"tạp chí\" tiếng Việt: 杂 (tạp) + 志 (chí).","ex":"这本杂志每个月出一期。","exPy":"Zhè běn zázhì měi ge yuè chū yì qī.","exVi":"Tạp chí này mỗi tháng ra một số.","w":"这 本 杂志 每 个 月 出 一 期。"},{"zh":"日记","py":"rìjì","vi":"nhật ký","hv":"nhật ký","note":"Chính là \"nhật ký\" tiếng Việt: 日 (nhật) + 记 (ký). Viết nhật ký là 写日记.","ex":"写日记是提高写作的好办法。","exPy":"Xiě rìjì shì tígāo xiězuò de hǎo bànfǎ.","exVi":"Viết nhật ký là cách hay để nâng khả năng viết.","w":"写 日记 是 提高 写作 的 好 办法。"}],"newChars":["盒","刀","塑","袋","封","材","页","台","杂"],"outro":"很好！Xong bài 118."};
G.ROOMS["zh-l119"] = {"id":"zh-l119","lang":"zh","level":4,"no":119,"teacher":"wang","title":"HSK4 · Bài 119 · 中国菜 Món ăn Trung Hoa","intro":["早饭我常吃包子喝豆浆。","Bài 119: Gọi tên món ăn đặc trưng và các vị cơ bản — bài rất thực dụng khi đi ăn. Bấm 1 · Học để bắt đầu."],"introPy":"Zǎofàn wǒ cháng chī bāozi hē dòujiāng.","gram":{"t":"Ngũ vị trong tiếng Trung","b":"酸 chua · 甜 ngọt · 苦 đắng · 辣 cay · 咸 mặn","d":"Người Trung Quốc gọi là 五味 (ngũ vị) — tiếng Việt cũng có \"ngũ vị hương\". Học đủ năm vị là gọi món và chê khen được thoải mái.","ex":[["这个菜又酸又辣。","Món này vừa chua vừa cay.","Zhège cài yòu suān yòu là."],["我喜欢甜的，不喜欢苦的。","Tôi thích đồ ngọt, không thích đắng.","Wǒ xǐhuan tián de, bù xǐhuan kǔ de."]]},"grams":[{"t":"Ngũ vị trong tiếng Trung","b":"酸 chua · 甜 ngọt · 苦 đắng · 辣 cay · 咸 mặn","d":"Người Trung Quốc gọi là 五味 (ngũ vị) — tiếng Việt cũng có \"ngũ vị hương\". Học đủ năm vị là gọi món và chê khen được thoải mái.","ex":[["这个菜又酸又辣。","Món này vừa chua vừa cay.","Zhège cài yòu suān yòu là."],["我喜欢甜的，不喜欢苦的。","Tôi thích đồ ngọt, không thích đắng.","Wǒ xǐhuan tián de, bù xǐhuan kǔ de."]]},{"t":"放 + gia vị — cho thêm vào món","b":"放 + gia vị (+ 多/少)","d":"放盐, 放糖, 放辣椒. Muốn dặn nhà hàng thì nói 少放盐 (bớt muối), 别放辣 (đừng cho cay). Rất hữu dụng khi bạn không ăn được cay.","ex":[["麻烦少放一点儿盐。","Làm ơn cho ít muối thôi.","Máfan shǎo fàng yìdiǎnr yán."],["我不吃辣，别放辣椒。","Tôi không ăn cay, đừng cho ớt.","Wǒ bù chī là, bié fàng làjiāo."]]},{"t":"Đuôi 子 trong tên đồ vật","b":"包子 · 饺子 · 勺子 · 盒子 · 筷子 · 杯子","d":"子 ở đây chỉ là đuôi tạo danh từ, đọc nhẹ và không mang nghĩa \"con\". Rất nhiều tên đồ vật hằng ngày mang đuôi này — nhận ra quy luật giúp bạn đoán ngay đó là một đồ vật.","ex":[["桌子 · 椅子 · 盘子 · 帽子","bàn · ghế · đĩa · mũ","zhuōzi · yǐzi · pánzi · màozi"]]}],"items":[{"zh":"包子","py":"bāozi","vi":"bánh bao","hv":"bao tử","note":"包 (bọc, bài 43) + 子. Tiếng Việt gọi \"bánh bao\" — mượn thẳng chữ 包 này.","ex":"早饭我常吃包子喝豆浆。","exPy":"Zǎofàn wǒ cháng chī bāozi hē dòujiāng.","exVi":"Bữa sáng tôi hay ăn bánh bao uống sữa đậu.","w":"早饭 我 常 吃 包子 喝 豆浆。"},{"zh":"饺子","py":"jiǎozi","vi":"sủi cảo, bánh chẻo","hv":"giáo tử","note":"Món ăn Tết bắt buộc ở miền Bắc Trung Quốc. Gói sủi cảo là 包饺子 — lại dùng chữ 包.","ex":"全家一起包饺子很热闹。","exPy":"Quánjiā yìqǐ bāo jiǎozi hěn rènao.","exVi":"Cả nhà cùng gói sủi cảo rất vui.","w":"全 家 一起 包 饺子 很 热闹。"},{"zh":"烤鸭","py":"kǎoyā","vi":"vịt quay","hv":"khảo áp","note":"烤 (nướng, bộ 火) + 鸭 (vịt, bộ 鸟). 北京烤鸭 là món nổi tiếng nhất Bắc Kinh.","ex":"北京烤鸭又香又好吃。","exPy":"Běijīng kǎoyā yòu xiāng yòu hǎochī.","exVi":"Vịt quay Bắc Kinh vừa thơm vừa ngon.","w":"北京 烤鸭 又 香 又 好吃。"},{"zh":"小吃","py":"xiǎochī","vi":"món ăn vặt, quà vặt","hv":"tiểu cật","note":"小 (nhỏ) + 吃 (ăn). Chỉ các món ăn đường phố đặc sản địa phương, không phải bữa chính.","ex":"我最喜欢逛小吃街。","exPy":"Wǒ zuì xǐhuan guàng xiǎochī jiē.","exVi":"Tôi thích nhất là dạo phố ăn vặt.","w":"我 最 喜欢 逛 小吃 街。"},{"zh":"汤","py":"tāng","vi":"canh, súp","hv":"thang","note":"Bộ 氵 (nước). Tiếng Việt: \"thang\" trong \"thang thuốc\" — vốn là nước sắc.","ex":"这个汤是妈妈做的。","exPy":"Zhège tāng shì māma zuò de.","exVi":"Bát canh này mẹ nấu.","w":"这个 汤 是 妈妈 做 的。"},{"zh":"糖","py":"táng","vi":"đường; kẹo","hv":"đường","note":"Chính là \"đường\" tiếng Việt! Bộ 米 (gạo) vì đường xưa nấu từ ngũ cốc.","ex":"吃太多糖对牙不好。","exPy":"Chī tài duō táng duì yá bù hǎo.","exVi":"Ăn nhiều đường không tốt cho răng.","w":"吃 太 多 糖 对 牙 不 好。"},{"zh":"盐","py":"yán","vi":"muối","hv":"diêm","note":"Tiếng Việt: \"diêm\" trong \"diêm dân\" (người làm muối), \"diêm nghiệp\".","ex":"盐放少一点儿更健康。","exPy":"Yán fàng shǎo yìdiǎnr gèng jiànkāng.","exVi":"Cho ít muối lại thì khoẻ hơn.","w":"盐 放 少 一点儿 更 健康。"},{"zh":"勺子","py":"sháozi","vi":"cái thìa","hv":"thược tử","note":"Chữ 勺 tượng hình cái muôi có cán. Bộ đồ ăn Trung Quốc: 筷子 (đũa) + 勺子 (thìa).","ex":"请再给我一个勺子。","exPy":"Qǐng zài gěi wǒ yí ge sháozi.","exVi":"Cho tôi thêm một cái thìa.","w":"请 再 给 我 一 个 勺子。"},{"zh":"酸","py":"suān","vi":"chua","hv":"toan","note":"Tiếng Việt: \"toan\" trong \"axit\" hoá học. Bộ 酉 (bình rượu) vì rượu để lâu thì chua.","ex":"西红柿是酸的还是甜的？","exPy":"Xīhóngshì shì suān de háishi tián de?","exVi":"Cà chua chua hay ngọt?","w":"西红柿 是 酸 的 还是 甜 的？"},{"zh":"辣","py":"là","vi":"cay","hv":"lạt","note":"Bộ 辛 (vị cay). Món Tứ Xuyên nổi tiếng cay — 四川菜很辣.","ex":"四川菜很辣，我受不了。","exPy":"Sìchuān cài hěn là, wǒ shòu bu liǎo.","exVi":"Món Tứ Xuyên cay lắm, tôi chịu không nổi.","w":"四 川 菜 很 辣， 我 受不了。"}],"newChars":["饺","烤","鸭","汤","糖","盐","勺","酸","辣"],"outro":"很好！Xong bài 119."};
G.ROOMS["zh-l120"] = {"id":"zh-l120","lang":"zh","level":4,"no":120,"teacher":"wang","title":"HSK4 · Bài 120 · 饮料和味道 Đồ uống và mùi vị","intro":["我买了一盒饼干带在路上吃。","Bài 120: Gọi đồ uống, tả mùi vị và nâng ly chúc mừng. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ mǎi le yì hé bǐnggān dài zài lù shàng chī.","gram":{"t":"Từ mượn âm và từ dịch nghĩa","b":"巧克力 (mượn âm) · 矿泉水 (dịch nghĩa)","d":"Tiếng Trung mượn âm cho tên riêng và sản phẩm ngoại (巧克力, 咖啡, 沙发, 幽默), nhưng dịch nghĩa cho khái niệm (矿泉水, 互联网, 电脑). Nhận ra loại nào giúp bạn đoán nghĩa nhanh hơn.","ex":[["咖啡 · 沙发 · 巧克力","mượn âm nước ngoài","kāfēi · shāfā · qiǎokèlì"],["电脑 · 火车 · 矿泉水","ghép chữ theo nghĩa","diànnǎo · huǒchē · kuàngquánshuǐ"]]},"grams":[{"t":"Từ mượn âm và từ dịch nghĩa","b":"巧克力 (mượn âm) · 矿泉水 (dịch nghĩa)","d":"Tiếng Trung mượn âm cho tên riêng và sản phẩm ngoại (巧克力, 咖啡, 沙发, 幽默), nhưng dịch nghĩa cho khái niệm (矿泉水, 互联网, 电脑). Nhận ra loại nào giúp bạn đoán nghĩa nhanh hơn.","ex":[["咖啡 · 沙发 · 巧克力","mượn âm nước ngoài","kāfēi · shāfā · qiǎokèlì"],["电脑 · 火车 · 矿泉水","ghép chữ theo nghĩa","diànnǎo · huǒchē · kuàngquánshuǐ"]]},{"t":"干杯 và văn hoá bàn tiệc","b":"为 + điều chúc + 干杯！","d":"为我们的友谊干杯, 为你的成功干杯. Ở Trung Quốc, người mời nâng ly trước và uống cạn thể hiện thành ý. Nếu không uống được rượu, nói 我以茶代酒 (tôi thay rượu bằng trà) là cách từ chối lịch sự.","ex":[["为大家的健康干杯！","Nâng ly vì sức khoẻ mọi người!","Wèi dàjiā de jiànkāng gānbēi!"]]},{"t":"味道 + tính từ — nhận xét món ăn","b":"味道 + 好 / 不错 / 怪 / 特别","d":"Muốn khen món ăn ngoài 好吃 còn có thể nói 味道很好, 味道不错. Chê nhẹ thì 味道有点儿怪 (vị hơi lạ) — lịch sự hơn nói thẳng là dở.","ex":[["这家饭馆的味道不错。","Quán này vị khá đấy.","Zhè jiā fànguǎn de wèidào búcuò."]]}],"items":[{"zh":"饼干","py":"bǐnggān","vi":"bánh quy","hv":"bính can","note":"饼 (bánh dẹt, bộ 饣) + 干 (khô). Nghĩa đen: bánh khô. Tiếng Việt: \"bính\" trong \"nguyệt bính\" (bánh trung thu).","ex":"我买了一盒饼干带在路上吃。","exPy":"Wǒ mǎi le yì hé bǐnggān dài zài lù shàng chī.","exVi":"Tôi mua một hộp bánh quy mang theo ăn dọc đường.","w":"我 买 了 一 盒 饼干 带 在 路上 吃。"},{"zh":"巧克力","py":"qiǎokèlì","vi":"sô cô la","hv":"xảo khắc lực","note":"Từ MƯỢN ÂM tiếng Anh \"chocolate\" — ba chữ chỉ mượn âm, không mang nghĩa.","ex":"情人节大家都送巧克力。","exPy":"Qíngrénjié dàjiā dōu sòng qiǎokèlì.","exVi":"Lễ Tình nhân ai cũng tặng sô cô la.","w":"情人 节 大家 都 送 巧克力。"},{"zh":"果汁","py":"guǒzhī","vi":"nước ép trái cây","hv":"quả trấp","note":"果 (quả) + 汁 (nước cốt, bộ 氵). Tiếng Việt: \"trấp\" trong từ cổ chỉ nước cốt.","ex":"早上喝一杯果汁很健康。","exPy":"Zǎoshang hē yì bēi guǒzhī hěn jiànkāng.","exVi":"Sáng uống một ly nước ép rất tốt.","w":"早上 喝 一 杯 果汁 很 健康。"},{"zh":"矿泉水","py":"kuàngquánshuǐ","vi":"nước khoáng","hv":"khoáng tuyền thuỷ","note":"矿 (khoáng) + 泉 (suối) + 水 (nước) = \"nước suối khoáng\". Tiếng Việt cũng gọi \"nước khoáng\".","ex":"出门记得带瓶矿泉水。","exPy":"Chūmén jìde dài píng kuàngquánshuǐ.","exVi":"Ra ngoài nhớ mang chai nước khoáng.","w":"出门 记得 带 瓶 矿泉水。"},{"zh":"西红柿","py":"xīhóngshì","vi":"cà chua","hv":"tây hồng thị","note":"西 (tây) + 红 (đỏ) + 柿 (quả hồng) = \"quả hồng đỏ phương tây\". Cách đặt tên rất hình ảnh.","ex":"夏天的西红柿又大又甜。","exPy":"Xiàtiān de xīhóngshì yòu dà yòu tián.","exVi":"Cà chua mùa hè vừa to vừa ngọt.","w":"夏天 的 西红柿 又 大 又 甜。"},{"zh":"香","py":"xiāng","vi":"thơm","hv":"hương","note":"Chính là \"hương\" tiếng Việt (\"hương thơm\", \"nước hoa\"). 禾 (lúa) trên 日 — mùi lúa chín.","ex":"刚做好的面包特别香。","exPy":"Gāng zuò hǎo de miànbāo tèbié xiāng.","exVi":"Bánh mì mới ra lò thơm đặc biệt.","w":"刚 做 好 的 面包 特别 香。"},{"zh":"尝","py":"cháng","vi":"nếm","hv":"thường","note":"Tiếng Việt: \"thường\" trong \"nếm thử\" của văn cổ. Hay dùng dạng lặp: 尝尝 (nếm thử chút).","ex":"你尝尝，看看咸不咸。","exPy":"Nǐ chángchang, kànkan xián bu xián.","exVi":"Bạn nếm thử xem có mặn không.","w":"你 尝 尝， 看 看 咸 不 咸。"},{"zh":"干杯","py":"gānbēi","vi":"cạn ly, nâng ly","hv":"can bôi","note":"干 (cạn khô) + 杯 (ly, bài 9). Nghĩa đen: uống cạn ly. Câu chúc bắt buộc biết khi dự tiệc.","ex":"来，为大家的健康干杯！","exPy":"Lái, wèi dàjiā de jiànkāng gānbēi!","exVi":"Nào, nâng ly vì sức khoẻ mọi người!","w":"来， 为 大家 的 健康 干杯！"},{"zh":"味道","py":"wèidào","vi":"mùi vị","hv":"vị đạo","note":"味 (vị) + 道 (đạo). Tiếng Việt: \"vị\", \"khẩu vị\". Dùng cho cả mùi lẫn vị.","ex":"这个菜的味道我很喜欢。","exPy":"Zhège cài de wèidào wǒ hěn xǐhuan.","exVi":"Vị món này tôi rất thích.","w":"这个 菜 的 味道 我 很 喜欢。"},{"zh":"咸","py":"xián","vi":"mặn","hv":"hàm","note":"Tiếng Việt: \"hàm\" trong \"hàm lượng muối\". Một trong ngũ vị đã học ở bài 82.","ex":"医生说吃太咸对身体不好。","exPy":"Yīshēng shuō chī tài xián duì shēntǐ bù hǎo.","exVi":"Bác sĩ nói ăn mặn quá không tốt.","w":"医生 说 吃 太 咸 对 身体 不 好。"}],"newChars":["饼","巧","克","汁","矿","泉","柿","尝","味","咸"],"outro":"很好！Xong bài 120."};
G.ROOMS["zh-l121"] = {"id":"zh-l121","lang":"zh","level":4,"no":121,"teacher":"wang","title":"HSK4 · Bài 121 · 收拾东西 Dọn dẹp và đồ hỏng","intro":["冬天要穿厚袜子。","Bài 121: Bộ động từ dọn dẹp, và phân biệt bốn chữ dễ lẫn 扔 / 丢 / 收 / 整理. Bấm 1 · Học để bắt đầu."],"introPy":"Dōngtiān yào chuān hòu wàzi.","gram":{"t":"扔 và 丢 — cố ý hay vô ý?","b":"扔 = cố ý ném bỏ · 丢 = vô ý đánh mất","d":"我扔了那件旧衣服 (tôi vứt bộ đồ cũ — có chủ ý). 我丢了钱包 (tôi đánh mất ví — ngoài ý muốn). Dùng nhầm 扔了钱包 nghĩa thành \"tôi cố tình ném cái ví đi\"!","ex":[["别把有用的东西扔了。","Đừng vứt những thứ còn dùng được.","Bié bǎ yǒuyòng de dōngxi rēng le."],["我的手机丢了，找了一天。","Điện thoại tôi mất rồi, tìm cả ngày.","Wǒ de shǒujī diū le, zhǎo le yì tiān."]]},"grams":[{"t":"扔 và 丢 — cố ý hay vô ý?","b":"扔 = cố ý ném bỏ · 丢 = vô ý đánh mất","d":"我扔了那件旧衣服 (tôi vứt bộ đồ cũ — có chủ ý). 我丢了钱包 (tôi đánh mất ví — ngoài ý muốn). Dùng nhầm 扔了钱包 nghĩa thành \"tôi cố tình ném cái ví đi\"!","ex":[["别把有用的东西扔了。","Đừng vứt những thứ còn dùng được.","Bié bǎ yǒuyòng de dōngxi rēng le."],["我的手机丢了，找了一天。","Điện thoại tôi mất rồi, tìm cả ngày.","Wǒ de shǒujī diū le, zhǎo le yì tiān."]]},{"t":"整理 và 收拾 — trang trọng hay khẩu ngữ","b":"整理 = sắp xếp có hệ thống · 收拾 = dọn dẹp, thu vén","d":"整理材料, 整理笔记 (sắp xếp có trật tự). 收拾房间, 收拾行李 (dọn dẹp, thu vén). 收拾 gần gũi hơn và hay dùng trong nhà.","ex":[["我要整理一下学习笔记。","Tôi phải sắp xếp lại vở ghi.","Wǒ yào zhěnglǐ yíxià xuéxí bǐjì."],["出发前收拾好行李。","Trước khi đi xếp gọn hành lý.","Chūfā qián shōushi hǎo xíngli."]]},{"t":"穿 / 脱 / 戴 — bộ ba mặc và cởi","b":"穿 ↔ 脱 (áo quần giày) · 戴 ↔ 摘 (mũ kính đồng hồ)","d":"Nhắc lại từ bài 21 và 43, nay đủ cả cặp trái nghĩa. 脱鞋 (cởi giày), 摘眼镜 (bỏ kính xuống). Ở Trung Quốc và Việt Nam đều có tục cởi giày khi vào nhà.","ex":[["天热了，把外套脱了吧。","Trời nóng rồi, cởi áo khoác ra đi.","Tiān rè le, bǎ wàitào tuō le ba."]]}],"items":[{"zh":"袜子","py":"wàzi","vi":"đôi tất","hv":"miệt tử","note":"Bộ 衤 (áo quần) bên trái — cùng nhóm với 衬衫, 裤子, 裙子 ở bài 43. Lượng từ: 一双袜子.","ex":"冬天要穿厚袜子。","exPy":"Dōngtiān yào chuān hòu wàzi.","exVi":"Mùa đông phải đi tất dày.","w":"冬天 要 穿 厚 袜子。"},{"zh":"脱","py":"tuō","vi":"cởi (quần áo)","hv":"thoát","note":"Chính là \"thoát\" tiếng Việt (\"thoát y\", \"giải thoát\"). Bộ 月 (thịt). Trái nghĩa với 穿 (bài 21).","ex":"进门请把鞋脱在门口。","exPy":"Jìn mén qǐng bǎ xié tuō zài ménkǒu.","exVi":"Vào cửa xin để giày ở ngoài.","w":"进 门 请 把 鞋 脱 在 门口。"},{"zh":"戴","py":"dài","vi":"đeo, đội","hv":"đái","note":"Dùng cho mũ, kính, đồng hồ, nhẫn — thứ GÀI lên người. Khác 穿 dùng cho thứ LUỒN người vào.","ex":"开车的时候别戴帽子挡住眼睛。","exPy":"Kāichē de shíhou bié dài màozi dǎng zhù yǎnjing.","exVi":"Lúc lái xe đừng đội mũ che mắt.","w":"开车 的 时候 别 戴 帽子 挡 住 眼睛。"},{"zh":"破","py":"pò","vi":"rách, vỡ","hv":"phá","note":"Chính là \"phá\" tiếng Việt (\"phá vỡ\", \"phá hỏng\"). Bộ 石 (đá).","ex":"杯子摔破了，小心别踩到。","exPy":"Bēizi shuāi pò le, xiǎoxīn bié cǎi dào.","exVi":"Cái cốc vỡ rồi, cẩn thận đừng giẫm phải.","w":"杯子 摔 破 了， 小心 别 踩 到。"},{"zh":"脏","py":"zāng","vi":"bẩn","hv":"tạng","note":"Bộ 月 (thịt). Trái nghĩa với 干净 (bài 44).","ex":"衣服脏了就洗，别放太久。","exPy":"Yīfu zāng le jiù xǐ, bié fàng tài jiǔ.","exVi":"Quần áo bẩn thì giặt, đừng để lâu quá.","w":"衣服 脏 了 就 洗， 别 放 太 久。"},{"zh":"扔","py":"rēng","vi":"vứt, ném","hv":"nhưng","note":"Bộ 扌 (tay). Là hành động CỐ Ý bỏ đi: 扔垃圾 (vứt rác).","ex":"请把垃圾扔进垃圾桶里。","exPy":"Qǐng bǎ lājī rēng jìn lājītǒng lǐ.","exVi":"Xin vứt rác vào thùng rác.","w":"请 把 垃圾 扔 进 垃圾桶 里。"},{"zh":"丢","py":"diū","vi":"làm mất; vứt","hv":"đâu","note":"Khác 扔: 丢 thường là VÔ Ý làm mất — 我丢了钱包 (tôi mất ví). Cũng có nghĩa vứt bỏ.","ex":"我在地铁上把伞丢了。","exPy":"Wǒ zài dìtiě shàng bǎ sǎn diū le.","exVi":"Tôi làm mất ô trên tàu điện.","w":"我 在 地铁 上 把 伞 丢 了。"},{"zh":"收","py":"shōu","vi":"nhận; thu, cất","hv":"thu","note":"Chính là \"thu\" tiếng Việt (\"thu nhập\", \"thu hoạch\"). 收到 = nhận được, 收好 = cất kỹ.","ex":"钱收好，别放在外面。","exPy":"Qián shōu hǎo, bié fàng zài wàimiàn.","exVi":"Tiền cất kỹ, đừng để bên ngoài.","w":"钱 收 好， 别 放 在 外面。"},{"zh":"整理","py":"zhěnglǐ","vi":"sắp xếp, chỉnh lý","hv":"chỉnh lý","note":"Chính là \"chỉnh lý\" tiếng Việt: 整 (chỉnh) + 理 (lý). Sắp cho có trật tự.","ex":"考试前我把笔记整理了一遍。","exPy":"Kǎoshì qián wǒ bǎ bǐjì zhěnglǐ le yí biàn.","exVi":"Trước khi thi tôi sắp xếp lại vở một lượt.","w":"考试 前 我 把 笔记 整理 了 一 遍。"},{"zh":"收拾","py":"shōushi","vi":"dọn dẹp; thu xếp","hv":"thu thập","note":"收 (thu) + 拾 (nhặt lên, bộ 扌). Khẩu ngữ hơn 整理. 收拾行李 = xếp hành lý.","ex":"周末我要好好收拾房间。","exPy":"Zhōumò wǒ yào hǎohǎo shōushi fángjiān.","exVi":"Cuối tuần tôi phải dọn phòng cho tử tế.","w":"周末 我 要好 好 收拾 房间。"}],"newChars":["袜","脱","戴","破","脏","扔","丢","整","拾"],"outro":"很好！Xong bài 121."};
G.ROOMS["zh-l122"] = {"id":"zh-l122","lang":"zh","level":4,"no":122,"teacher":"wang","title":"HSK4 · Bài 122 · 机场和证件 Sân bay và giấy tờ","intro":["请问我的航班几点起飞？","Bài 122: Trọn bộ từ vựng đi máy bay và làm thủ tục xuất nhập cảnh. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐngwèn wǒ de hángbān jǐ diǎn qǐfēi?","gram":{"t":"加油 — câu cổ vũ quốc dân","b":"加油！· 为…加油","d":"Nghĩa đen là \"thêm dầu\" (đổ xăng), nhưng dùng để cổ vũ ở mọi hoàn cảnh: thi cử, thi đấu, gặp khó khăn. Tương đương \"cố lên!\" của tiếng Việt.","ex":[["考试加油！","Thi tốt nhé!","Kǎoshì jiāyóu!"],["大家为他加油。","Mọi người cổ vũ cho anh ấy.","Dàjiā wèi tā jiāyóu."]]},"grams":[{"t":"加油 — câu cổ vũ quốc dân","b":"加油！· 为…加油","d":"Nghĩa đen là \"thêm dầu\" (đổ xăng), nhưng dùng để cổ vũ ở mọi hoàn cảnh: thi cử, thi đấu, gặp khó khăn. Tương đương \"cố lên!\" của tiếng Việt.","ex":[["考试加油！","Thi tốt nhé!","Kǎoshì jiāyóu!"],["大家为他加油。","Mọi người cổ vũ cho anh ấy.","Dàjiā wèi tā jiāyóu."]]},{"t":"Bộ câu ở sân bay","b":"办登机牌 → 过安检 → 登机 → 起飞 → 降落 → 取行李","d":"Sáu bước theo đúng thứ tự bạn sẽ đi qua. Học nguyên chuỗi giúp bạn nghe hiểu thông báo sân bay và làm thủ tục trôi chảy.","ex":[["请到三号柜台办登机牌。","Xin tới quầy số 3 làm thủ tục.","Qǐng dào sān hào guìtái bàn dēngjīpái."],["行李在几号出口取？","Hành lý lấy ở cửa số mấy?","Xíngli zài jǐ hào chūkǒu qǔ?"]]},{"t":"办 — làm thủ tục giấy tờ","b":"办 + giấy tờ / thủ tục","d":"办签证, 办护照, 办手续, 办登机牌. Chữ 办 (bài 39 trong 办法, 办公室) là động từ chuyên dùng cho việc hành chính. Không dùng 做 cho những việc này.","ex":[["办护照需要多长时间？","Làm hộ chiếu mất bao lâu?","Bàn hùzhào xūyào duō cháng shíjiān?"]]}],"items":[{"zh":"航班","py":"hángbān","vi":"chuyến bay","hv":"hàng ban","note":"航 (hàng hải, hàng không) + 班 (chuyến, ca). Tiếng Việt: \"hàng không\", \"hải hàng\".","ex":"请问我的航班几点起飞？","exPy":"Qǐngwèn wǒ de hángbān jǐ diǎn qǐfēi?","exVi":"Cho hỏi chuyến bay của tôi mấy giờ cất cánh?","w":"请问 我 的 航班 几 点 起飞？"},{"zh":"起飞","py":"qǐfēi","vi":"cất cánh","hv":"khởi phi","note":"起 (dậy, bài 18 trong 起床) + 飞 (bay). Cặp đối với 降落.","ex":"飞机准时起飞了。","exPy":"Fēijī zhǔnshí qǐfēi le.","exVi":"Máy bay cất cánh đúng giờ.","w":"飞机 准时 起飞 了。"},{"zh":"降落","py":"jiàngluò","vi":"hạ cánh","hv":"giáng lạc","note":"降 (hạ xuống — cùng chữ với 降低 bài 113) + 落 (rơi). Đọc Hán Việt là \"giáng\" như trong \"giáng cấp\", \"giáng sinh\". Âm \"hàng\" chỉ dùng khi 降 nghĩa là đầu hàng (投降).","ex":"因为天气不好，飞机推迟降落。","exPy":"Yīnwèi tiānqì bù hǎo, fēijī tuīchí jiàngluò.","exVi":"Vì thời tiết xấu, máy bay hạ cánh muộn.","w":"因为 天气 不 好， 飞机 推迟 降落。"},{"zh":"登机牌","py":"dēngjīpái","vi":"thẻ lên máy bay","hv":"đăng cơ bài","note":"登 (lên) + 机 (máy bay) + 牌 (thẻ). Tiếng Việt: \"đăng\" trong \"đăng đàn\", \"bài\" trong \"bài vị\".","ex":"登机牌和护照请拿好。","exPy":"Dēngjīpái hé hùzhào qǐng ná hǎo.","exVi":"Thẻ lên máy bay và hộ chiếu xin cầm kỹ.","w":"登机牌 和 护照 请 拿 好。"},{"zh":"签证","py":"qiānzhèng","vi":"visa, thị thực","hv":"thiêm chứng","note":"签 (ký, bộ 竹) + 证 (chứng, bài 73). Xin visa là 办签证 hoặc 申请签证.","ex":"我的签证下个月就到期了。","exPy":"Wǒ de qiānzhèng xià ge yuè jiù dàoqī le.","exVi":"Visa của tôi tháng sau hết hạn.","w":"我 的 签证 下 个 月 就 到期 了。"},{"zh":"大使馆","py":"dàshǐguǎn","vi":"đại sứ quán","hv":"đại sứ quán","note":"Chính là \"đại sứ quán\" tiếng Việt: 大使 (đại sứ) + 馆 (quán, bài 40).","ex":"中国大使馆在市中心。","exPy":"Zhōngguó dàshǐguǎn zài shì zhōngxīn.","exVi":"Đại sứ quán Trung Quốc ở trung tâm thành phố.","w":"中国 大使馆 在 市 中心。"},{"zh":"堵车","py":"dǔchē","vi":"tắc đường","hv":"đổ xa","note":"堵 (chặn, bít, bộ 土) + 车 (xe). Động từ ly hợp: 堵了半个小时车.","ex":"早上八点最容易堵车。","exPy":"Zǎoshang bā diǎn zuì róngyì dǔchē.","exVi":"Tám giờ sáng dễ tắc đường nhất.","w":"早上 八 点 最 容易 堵车。"},{"zh":"加油站","py":"jiāyóuzhàn","vi":"trạm xăng","hv":"gia du trạm","note":"加 (thêm) + 油 (dầu) + 站 (trạm). 加油 còn nghĩa là \"cố lên!\" — câu cổ vũ phổ biến nhất.","ex":"去机场前先到加油站加油。","exPy":"Qù jīchǎng qián xiān dào jiāyóuzhàn jiāyóu.","exVi":"Trước khi ra sân bay ghé trạm đổ xăng.","w":"去 机场 前 先 到 加油站 加油。"},{"zh":"邮局","py":"yóujú","vi":"bưu điện","hv":"bưu cục","note":"Chính là \"bưu cục\" tiếng Việt: 邮 (bưu) + 局 (cục). Nay hay gọi \"bưu điện\".","ex":"邮局星期天不开门。","exPy":"Yóujú xīngqītiān bù kāimén.","exVi":"Bưu điện chủ nhật không mở cửa.","w":"邮局 星期天 不 开 门。"},{"zh":"入口","py":"rùkǒu","vi":"lối vào","hv":"nhập khẩu","note":"入 (vào) + 口 (miệng, cửa). Trái nghĩa là 出口 (lối ra). Biển chỉ dẫn khắp nơi dùng hai từ này.","ex":"请从入口进，从出口出。","exPy":"Qǐng cóng rùkǒu jìn, cóng chūkǒu chū.","exVi":"Xin vào lối vào, ra lối ra.","w":"请 从 入口 进， 从 出口 出。"}],"newChars":["航","落","登","牌","签","堵","油","局"],"outro":"很好！Xong bài 122."};
G.ROOMS["zh-l123"] = {"id":"zh-l123","lang":"zh","level":4,"no":123,"teacher":"wang","title":"HSK4 · Bài 123 · 路上 Đường sá và địa chỉ","intro":["这个城市的公共交通很发达。","Bài 123: Nói khoảng cách, phương hướng, địa chỉ — bộ từ dùng khi chỉ đường và đặt xe. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège chéngshì de gōnggòng jiāotōng hěn fādá.","gram":{"t":"到处 + 都 — khắp nơi đều…","b":"到处 + 都 + động từ / tính từ","d":"到处 hầu như luôn đi kèm 都 ở sau, giống quy tắc của 每 (bài 18). Nhấn mạnh sự phổ biến ở mọi chỗ.","ex":[["到处都是人。","Chỗ nào cũng đầy người.","Dàochù dōu shì rén."],["我到处找你。","Tôi tìm bạn khắp nơi.","Wǒ dàochù zhǎo nǐ."]]},"grams":[{"t":"到处 + 都 — khắp nơi đều…","b":"到处 + 都 + động từ / tính từ","d":"到处 hầu như luôn đi kèm 都 ở sau, giống quy tắc của 每 (bài 18). Nhấn mạnh sự phổ biến ở mọi chỗ.","ex":[["到处都是人。","Chỗ nào cũng đầy người.","Dàochù dōu shì rén."],["我到处找你。","Tôi tìm bạn khắp nơi.","Wǒ dàochù zhǎo nǐ."]]},{"t":"Ba từ hỏi khoảng cách","b":"多远？· 有多少公里？· A 离 B 有多远？","d":"Nhắc lại 离 ở bài 24, nay dùng với con số cụ thể: 我家离学校有三公里. Từ để hỏi là 多远.","ex":[["从这儿到那儿有多远？","Từ đây tới đó bao xa?","Cóng zhèr dào nàr yǒu duō yuǎn?"],["大概五公里。","Khoảng năm cây số.","Dàgài wǔ gōnglǐ."]]},{"t":"地点 và 地址 — nơi hẹn hay số nhà?","b":"地点 = nơi diễn ra việc gì · 地址 = địa chỉ cụ thể để tìm tới","d":"开会地点 (nơi họp — có thể chỉ là \"phòng 302\"). 家庭地址 (địa chỉ nhà — số nhà, tên phố, thành phố). Điền vào biểu mẫu thì luôn là 地址.","ex":[["请告诉我详细地址。","Xin cho tôi địa chỉ chi tiết.","Qǐng gàosu wǒ xiángxì dìzhǐ."],["见面的地点改了。","Địa điểm gặp mặt đổi rồi.","Jiànmiàn de dìdiǎn gǎi le."]]}],"items":[{"zh":"交通","py":"jiāotōng","vi":"giao thông","hv":"giao thông","note":"Chính là \"giao thông\" tiếng Việt: 交 (giao) + 通 (thông).","ex":"这个城市的公共交通很发达。","exPy":"Zhège chéngshì de gōnggòng jiāotōng hěn fādá.","exVi":"Giao thông công cộng thành phố này rất phát triển.","w":"这个 城市 的 公共 交通 很 发达。"},{"zh":"公里","py":"gōnglǐ","vi":"ki-lô-mét","hv":"công lý","note":"公 (chuẩn quốc tế) + 里 (dặm Trung Quốc). Cùng lối ghép với 公斤 (bài 22).","ex":"我每天骑十公里自行车。","exPy":"Wǒ měi tiān qí shí gōnglǐ zìxíngchē.","exVi":"Ngày nào tôi cũng đạp xe mười cây.","w":"我 每 天 骑 十 公里 自行车。"},{"zh":"距离","py":"jùlí","vi":"khoảng cách","hv":"cự ly","note":"Chính là \"cự ly\" tiếng Việt: 距 (cự) + 离 (ly, bài 24).","ex":"两个人的距离越来越远了。","exPy":"Liǎng ge rén de jùlí yuè lái yuè yuǎn le.","exVi":"Khoảng cách hai người ngày càng xa.","w":"两 个人 的 距离 越 来 越 远 了。"},{"zh":"方向","py":"fāngxiàng","vi":"phương hướng","hv":"phương hướng","note":"Chính là \"phương hướng\" tiếng Việt: 方 (phương) + 向 (hướng, bài 53).","ex":"没有地图我会走错方向。","exPy":"Méiyǒu dìtú wǒ huì zǒu cuò fāngxiàng.","exVi":"Không có bản đồ tôi sẽ đi sai hướng.","w":"没有 地图 我 会 走 错 方向。"},{"zh":"地点","py":"dìdiǎn","vi":"địa điểm","hv":"địa điểm","note":"Chính là \"địa điểm\" tiếng Việt: 地 (địa) + 点 (điểm).","ex":"考试的时间和地点都通知了。","exPy":"Kǎoshì de shíjiān hé dìdiǎn dōu tōngzhī le.","exVi":"Thời gian và địa điểm thi đều đã thông báo.","w":"考试 的 时间 和 地点 都 通知 了。"},{"zh":"地址","py":"dìzhǐ","vi":"địa chỉ","hv":"địa chỉ","note":"Chính là \"địa chỉ\" tiếng Việt: 地 (địa) + 址 (chỉ, nền đất).","ex":"快递需要详细的地址。","exPy":"Kuàidì xūyào xiángxì de dìzhǐ.","exVi":"Chuyển phát cần địa chỉ chi tiết.","w":"快递 需要 详细 的 地址。"},{"zh":"号码","py":"hàomǎ","vi":"số (điện thoại, phòng)","hv":"hiệu mã","note":"号 (số, bài 7) + 码 (mã, bài 75 trong 密码).","ex":"请把房间号码告诉我。","exPy":"Qǐng bǎ fángjiān hàomǎ gàosu wǒ.","exVi":"Xin cho tôi biết số phòng.","w":"请 把 房间 号码 告诉 我。"},{"zh":"到处","py":"dàochù","vi":"khắp nơi","hv":"đáo xứ","note":"到 (đến) + 处 (nơi chốn). Đứng trước động từ: 到处都是人.","ex":"夏天公园里到处都是花。","exPy":"Xiàtiān gōngyuán lǐ dàochù dōu shì huā.","exVi":"Mùa hè trong công viên chỗ nào cũng có hoa.","w":"夏天 公园 里 到处 都 是 花。"},{"zh":"郊区","py":"jiāoqū","vi":"ngoại ô","hv":"giao khu","note":"郊 (vùng ven, bộ 阝) + 区 (khu). Trái nghĩa với 市中心 (trung tâm thành phố).","ex":"住在郊区安静，但是上班不方便。","exPy":"Zhù zài jiāoqū ānjìng, dànshì shàngbān bù fāngbiàn.","exVi":"Ở ngoại ô yên tĩnh nhưng đi làm bất tiện.","w":"住 在 郊区 安静， 但是 上班 不 方便。"},{"zh":"桥","py":"qiáo","vi":"cây cầu","hv":"kiều","note":"Chính là \"kiều\" tiếng Việt (\"kiều lộ\", \"Kiều\" trong địa danh). Bộ 木 vì cầu xưa làm bằng gỗ. Lượng từ: 一座桥.","ex":"这座桥是去年建好的。","exPy":"Zhè zuò qiáo shì qùnián jiàn hǎo de.","exVi":"Cây cầu này xây xong năm ngoái.","w":"这 座 桥 是 去年 建 好 的。"}],"newChars":["距","址","郊","桥"],"outro":"很好！Xong bài 123."};
G.ROOMS["zh-l124"] = {"id":"zh-l124","lang":"zh","level":4,"no":124,"teacher":"wang","title":"HSK4 · Bài 124 · 名胜古迹 Danh lam thắng cảnh","intro":["导游带我们参观了三个地方。","Bài 124: Tham quan, tả cảnh đẹp và gọi tên những địa danh nổi tiếng nhất Trung Quốc. Bấm 1 · Học để bắt đầu."],"introPy":"Dǎoyóu dài wǒmen cānguān le sān ge dìfang.","gram":{"t":"Chữ hội ý: nhân đôi, nhân ba để tăng nghĩa","b":"木 → 林 → 森 · 人 → 从 → 众 · 火 → 炎","d":"Một cây là 木, hai cây thành 林 (rừng thưa), ba cây thành 森 (rừng rậm). Một người là 人, hai người là 从 (đi theo), ba người là 众 (đám đông). Đây là một trong sáu cách tạo chữ Hán, và là cách dễ nhớ nhất.","ex":[["森林 = 森 + 林","ba cây + hai cây = rừng","sēnlín"],["观众 = 观 + 众","xem + đám đông = khán giả","guānzhòng"]]},"grams":[{"t":"Chữ hội ý: nhân đôi, nhân ba để tăng nghĩa","b":"木 → 林 → 森 · 人 → 从 → 众 · 火 → 炎","d":"Một cây là 木, hai cây thành 林 (rừng thưa), ba cây thành 森 (rừng rậm). Một người là 人, hai người là 从 (đi theo), ba người là 众 (đám đông). Đây là một trong sáu cách tạo chữ Hán, và là cách dễ nhớ nhất.","ex":[["森林 = 森 + 林","ba cây + hai cây = rừng","sēnlín"],["观众 = 观 + 众","xem + đám đông = khán giả","guānzhòng"]]},{"t":"参观 và 旅游 và 逛 — ba kiểu đi chơi","b":"参观 = thăm nơi có tổ chức · 旅游 = du lịch · 逛 = dạo chơi","d":"参观博物馆, 参观工厂 (có mục đích tìm hiểu). 旅游 là cả chuyến đi. 逛街, 逛商店 (đi dạo lòng vòng, không mục đích rõ). Chọn đúng từ là câu nghe rất tự nhiên.","ex":[["周末我们去参观博物馆。","Cuối tuần chúng tôi đi thăm bảo tàng.","Zhōumò wǒmen qù cānguān bówùguǎn."],["我喜欢一个人逛书店。","Tôi thích một mình dạo hiệu sách.","Wǒ xǐhuan yí ge rén guàng shūdiàn."]]},{"t":"Đuôi 洲 cho tên châu lục","b":"亚洲 · 欧洲 · 非洲 · 美洲 · 澳洲","d":"洲 nghĩa là châu lục, có bộ 氵 vì châu lục là vùng đất giữa biển. Người Việt gọi Á châu, Âu châu, Phi châu — cùng một hệ thống.","ex":[["他去过亚洲和欧洲。","Anh ấy từng đi châu Á và châu Âu.","Tā qù guo Yàzhōu hé Ōuzhōu."]]}],"items":[{"zh":"参观","py":"cānguān","vi":"tham quan","hv":"tham quan","note":"Chính là \"tham quan\" tiếng Việt: 参 (tham) + 观 (quan, xem). Dùng cho nơi chốn: 参观博物馆.","ex":"导游带我们参观了三个地方。","exPy":"Dǎoyóu dài wǒmen cānguān le sān ge dìfang.","exVi":"Hướng dẫn viên đưa chúng tôi thăm ba nơi.","w":"导游 带 我们 参观 了 三 个 地方。"},{"zh":"景色","py":"jǐngsè","vi":"cảnh sắc","hv":"cảnh sắc","note":"Chính là \"cảnh sắc\" tiếng Việt: 景 (cảnh) + 色 (sắc, bài 21 trong 颜色).","ex":"秋天山上的景色最美。","exPy":"Qiūtiān shān shàng de jǐngsè zuì měi.","exVi":"Mùa thu cảnh trên núi đẹp nhất.","w":"秋天 山 上 的 景色 最 美。"},{"zh":"风景","py":"fēngjǐng","vi":"phong cảnh","hv":"phong cảnh","note":"Chính là \"phong cảnh\" tiếng Việt: 风 (phong, gió) + 景 (cảnh). Gần nghĩa 景色, dùng thay nhau được.","ex":"这里风景好，空气也新鲜。","exPy":"Zhèlǐ fēngjǐng hǎo, kōngqì yě xīnxiān.","exVi":"Ở đây phong cảnh đẹp, không khí cũng trong lành.","w":"这里 风景 好， 空气 也 新鲜。"},{"zh":"长城","py":"Chángchéng","vi":"Vạn Lý Trường Thành","hv":"Trường Thành","note":"Chính là \"Trường Thành\" tiếng Việt: 长 (trường, dài) + 城 (thành). Tên đủ là 万里长城.","ex":"长城是世界有名的古迹。","exPy":"Chángchéng shì shìjiè yǒumíng de gǔjì.","exVi":"Trường Thành là di tích nổi tiếng thế giới.","w":"长城 是 世界 有名 的 古迹。"},{"zh":"长江","py":"Chángjiāng","vi":"sông Trường Giang","hv":"Trường Giang","note":"Chính là \"Trường Giang\" tiếng Việt. Con sông dài nhất Trung Quốc, cùng với 黄河 (bài 58) làm nên nền văn minh Hoa Hạ.","ex":"长江经过很多大城市。","exPy":"Chángjiāng jīngguò hěn duō dà chéngshì.","exVi":"Trường Giang chảy qua nhiều thành phố lớn.","w":"长江 经过 很 多 大 城市。"},{"zh":"首都","py":"shǒudū","vi":"thủ đô","hv":"thủ đô","note":"Chính là \"thủ đô\" tiếng Việt: 首 (thủ, đầu) + 都 (đô). Chú ý 都 ở đây đọc dū, khác 都 dōu (đều).","ex":"越南的首都是河内。","exPy":"Yuènán de shǒudū shì Hénèi.","exVi":"Thủ đô Việt Nam là Hà Nội.","w":"越 南 的 首都 是 河 内。"},{"zh":"亚洲","py":"Yàzhōu","vi":"châu Á","hv":"Á châu","note":"Chính là \"Á châu\" tiếng Việt: 亚 (Á) + 洲 (châu). Các châu khác: 欧洲 (Âu), 非洲 (Phi), 美洲 (Mỹ).","ex":"亚洲是最大的洲。","exPy":"Yàzhōu shì zuì dà de zhōu.","exVi":"Châu Á là châu lục lớn nhất.","w":"亚洲 是 最 大 的 洲。"},{"zh":"地球","py":"dìqiú","vi":"trái đất","hv":"địa cầu","note":"Chính là \"địa cầu\" tiếng Việt: 地 (địa) + 球 (cầu, quả bóng).","ex":"地球只有一个，要好好保护。","exPy":"Dìqiú zhǐ yǒu yí ge, yào hǎohǎo bǎohù.","exVi":"Trái đất chỉ có một, phải bảo vệ cho tốt.","w":"地球 只有 一 个， 要好 好 保护。"},{"zh":"海洋","py":"hǎiyáng","vi":"biển cả, đại dương","hv":"hải dương","note":"Chính là \"hải dương\" tiếng Việt: 海 (hải) + 洋 (dương). Cả hai đều có bộ 氵.","ex":"我从来没见过海洋。","exPy":"Wǒ cónglái méi jiàn guo hǎiyáng.","exVi":"Tôi chưa bao giờ nhìn thấy biển.","w":"我 从来 没 见 过 海洋。"},{"zh":"森林","py":"sēnlín","vi":"rừng","hv":"sâm lâm","note":"Chữ đẹp nhất bài: 森 là BA chữ 木 (cây), 林 là HAI chữ 木. Nhiều cây thành rừng — nhìn là hiểu ngay.","ex":"森林里空气特别好。","exPy":"Sēnlín lǐ kōngqì tèbié hǎo.","exVi":"Trong rừng không khí đặc biệt tốt.","w":"森林 里 空气 特别 好。"}],"newChars":["景","江","亚","洲","海","洋","森","林"],"outro":"很好！Xong bài 124."};
G.ROOMS["zh-l125"] = {"id":"zh-l125","lang":"zh","level":4,"no":125,"teacher":"wang","title":"HSK4 · Bài 125 · 自然和污染 Thiên nhiên và ô nhiễm","intro":["北方和南方的气候很不一样。","Bài 125: Nói về khí hậu, cây cỏ, loài vật và vấn đề môi trường. Bấm 1 · Học để bắt đầu."],"introPy":"Běifāng hé nánfāng de qìhòu hěn bù yíyàng.","gram":{"t":"气候 và 天气 — dài hạn hay hôm nay?","b":"气候 = đặc điểm khí hậu của vùng · 天气 = thời tiết cụ thể","d":"北京的气候很干 (khí hậu Bắc Kinh khô — nói chung, quanh năm). 今天天气很好 (thời tiết hôm nay đẹp — cụ thể). Nói 今天气候很好 là sai.","ex":[["这里的气候适合种水果。","Khí hậu ở đây hợp trồng cây ăn quả.","Zhèlǐ de qìhòu shìhé zhòng shuǐguǒ."],["明天天气怎么样？","Thời tiết mai thế nào?","Míngtiān tiānqì zěnmeyàng?"]]},"grams":[{"t":"气候 và 天气 — dài hạn hay hôm nay?","b":"气候 = đặc điểm khí hậu của vùng · 天气 = thời tiết cụ thể","d":"北京的气候很干 (khí hậu Bắc Kinh khô — nói chung, quanh năm). 今天天气很好 (thời tiết hôm nay đẹp — cụ thể). Nói 今天气候很好 là sai.","ex":[["这里的气候适合种水果。","Khí hậu ở đây hợp trồng cây ăn quả.","Zhèlǐ de qìhòu shìhé zhòng shuǐguǒ."],["明天天气怎么样？","Thời tiết mai thế nào?","Míngtiān tiānqì zěnmeyàng?"]]},{"t":"光 làm bổ ngữ — hết sạch","b":"động từ + 光","d":"吃光 (ăn sạch), 卖光 (bán hết), 用光 (dùng hết). Cùng nhóm bổ ngữ kết quả với 完 (bài 23), nhưng 光 nhấn mạnh KHÔNG CÒN GÌ.","ex":[["票已经卖光了。","Vé đã bán hết sạch.","Piào yǐjīng mài guāng le."],["钱花光了。","Tiền tiêu hết nhẵn rồi.","Qián huā guāng le."]]},{"t":"Lượng từ cho gia súc: 头 và 只","b":"一头猪 · 一头牛 · 一只鸡 · 一只老虎","d":"头 (đầu) dùng cho gia súc lớn — lợn, bò, trâu. 只 dùng cho con vật nhỏ và gia cầm. Tiếng Việt cũng đếm \"một đầu lợn\" trong cách nói cổ.","ex":[["农民养了三头牛。","Nông dân nuôi ba con bò.","Nóngmín yǎng le sān tóu niú."]]}],"items":[{"zh":"气候","py":"qìhòu","vi":"khí hậu","hv":"khí hậu","note":"Chính là \"khí hậu\" tiếng Việt: 气 (khí) + 候 (hậu). Khác 天气 (thời tiết hôm nay) — 气候 là đặc điểm lâu dài của một vùng.","ex":"北方和南方的气候很不一样。","exPy":"Běifāng hé nánfāng de qìhòu hěn bù yíyàng.","exVi":"Khí hậu miền Bắc và miền Nam rất khác nhau.","w":"北方 和 南方 的 气候 很 不 一样。"},{"zh":"温度","py":"wēndù","vi":"nhiệt độ","hv":"ôn độ","note":"温 (ấm) + 度 (độ). Tiếng Việt: \"ôn hoà\", \"ôn đới\". Hỏi nhiệt độ: 今天多少度？","ex":"冬天的温度常常低于零度。","exPy":"Dōngtiān de wēndù chángcháng dī yú líng dù.","exVi":"Nhiệt độ mùa đông thường dưới không độ.","w":"冬天 的 温度 常常 低于 零 度。"},{"zh":"阳光","py":"yángguāng","vi":"ánh nắng","hv":"dương quang","note":"阳 (dương, mặt trời — bài 46 trong 太阳) + 光 (ánh sáng).","ex":"早上的阳光照进了房间。","exPy":"Zǎoshang de yángguāng zhào jìn le fángjiān.","exVi":"Nắng sớm rọi vào phòng.","w":"早上 的 阳光 照 进 了 房间。"},{"zh":"叶子","py":"yèzi","vi":"chiếc lá","hv":"diệp tử","note":"Tiếng Việt: \"diệp\" trong \"diệp lục\", \"kim chi ngọc diệp\". Bộ 艹 ở trên.","ex":"秋天的叶子红了。","exPy":"Qiūtiān de yèzi hóng le.","exVi":"Lá mùa thu đỏ rồi.","w":"秋天 的 叶子 红 了。"},{"zh":"竹子","py":"zhúzi","vi":"cây tre, trúc","hv":"trúc tử","note":"竹 chính là bộ thủ \"trúc\" đã học. Gấu trúc 熊猫 ăn 竹子 — hai từ này đi liền nhau.","ex":"南方有很多竹子。","exPy":"Nánfāng yǒu hěn duō zhúzi.","exVi":"Miền Nam có nhiều tre.","w":"南方 有 很 多 竹子。"},{"zh":"老虎","py":"lǎohǔ","vi":"con hổ","hv":"lão hổ","note":"Chính là \"lão hổ\" tiếng Việt. Chữ 虎 có bộ 虍 tượng hình đầu hổ. Chữ 老 ở đây chỉ là tiền tố quen thuộc.","ex":"老虎是很危险的动物。","exPy":"Lǎohǔ shì hěn wēixiǎn de dòngwù.","exVi":"Hổ là loài vật rất nguy hiểm.","w":"老虎 是 很 危险 的 动物。"},{"zh":"猪","py":"zhū","vi":"con lợn","hv":"trư","note":"Tiếng Việt: \"trư\" trong \"Trư Bát Giới\". Bộ 犭 (thú bốn chân). Nhắc lại: 家 = 宀 + 豕 (lợn dưới mái nhà).","ex":"这个菜是猪肉做的。","exPy":"Zhège cài shì zhūròu zuò de.","exVi":"Món này làm từ thịt lợn.","w":"这个 菜 是 猪 肉 做 的。"},{"zh":"污染","py":"wūrǎn","vi":"ô nhiễm","hv":"ô nhiễm","note":"Chính là \"ô nhiễm\" tiếng Việt: 污 (ô, bẩn) + 染 (nhiễm). Cả hai đều có bộ 氵.","ex":"工厂造成了很严重的污染。","exPy":"Gōngchǎng zàochéng le hěn yánzhòng de wūrǎn.","exVi":"Nhà máy gây ô nhiễm rất nghiêm trọng.","w":"工厂 造成 了 很 严重 的 污染。"},{"zh":"光","py":"guāng","vi":"ánh sáng; hết sạch","hv":"quang","note":"Chính là \"quang\" tiếng Việt (\"quang minh\", \"ánh quang\"). Còn nghĩa \"hết nhẵn\": 吃光了 (ăn sạch).","ex":"房间里一点儿光都没有。","exPy":"Fángjiān lǐ yìdiǎnr guāng dōu méiyǒu.","exVi":"Trong phòng chẳng có chút ánh sáng nào.","w":"房间 里 一点儿 光 都 没有。"},{"zh":"火","py":"huǒ","vi":"lửa","hv":"hoả","note":"Bộ thủ đã học. Tiếng Việt: \"hoả\" trong \"hoả hoạn\", \"hoả xa\". 着火了！= cháy rồi!","ex":"用火以后一定要检查。","exPy":"Yòng huǒ yǐhòu yídìng yào jiǎnchá.","exVi":"Dùng lửa xong nhất định phải kiểm tra.","w":"用 火 以后 一定 要 检查。"}],"newChars":["温","光","叶","竹","猪","污","染"],"outro":"很好！Xong bài 125."};
G.ROOMS["zh-l126"] = {"id":"zh-l126","lang":"zh","level":4,"no":126,"teacher":"wang","title":"HSK4 · Bài 126 · 频率和过去 Tần suất và chuyện đã qua","intro":["平时他很安静，喝了酒就爱说话。","Bài 126: Nhóm phó từ thời gian tinh tế nhất HSK 4 — 本来, 原来, 从来, 往往. Bấm 1 · Học để bắt đầu."],"introPy":"Píngshí tā hěn ānjìng, hē le jiǔ jiù ài shuōhuà.","gram":{"t":"本来 và 原来 — hai chữ \"vốn dĩ\"","b":"本来 = ý định ban đầu (rồi đổi) · 原来 = hoá ra (vỡ lẽ)","d":"我本来想去 nhấn vào KẾ HOẠCH cũ đã thay đổi. 原来你也在 nhấn vào sự BẤT NGỜ vừa nhận ra. Đây là cặp người Việt hay dùng lẫn vì tiếng Việt đều nói \"vốn\", \"hoá ra\".","ex":[["我本来要买这个，后来买了那个。","Ban đầu tôi định mua cái này, sau lại mua cái kia.","Wǒ běnlái yào mǎi zhège, hòulái mǎi le nàge."],["原来他早就知道了。","Hoá ra anh ấy biết từ lâu rồi.","Yuánlái tā zǎo jiù zhīdào le."]]},"grams":[{"t":"本来 và 原来 — hai chữ \"vốn dĩ\"","b":"本来 = ý định ban đầu (rồi đổi) · 原来 = hoá ra (vỡ lẽ)","d":"我本来想去 nhấn vào KẾ HOẠCH cũ đã thay đổi. 原来你也在 nhấn vào sự BẤT NGỜ vừa nhận ra. Đây là cặp người Việt hay dùng lẫn vì tiếng Việt đều nói \"vốn\", \"hoá ra\".","ex":[["我本来要买这个，后来买了那个。","Ban đầu tôi định mua cái này, sau lại mua cái kia.","Wǒ běnlái yào mǎi zhège, hòulái mǎi le nàge."],["原来他早就知道了。","Hoá ra anh ấy biết từ lâu rồi.","Yuánlái tā zǎo jiù zhīdào le."]]},{"t":"从来 gần như luôn đi với phủ định","b":"从来不 + động từ · 从来没 + động từ + 过","d":"从来不 phủ định thói quen (không bao giờ làm). 从来没…过 phủ định kinh nghiệm (chưa từng làm lần nào). Nhắc lại cấu trúc 过 ở bài 25.","ex":[["他从来不迟到。","Anh ấy không bao giờ đến muộn.","Tā cónglái bù chídào."],["我从来没去过日本。","Tôi chưa từng đi Nhật.","Wǒ cónglái méi qù guo Rìběn."]]},{"t":"往往 và 经常 — quy luật hay thói quen?","b":"往往 = quy luật khách quan (chỉ quá khứ) · 经常 = tần suất (mọi thì)","d":"冬天往往下雪 (mùa đông hay có tuyết — quy luật tự nhiên đã quan sát). 我经常去图书馆 (tôi thường đi thư viện — thói quen của tôi). Nói 明天往往下雨 là SAI vì 往往 không dùng cho tương lai.","ex":[["周末的商店往往人很多。","Cửa hàng cuối tuần thường rất đông.","Zhōumò de shāngdiàn wǎngwǎng rén hěn duō."],["我经常给妈妈打电话。","Tôi thường gọi điện cho mẹ.","Wǒ jīngcháng gěi māma dǎ diànhuà."]]}],"items":[{"zh":"平时","py":"píngshí","vi":"ngày thường, bình thường","hv":"bình thời","note":"平 (bình thường) + 时 (thời). Chỉ khoảng thời gian thông thường, đối lại với dịp đặc biệt.","ex":"平时他很安静，喝了酒就爱说话。","exPy":"Píngshí tā hěn ānjìng, hē le jiǔ jiù ài shuōhuà.","exVi":"Ngày thường anh ấy trầm, uống rượu vào là nói nhiều.","w":"平时 他 很 安静， 喝 了 酒 就 爱 说话。"},{"zh":"从来","py":"cónglái","vi":"từ trước tới nay","hv":"tòng lai","note":"Hầu như LUÔN dùng với phủ định: 从来不 (chưa bao giờ), 从来没 (chưa từng). Ít khi dùng câu khẳng định.","ex":"我从来没吃过这么辣的菜。","exPy":"Wǒ cónglái méi chī guo zhème là de cài.","exVi":"Tôi chưa từng ăn món cay thế này.","w":"我 从来 没 吃 过 这么 辣 的 菜。"},{"zh":"往往","py":"wǎngwǎng","vi":"thường thường, hay là","hv":"vãng vãng","note":"Chỉ quy luật KHÁCH QUAN đã quan sát được, khác 经常 chỉ tần suất chủ quan. Không dùng cho tương lai.","ex":"努力的人往往运气也不错。","exPy":"Nǔlì de rén wǎngwǎng yùnqi yě búcuò.","exVi":"Người chăm chỉ thường cũng gặp may.","w":"努力 的 人 往往 运气 也 不错。"},{"zh":"偶尔","py":"ǒu'ěr","vi":"thỉnh thoảng","hv":"ngẫu nhĩ","note":"偶 = \"ngẫu\" trong \"ngẫu nhiên\". Tần suất thấp nhất trong thang: 偶尔 < 有时候 < 经常 < 总是.","ex":"我偶尔会想起小时候的事。","exPy":"Wǒ ǒu'ěr huì xiǎng qǐ xiǎo shíhou de shì.","exVi":"Thỉnh thoảng tôi nhớ chuyện hồi nhỏ.","w":"我 偶尔 会 想 起 小时候 的 事。"},{"zh":"暂时","py":"zànshí","vi":"tạm thời","hv":"tạm thời","note":"Chính là \"tạm thời\" tiếng Việt: 暂 (tạm) + 时 (thời).","ex":"这个问题暂时还没有答案。","exPy":"Zhège wèntí zànshí hái méiyǒu dá'àn.","exVi":"Vấn đề này tạm thời chưa có đáp án.","w":"这个 问题 暂时 还 没有 答案。"},{"zh":"将来","py":"jiānglái","vi":"tương lai","hv":"tương lai","note":"Chính là \"tương lai\" tiếng Việt: 将 (tương, sắp) + 来 (lai, đến).","ex":"将来的事谁也说不准。","exPy":"Jiānglái de shì shéi yě shuō bu zhǔn.","exVi":"Chuyện tương lai chẳng ai nói chắc được.","w":"将来 的 事 谁 也 说 不准。"},{"zh":"本来","py":"běnlái","vi":"vốn dĩ, ban đầu","hv":"bản lai","note":"Tiếng Việt: \"bản lai diện mục\" (bộ mặt vốn có). Nêu ý định BAN ĐẦU, thường kèm sự thay đổi sau đó.","ex":"我本来打算今天去，可是下雨了。","exPy":"Wǒ běnlái dǎsuàn jīntiān qù, kěshì xiàyǔ le.","exVi":"Vốn tôi định hôm nay đi, nhưng lại mưa.","w":"我 本来 打算 今天 去， 可是 下雨 了。"},{"zh":"原来","py":"yuánlái","vi":"hoá ra; vốn là","hv":"nguyên lai","note":"Hai nghĩa: \"hoá ra\" (vỡ lẽ điều mới biết) và \"vốn dĩ\" (giống 本来). Nghĩa \"hoá ra\" hay gặp hơn.","ex":"原来这本书是你的！","exPy":"Yuánlái zhè běn shū shì nǐ de!","exVi":"Hoá ra quyển sách này của bạn!","w":"原来 这 本 书 是 你 的！"},{"zh":"当时","py":"dāngshí","vi":"lúc đó, khi ấy","hv":"đương thời","note":"Chính là \"đương thời\" tiếng Việt: 当 (đương) + 时 (thời). Chỉ một thời điểm trong quá khứ đang kể.","ex":"当时我一句汉语也不会说。","exPy":"Dāngshí wǒ yí jù Hànyǔ yě bú huì shuō.","exVi":"Lúc đó tôi không nói nổi một câu tiếng Trung.","w":"当时 我 一 句 汉语 也 不 会 说。"},{"zh":"及时","py":"jíshí","vi":"kịp thời","hv":"cập thời","note":"Chính là \"kịp thời\" tiếng Việt: 及 (cập, kịp) + 时 (thời).","ex":"谢谢你及时提醒我。","exPy":"Xièxie nǐ jíshí tíxǐng wǒ.","exVi":"Cảm ơn bạn đã nhắc tôi kịp thời.","w":"谢谢 你 及时 提醒 我。"}],"newChars":["偶","尔","暂","将","及"],"outro":"很好！Xong bài 126."};
G.ROOMS["zh-l127"] = {"id":"zh-l127","lang":"zh","level":4,"no":127,"teacher":"wang","title":"HSK4 · Bài 127 · 准时和迟到 Đúng giờ và trễ hẹn","intro":["请大家按时完成任务。","Bài 127: Nói về hẹn giờ, hoãn, kịp hay không kịp — rất cần khi làm việc với người Trung Quốc. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐng dàjiā ànshí wánchéng rènwu.","gram":{"t":"按时 và 准时 — theo lịch hay đúng khắc?","b":"按时 = theo đúng lịch trình lặp lại · 准时 = đúng khắc giờ hẹn","d":"按时吃饭, 按时睡觉, 按时吃药 (đều đặn theo lịch). 准时到, 准时开始 (đúng khắc thời điểm). Nói 准时吃药 nghe kỳ vì thuốc uống nhiều lần trong ngày.","ex":[["医生说要按时吃药。","Bác sĩ nói phải uống thuốc đúng cữ.","Yīshēng shuō yào ànshí chī yào."],["飞机准时起飞了。","Máy bay cất cánh đúng giờ.","Fēijī zhǔnshí qǐfēi le."]]},"grams":[{"t":"按时 và 准时 — theo lịch hay đúng khắc?","b":"按时 = theo đúng lịch trình lặp lại · 准时 = đúng khắc giờ hẹn","d":"按时吃饭, 按时睡觉, 按时吃药 (đều đặn theo lịch). 准时到, 准时开始 (đúng khắc thời điểm). Nói 准时吃药 nghe kỳ vì thuốc uống nhiều lần trong ngày.","ex":[["医生说要按时吃药。","Bác sĩ nói phải uống thuốc đúng cữ.","Yīshēng shuō yào ànshí chī yào."],["飞机准时起飞了。","Máy bay cất cánh đúng giờ.","Fēijī zhǔnshí qǐfēi le."]]},{"t":"来得及 và 来不及","b":"还来得及 (còn kịp) · 来不及了 (không kịp rồi)","d":"Đây là cặp câu bạn dùng liên tục khi đi lại và hẹn hò. Có thể thêm động từ ở sau: 来不及吃早饭 (không kịp ăn sáng).","ex":[["现在出发还来得及吗？","Giờ xuất phát còn kịp không?","Xiànzài chūfā hái láidejí ma?"],["我来不及跟他说再见。","Tôi không kịp chào tạm biệt anh ấy.","Wǒ láibují gēn tā shuō zàijiàn."]]},{"t":"期间 đứng SAU cụm thời gian","b":"[thời gian] + 期间","d":"放假期间, 考试期间, 出差期间. Ngược với tiếng Việt nói \"trong kỳ nghỉ\" (giới từ đứng trước). Đây lại là quy tắc \"từ chỉ vị trí/thời gian đứng sau\" đã gặp từ bài 11.","ex":[["考试期间图书馆人很多。","Trong kỳ thi thư viện rất đông.","Kǎoshì qījiān túshūguǎn rén hěn duō."]]}],"items":[{"zh":"按时","py":"ànshí","vi":"đúng giờ (theo lịch)","hv":"án thời","note":"按 (theo, bài 104 trong 按照) + 时 (giờ). Nhấn vào việc tuân theo lịch đã định: 按时吃药.","ex":"请大家按时完成任务。","exPy":"Qǐng dàjiā ànshí wánchéng rènwu.","exVi":"Xin mọi người hoàn thành nhiệm vụ đúng hạn.","w":"请 大家 按时 完成 任务。"},{"zh":"准时","py":"zhǔnshí","vi":"đúng giờ (không sớm không muộn)","hv":"chuẩn thời","note":"准 (chuẩn, bài 73 trong 标准) + 时. Nhấn vào ĐÚNG KHẮC giờ hẹn: 准时到.","ex":"开会请准时参加。","exPy":"Kāihuì qǐng zhǔnshí cānjiā.","exVi":"Họp xin dự đúng giờ.","w":"开会 请 准时 参加。"},{"zh":"提前","py":"tíqián","vi":"làm sớm hơn dự định","hv":"đề tiền","note":"提 (nâng, bài 94) + 前 (trước). Kéo việc lên sớm hơn. Trái nghĩa với 推迟.","ex":"我们提前半个小时到了机场。","exPy":"Wǒmen tíqián bàn ge xiǎoshí dào le jīchǎng.","exVi":"Chúng tôi tới sân bay sớm nửa tiếng.","w":"我们 提前 半 个 小时 到 了 机场。"},{"zh":"推迟","py":"tuīchí","vi":"hoãn lại","hv":"thôi trì","note":"推 (đẩy, bài 91) + 迟 (chậm, bài 51 trong 迟到). Đẩy việc lùi về sau.","ex":"因为下雨，运动会推迟了。","exPy":"Yīnwèi xiàyǔ, yùndònghuì tuīchí le.","exVi":"Vì mưa, hội thao bị hoãn.","w":"因为 下雨， 运动会 推迟 了。"},{"zh":"来不及","py":"láibují","vi":"không kịp","hv":"lai bất cập","note":"来 (đến) + 不及 (không kịp). Tiếng Việt: \"bất cập\". Cặp đối với 来得及.","ex":"再不走就来不及了。","exPy":"Zài bù zǒu jiù láibují le.","exVi":"Không đi ngay là không kịp mất.","w":"再 不 走 就 来不及 了。"},{"zh":"来得及","py":"láidejí","vi":"còn kịp","hv":"lai đắc cập","note":"Cấu trúc 得/不 chèn giữa, giống 听得懂 / 听不懂 ở bài 19.","ex":"别着急，时间还来得及。","exPy":"Bié zháojí, shíjiān hái láidejí.","exVi":"Đừng vội, thời gian vẫn còn kịp.","w":"别 着急， 时间 还 来得及。"},{"zh":"秒","py":"miǎo","vi":"giây","hv":"miểu","note":"Bộ 禾 (lúa) — vốn chỉ sợi râu lúa, thứ nhỏ nhất. Bộ ba đơn vị: 秒 → 分 → 小时.","ex":"他跑一百米只用了十二秒。","exPy":"Tā pǎo yìbǎi mǐ zhǐ yòng le shí'èr miǎo.","exVi":"Anh ấy chạy trăm mét chỉ mất mười hai giây.","w":"他 跑 一 百 米 只 用 了 十 二 秒。"},{"zh":"期间","py":"qījiān","vi":"trong thời gian, thời kỳ","hv":"kỳ gian","note":"期 (kỳ, bài 47 trong 季节) + 间 (gian). Đứng SAU cụm chỉ thời gian: 放假期间.","ex":"出差期间他每天给家里打电话。","exPy":"Chūchāi qījiān tā měi tiān gěi jiā lǐ dǎ diànhuà.","exVi":"Trong thời gian công tác ngày nào anh ấy cũng gọi về nhà.","w":"出差 期间 他 每 天 给 家 里 打电话。"},{"zh":"同时","py":"tóngshí","vi":"đồng thời, cùng lúc","hv":"đồng thời","note":"Chính là \"đồng thời\" tiếng Việt: 同 (đồng) + 时 (thời).","ex":"他同时做着两份工作。","exPy":"Tā tóngshí zuò zhe liǎng fèn gōngzuò.","exVi":"Anh ấy làm hai việc cùng lúc.","w":"他 同时 做 着 两 份 工作。"},{"zh":"陆续","py":"lùxù","vi":"lần lượt, lũ lượt","hv":"lục tục","note":"Chính là \"lục tục\" tiếng Việt. Chỉ nhiều người hoặc việc xảy ra nối tiếp, không cùng lúc — trái với 同时.","ex":"学生们陆续走进了教室。","exPy":"Xuéshengmen lùxù zǒu jìn le jiàoshì.","exVi":"Học sinh lần lượt bước vào lớp.","w":"学生 们 陆续 走 进 了 教室。"}],"newChars":["推","秒","陆"],"outro":"很好！Xong bài 127."};
G.ROOMS["zh-l128"] = {"id":"zh-l128","lang":"zh","level":4,"no":128,"teacher":"wang","title":"HSK4 · Bài 128 · 手上的动作 Động tác của tay","intro":["这个门是拉的，不是推的。","Bài 128: Mười động từ tay — và thấy sức mạnh của bộ 扌 khi đoán nghĩa. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège mén shì lā de, bú shì tuī de.","gram":{"t":"Bộ 扌 — nhìn là biết động tác của tay","b":"拉 · 推 · 抬 · 拍 · 抱 · 指 · 擦 · 打 · 找 · 换","d":"Tám trong mười từ bài này mang bộ 扌 (đề thủ bàng). Gặp chữ lạ có bộ này, bạn đoán ngay đó là một hành động làm bằng tay — đã hiểu được nửa nghĩa mà chưa cần tra.","ex":[["拉 · 推 · 抬 · 拍","kéo · đẩy · khiêng · vỗ","lā · tuī · tái · pāi"],["抱 · 指 · 擦","ôm · chỉ · lau","bào · zhǐ · cā"]]},"grams":[{"t":"Bộ 扌 — nhìn là biết động tác của tay","b":"拉 · 推 · 抬 · 拍 · 抱 · 指 · 擦 · 打 · 找 · 换","d":"Tám trong mười từ bài này mang bộ 扌 (đề thủ bàng). Gặp chữ lạ có bộ này, bạn đoán ngay đó là một hành động làm bằng tay — đã hiểu được nửa nghĩa mà chưa cần tra.","ex":[["拉 · 推 · 抬 · 拍","kéo · đẩy · khiêng · vỗ","lā · tuī · tái · pāi"],["抱 · 指 · 擦","ôm · chỉ · lau","bào · zhǐ · cā"]]},{"t":"拉 và 推 — hai chữ trên mọi cánh cửa","b":"拉 = kéo · 推 = đẩy","d":"Hai chữ này dán trên cửa khắp Trung Quốc. Nhớ được là không còn cảnh đẩy nhầm cửa kéo. Mẹo: 推 có bộ 扌 và 隹 (chim) — đẩy cho chim bay đi.","ex":[["门上写着「推」。","Trên cửa ghi chữ \"đẩy\".","Mén shàng xiě zhe \"tuī\"."]]},{"t":"Động từ + 着 tả tư thế đang giữ","b":"抱着 · 指着 · 拿着 · 戴着","d":"Nhắc lại 着 ở bài 29. Với động từ tay, 着 tả TRẠNG THÁI đang duy trì: 抱着孩子 (đang bế con), 拿着一本书 (đang cầm quyển sách). Rất hay dùng để tả người trong ảnh.","ex":[["他手里拿着一把伞。","Tay anh ấy cầm một cái ô.","Tā shǒu lǐ ná zhe yì bǎ sǎn."]]}],"items":[{"zh":"拉","py":"lā","vi":"kéo","hv":"lạp","note":"Bộ 扌 (tay). Trái nghĩa với 推. Cửa ở Trung Quốc ghi 拉 (kéo) và 推 (đẩy).","ex":"这个门是拉的，不是推的。","exPy":"Zhège mén shì lā de, bú shì tuī de.","exVi":"Cửa này là kéo, không phải đẩy.","w":"这个 门 是 拉 的， 不 是 推 的。"},{"zh":"推","py":"tuī","vi":"đẩy","hv":"thôi","note":"Bộ 扌. Tiếng Việt: \"thôi thúc\", \"thôi động\". Cũng có trong 推迟 (bài 90).","ex":"请帮我推一下车。","exPy":"Qǐng bāng wǒ tuī yíxià chē.","exVi":"Giúp tôi đẩy xe một chút.","w":"请 帮 我 推 一下 车。"},{"zh":"抬","py":"tái","vi":"khiêng, nhấc lên","hv":"đài","note":"Bộ 扌. Khiêng vật nặng bằng nhiều người, hoặc nhấc lên: 抬头 (ngẩng đầu).","ex":"箱子太重，两个人才抬得动。","exPy":"Xiāngzi tài zhòng, liǎng ge rén cái tái de dòng.","exVi":"Thùng nặng quá, hai người mới khiêng nổi.","w":"箱子 太 重， 两 个人 才 抬 得 动。"},{"zh":"举","py":"jǔ","vi":"giơ lên; nêu ra","hv":"cử","note":"Chính là \"cử\" tiếng Việt (\"cử chỉ\", \"cử tạ\"). 举手 (giơ tay), 举例子 (nêu ví dụ). Cũng có trong 举办, 举行 (bài 95).","ex":"知道答案的同学请举手。","exPy":"Zhīdào dá'àn de tóngxué qǐng jǔ shǒu.","exVi":"Bạn nào biết đáp án xin giơ tay.","w":"知道 答案 的 同学 请 举 手。"},{"zh":"拍","py":"pāi","vi":"vỗ; chụp (ảnh)","hv":"phách","note":"Bộ 扌. Hai nghĩa: vỗ tay (拍手) và chụp ảnh (拍照). Cũng là dụng cụ: 球拍 (cái vợt).","ex":"我们在长城前拍了很多照片。","exPy":"Wǒmen zài Chángchéng qián pāi le hěn duō zhàopiàn.","exVi":"Chúng tôi chụp nhiều ảnh trước Trường Thành.","w":"我们 在 长城 前 拍 了 很 多 照片。"},{"zh":"敲","py":"qiāo","vi":"gõ","hv":"xao","note":"Tiếng Việt: \"xao\" trong \"lao xao\". 敲门 (gõ cửa) — phép lịch sự bắt buộc trước khi vào phòng.","ex":"有人在敲门，去看看。","exPy":"Yǒu rén zài qiāo mén, qù kànkan.","exVi":"Có người gõ cửa, ra xem đi.","w":"有 人 在 敲 门， 去 看 看。"},{"zh":"抱","py":"bào","vi":"ôm, bế","hv":"bão","note":"Bộ 扌 + 包 (bọc, bài 43). Nghĩa đen: dùng tay bọc lấy. Cũng có trong 抱歉 (bài 64).","ex":"很久没见，他抱了抱我。","exPy":"Hěn jiǔ méi jiàn, tā bào le bào wǒ.","exVi":"Lâu không gặp, anh ấy ôm tôi một cái.","w":"很 久 没 见， 他 抱 了 抱 我。"},{"zh":"指","py":"zhǐ","vi":"chỉ (bằng ngón tay); ngón tay","hv":"chỉ","note":"Chính là \"chỉ\" tiếng Việt. Bộ 扌. Ngón tay là 手指. Chỉ vào người khác bị coi là bất lịch sự.","ex":"用手指着别人不礼貌。","exPy":"Yòng shǒu zhǐ zhe biéren bù lǐmào.","exVi":"Chỉ tay vào người khác là bất lịch sự.","w":"用 手指 着 别人 不 礼貌。"},{"zh":"擦","py":"cā","vi":"lau, chùi","hv":"sát","note":"Bộ 扌. Tiếng Việt: \"sát\" trong \"ma sát\", \"cọ xát\". 擦桌子 (lau bàn), 擦黑板 (lau bảng).","ex":"吃完饭请把桌子擦一擦。","exPy":"Chī wán fàn qǐng bǎ zhuōzi cā yi cā.","exVi":"Ăn xong xin lau bàn một chút.","w":"吃 完 饭 请 把 桌子 擦 一 擦。"},{"zh":"弹钢琴","py":"tán gāngqín","vi":"chơi đàn dương cầm","hv":"đàn cương cầm","note":"弹 (gảy, bật) + 钢琴 (piano — 钢 thép + 琴 đàn). Tiếng Việt gọi \"dương cầm\"; chữ 弹 chính là \"đàn\".","ex":"她从五岁开始学弹钢琴。","exPy":"Tā cóng wǔ suì kāishǐ xué tán gāngqín.","exVi":"Cô ấy học piano từ năm tuổi.","w":"她 从 五 岁 开始 学 弹钢琴。"}],"newChars":["拉","抬","举","拍","敲","指","擦","弹","钢","琴"],"outro":"很好！Xong bài 128."};
G.ROOMS["zh-l129"] = {"id":"zh-l129","lang":"zh","level":4,"no":129,"teacher":"wang","title":"HSK4 · Bài 129 · 身体的动作 Động tác của thân","intro":["累了就躺一会儿吧。","Bài 129: Động từ chỉ tư thế và di chuyển, kèm ba động từ ngữ pháp 弄 / 使 / 敢. Bấm 1 · Học để bắt đầu."],"introPy":"Lèi le jiù tǎng yíhuìr ba.","gram":{"t":"弄 — động từ cứu cánh khi bí từ","b":"弄 + bổ ngữ kết quả","d":"弄坏 (làm hỏng), 弄丢 (làm mất), 弄错 (làm sai), 弄清楚 (làm rõ), 弄干净 (làm sạch). Khi chưa nhớ ra động từ chính xác, dùng 弄 vẫn diễn đạt được ý — người bản xứ cũng dùng rất nhiều.","ex":[["对不起，我弄错了。","Xin lỗi, tôi nhầm rồi.","Duìbuqǐ, wǒ nòng cuò le."],["这个问题要弄清楚。","Vấn đề này phải làm cho rõ.","Zhège wèntí yào nòng qīngchu."]]},"grams":[{"t":"弄 — động từ cứu cánh khi bí từ","b":"弄 + bổ ngữ kết quả","d":"弄坏 (làm hỏng), 弄丢 (làm mất), 弄错 (làm sai), 弄清楚 (làm rõ), 弄干净 (làm sạch). Khi chưa nhớ ra động từ chính xác, dùng 弄 vẫn diễn đạt được ý — người bản xứ cũng dùng rất nhiều.","ex":[["对不起，我弄错了。","Xin lỗi, tôi nhầm rồi.","Duìbuqǐ, wǒ nòng cuò le."],["这个问题要弄清楚。","Vấn đề này phải làm cho rõ.","Zhège wèntí yào nòng qīngchu."]]},{"t":"使 và 让 — khiến cho","b":"让 = khẩu ngữ, đời thường · 使 = văn viết, trang trọng","d":"这个消息让我很高兴 (khẩu ngữ). 这个消息使我们感到高兴 (văn viết). Cả hai cùng cấu trúc, chỉ khác sắc thái. Trong bài thi và báo chí, 使 xuất hiện nhiều hơn.","ex":[["音乐使人放松。","Âm nhạc khiến người ta thư giãn.","Yīnyuè shǐ rén fàngsōng."]]},{"t":"Ba tư thế cơ thể","b":"站 đứng · 坐 ngồi · 躺 nằm","d":"Ba động từ này thường đi với 着 để tả trạng thái đang giữ: 站着 (đang đứng), 坐着 (đang ngồi), 躺着 (đang nằm). Kết hợp với 在 + nơi chốn để nói rõ chỗ.","ex":[["他站着看书。","Anh ấy đứng đọc sách.","Tā zhàn zhe kàn shū."],["别躺着玩手机。","Đừng nằm nghịch điện thoại.","Bié tǎng zhe wán shǒujī."]]}],"items":[{"zh":"躺","py":"tǎng","vi":"nằm","hv":"thảng","note":"Bộ ⻊ (chân) + 尚. Bộ ba tư thế: 站 (đứng) — 坐 (ngồi) — 躺 (nằm).","ex":"累了就躺一会儿吧。","exPy":"Lèi le jiù tǎng yíhuìr ba.","exVi":"Mệt thì nằm một lát đi.","w":"累 了 就 躺 一会儿 吧。"},{"zh":"停","py":"tíng","vi":"dừng, đỗ","hv":"đình","note":"Chính là \"đình\" tiếng Việt (\"đình chỉ\", \"tạm đình\"). 停车 (đỗ xe), 雨停了 (mưa tạnh rồi).","ex":"雨停了，我们出发吧。","exPy":"Yǔ tíng le, wǒmen chūfā ba.","exVi":"Mưa tạnh rồi, chúng ta lên đường thôi.","w":"雨 停 了， 我们 出发 吧。"},{"zh":"转","py":"zhuǎn","vi":"quay, rẽ; chuyển","hv":"chuyển","note":"Chính là \"chuyển\" tiếng Việt. Bộ 车 (xe). Đọc zhuǎn là rẽ/chuyển; đọc zhuàn là xoay tròn.","ex":"到红绿灯向左转。","exPy":"Dào hónglǜdēng xiàng zuǒ zhuǎn.","exVi":"Tới đèn giao thông rẽ trái.","w":"到 红绿灯 向 左 转。"},{"zh":"逛","py":"guàng","vi":"dạo chơi, đi lòng vòng","hv":"cuống","note":"Bộ 辶 (đi đường). 逛街 (dạo phố), 逛商店 (đi ngắm cửa hàng) — đi không có mục đích mua cụ thể.","ex":"我们逛了一下午商店。","exPy":"Wǒmen guàng le yí xiàwǔ shāngdiàn.","exVi":"Chúng tôi dạo cửa hàng cả buổi chiều.","w":"我们 逛 了 一下 午 商店。"},{"zh":"散步","py":"sànbù","vi":"đi dạo, tản bộ","hv":"tản bộ","note":"Chính là \"tản bộ\" tiếng Việt: 散 (tản) + 步 (bộ). Động từ ly hợp: 散了半个小时步.","ex":"爷爷每天早上都去公园散步。","exPy":"Yéye měi tiān zǎoshang dōu qù gōngyuán sànbù.","exVi":"Sáng nào ông cũng ra công viên tản bộ.","w":"爷爷 每 天 早上 都 去 公园 散步。"},{"zh":"排队","py":"páiduì","vi":"xếp hàng","hv":"bài đội","note":"排 (sắp, bài 112 trong 排列) + 队 (hàng, đội). Động từ ly hợp: 排了一个小时队.","ex":"买票要排队。","exPy":"Mǎi piào yào páiduì.","exVi":"Mua vé phải xếp hàng.","w":"买 票 要 排队。"},{"zh":"赶","py":"gǎn","vi":"vội đuổi theo, kịp chuyến","hv":"cản","note":"Bộ ⻊ (chân) + 干. 赶飞机 (chạy cho kịp chuyến bay), 赶时间 (gấp gáp về thời gian).","ex":"时间来不及了，我们赶紧走。","exPy":"Shíjiān láibují le, wǒmen gǎnjǐn zǒu.","exVi":"Không kịp giờ rồi, ta đi gấp thôi.","w":"时间 来不及 了， 我们 赶紧 走。"},{"zh":"敢","py":"gǎn","vi":"dám","hv":"cảm","note":"Chính là \"cảm\" trong \"dũng cảm\" (bài 61). Đứng trước động từ: 不敢说 (không dám nói).","ex":"他不敢跟经理说这件事。","exPy":"Tā bù gǎn gēn jīnglǐ shuō zhè jiàn shì.","exVi":"Anh ấy không dám nói việc này với giám đốc.","w":"他 不 敢 跟 经理 说 这 件 事。"},{"zh":"弄","py":"nòng","vi":"làm, nghịch (động từ vạn năng)","hv":"lộng","note":"Động từ thay thế khi không nhớ từ chính xác: 弄坏 (làm hỏng), 弄丢 (làm mất), 弄干净 (làm sạch). Rất tiện khi mới học.","ex":"别把衣服弄脏了。","exPy":"Bié bǎ yīfu nòng zāng le.","exVi":"Đừng làm bẩn quần áo.","w":"别 把 衣服 弄 脏 了。"},{"zh":"使","py":"shǐ","vi":"khiến cho; sử dụng","hv":"sử","note":"Chính là \"sử\" tiếng Việt (\"sử dụng\", \"sai sử\"). Trang trọng hơn 让 (bài 20), hay dùng trong văn viết.","ex":"他的话使大家都笑了。","exPy":"Tā de huà shǐ dàjiā dōu xiào le.","exVi":"Lời anh ấy khiến mọi người đều cười.","w":"他 的话 使 大家 都 笑 了。"}],"newChars":["躺","停","转","逛","散","队","赶","弄"],"outro":"很好！Xong bài 129."};
G.ROOMS["zh-l130"] = {"id":"zh-l130","lang":"zh","level":4,"no":130,"teacher":"wang","title":"HSK4 · Bài 130 · 日常琐事 Việc thường ngày","intro":["对不起，打扰您了。","Bài 130: Nhóm động từ 打, chuyện tiết kiệm và sửa chữa. Bấm 1 · Học để bắt đầu."],"introPy":"Duìbuqǐ, dǎrǎo nín le.","gram":{"t":"Nhóm động từ mở đầu bằng 打","b":"打电话 · 打扰 · 打招呼 · 打针 · 打折 · 打扫 · 打印 · 打算","d":"打 nghĩa gốc là \"đánh\", nhưng ghép với danh từ tạo ra hàng chục động từ chẳng liên quan gì tới việc đánh. Đây là động từ sinh lợi nhất tiếng Trung — gặp 打 + danh từ, hãy học nguyên khối chứ đừng dịch từng chữ.","ex":[["打电话 · 打招呼 · 打针","gọi điện · chào hỏi · tiêm","dǎ diànhuà · dǎ zhāohu · dǎzhēn"],["打扫 · 打印 · 打算","quét dọn · in · dự định","dǎsǎo · dǎyìn · dǎsuàn"]]},"grams":[{"t":"Nhóm động từ mở đầu bằng 打","b":"打电话 · 打扰 · 打招呼 · 打针 · 打折 · 打扫 · 打印 · 打算","d":"打 nghĩa gốc là \"đánh\", nhưng ghép với danh từ tạo ra hàng chục động từ chẳng liên quan gì tới việc đánh. Đây là động từ sinh lợi nhất tiếng Trung — gặp 打 + danh từ, hãy học nguyên khối chứ đừng dịch từng chữ.","ex":[["打电话 · 打招呼 · 打针","gọi điện · chào hỏi · tiêm","dǎ diànhuà · dǎ zhāohu · dǎzhēn"],["打扫 · 打印 · 打算","quét dọn · in · dự định","dǎsǎo · dǎyìn · dǎsuàn"]]},{"t":"节约 ↔ 浪费, và 省 trong khẩu ngữ","b":"节约 (trang trọng) · 省 (khẩu ngữ) · 浪费 (trái nghĩa)","d":"Khẩu hiệu dùng 节约用水. Đời thường nói 省钱, 省时间. 浪费 là mặt trái của cả hai. Người Trung Quốc rất coi trọng 节约 — khen ai đó 很节约 là lời khen.","ex":[["自己做饭比较省钱。","Tự nấu ăn đỡ tốn hơn.","Zìjǐ zuòfàn bǐjiào shěng qián."],["浪费粮食是不好的习惯。","Lãng phí lương thực là thói quen xấu.","Làngfèi liángshi shì bù hǎo de xíguàn."]]},{"t":"打扰一下 — câu mở lời lịch sự nhất","b":"打扰一下，请问…","d":"Khi cần hỏi đường, hỏi giờ, ngắt lời ai đó, mở đầu bằng 打扰一下 là lịch sự nhất. Kết thúc thì nói 不好意思，打扰了 (xin lỗi đã làm phiền).","ex":[["打扰一下，请问这个座位有人吗？","Làm phiền chút, chỗ này có ai ngồi chưa ạ?","Dǎrǎo yíxià, qǐngwèn zhège zuòwèi yǒu rén ma?"]]}],"items":[{"zh":"打扰","py":"dǎrǎo","vi":"làm phiền, quấy rầy","hv":"đả nhiễu","note":"打 (làm) + 扰 (quấy). Câu lịch sự mở đầu: 打扰一下 (làm phiền chút).","ex":"对不起，打扰您了。","exPy":"Duìbuqǐ, dǎrǎo nín le.","exVi":"Xin lỗi đã làm phiền ngài.","w":"对不起， 打扰 您 了。"},{"zh":"打招呼","py":"dǎ zhāohu","vi":"chào hỏi","hv":"đả chiêu hô","note":"招 (vẫy) + 呼 (gọi) — vẫy tay gọi. Là động từ ly hợp: 跟他打了个招呼.","ex":"见到老师要打招呼。","exPy":"Jiàn dào lǎoshī yào dǎ zhāohu.","exVi":"Gặp thầy cô phải chào.","w":"见 到 老师 要 打招呼。"},{"zh":"打针","py":"dǎzhēn","vi":"tiêm","hv":"đả châm","note":"打 (đánh, chọc) + 针 (kim, bộ 钅). Tiếng Việt: \"châm cứu\" cùng chữ 针. Động từ ly hợp.","ex":"感冒严重的话可能要打针。","exPy":"Gǎnmào yánzhòng dehuà kěnéng yào dǎzhēn.","exVi":"Cảm nặng thì có thể phải tiêm.","w":"感冒 严重 的话 可能 要 打针。"},{"zh":"抽烟","py":"chōuyān","vi":"hút thuốc","hv":"trừu yên","note":"抽 (rút, hút, bộ 扌) + 烟 (khói, thuốc lá, bộ 火). Động từ ly hợp: 抽了两支烟.","ex":"为了健康，他戒了抽烟。","exPy":"Wèile jiànkāng, tā jiè le chōuyān.","exVi":"Vì sức khoẻ, anh ấy bỏ thuốc.","w":"为了 健康， 他 戒 了 抽烟。"},{"zh":"干活儿","py":"gànhuór","vi":"làm việc (chân tay)","hv":"cán hoạt nhi","note":"干 ở đây đọc gàn nghĩa là LÀM (khác 干 gān là khô). Chỉ lao động chân tay, khẩu ngữ.","ex":"他从早到晚都在干活儿。","exPy":"Tā cóng zǎo dào wǎn dōu zài gànhuór.","exVi":"Anh ấy làm việc từ sáng tới tối.","w":"他 从 早 到 晚 都 在 干活儿。"},{"zh":"节约","py":"jiéyuē","vi":"tiết kiệm","hv":"tiết ước","note":"Tiếng Việt: \"tiết kiệm\", \"tiết chế\". 节约用水 (tiết kiệm nước) — khẩu hiệu thấy khắp nơi.","ex":"节约用电也是保护环境。","exPy":"Jiéyuē yòng diàn yě shì bǎohù huánjìng.","exVi":"Tiết kiệm điện cũng là bảo vệ môi trường.","w":"节约 用 电 也 是 保护 环境。"},{"zh":"浪费","py":"làngfèi","vi":"lãng phí","hv":"lãng phí","note":"Chính là \"lãng phí\" tiếng Việt: 浪 (lãng, sóng) + 费 (phí, bộ 贝). Trái nghĩa với 节约.","ex":"点这么多菜太浪费了。","exPy":"Diǎn zhème duō cài tài làngfèi le.","exVi":"Gọi nhiều món thế này lãng phí quá.","w":"点 这么 多 菜 太 浪费 了。"},{"zh":"省","py":"shěng","vi":"tiết kiệm, đỡ tốn; tỉnh (đơn vị hành chính)","hv":"tỉnh","note":"Hai nghĩa: đọc shěng là tiết kiệm (省钱), cũng là TỈNH — đơn vị hành chính của Trung Quốc, giống \"tỉnh\" tiếng Việt.","ex":"买这个牌子能省不少钱。","exPy":"Mǎi zhège páizi néng shěng bù shǎo qián.","exVi":"Mua hãng này đỡ được khá nhiều tiền.","w":"买 这个 牌子 能 省 不 少 钱。"},{"zh":"修理","py":"xiūlǐ","vi":"sửa chữa","hv":"tu lý","note":"修 (tu sửa) + 理 (lý). Tiếng Việt: \"tu sửa\", \"tu bổ\". Nói tắt là 修: 修车, 修手机.","ex":"空调坏了，师傅明天来修理。","exPy":"Kōngtiáo huài le, shīfu míngtiān lái xiūlǐ.","exVi":"Điều hoà hỏng rồi, mai thợ đến sửa.","w":"空调 坏 了， 师傅 明天 来 修理。"},{"zh":"保证","py":"bǎozhèng","vi":"bảo đảm, cam đoan","hv":"bảo chứng","note":"保 (bảo, bài 68 trong 保护) + 证 (chứng, bài 73). Tiếng Việt: \"bảo chứng\", \"bảo đảm\".","ex":"我保证以后不再迟到。","exPy":"Wǒ bǎozhèng yǐhòu bú zài chídào.","exVi":"Tôi cam đoan sau này không đến muộn nữa.","w":"我 保证 以后 不 再 迟到。"}],"newChars":["扰","呼","针","抽","烟","省","修"],"outro":"很好！Xong bài 130."};
G.ROOMS["zh-l131"] = {"id":"zh-l131","lang":"zh","level":4,"no":131,"teacher":"wang","title":"HSK4 · Bài 131 · 传达和鼓励 Truyền đạt và động viên","intro":["学校通知明天不上课。","Bài 131: Thông báo, nhắc nhở, khen chê, động viên — bộ động từ giao tiếp công việc. Bấm 1 · Học để bắt đầu."],"introPy":"Xuéxiào tōngzhī míngtiān bú shàngkè.","gram":{"t":"表扬 ↔ 批评 — cặp khen chê nơi công sở","b":"表扬 + người · 批评 + người","d":"Hai từ này rất hay xuất hiện trong câu bị động với 被 (bài 56): 被表扬了 (được khen), 被批评了 (bị phê bình). Chú ý tiếng Trung dùng 被 cho cả việc tốt lẫn xấu ở đây.","ex":[["他因为工作认真被表扬了。","Anh ấy được khen vì làm việc nghiêm túc.","Tā yīnwèi gōngzuò rènzhēn bèi biǎoyáng le."],["迟到的学生被老师批评了。","Học sinh đi muộn bị thầy phê bình.","Chídào de xuésheng bèi lǎoshī pīpíng le."]]},"grams":[{"t":"表扬 ↔ 批评 — cặp khen chê nơi công sở","b":"表扬 + người · 批评 + người","d":"Hai từ này rất hay xuất hiện trong câu bị động với 被 (bài 56): 被表扬了 (được khen), 被批评了 (bị phê bình). Chú ý tiếng Trung dùng 被 cho cả việc tốt lẫn xấu ở đây.","ex":[["他因为工作认真被表扬了。","Anh ấy được khen vì làm việc nghiêm túc.","Tā yīnwèi gōngzuò rènzhēn bèi biǎoyáng le."],["迟到的学生被老师批评了。","Học sinh đi muộn bị thầy phê bình.","Chídào de xuésheng bèi lǎoshī pīpíng le."]]},{"t":"建议 — vừa động từ vừa danh từ","b":"我建议你… (động từ) · 提一个建议 (danh từ)","d":"Làm động từ thì theo sau là cả một câu: 我建议你多休息. Làm danh từ thì đi với 提 hoặc 给: 我给你一个建议. Cùng kiểu với 计划, 决定, 影响.","ex":[["我建议我们坐地铁去。","Tôi đề nghị chúng ta đi tàu điện.","Wǒ jiànyì wǒmen zuò dìtiě qù."],["你的建议很好。","Đề xuất của bạn rất hay.","Nǐ de jiànyì hěn hǎo."]]},{"t":"Nhóm động từ mở đầu bằng 提","b":"提 · 提醒 · 提供 · 提前 · 提高","d":"提 nghĩa gốc là NÂNG LÊN bằng tay. Từ đó ra: 提高 (nâng cao), 提前 (kéo lên sớm), 提醒 (nâng ai đó tỉnh dậy), 提供 (đưa ra cung cấp), 提问题 (nêu vấn đề lên).","ex":[["提高 · 提前 · 提醒 · 提供","nâng cao · làm sớm · nhắc nhở · cung cấp","tígāo · tíqián · tíxǐng · tígōng"]]}],"items":[{"zh":"通知","py":"tōngzhī","vi":"thông báo","hv":"thông tri","note":"Chính là \"thông tri\" tiếng Việt: 通 (thông) + 知 (tri, biết). Vừa là hành động vừa là tờ thông báo.","ex":"学校通知明天不上课。","exPy":"Xuéxiào tōngzhī míngtiān bú shàngkè.","exVi":"Trường thông báo mai nghỉ học.","w":"学校 通知 明天 不 上课。"},{"zh":"提醒","py":"tíxǐng","vi":"nhắc nhở","hv":"đề tỉnh","note":"提 (nâng lên) + 醒 (tỉnh, bài 109). Nghĩa đen: đánh thức ai đó nhớ ra.","ex":"请提醒我八点出发。","exPy":"Qǐng tíxǐng wǒ bā diǎn chūfā.","exVi":"Nhắc tôi tám giờ lên đường nhé.","w":"请 提醒 我 八 点 出发。"},{"zh":"提供","py":"tígōng","vi":"cung cấp","hv":"đề cung","note":"提 (đưa ra) + 供 (cung). Tiếng Việt: \"cung cấp\", \"cung ứng\". Dùng cho dịch vụ, thông tin, tài liệu.","ex":"这家公司提供住的地方。","exPy":"Zhè jiā gōngsī tígōng zhù de dìfang.","exVi":"Công ty này cung cấp chỗ ở.","w":"这 家 公司 提供 住 的 地方。"},{"zh":"提","py":"tí","vi":"nêu ra; xách","hv":"đề","note":"Bộ 扌 (tay). Hai nghĩa: nêu ra (提问题, 提意见) và xách bằng tay (提行李).","ex":"开会时他提了几个问题。","exPy":"Kāihuì shí tā tí le jǐ ge wèntí.","exVi":"Lúc họp anh ấy nêu vài câu hỏi.","w":"开会 时 他 提 了 几 个 问题。"},{"zh":"表示","py":"biǎoshì","vi":"biểu thị, bày tỏ","hv":"biểu thị","note":"Chính là \"biểu thị\" tiếng Việt: 表 (biểu) + 示 (thị).","ex":"大家都表示支持这个计划。","exPy":"Dàjiā dōu biǎoshì zhīchí zhège jìhuà.","exVi":"Mọi người đều bày tỏ ủng hộ kế hoạch này.","w":"大家 都 表示 支持 这个 计划。"},{"zh":"表扬","py":"biǎoyáng","vi":"biểu dương, khen ngợi","hv":"biểu dương","note":"Chính là \"biểu dương\" tiếng Việt: 表 (biểu) + 扬 (dương, nêu cao). Trái nghĩa với 批评.","ex":"孩子做得好要及时表扬。","exPy":"Háizi zuò de hǎo yào jíshí biǎoyáng.","exVi":"Trẻ làm tốt phải khen kịp thời.","w":"孩子 做 得 好 要 及时 表扬。"},{"zh":"批评","py":"pīpíng","vi":"phê bình, khiển trách","hv":"phê bình","note":"Chính là \"phê bình\" tiếng Việt: 批 (phê, bộ 扌) + 评 (bình, bộ 讠).","ex":"批评的时候要注意方法。","exPy":"Pīpíng de shíhou yào zhùyì fāngfǎ.","exVi":"Khi phê bình phải chú ý cách nói.","w":"批评 的 时候 要 注意 方法。"},{"zh":"鼓励","py":"gǔlì","vi":"khích lệ, động viên","hv":"cổ lệ","note":"鼓 (cái trống — đánh trống thúc quân) + 励 (khích lệ). Tiếng Việt: \"cổ vũ\", \"khích lệ\".","ex":"他的鼓励让我有了信心。","exPy":"Tā de gǔlì ràng wǒ yǒu le xìnxīn.","exVi":"Sự động viên của anh ấy cho tôi niềm tin.","w":"他 的 鼓励 让 我 有 了 信心。"},{"zh":"建议","py":"jiànyì","vi":"kiến nghị, đề xuất","hv":"kiến nghị","note":"Chính là \"kiến nghị\" tiếng Việt: 建 (kiến, dựng) + 议 (nghị, bàn).","ex":"医生建议他少吃盐。","exPy":"Yīshēng jiànyì tā shǎo chī yán.","exVi":"Bác sĩ khuyên anh ấy ăn ít muối.","w":"医生 建议 他 少 吃 盐。"},{"zh":"祝贺","py":"zhùhè","vi":"chúc mừng","hv":"chúc hạ","note":"祝 (chúc, bài 62) + 贺 (hạ, mừng — bộ 贝). Trang trọng hơn 恭喜.","ex":"祝贺你找到了新工作！","exPy":"Zhùhè nǐ zhǎo dào le xīn gōngzuò!","exVi":"Chúc mừng bạn tìm được việc mới!","w":"祝贺 你 找 到 了 新 工作！"}],"newChars":["供","示","扬","批","评","鼓","励","建","祝","贺"],"outro":"很好！Xong bài 131."};
G.ROOMS["zh-l132"] = {"id":"zh-l132","lang":"zh","level":4,"no":132,"teacher":"wang","title":"HSK4 · Bài 132 · 安排和进行 Tổ chức công việc","intro":["这个月的工作我已经安排好了。","Bài 132: Lên kế hoạch, tổ chức sự kiện, triển khai công việc. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège yuè de gōngzuò wǒ yǐjīng ānpái hǎo le.","gram":{"t":"进行 chỉ đi với hoạt động trang trọng","b":"进行 + danh từ/động từ hai âm tiết","d":"进行讨论, 进行调查, 进行研究 — đều đúng. Nhưng KHÔNG nói 进行吃饭 hay 进行看书, vì 进行 chỉ dùng cho hoạt động có tổ chức, kéo dài. Đây là điểm dễ sai khi viết văn.","ex":[["我们对这个问题进行了讨论。","Chúng tôi đã tiến hành thảo luận vấn đề này.","Wǒmen duì zhège wèntí jìnxíng le tǎolùn."],["比赛正在进行中。","Trận đấu đang diễn ra.","Bǐsài zhèngzài jìnxíng zhōng."]]},"grams":[{"t":"进行 chỉ đi với hoạt động trang trọng","b":"进行 + danh từ/động từ hai âm tiết","d":"进行讨论, 进行调查, 进行研究 — đều đúng. Nhưng KHÔNG nói 进行吃饭 hay 进行看书, vì 进行 chỉ dùng cho hoạt động có tổ chức, kéo dài. Đây là điểm dễ sai khi viết văn.","ex":[["我们对这个问题进行了讨论。","Chúng tôi đã tiến hành thảo luận vấn đề này.","Wǒmen duì zhège wèntí jìnxíng le tǎolùn."],["比赛正在进行中。","Trận đấu đang diễn ra.","Bǐsài zhèngzài jìnxíng zhōng."]]},{"t":"举办 và 举行 — tổ chức hay cử hành?","b":"举办 = đứng ra tổ chức (nhấn chủ thể) · 举行 = sự kiện diễn ra (nhấn sự việc)","d":"学校举办比赛 (trường đứng ra tổ chức). 比赛在体育馆举行 (trận đấu diễn ra ở nhà thi đấu). Mẹo: có chủ thể tổ chức thì dùng 举办, nêu địa điểm/thời gian thì dùng 举行.","ex":[["公司举办了一个聚会。","Công ty tổ chức một buổi tiệc.","Gōngsī jǔbàn le yí ge jùhuì."],["会议将在北京举行。","Hội nghị sẽ diễn ra ở Bắc Kinh.","Huìyì jiāng zài Běijīng jǔxíng."]]},{"t":"完全 + phủ định — hoàn toàn không","b":"完全不 · 完全没有","d":"完全 đứng trước phủ định để nhấn mạnh tuyệt đối: 我完全不知道 (tôi hoàn toàn không biết). Mạnh hơn nhiều so với chỉ nói 我不知道.","ex":[["这件事我完全不知道。","Việc này tôi hoàn toàn không biết.","Zhè jiàn shì wǒ wánquán bù zhīdào."],["两个人的看法完全不同。","Quan điểm hai người hoàn toàn khác nhau.","Liǎng ge rén de kànfǎ wánquán bù tóng."]]}],"items":[{"zh":"安排","py":"ānpái","vi":"sắp xếp, bố trí","hv":"an bài","note":"Chính là \"an bài\" tiếng Việt: 安 (an) + 排 (bài, sắp). Nhưng tiếng Trung trung tính, không mang nghĩa định mệnh.","ex":"这个月的工作我已经安排好了。","exPy":"Zhège yuè de gōngzuò wǒ yǐjīng ānpái hǎo le.","exVi":"Công việc tháng này tôi đã sắp xếp xong.","w":"这个 月 的 工作 我 已经 安排 好 了。"},{"zh":"计划","py":"jìhuà","vi":"kế hoạch","hv":"kế hoạch","note":"Chính là \"kế hoạch\" tiếng Việt: 计 (kế) + 划 (hoạch).","ex":"你有什么假期计划？","exPy":"Nǐ yǒu shénme jiàqī jìhuà?","exVi":"Bạn có kế hoạch gì cho kỳ nghỉ?","w":"你 有 什么 假期 计划？"},{"zh":"调查","py":"diàochá","vi":"điều tra, khảo sát","hv":"điều tra","note":"Chính là \"điều tra\" tiếng Việt: 调 (điều — đọc diào ở đây) + 查 (tra).","ex":"警察正在调查这件事。","exPy":"Jǐngchá zhèngzài diàochá zhè jiàn shì.","exVi":"Cảnh sát đang điều tra việc này.","w":"警察 正在 调查 这 件 事。"},{"zh":"进行","py":"jìnxíng","vi":"tiến hành","hv":"tiến hành","note":"Chính là \"tiến hành\" tiếng Việt: 进 (tiến) + 行 (hành). Chỉ dùng với hoạt động HAI ÂM TIẾT trở lên và trang trọng.","ex":"考试正在进行，请安静。","exPy":"Kǎoshì zhèngzài jìnxíng, qǐng ānjìng.","exVi":"Đang thi, xin giữ yên lặng.","w":"考试 正在 进行， 请 安静。"},{"zh":"举办","py":"jǔbàn","vi":"tổ chức (sự kiện)","hv":"cử biện","note":"举 (nêu lên, bài 91) + 办 (làm, bài 39). Dùng cho sự kiện lớn: 举办比赛, 举办展览.","ex":"他们每年举办一次运动会。","exPy":"Tāmen měi nián jǔbàn yí cì yùndònghuì.","exVi":"Mỗi năm họ tổ chức một lần hội thao.","w":"他们 每 年 举办 一 次 运动会。"},{"zh":"举行","py":"jǔxíng","vi":"cử hành, tiến hành (nghi lễ)","hv":"cử hành","note":"Chính là \"cử hành\" tiếng Việt. Gần nghĩa 举办 nhưng thiên về nghi thức: 举行婚礼, 举行会议.","ex":"毕业典礼下周举行。","exPy":"Bìyè diǎnlǐ xià zhōu jǔxíng.","exVi":"Lễ tốt nghiệp diễn ra tuần sau.","w":"毕业 典礼 下 周 举行。"},{"zh":"制造","py":"zhìzào","vi":"chế tạo, sản xuất","hv":"chế tạo","note":"Chính là \"chế tạo\" tiếng Việt: 制 (chế) + 造 (tạo). 中国制造 = Made in China.","ex":"这些产品都是中国制造的。","exPy":"Zhèxiē chǎnpǐn dōu shì Zhōngguó zhìzào de.","exVi":"Các sản phẩm này đều do Trung Quốc sản xuất.","w":"这些 产品 都 是 中国 制造 的。"},{"zh":"使用","py":"shǐyòng","vi":"sử dụng","hv":"sử dụng","note":"Chính là \"sử dụng\" tiếng Việt: 使 (sử, bài 92) + 用 (dụng, bài 57). Trang trọng hơn 用.","ex":"这个软件使用起来很方便。","exPy":"Zhège ruǎnjiàn shǐyòng qǐlai hěn fāngbiàn.","exVi":"Phần mềm này dùng rất tiện.","w":"这个 软件 使用 起来 很 方便。"},{"zh":"完全","py":"wánquán","vi":"hoàn toàn","hv":"hoàn toàn","note":"Chính là \"hoàn toàn\" tiếng Việt: 完 (hoàn) + 全 (toàn).","ex":"我完全理解你的想法。","exPy":"Wǒ wánquán lǐjiě nǐ de xiǎngfǎ.","exVi":"Tôi hoàn toàn hiểu suy nghĩ của bạn.","w":"我 完全 理解 你 的 想法。"},{"zh":"顺利","py":"shùnlì","vi":"thuận lợi, suôn sẻ","hv":"thuận lợi","note":"Chính là \"thuận lợi\" tiếng Việt: 顺 (thuận) + 利 (lợi). Lời chúc: 祝你一切顺利.","ex":"祝你考试顺利！","exPy":"Zhù nǐ kǎoshì shùnlì!","exVi":"Chúc bạn thi suôn sẻ!","w":"祝 你 考试 顺利！"}],"newChars":["划","制","造","利"],"outro":"很好！Xong bài 132."};
G.ROOMS["zh-l133"] = {"id":"zh-l133","lang":"zh","level":4,"no":133,"teacher":"wang","title":"HSK4 · Bài 133 · 成功和失败 Thành công và thất bại","intro":["经过多次失败，他终于成功了。","Bài 133: Nói về kết quả, kiên trì hay bỏ cuộc — bộ từ động viên bản thân. Bấm 1 · Học để bắt đầu."],"introPy":"Jīngguò duō cì shībài, tā zhōngyú chénggōng le.","gram":{"t":"受到 và 接受 — bị động hay chủ động?","b":"受到 = nhận lấy (không chọn) · 接受 = chấp nhận (có chọn)","d":"受到影响 (chịu ảnh hưởng — không tự chọn). 接受建议 (chấp nhận đề xuất — có quyền từ chối). Người Việt hay dùng lẫn vì tiếng Việt đều nói \"nhận\".","ex":[["他受到了很大的影响。","Anh ấy chịu ảnh hưởng rất lớn.","Tā shòudào le hěn dà de yǐngxiǎng."],["我不能接受这个价格。","Tôi không chấp nhận được giá này.","Wǒ bù néng jiēshòu zhège jiàgé."]]},"grams":[{"t":"受到 và 接受 — bị động hay chủ động?","b":"受到 = nhận lấy (không chọn) · 接受 = chấp nhận (có chọn)","d":"受到影响 (chịu ảnh hưởng — không tự chọn). 接受建议 (chấp nhận đề xuất — có quyền từ chối). Người Việt hay dùng lẫn vì tiếng Việt đều nói \"nhận\".","ex":[["他受到了很大的影响。","Anh ấy chịu ảnh hưởng rất lớn.","Tā shòudào le hěn dà de yǐngxiǎng."],["我不能接受这个价格。","Tôi không chấp nhận được giá này.","Wǒ bù néng jiēshòu zhège jiàgé."]]},{"t":"坚持 ↔ 放弃 — cặp từ của ý chí","b":"坚持 + động từ · 放弃 + danh từ/động từ","d":"坚持学习 (kiên trì học), 坚持锻炼 (kiên trì tập). 放弃机会 (bỏ lỡ cơ hội), 放弃学习 (bỏ học). Đây là cặp từ xuất hiện nhiều nhất trong bài viết động viên.","ex":[["他坚持每天写一篇日记。","Anh ấy kiên trì mỗi ngày viết một bài nhật ký.","Tā jiānchí měi tiān xiě yì piān rìjì."],["遇到困难别放弃。","Gặp khó khăn đừng bỏ cuộc.","Yù dào kùnnan bié fàngqì."]]},{"t":"之 — chữ văn ngôn còn sót trong tục ngữ","b":"失败是成功之母 · 三分之一","d":"之 là chữ cổ tương đương 的. Nay chỉ còn trong thành ngữ và phân số: 三分之一 (một phần ba), 百分之十 (mười phần trăm — bài 100). Tiếng Việt cũng giữ \"chi\" trong \"vô sở bất chi\".","ex":[["失败是成功之母。","Thất bại là mẹ thành công.","Shībài shì chénggōng zhī mǔ."],["四分之三","ba phần tư","sì fēn zhī sān"]]}],"items":[{"zh":"成功","py":"chénggōng","vi":"thành công","hv":"thành công","note":"Chính là \"thành công\" tiếng Việt: 成 (thành) + 功 (công).","ex":"经过多次失败，他终于成功了。","exPy":"Jīngguò duō cì shībài, tā zhōngyú chénggōng le.","exVi":"Qua nhiều lần thất bại, cuối cùng anh ấy thành công.","w":"经过 多 次 失败， 他 终于 成功 了。"},{"zh":"失败","py":"shībài","vi":"thất bại","hv":"thất bại","note":"Chính là \"thất bại\" tiếng Việt: 失 (thất, mất) + 败 (bại). Câu tục ngữ: 失败是成功之母.","ex":"失败是成功之母。","exPy":"Shībài shì chénggōng zhī mǔ.","exVi":"Thất bại là mẹ thành công.","w":"失败 是 成功 之 母。"},{"zh":"输","py":"shū","vi":"thua","hv":"thâu","note":"Bộ 车 (xe) — vốn nghĩa là vận chuyển, sau thành \"thua\". Trái nghĩa với 赢.","ex":"输了不要紧，下次再来。","exPy":"Shū le búyàojǐn, xià cì zài lái.","exVi":"Thua không sao, lần sau lại làm.","w":"输 了 不要紧， 下 次 再 来。"},{"zh":"赢","py":"yíng","vi":"thắng","hv":"doanh","note":"Chữ nhiều nét nhất bài (17 nét). Gồm 亡, 口, 月, 贝, 凡 — thắng thì phải có đủ mọi thứ.","ex":"我们队赢了三比一。","exPy":"Wǒmen duì yíng le sān bǐ yī.","exVi":"Đội tôi thắng ba một.","w":"我们 队 赢 了 三 比 一。"},{"zh":"获得","py":"huòdé","vi":"giành được, đạt được","hv":"hoạch đắc","note":"获 (hoạch, thu hoạch) + 得 (được). Trang trọng, dùng cho giải thưởng và thành tựu.","ex":"他获得了汉语比赛的第一名。","exPy":"Tā huòdé le Hànyǔ bǐsài de dì-yī míng.","exVi":"Cậu ấy giành giải nhất cuộc thi tiếng Trung.","w":"他 获得 了 汉语 比赛 的 第一 名。"},{"zh":"受到","py":"shòudào","vi":"nhận được, chịu","hv":"thụ đáo","note":"受 (chịu, nhận) + 到 (tới). Dùng cho thứ trừu tượng: 受到欢迎, 受到影响, 受到批评.","ex":"这本书受到了很多读者的欢迎。","exPy":"Zhè běn shū shòudào le hěn duō dúzhě de huānyíng.","exVi":"Quyển sách này được nhiều độc giả đón nhận.","w":"这 本 书 受到 了 很 多 读者 的 欢迎。"},{"zh":"接受","py":"jiēshòu","vi":"tiếp nhận, chấp nhận","hv":"tiếp thụ","note":"Chính là \"tiếp thụ\" tiếng Việt: 接 (tiếp, bài 41) + 受 (thụ). Khác 受到 ở chỗ 接受 là CHỦ ĐỘNG nhận.","ex":"我接受你的道歉。","exPy":"Wǒ jiēshòu nǐ de dàoqiàn.","exVi":"Tôi chấp nhận lời xin lỗi của bạn.","w":"我 接受 你 的 道歉。"},{"zh":"坚持","py":"jiānchí","vi":"kiên trì","hv":"kiên trì","note":"Chính là \"kiên trì\" tiếng Việt: 坚 (kiên) + 持 (trì, giữ — bộ 扌).","ex":"学汉语最重要的是坚持。","exPy":"Xué Hànyǔ zuì zhòngyào de shì jiānchí.","exVi":"Học tiếng Trung quan trọng nhất là kiên trì.","w":"学 汉语 最 重要 的 是 坚持。"},{"zh":"放弃","py":"fàngqì","vi":"từ bỏ","hv":"phóng khí","note":"放 (buông, bài 60) + 弃 (vứt bỏ). Trái nghĩa hoàn toàn với 坚持.","ex":"他放弃了那个工作机会。","exPy":"Tā fàngqì le nàge gōngzuò jīhuì.","exVi":"Anh ấy từ bỏ cơ hội việc làm đó.","w":"他 放弃 了 那个 工作 机会。"},{"zh":"竞争","py":"jìngzhēng","vi":"cạnh tranh","hv":"cạnh tranh","note":"Chính là \"cạnh tranh\" tiếng Việt: 竞 (cạnh) + 争 (tranh).","ex":"找工作的竞争越来越大。","exPy":"Zhǎo gōngzuò de jìngzhēng yuè lái yuè dà.","exVi":"Cạnh tranh tìm việc ngày càng lớn.","w":"找 工作 的 竞争 越 来 越 大。"}],"newChars":["败","输","赢","获","坚","持","弃","竞","争"],"outro":"很好！Xong bài 133."};
G.ROOMS["zh-l134"] = {"id":"zh-l134","lang":"zh","level":4,"no":134,"teacher":"wang","title":"HSK4 · Bài 134 · 形状和状态 Hình dáng và trạng thái","intro":["这本词典又厚又重。","Bài 134: Mười tính từ tả vật — và các cặp trái nghĩa cần học chung. Bấm 1 · Học để bắt đầu."],"introPy":"Zhè běn cídiǎn yòu hòu yòu zhòng.","gram":{"t":"Sáu cặp trái nghĩa nên học chung","b":"厚↔薄 · 深↔浅 · 空↔满 · 轻↔重 · 穷↔富 · 硬↔软","d":"Não ghi nhớ bằng đối chiếu, nên học theo cặp hiệu quả gấp đôi. Trong bài này bạn đã có sẵn ba cặp đầy đủ (空满, 轻重, và 穷 với 富 ở bài 78).","ex":[["这本书很厚，那本很薄。","Quyển này dày, quyển kia mỏng.","Zhè běn shū hěn hòu, nà běn hěn báo."],["箱子空的时候很轻。","Vali lúc rỗng thì rất nhẹ.","Xiāngzi kōng de shíhou hěn qīng."]]},"grams":[{"t":"Sáu cặp trái nghĩa nên học chung","b":"厚↔薄 · 深↔浅 · 空↔满 · 轻↔重 · 穷↔富 · 硬↔软","d":"Não ghi nhớ bằng đối chiếu, nên học theo cặp hiệu quả gấp đôi. Trong bài này bạn đã có sẵn ba cặp đầy đủ (空满, 轻重, và 穷 với 富 ở bài 78).","ex":[["这本书很厚，那本很薄。","Quyển này dày, quyển kia mỏng.","Zhè běn shū hěn hòu, nà běn hěn báo."],["箱子空的时候很轻。","Vali lúc rỗng thì rất nhẹ.","Xiāngzi kōng de shíhou hěn qīng."]]},{"t":"Một chữ, hai âm, hai nghĩa","b":"空 kōng/kòng · 重 zhòng/chóng · 长 cháng/zhǎng","d":"空 kōng (trống) và kòng (thời gian rảnh): 有空吗？= có rảnh không. 重 zhòng (nặng) và chóng (lặp lại): 重新 chóngxīn. Đây là hiện tượng 多音字 (đa âm tự) rất phổ biến — chú ý ngữ cảnh mà chọn âm.","ex":[["你今天有空吗？","Hôm nay bạn rảnh không?","Nǐ jīntiān yǒu kòng ma?"],["请重新写一遍。","Xin viết lại một lần nữa.","Qǐng chóngxīn xiě yí biàn."]]},{"t":"深 tả cả không gian lẫn màu sắc và tình cảm","b":"水很深 · 深蓝色 · 感情很深","d":"Một tính từ dùng cho ba lớp nghĩa: vật lý (sâu), thị giác (màu đậm), trừu tượng (tình cảm sâu đậm). Tiếng Việt cũng nói \"xanh đậm\", \"tình sâu nghĩa nặng\".","ex":[["我喜欢深蓝色的衣服。","Tôi thích đồ màu xanh đậm.","Wǒ xǐhuan shēn lánsè de yīfu."],["他们的感情很深。","Tình cảm của họ rất sâu đậm.","Tāmen de gǎnqíng hěn shēn."]]}],"items":[{"zh":"厚","py":"hòu","vi":"dày","hv":"hậu","note":"Chính là \"hậu\" tiếng Việt (\"hậu hĩnh\", \"nhân hậu\" — lòng dày dặn). Trái nghĩa là 薄 báo (mỏng).","ex":"这本词典又厚又重。","exPy":"Zhè běn cídiǎn yòu hòu yòu zhòng.","exVi":"Quyển từ điển này vừa dày vừa nặng.","w":"这 本 词典 又 厚 又 重。"},{"zh":"深","py":"shēn","vi":"sâu; đậm (màu)","hv":"thâm","note":"Chính là \"thâm\" tiếng Việt (\"thâm sâu\", \"thâm niên\"). Bộ 氵. Hai nghĩa: sâu và màu đậm.","ex":"小心，这里的水很深。","exPy":"Xiǎoxīn, zhèlǐ de shuǐ hěn shēn.","exVi":"Cẩn thận, nước ở đây sâu lắm.","w":"小心， 这里 的 水 很 深。"},{"zh":"空","py":"kōng","vi":"trống, rỗng","hv":"không","note":"Chính là \"không\" trong \"chân không\", \"hư không\". Đọc kōng là trống; đọc kòng là chỗ trống, thời gian rảnh (有空).","ex":"教室里空空的，没有人。","exPy":"Jiàoshì lǐ kōngkōng de, méiyǒu rén.","exVi":"Trong lớp trống trơn, không có ai.","w":"教室 里 空 空 的， 没有 人。"},{"zh":"满","py":"mǎn","vi":"đầy","hv":"mãn","note":"Chính là \"mãn\" tiếng Việt (\"mãn nguyện\", \"viên mãn\"). Bộ 氵. Trái nghĩa với 空.","ex":"周末的地铁总是满的。","exPy":"Zhōumò de dìtiě zǒngshì mǎn de.","exVi":"Tàu điện cuối tuần lúc nào cũng đầy.","w":"周末 的 地铁 总是 满 的。"},{"zh":"圆","py":"yuán","vi":"tròn","hv":"viên","note":"Chính là \"viên\" tiếng Việt (\"viên mãn\", \"đoàn viên\"). Cùng chữ với 元 (đồng tiền tròn).","ex":"中秋节的月亮特别圆。","exPy":"Zhōngqiūjié de yuèliang tèbié yuán.","exVi":"Trăng Trung thu đặc biệt tròn.","w":"中 秋 节 的 月亮 特别 圆。"},{"zh":"轻","py":"qīng","vi":"nhẹ","hv":"khinh","note":"Chính là \"khinh\" tiếng Việt (\"khinh khí cầu\", \"coi khinh\"). Bộ 车. Đã gặp trong 年轻, 轻松.","ex":"这个包很轻，你拿得动。","exPy":"Zhège bāo hěn qīng, nǐ ná de dòng.","exVi":"Cái túi này nhẹ, bạn xách nổi.","w":"这个 包 很 轻， 你 拿 得 动。"},{"zh":"重","py":"zhòng","vi":"nặng","hv":"trọng","note":"Chính là \"trọng\" tiếng Việt (\"trọng lượng\", \"quan trọng\"). Đọc zhòng là nặng; đọc chóng nghĩa là lặp lại (重新, bài 105).","ex":"你的行李有多重？","exPy":"Nǐ de xíngli yǒu duō zhòng?","exVi":"Hành lý của bạn nặng bao nhiêu?","w":"你 的 行李 有 多 重？"},{"zh":"穷","py":"qióng","vi":"nghèo","hv":"cùng","note":"Tiếng Việt: \"cùng\" trong \"bần cùng\", \"cùng khổ\". Bộ 穴 (hang) — nghèo phải ở hang. Trái nghĩa với 富 (bài 78).","ex":"以前很穷，现在生活好多了。","exPy":"Yǐqián hěn qióng, xiànzài shēnghuó hǎo duō le.","exVi":"Trước nghèo lắm, giờ cuộc sống khá hơn nhiều.","w":"以前 很 穷， 现在 生活 好多 了。"},{"zh":"苦","py":"kǔ","vi":"đắng; khổ","hv":"khổ","note":"Chính là \"khổ\" tiếng Việt. Bộ 艹 (cỏ) — vị đắng của thuốc thảo dược. Hai nghĩa: vị đắng và cuộc sống khổ.","ex":"良药苦口。","exPy":"Liáng yào kǔ kǒu.","exVi":"Thuốc tốt thì đắng miệng.","w":"良 药 苦 口。"},{"zh":"硬","py":"yìng","vi":"cứng","hv":"ngạnh","note":"Bộ 石 (đá). Tiếng Việt: \"ngạnh\" trong \"ngoan ngạnh\" (cứng đầu). Trái nghĩa là 软 ruǎn (mềm).","ex":"这个面包放久了，变硬了。","exPy":"Zhège miànbāo fàng jiǔ le, biàn yìng le.","exVi":"Bánh mì để lâu, cứng lại rồi.","w":"这个 面包 放 久 了， 变 硬 了。"}],"newChars":["厚","深","圆","穷","硬"],"outro":"很好！Xong bài 134."};
G.ROOMS["zh-l135"] = {"id":"zh-l135","lang":"zh","level":4,"no":135,"teacher":"wang","title":"HSK4 · Bài 135 · 准确不准确 Chính xác hay không","intro":["请把情况详细地说一遍。","Bài 135: Nhóm tính từ đánh giá độ chính xác và tính chính thức — mười từ Hán Việt. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐng bǎ qíngkuàng xiángxì de shuō yí biàn.","gram":{"t":"Gia đình chữ 正 và chữ 实","b":"正常 · 正确 · 正式 · 真正 · 实际 · 实在 · 确实","d":"正 (chính, ngay thẳng) và 实 (thực, có thật) là hai chữ gốc sinh ra cả nhóm từ này. Nhận ra chữ gốc giúp bạn đoán nghĩa và nhớ nhanh hơn nhiều so với học rời từng từ.","ex":[["正常 · 正确 · 正式 · 真正","đều mang chữ 正 (chính)","zhèngcháng · zhèngquè · zhèngshì · zhēnzhèng"],["实际 · 实在 · 确实 · 诚实","đều mang chữ 实 (thực)","shíjì · shízài · quèshí · chéngshí"]]},"grams":[{"t":"Gia đình chữ 正 và chữ 实","b":"正常 · 正确 · 正式 · 真正 · 实际 · 实在 · 确实","d":"正 (chính, ngay thẳng) và 实 (thực, có thật) là hai chữ gốc sinh ra cả nhóm từ này. Nhận ra chữ gốc giúp bạn đoán nghĩa và nhớ nhanh hơn nhiều so với học rời từng từ.","ex":[["正常 · 正确 · 正式 · 真正","đều mang chữ 正 (chính)","zhèngcháng · zhèngquè · zhèngshì · zhēnzhèng"],["实际 · 实在 · 确实 · 诚实","đều mang chữ 实 (thực)","shíjì · shízài · quèshí · chéngshí"]]},{"t":"实际上 và 其实 — trên thực tế","b":"实际上 (trang trọng) · 其实 (khẩu ngữ)","d":"Cả hai nêu sự thật trái với vẻ ngoài. 其实 (bài 118) dùng trong hội thoại, 实际上 dùng trong văn viết và tranh luận. Đặt đầu câu.","ex":[["实际上，这件事没那么难。","Trên thực tế, việc này không khó thế đâu.","Shíjì shàng, zhè jiàn shì méi nàme nán."]]},{"t":"确实 dùng để xác nhận","b":"确实 + tính từ / động từ","d":"Khi ai đó nói gì mà bạn thấy đúng, dùng 确实 để đồng tình có trọng lượng: 你说得对，他确实很聪明. Mạnh hơn chỉ nói 对.","ex":[["这个地方确实很美。","Nơi này quả thực rất đẹp.","Zhège dìfang quèshí hěn měi."]]}],"items":[{"zh":"详细","py":"xiángxì","vi":"chi tiết, tỉ mỉ","hv":"tường tế","note":"Tiếng Việt: \"tường tận\", \"tường thuật\". 细 là chữ \"tế\" trong 仔细 (bài 65).","ex":"请把情况详细地说一遍。","exPy":"Qǐng bǎ qíngkuàng xiángxì de shuō yí biàn.","exVi":"Xin kể lại tình hình một cách chi tiết.","w":"请 把 情况 详细 地 说 一 遍。"},{"zh":"复杂","py":"fùzá","vi":"phức tạp","hv":"phức tạp","note":"Chính là \"phức tạp\" tiếng Việt: 复 (phức) + 杂 (tạp, bài 81 trong 杂志). Trái nghĩa với 简单.","ex":"汉语的语法其实不太复杂。","exPy":"Hànyǔ de yǔfǎ qíshí bú tài fùzá.","exVi":"Ngữ pháp tiếng Trung thật ra không phức tạp lắm.","w":"汉语 的 语法 其实 不 太 复杂。"},{"zh":"正常","py":"zhèngcháng","vi":"bình thường","hv":"chính thường","note":"正 (chính) + 常 (thường). Tiếng Việt nói \"bình thường\", nhưng nghĩa là \"đúng như lẽ thường\".","ex":"刚开始不习惯是很正常的。","exPy":"Gāng kāishǐ bù xíguàn shì hěn zhèngcháng de.","exVi":"Mới đầu chưa quen là chuyện bình thường.","w":"刚 开始 不 习惯 是 很 正常 的。"},{"zh":"正确","py":"zhèngquè","vi":"chính xác, đúng đắn","hv":"chính xác","note":"Chính là \"chính xác\" tiếng Việt: 正 (chính) + 确 (xác). Trang trọng hơn 对.","ex":"他的发音很正确。","exPy":"Tā de fāyīn hěn zhèngquè.","exVi":"Phát âm của anh ấy rất chuẩn.","w":"他 的 发音 很 正确。"},{"zh":"正式","py":"zhèngshì","vi":"chính thức","hv":"chính thức","note":"Chính là \"chính thức\" tiếng Việt: 正 (chính) + 式 (thức). Tả trang phục, buổi lễ, văn bản.","ex":"面试要穿得正式一点儿。","exPy":"Miànshì yào chuān de zhèngshì yìdiǎnr.","exVi":"Phỏng vấn phải ăn mặc trang trọng chút.","w":"面试 要 穿 得 正式 一点儿。"},{"zh":"准确","py":"zhǔnquè","vi":"chuẩn xác","hv":"chuẩn xác","note":"Chính là \"chuẩn xác\" tiếng Việt: 准 (chuẩn) + 确 (xác). Nhấn vào sự khớp đúng con số, thời gian.","ex":"这个数字不太准确。","exPy":"Zhège shùzì bú tài zhǔnquè.","exVi":"Con số này không chính xác lắm.","w":"这个 数字 不 太 准确。"},{"zh":"真正","py":"zhēnzhèng","vi":"thật sự, đích thực","hv":"chân chính","note":"Chính là \"chân chính\" tiếng Việt: 真 (chân) + 正 (chính).","ex":"真正的朋友会在你困难时帮你。","exPy":"Zhēnzhèng de péngyou huì zài nǐ kùnnan shí bāng nǐ.","exVi":"Bạn thật sự sẽ giúp bạn lúc khó khăn.","w":"真正 的 朋友 会 在 你 困难 时 帮 你。"},{"zh":"实际","py":"shíjì","vi":"thực tế","hv":"thực tế","note":"Chính là \"thực tế\" tiếng Việt: 实 (thực) + 际 (tế). 实际上 = trên thực tế.","ex":"计划和实际总是有距离。","exPy":"Jìhuà hé shíjì zǒngshì yǒu jùlí.","exVi":"Kế hoạch và thực tế luôn có khoảng cách.","w":"计划 和 实际 总是 有 距离。"},{"zh":"实在","py":"shízài","vi":"thật là, quả thực","hv":"thực tại","note":"Dùng để nhấn mạnh sự thật khó phủ nhận: 实在太累了 (thật là mệt quá). Cũng có nghĩa \"thành thật\" khi tả người.","ex":"今天实在太热了。","exPy":"Jīntiān shízài tài rè le.","exVi":"Hôm nay thật là nóng quá.","w":"今天 实在 太 热 了。"},{"zh":"确实","py":"quèshí","vi":"quả thực, đúng là","hv":"xác thực","note":"Chính là \"xác thực\" tiếng Việt: 确 (xác) + 实 (thực). Dùng để xác nhận điều người khác nói.","ex":"你说得对，我确实错了。","exPy":"Nǐ shuō de duì, wǒ quèshí cuò le.","exVi":"Bạn nói đúng, tôi quả thực sai rồi.","w":"你 说 得 对， 我 确实 错 了。"}],"newChars":["详","确","式"],"outro":"很好！Xong bài 135."};
G.ROOMS["zh-l136"] = {"id":"zh-l136","lang":"zh","level":4,"no":136,"teacher":"wang","title":"HSK4 · Bài 136 · 程度和估计 Mức độ và ước lượng","intro":["对您的帮助我十分感谢。","Bài 136: Nhóm phó từ mức độ — công cụ để nói năng có sắc thái thay vì chỉ 很 và 太. Bấm 1 · Học để bắt đầu."],"introPy":"Duì nín de bāngzhù wǒ shífēn gǎnxiè.","gram":{"t":"Thang mức độ đầy đủ của tiếng Trung","b":"稍微 < 有点儿 < 比较 < 很 < 非常/十分/特别 < 太…了 < 极了","d":"Đến HSK 4 bạn đã có đủ bảy nấc. Dùng đúng nấc là câu nói có sắc thái như người bản xứ, thay vì lúc nào cũng 很 và 太.","ex":[["稍微有点儿贵。","Hơi đắt một chút.","Shāowēi yǒudiǎnr guì."],["十分感谢！","Vô cùng cảm ơn!","Shífēn gǎnxiè!"]]},"grams":[{"t":"Thang mức độ đầy đủ của tiếng Trung","b":"稍微 < 有点儿 < 比较 < 很 < 非常/十分/特别 < 太…了 < 极了","d":"Đến HSK 4 bạn đã có đủ bảy nấc. Dùng đúng nấc là câu nói có sắc thái như người bản xứ, thay vì lúc nào cũng 很 và 太.","ex":[["稍微有点儿贵。","Hơi đắt một chút.","Shāowēi yǒudiǎnr guì."],["十分感谢！","Vô cùng cảm ơn!","Shífēn gǎnxiè!"]]},{"t":"大约 / 大概 / 差不多 / 左右 — bốn cách nói \"khoảng\"","b":"大约 + số (trước) · 左右 (sau số) · 大概 (còn dùng phỏng đoán) · 差不多 (xấp xỉ ngang nhau)","d":"大约三十人 và 三十人左右 đều đúng, chỉ khác vị trí. 大概 còn dùng đoán sự việc: 他大概病了. 差不多 nhấn vào sự NGANG BẰNG giữa hai thứ.","ex":[["大约二十分钟就到。","Khoảng hai mươi phút là tới.","Dàyuē èrshí fēnzhōng jiù dào."],["五点左右我给你打电话。","Khoảng năm giờ tôi gọi bạn.","Wǔ diǎn zuǒyòu wǒ gěi nǐ dǎ diànhuà."]]},{"t":"甚至 — nêu trường hợp cực đoan","b":"…, 甚至 + trường hợp mạnh nhất","d":"Dùng sau khi đã nêu vài ví dụ, để đẩy lên mức cao nhất: 他很忙，甚至周末也要工作. Giống hệt \"thậm chí\" tiếng Việt cả về vị trí lẫn chức năng.","ex":[["他连饭都没吃，甚至水也没喝。","Anh ấy cơm còn chưa ăn, thậm chí nước cũng chưa uống.","Tā lián fàn dōu méi chī, shènzhì shuǐ yě méi hē."]]}],"items":[{"zh":"十分","py":"shífēn","vi":"vô cùng, hết sức","hv":"thập phần","note":"Nghĩa đen \"mười phần\" — đủ mười phần tức là hoàn toàn. Tiếng Việt cũng nói \"mười phần chắc chắn\". Trang trọng, ngang 非常.","ex":"对您的帮助我十分感谢。","exPy":"Duì nín de bāngzhù wǒ shífēn gǎnxiè.","exVi":"Tôi vô cùng cảm ơn sự giúp đỡ của ngài.","w":"对 您 的 帮助 我 十分 感谢。"},{"zh":"稍微","py":"shāowēi","vi":"hơi, một chút","hv":"sảo vi","note":"Mức độ NHẸ nhất. Thường đi với 一点儿 ở cuối: 稍微等一下.","ex":"请稍微大声一点儿。","exPy":"Qǐng shāowēi dàshēng yìdiǎnr.","exVi":"Xin nói to lên chút.","w":"请 稍微 大 声 一点儿。"},{"zh":"尤其","py":"yóuqí","vi":"nhất là, đặc biệt là","hv":"vưu kỳ","note":"Dùng để nêu bật một trường hợp trong nhóm. Thường đi với 是: 尤其是….","ex":"我喜欢运动，尤其是游泳。","exPy":"Wǒ xǐhuan yùndòng, yóuqí shì yóuyǒng.","exVi":"Tôi thích thể thao, nhất là bơi.","w":"我 喜欢 运动， 尤其 是 游泳。"},{"zh":"甚至","py":"shènzhì","vi":"thậm chí","hv":"thậm chí","note":"Chính là \"thậm chí\" tiếng Việt: 甚 (thậm) + 至 (chí). Nêu trường hợp cực đoan nhất.","ex":"他忙得甚至没时间吃早饭。","exPy":"Tā máng de shènzhì méi shíjiān chī zǎofàn.","exVi":"Anh ấy bận tới mức không có thời gian ăn sáng.","w":"他 忙 得 甚至 没 时间 吃 早饭。"},{"zh":"至少","py":"zhìshǎo","vi":"ít nhất","hv":"chí thiểu","note":"至 (đến, tới cùng) + 少 (ít). Tiếng Việt: \"chí ít\". Trái nghĩa là 至多 (nhiều nhất).","ex":"写一篇文章至少要两个小时。","exPy":"Xiě yì piān wénzhāng zhìshǎo yào liǎng ge xiǎoshí.","exVi":"Viết một bài ít nhất mất hai tiếng.","w":"写 一 篇 文章 至少 要 两 个 小时。"},{"zh":"大约","py":"dàyuē","vi":"khoảng chừng","hv":"đại ước","note":"大 (lớn, đại thể) + 约 (ước). Tiếng Việt: \"đại khái\", \"ước chừng\". Đứng trước con số.","ex":"从这儿到机场大约五十公里。","exPy":"Cóng zhèr dào jīchǎng dàyuē wǔshí gōnglǐ.","exVi":"Từ đây ra sân bay khoảng năm mươi cây.","w":"从 这儿 到 机场 大约 五 十 公里。"},{"zh":"大概","py":"dàgài","vi":"đại khái, chắc là","hv":"đại khái","note":"Chính là \"đại khái\" tiếng Việt. Gần nghĩa 大约 nhưng còn dùng để phỏng đoán: 他大概不来了.","ex":"他大概已经到家了。","exPy":"Tā dàgài yǐjīng dào jiā le.","exVi":"Chắc anh ấy về đến nhà rồi.","w":"他 大概 已经 到 家 了。"},{"zh":"差不多","py":"chàbuduō","vi":"gần như, xấp xỉ","hv":"sai bất đa","note":"差 (kém, bài 54) + 不多 (không nhiều) = chênh không đáng kể. Câu cửa miệng của người Trung Quốc.","ex":"这两件衣服的价格差不多。","exPy":"Zhè liǎng jiàn yīfu de jiàgé chàbuduō.","exVi":"Giá hai bộ đồ này xấp xỉ nhau.","w":"这 两 件 衣服 的 价格 差不多。"},{"zh":"左右","py":"zuǒyòu","vi":"khoảng, xấp xỉ","hv":"tả hữu","note":"左 (trái) + 右 (phải) — trên dưới một chút. Đặt SAU con số: 三十岁左右 (khoảng ba mươi tuổi).","ex":"会议开了两个小时左右。","exPy":"Huìyì kāi le liǎng ge xiǎoshí zuǒyòu.","exVi":"Cuộc họp kéo dài khoảng hai tiếng.","w":"会议 开 了 两 个 小时 左右。"},{"zh":"究竟","py":"jiūjìng","vi":"rốt cuộc, cuối cùng thì","hv":"cứu cánh","note":"Dùng trong câu hỏi để nhấn mạnh sự truy vấn: 你究竟想说什么？Gần nghĩa 到底 (bài 104).","ex":"你究竟想要什么？","exPy":"Nǐ jiūjìng xiǎng yào shénme?","exVi":"Rốt cuộc bạn muốn gì?","w":"你 究竟 想 要 什么？"}],"newChars":["稍","微","尤","甚","至","概","竟"],"outro":"很好！Xong bài 136."};
G.ROOMS["zh-l137"] = {"id":"zh-l137","lang":"zh","level":4,"no":137,"teacher":"wang","title":"HSK4 · Bài 137 · 更多量词 Lượng từ mở rộng","intro":["图书馆里有许多中文书。","Bài 137: Bài thứ 100: hoàn thiện bộ lượng từ — thứ khiến tiếng Trung và tiếng Việt giống nhau nhất. Bấm 1 · Học để bắt đầu."],"introPy":"Túshūguǎn lǐ yǒu xǔduō Zhōngwén shū.","gram":{"t":"次 và 遍 và 趟 — ba cách đếm \"lần\"","b":"次 = số lần bất kỳ · 遍 = trọn vẹn từ đầu tới cuối · 趟 = lượt đi lại một nơi","d":"我看了三次 (xem ba lần, có thể xem dở). 我看了三遍 (xem trọn ba lượt). 我去了三趟 (đi tới đó ba chuyến). Đây là bộ ba dễ nhầm nhất về lượng từ ở HSK 4.","ex":[["这本书我读了两遍。","Quyển sách này tôi đọc trọn hai lượt.","Zhè běn shū wǒ dú le liǎng biàn."],["今天我跑了三趟医院。","Hôm nay tôi chạy tới bệnh viện ba chuyến.","Jīntiān wǒ pǎo le sān tàng yīyuàn."]]},"grams":[{"t":"次 và 遍 và 趟 — ba cách đếm \"lần\"","b":"次 = số lần bất kỳ · 遍 = trọn vẹn từ đầu tới cuối · 趟 = lượt đi lại một nơi","d":"我看了三次 (xem ba lần, có thể xem dở). 我看了三遍 (xem trọn ba lượt). 我去了三趟 (đi tới đó ba chuyến). Đây là bộ ba dễ nhầm nhất về lượng từ ở HSK 4.","ex":[["这本书我读了两遍。","Quyển sách này tôi đọc trọn hai lượt.","Zhè běn shū wǒ dú le liǎng biàn."],["今天我跑了三趟医院。","Hôm nay tôi chạy tới bệnh viện ba chuyến.","Jīntiān wǒ pǎo le sān tàng yīyuàn."]]},{"t":"Cách nói phân số và phần trăm","b":"分母 + 分之 + 分子","d":"Ngược với tiếng Việt: nói MẪU SỐ trước. 三分之一 = một phần ba (ba phần chi một). 百分之五十 = năm mươi phần trăm. Nhớ thứ tự này là đọc được mọi số liệu.","ex":[["四分之三","ba phần tư","sì fēn zhī sān"],["百分之百","một trăm phần trăm","bǎi fēn zhī bǎi"]]},{"t":"倍 dùng trong so sánh","b":"A 比 B + tính từ + 数 + 倍","d":"这个比那个大两倍 (cái này lớn gấp hai cái kia). Lưu ý: tiếng Trung 增加了一倍 nghĩa là TĂNG THÊM một lần, tức thành gấp đôi — dễ nhầm khi đọc số liệu.","ex":[["他的工资比我高一倍。","Lương anh ấy cao gấp đôi tôi.","Tā de gōngzī bǐ wǒ gāo yí bèi."]]}],"items":[{"zh":"许多","py":"xǔduō","vi":"rất nhiều","hv":"hứa đa","note":"许 (hứa, nhiều) + 多 (đa). Trang trọng hơn 很多, hay dùng trong văn viết. KHÔNG cần 很 đứng trước.","ex":"图书馆里有许多中文书。","exPy":"Túshūguǎn lǐ yǒu xǔduō Zhōngwén shū.","exVi":"Trong thư viện có rất nhiều sách tiếng Trung.","w":"图书馆 里 有 许多 中文 书。"},{"zh":"棵","py":"kē","vi":"cây (lượng từ cho cây cối)","hv":"khoả","note":"Bộ 木 (gỗ) — nhìn bộ là biết dùng cho cây. 一棵树, 一棵草.","ex":"他在门口种了两棵树。","exPy":"Tā zài ménkǒu zhòng le liǎng kē shù.","exVi":"Anh ấy trồng hai cây trước cửa.","w":"他 在 门口 种 了 两 棵 树。"},{"zh":"篇","py":"piān","vi":"bài (lượng từ cho bài viết)","hv":"thiên","note":"Bộ 竹 (tre) — bài viết xưa chép trên thẻ tre. Tiếng Việt: \"thiên\" trong \"thiên truyện\", \"thiên tuỳ bút\".","ex":"老师让我们写一篇日记。","exPy":"Lǎoshī ràng wǒmen xiě yì piān rìjì.","exVi":"Thầy bảo chúng tôi viết một bài nhật ký.","w":"老师 让 我们 写 一 篇 日记。"},{"zh":"趟","py":"tàng","vi":"chuyến, lượt đi","hv":"thảng","note":"Bộ ⻊ (chân). Đếm số lần ĐI LẠI một nơi: 去一趟北京 (đi Bắc Kinh một chuyến).","ex":"为了办签证我跑了好几趟。","exPy":"Wèile bàn qiānzhèng wǒ pǎo le hǎo jǐ tàng.","exVi":"Để làm visa tôi chạy đi mấy chuyến.","w":"为了 办 签证 我 跑 了 好 几 趟。"},{"zh":"遍","py":"biàn","vi":"lượt, lần (từ đầu đến cuối)","hv":"biến","note":"Khác 次 (bài 18): 遍 nhấn mạnh làm TRỌN VẸN từ đầu tới cuối. 看了三遍 = xem trọn ba lượt.","ex":"这个电影我看了两遍。","exPy":"Zhège diànyǐng wǒ kàn le liǎng biàn.","exVi":"Bộ phim này tôi xem hai lượt.","w":"这个 电影 我 看 了 两 遍。"},{"zh":"节","py":"jié","vi":"tiết (học); đốt","hv":"tiết","note":"Chính là \"tiết\" tiếng Việt (\"tiết học\"). Bộ 艹 — vốn là đốt tre. Cũng có trong 节日, 节约.","ex":"我们一天上六节课。","exPy":"Wǒmen yì tiān shàng liù jié kè.","exVi":"Một ngày chúng tôi học sáu tiết.","w":"我们 一 天上 六 节 课。"},{"zh":"场","py":"chǎng","vi":"trận, buổi","hv":"trường","note":"Đếm sự việc diễn ra trong một khoảng thời gian: 一场比赛, 一场电影, 一场雨. Tiếng Việt cũng nói \"một trận mưa\".","ex":"昨晚的那场比赛很精彩。","exPy":"Zuówǎn de nà chǎng bǐsài hěn jīngcǎi.","exVi":"Trận đấu tối qua rất hay.","w":"昨 晚 的 那 场 比赛 很 精彩。"},{"zh":"份","py":"fèn","vi":"phần, bản, suất","hv":"phần","note":"Chính là \"phần\" tiếng Việt. Đếm tài liệu, suất ăn, công việc: 一份材料, 一份工作, 一份饭.","ex":"请给我一份菜单。","exPy":"Qǐng gěi wǒ yí fèn càidān.","exVi":"Cho tôi một tờ thực đơn.","w":"请 给 我 一 份 菜单。"},{"zh":"倍","py":"bèi","vi":"lần (gấp bội)","hv":"bội","note":"Chính là \"bội\" tiếng Việt (\"bội số\", \"gấp bội\"). Dùng so sánh: 大两倍 (lớn gấp hai).","ex":"今年的收入是去年的两倍。","exPy":"Jīnnián de shōurù shì qùnián de liǎng bèi.","exVi":"Thu nhập năm nay gấp đôi năm ngoái.","w":"今年 的 收入 是 去年 的 两 倍。"},{"zh":"百分之","py":"bǎi fēn zhī","vi":"phần trăm","hv":"bách phân chi","note":"Nghĩa đen: \"trong một trăm phần thì lấy…\". 百分之十 = 10%. Chữ 之 là chữ văn ngôn thay cho 的 (bài 96).","ex":"百分之九十的学生通过了考试。","exPy":"Bǎi fēn zhī jiǔshí de xuésheng tōngguò le kǎoshì.","exVi":"Chín mươi phần trăm học sinh qua kỳ thi.","w":"百分之 九 十 的 学生 通过 了 考试。"}],"newChars":["许","棵","篇","趟","遍","节","场","份","倍","百","之"],"outro":"很好！Xong bài 137."};
G.ROOMS["zh-l138"] = {"id":"zh-l138","lang":"zh","level":4,"no":138,"teacher":"wang","title":"HSK4 · Bài 138 · 比较和举例 So sánh và ví dụ","intro":["我们两个人的爱好完全相同。","Bài 138: Cách nêu điểm giống, điểm khác và dẫn ví dụ — bộ khung của mọi bài nói có lập luận. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒmen liǎng ge rén de àihào wánquán xiāngtóng.","gram":{"t":"Bộ khung nêu ví dụ","b":"…，比如／例如 + ví dụ + 等等","d":"比如 dùng khi nói, 例如 dùng khi viết. Kết bằng 等 hoặc 等等 (vân vân) cho tự nhiên: 我喜欢很多运动，比如游泳、跑步等等.","ex":[["我学过几种语言，例如英语和汉语。","Tôi từng học vài ngoại ngữ, ví dụ tiếng Anh và tiếng Trung.","Wǒ xué guo jǐ zhǒng yǔyán, lìrú Yīngyǔ hé Hànyǔ."]]},"grams":[{"t":"Bộ khung nêu ví dụ","b":"…，比如／例如 + ví dụ + 等等","d":"比如 dùng khi nói, 例如 dùng khi viết. Kết bằng 等 hoặc 等等 (vân vân) cho tự nhiên: 我喜欢很多运动，比如游泳、跑步等等.","ex":[["我学过几种语言，例如英语和汉语。","Tôi từng học vài ngoại ngữ, ví dụ tiếng Anh và tiếng Trung.","Wǒ xué guo jǐ zhǒng yǔyán, lìrú Yīngyǔ hé Hànyǔ."]]},{"t":"好像 — hai nghĩa, phân biệt bằng ngữ cảnh","b":"好像 + phỏng đoán · 好像 + 一样 (so sánh)","d":"他好像生病了 = phỏng đoán (hình như ốm). 他好像孩子一样 = so sánh (giống như trẻ con). Có 一样 ở cuối thì chắc chắn là so sánh.","ex":[["时间过得好像水一样快。","Thời gian trôi nhanh như nước.","Shíjiān guò de hǎoxiàng shuǐ yíyàng kuài."]]},{"t":"任何 · 一切 · 所有 — ba từ \"tất cả\"","b":"任何 + danh từ + 都 · 一切 (trừu tượng, đứng riêng) · 所有的 + danh từ","d":"任何 nhấn \"bất kỳ cái nào cũng vậy\", bắt buộc có 都/也. 一切 chỉ tổng thể trừu tượng: 一切都好. 所有 (bài 111) chỉ toàn bộ một tập cụ thể: 所有的学生.","ex":[["任何问题都可以问我。","Bất kỳ câu hỏi nào cũng hỏi tôi được.","Rènhé wèntí dōu kěyǐ wèn wǒ."],["别担心，一切都很顺利。","Đừng lo, mọi thứ đều suôn sẻ.","Bié dānxīn, yíqiè dōu hěn shùnlì."]]}],"items":[{"zh":"相同","py":"xiāngtóng","vi":"giống nhau","hv":"tương đồng","note":"Chính là \"tương đồng\" tiếng Việt: 相 (tương, lẫn nhau) + 同 (đồng).","ex":"我们两个人的爱好完全相同。","exPy":"Wǒmen liǎng ge rén de àihào wánquán xiāngtóng.","exVi":"Sở thích của hai chúng tôi hoàn toàn giống nhau.","w":"我们 两 个人 的 爱好 完全 相同。"},{"zh":"相反","py":"xiāngfǎn","vi":"trái ngược","hv":"tương phản","note":"Chính là \"tương phản\" tiếng Việt. Đầu câu 相反， = ngược lại.","ex":"结果跟我想的正好相反。","exPy":"Jiéguǒ gēn wǒ xiǎng de zhènghǎo xiāngfǎn.","exVi":"Kết quả ngược hẳn với điều tôi nghĩ.","w":"结果 跟 我 想 的 正好 相反。"},{"zh":"区别","py":"qūbié","vi":"sự khác biệt; phân biệt","hv":"khu biệt","note":"区 (khu, chia vùng) + 别 (biệt). Tiếng Việt có \"khu biệt\" trong ngôn ngữ học.","ex":"这两种方法没有太大的区别。","exPy":"Zhè liǎng zhǒng fāngfǎ méiyǒu tài dà de qūbié.","exVi":"Hai cách này không khác nhau nhiều.","w":"这 两 种 方法 没有 太 大 的 区别。"},{"zh":"比如","py":"bǐrú","vi":"ví dụ như","hv":"bỉ như","note":"比 (so) + 如 (như). Khẩu ngữ, hay dùng dạng 比如说.","ex":"我喜欢中国菜，比如饺子。","exPy":"Wǒ xǐhuan Zhōngguó cài, bǐrú jiǎozi.","exVi":"Tôi thích món Trung Quốc, ví dụ sủi cảo.","w":"我 喜欢 中国 菜， 比如 饺子。"},{"zh":"例如","py":"lìrú","vi":"ví dụ như","hv":"lệ như","note":"例 (lệ, trong \"ví dụ\", \"tiền lệ\") + 如 (như). Trang trọng hơn 比如, dùng trong văn viết.","ex":"汉字有很多部首，例如水部。","exPy":"Hànzì yǒu hěn duō bùshǒu, lìrú shuǐ bù.","exVi":"Chữ Hán có nhiều bộ thủ, ví dụ bộ thuỷ.","w":"汉字 有 很 多 部首， 例如 水 部。"},{"zh":"好像","py":"hǎoxiàng","vi":"hình như, giống như","hv":"hảo tượng","note":"好 (tốt, ở đây là \"rất\") + 像 (giống). Hai nghĩa: phỏng đoán (hình như) và so sánh (giống như).","ex":"外面好像下雨了。","exPy":"Wàimiàn hǎoxiàng xià yǔ le.","exVi":"Hình như bên ngoài mưa rồi.","w":"外面 好像 下雨 了。"},{"zh":"一切","py":"yíqiè","vi":"tất cả, mọi thứ","hv":"nhất thiết","note":"Chính là \"nhất thiết\" trong \"nhất thiết mọi người\". Trừu tượng hơn 所有, đứng một mình được: 一切都好.","ex":"谢谢你为我做的一切。","exPy":"Xièxie nǐ wèi wǒ zuò de yíqiè.","exVi":"Cảm ơn tất cả những gì bạn đã làm cho tôi.","w":"谢谢 你 为 我 做 的 一切。"},{"zh":"任何","py":"rènhé","vi":"bất kỳ","hv":"nhậm hà","note":"Luôn đi kèm 都/也: 任何人都可以来 (bất kỳ ai cũng có thể tới).","ex":"有任何困难都可以找我。","exPy":"Yǒu rènhé kùnnan dōu kěyǐ zhǎo wǒ.","exVi":"Có bất kỳ khó khăn nào cứ tìm tôi.","w":"有 任何 困难 都 可以 找 我。"},{"zh":"另外","py":"lìngwài","vi":"ngoài ra; cái kia","hv":"lánh ngoại","note":"另 (khác) + 外 (ngoài). Vừa là liên từ nối ý (ngoài ra), vừa chỉ vật còn lại: 另外一个.","ex":"另外一个办法可能更好。","exPy":"Lìngwài yí ge bànfǎ kěnéng gèng hǎo.","exVi":"Cách kia có lẽ hay hơn.","w":"另外 一 个 办法 可能 更 好。"},{"zh":"其次","py":"qícì","vi":"thứ hai là, tiếp theo","hv":"kỳ thứ","note":"其 (cái đó) + 次 (thứ tự). Đi cặp với 首先 (bài 105): 首先… 其次… 最后….","ex":"首先是身体，其次才是工作。","exPy":"Shǒuxiān shì shēntǐ, qícì cái shì gōngzuò.","exVi":"Trước hết là sức khoẻ, sau đó mới đến công việc.","w":"首先 是 身体， 其次 才 是 工作。"}],"newChars":["相","反","区","别","比","如","例","像","切","任","何","另","外","其","次"],"outro":"很好！Xong bài 138."};
G.ROOMS["zh-l139"] = {"id":"zh-l139","lang":"zh","level":4,"no":139,"teacher":"wang","title":"HSK4 · Bài 139 · 书面连词 Liên từ trang trọng","intro":["这个方法简单并且有效。","Bài 139: Mười liên từ của văn viết — thứ nâng câu văn từ trình độ nói lên trình độ viết. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège fāngfǎ jiǎndān bìngqiě yǒuxiào.","gram":{"t":"既然 … 就 … — đã vậy thì","b":"既然 + sự thật đã biết，就 + kết luận","d":"Khác 因为: 因为 nêu nguyên nhân MỚI cho người nghe, còn 既然 nêu điều CẢ HAI đã biết rồi rút ra kết luận. 既然你不舒服，就早点儿休息吧.","ex":[["既然你决定了，我就不说了。","Đã quyết rồi thì tôi không nói nữa.","Jìrán nǐ juédìng le, wǒ jiù bù shuō le."]]},"grams":[{"t":"既然 … 就 … — đã vậy thì","b":"既然 + sự thật đã biết，就 + kết luận","d":"Khác 因为: 因为 nêu nguyên nhân MỚI cho người nghe, còn 既然 nêu điều CẢ HAI đã biết rồi rút ra kết luận. 既然你不舒服，就早点儿休息吧.","ex":[["既然你决定了，我就不说了。","Đã quyết rồi thì tôi không nói nữa.","Jìrán nǐ juédìng le, wǒ jiù bù shuō le."]]},{"t":"尽管 … 还是 … và 不管 … 都 …","b":"尽管 + sự thật，还是 · 不管 + từ nghi vấn，都/也","d":"Đây là cặp cực dễ nhầm. 尽管 đi với sự thật CỤ THỂ (尽管下雨). 不管 đi với điều CHƯA XÁC ĐỊNH, bắt buộc có 谁/什么/多/还是 phía sau (不管下不下雨).","ex":[["尽管下着雨，他还是来了。","Mặc dù đang mưa, anh ấy vẫn tới.","Jǐnguǎn xià zhe yǔ, tā háishi lái le."],["不管下不下雨，我都去。","Mưa hay không tôi cũng đi.","Bùguǎn xià bu xià yǔ, wǒ dōu qù."]]},{"t":"于是 hay 因此 — kể chuyện hay lập luận?","b":"于是 = rồi thì (trình tự) · 因此 = do đó (nhân quả)","d":"于是 dùng khi kể lại chuỗi sự việc, không nhất thiết là nhân quả chặt. 因此 khẳng định quan hệ nguyên nhân — kết quả, hay gặp trong bài luận. 由于 luôn đứng ở vế nguyên nhân, 因此 ở vế kết quả.","ex":[["由于工作忙，因此我很少运动。","Do công việc bận, vì thế tôi ít vận động.","Yóuyú gōngzuò máng, yīncǐ wǒ hěn shǎo yùndòng."]]}],"items":[{"zh":"并且","py":"bìngqiě","vi":"hơn nữa, đồng thời","hv":"tịnh thả","note":"并 (cùng, song song) + 且 (vả lại). Nối hai vế cùng chiều, trang trọng hơn 而且.","ex":"这个方法简单并且有效。","exPy":"Zhège fāngfǎ jiǎndān bìngqiě yǒuxiào.","exVi":"Cách này đơn giản mà lại hiệu quả.","w":"这个 方法 简单 并且 有效。"},{"zh":"而","py":"ér","vi":"mà, còn","hv":"nhi","note":"Chữ văn ngôn một âm tiết. Nối hai vế TRÁI chiều: 他去了，而我没去. Cũng có trong 而且, 然而.","ex":"他是南方人，而我是北方人。","exPy":"Tā shì nánfāng rén, ér wǒ shì běifāng rén.","exVi":"Anh ấy người miền Nam, còn tôi người miền Bắc.","w":"他 是 南方 人， 而 我 是 北方 人。"},{"zh":"否则","py":"fǒuzé","vi":"nếu không thì","hv":"phủ tắc","note":"否 (phủ định) + 则 (thì). Nêu hậu quả xấu nếu không làm: 快走，否则会迟到.","ex":"记得带钥匙，否则进不去。","exPy":"Jìde dài yàoshi, fǒuzé jìn bu qù.","exVi":"Nhớ mang chìa khoá, không thì không vào được.","w":"记得 带 钥匙， 否则 进 不 去。"},{"zh":"然而","py":"rán'ér","vi":"tuy nhiên","hv":"nhiên nhi","note":"然 (như vậy) + 而 (nhi). Chuyển ý mạnh trong văn viết, ngang \"tuy nhiên\" tiếng Việt.","ex":"计划很好，然而没能实现。","exPy":"Jìhuà hěn hǎo, rán'ér méi néng shíxiàn.","exVi":"Kế hoạch rất hay, tuy nhiên đã không thực hiện được.","w":"计划 很 好， 然而 没 能 实现。"},{"zh":"于是","py":"yúshì","vi":"thế là, do đó","hv":"vu thị","note":"于 (ở, tại) + 是 (đó). Nối sự việc theo trình tự thời gian: xảy ra A, 于是 làm B.","ex":"他没接电话，于是我发了短信。","exPy":"Tā méi jiē diànhuà, yúshì wǒ fā le duǎnxìn.","exVi":"Anh ấy không nghe máy, thế là tôi nhắn tin.","w":"他 没 接 电话， 于是 我 发 了 短信。"},{"zh":"因此","py":"yīncǐ","vi":"vì thế, do đó","hv":"nhân thử","note":"因 (nhân) + 此 (thử, cái này). Nhấn quan hệ NHÂN QUẢ, trang trọng hơn 所以.","ex":"他很有经验，因此大家都相信他。","exPy":"Tā hěn yǒu jīngyàn, yīncǐ dàjiā dōu xiāngxìn tā.","exVi":"Anh ấy có kinh nghiệm, do đó mọi người tin anh ấy.","w":"他 很 有 经验， 因此 大家 都 相信 他。"},{"zh":"由于","py":"yóuyú","vi":"do, bởi vì","hv":"do vu","note":"由 (do) + 于. Chỉ dùng cho nguyên nhân KHÁCH QUAN, đứng đầu câu. Cặp: 由于…，因此….","ex":"由于堵车，我迟到了半个小时。","exPy":"Yóuyú dǔchē, wǒ chídào le bàn ge xiǎoshí.","exVi":"Do tắc đường, tôi trễ nửa tiếng.","w":"由于 堵车， 我 迟到 了 半 个 小时。"},{"zh":"既然","py":"jìrán","vi":"đã… thì","hv":"ký nhiên","note":"既 (đã) + 然. Nêu sự thật hai bên đều biết rồi suy ra kết luận. Cặp: 既然…，就….","ex":"既然大家都同意，那就这样办。","exPy":"Jìrán dàjiā dōu tóngyì, nà jiù zhèyàng bàn.","exVi":"Đã ai cũng đồng ý thì làm vậy đi.","w":"既然 大家 都 同意， 那 就 这样 办。"},{"zh":"尽管","py":"jǐnguǎn","vi":"mặc dù","hv":"tận quản","note":"Trang trọng hơn 虽然. Còn một nghĩa khẩu ngữ: \"cứ việc\" — 有问题尽管问 (có gì cứ hỏi).","ex":"尽管学了很久，我还是常常忘。","exPy":"Jǐnguǎn xué le hěn jiǔ, wǒ háishi chángcháng wàng.","exVi":"Dù học đã lâu, tôi vẫn hay quên.","w":"尽管 学 了 很 久， 我 还是 常常 忘。"},{"zh":"不管","py":"bùguǎn","vi":"bất kể, dù cho","hv":"bất quản","note":"Sau 不管 phải có từ nghi vấn hoặc cấu trúc lựa chọn: 不管谁, 不管去不去. Vế sau có 都/也.","ex":"不管别人怎么说，我都相信你。","exPy":"Bùguǎn biéren zěnme shuō, wǒ dōu xiāngxìn nǐ.","exVi":"Bất kể người khác nói gì, tôi vẫn tin bạn.","w":"不管 别人 怎么 说， 我 都 相信 你。"}],"newChars":["并","且","而","否","则","然","于","因","此","由","既","尽","管"],"outro":"很好！Xong bài 139."};
G.ROOMS["zh-l140"] = {"id":"zh-l140","lang":"zh","level":4,"no":140,"teacher":"wang","title":"HSK4 · Bài 140 · 口语连词 Liên từ hội thoại","intro":["这家店不错，不过有点儿远。","Bài 140: Liên từ dùng khi nói chuyện — ngắn, nhanh, tự nhiên như người bản xứ. Bấm 1 · Học để bắt đầu."],"introPy":"Zhè jiā diàn búcuò, búguò yǒudiǎnr yuǎn.","gram":{"t":"即使 · 虽然 · 尽管 — ba kiểu nhượng bộ","b":"虽然/尽管 + việc CÓ THẬT · 即使 + việc GIẢ ĐỊNH","d":"虽然他很忙 = anh ấy bận thật. 即使他很忙 = giả sử anh ấy bận. Vế sau: 虽然…但是/还是, còn 即使…也. Đây là điểm ngữ pháp hay ra trong đề HSK 4.","ex":[["即使失败了，也不要难过。","Dù có thất bại cũng đừng buồn.","Jíshǐ shībài le, yě búyào nánguò."]]},"grams":[{"t":"即使 · 虽然 · 尽管 — ba kiểu nhượng bộ","b":"虽然/尽管 + việc CÓ THẬT · 即使 + việc GIẢ ĐỊNH","d":"虽然他很忙 = anh ấy bận thật. 即使他很忙 = giả sử anh ấy bận. Vế sau: 虽然…但是/还是, còn 即使…也. Đây là điểm ngữ pháp hay ra trong đề HSK 4.","ex":[["即使失败了，也不要难过。","Dù có thất bại cũng đừng buồn.","Jíshǐ shībài le, yě búyào nánguò."]]},{"t":"却 — phó từ, không phải liên từ","b":"Chủ ngữ + 却 + động từ","d":"Người Việt hay viết sai thành 却他不同意 vì dịch từ \"thế mà anh ấy…\". Đúng phải là 他却不同意. Có thể dùng chung với 但是: 但是他却不同意.","ex":[["我等了很久，他却没来。","Tôi đợi rất lâu, thế mà anh ấy không đến.","Wǒ děng le hěn jiǔ, tā què méi lái."]]},{"t":"Bốn cách nói \"nếu\" theo mức trang trọng","b":"要是 (nói) < 如果 (chung) < 假如 (viết) < 倘若 (văn học)","d":"Ở HSK 4 bạn cần ba cái đầu. Vế sau đều dùng 就 hoặc 那么. Có thể thêm 的话 ở cuối vế điều kiện: 要是明天下雨的话，我们就不去了.","ex":[["如果明天有空的话，我们就去看电影。","Nếu mai rảnh thì chúng ta đi xem phim.","Rúguǒ míngtiān yǒu kòng dehuà, wǒmen jiù qù kàn diànyǐng."]]}],"items":[{"zh":"不过","py":"búguò","vi":"nhưng mà, có điều","hv":"bất quá","note":"Chính là \"bất quá\" tiếng Việt. Nhẹ hơn 但是 — dùng để bổ sung một điểm nhỏ, rất khẩu ngữ.","ex":"这家店不错，不过有点儿远。","exPy":"Zhè jiā diàn búcuò, búguò yǒudiǎnr yuǎn.","exVi":"Quán này ổn, có điều hơi xa.","w":"这 家 店 不错， 不过 有点儿 远。"},{"zh":"可是","py":"kěshì","vi":"nhưng","hv":"khả thị","note":"Đồng nghĩa 但是 nhưng khẩu ngữ hơn, hay đứng đầu câu nói.","ex":"我很想帮你，可是我也不会。","exPy":"Wǒ hěn xiǎng bāng nǐ, kěshì wǒ yě bú huì.","exVi":"Tôi rất muốn giúp bạn, nhưng tôi cũng không biết làm.","w":"我 很 想 帮 你， 可是 我 也 不 会。"},{"zh":"却","py":"què","vi":"thế mà, lại","hv":"khước","note":"Là PHÓ TỪ, phải đứng SAU chủ ngữ, trước động từ: 他却不来 (chứ không nói 却他不来).","ex":"大家都走了，他却还在工作。","exPy":"Dàjiā dōu zǒu le, tā què hái zài gōngzuò.","exVi":"Mọi người về hết rồi, anh ấy thì vẫn còn làm.","w":"大家 都 走 了， 他 却 还 在 工作。"},{"zh":"仍然","py":"réngrán","vi":"vẫn, vẫn còn","hv":"nhưng nhiên","note":"Trang trọng hơn 还是. Nhấn tình trạng KHÔNG THAY ĐỔI sau một biến cố.","ex":"虽然很晚了，他仍然在看书。","exPy":"Suīrán hěn wǎn le, tā réngrán zài kàn shū.","exVi":"Tuy đã muộn, anh ấy vẫn đang đọc sách.","w":"虽然 很 晚 了， 他 仍然 在 看 书。"},{"zh":"无论","py":"wúlùn","vi":"bất luận, dù cho","hv":"vô luận","note":"Chính là \"vô luận\" tiếng Việt. Cùng cách dùng với 不管 (bài 102) nhưng trang trọng hơn.","ex":"无论谁问，你都别说。","exPy":"Wúlùn shéi wèn, nǐ dōu bié shuō.","exVi":"Bất luận ai hỏi, bạn cũng đừng nói.","w":"无论 谁 问， 你 都 别说。"},{"zh":"即使","py":"jíshǐ","vi":"cho dù (giả định)","hv":"tức sử","note":"Khác 虽然: 即使 nêu điều CHƯA xảy ra, chỉ giả định. Cặp: 即使…，也….","ex":"即使很难，我也不会放弃。","exPy":"Jíshǐ hěn nán, wǒ yě bú huì fàngqì.","exVi":"Cho dù khó, tôi cũng không bỏ cuộc.","w":"即使 很 难， 我 也 不 会 放弃。"},{"zh":"假如","py":"jiǎrú","vi":"giả như, nếu như","hv":"giả như","note":"Chính là \"giả như\" tiếng Việt: 假 (giả) + 如 (như). Nêu giả thiết, hơi trang trọng.","ex":"假如再给我一次机会，我会更努力。","exPy":"Jiǎrú zài gěi wǒ yí cì jīhuì, wǒ huì gèng nǔlì.","exVi":"Giả như cho tôi thêm một cơ hội, tôi sẽ cố hơn.","w":"假如 再 给 我 一 次 机会， 我 会 更 努力。"},{"zh":"要是","py":"yàoshi","vi":"nếu","hv":"yếu thị","note":"Bản khẩu ngữ của 如果. Cặp quen thuộc: 要是…就….","ex":"要是你不忙，帮我看看这个。","exPy":"Yàoshi nǐ bù máng, bāng wǒ kànkan zhège.","exVi":"Nếu bạn không bận, xem giúp tôi cái này.","w":"要是 你 不 忙， 帮 我 看 看 这个。"},{"zh":"只好","py":"zhǐhǎo","vi":"đành phải","hv":"chỉ hảo","note":"只 (chỉ) + 好 (đành). Diễn tả không còn lựa chọn nào khác — tiếng Việt: \"chỉ còn cách\".","ex":"票卖完了，我们只好改天再来。","exPy":"Piào mài wán le, wǒmen zhǐhǎo gǎi tiān zài lái.","exVi":"Vé bán hết rồi, đành hôm khác quay lại.","w":"票 卖 完 了， 我们 只好 改天 再 来。"},{"zh":"与","py":"yǔ","vi":"và, với","hv":"dữ","note":"Bản văn ngôn của 和. Dùng trong tên sách, tiêu đề: 中国与越南. Tiếng Việt có \"dữ\" trong \"tham dự\".","ex":"这本书与那本内容差不多。","exPy":"Zhè běn shū yǔ nà běn nèiróng chàbuduō.","exVi":"Nội dung quyển này với quyển kia gần như nhau.","w":"这 本 书 与 那 本 内容 差不多。"}],"newChars":["过","可","却","仍","无","论","即","使","假","要","只","与"],"outro":"很好！Xong bài 140."};
G.ROOMS["zh-l141"] = {"id":"zh-l141","lang":"zh","level":4,"no":141,"teacher":"wang","title":"HSK4 · Bài 141 · 介词和强调 Giới từ và nhấn mạnh","intro":["请按照顺序排队。","Bài 141: Giới từ trang trọng và các phó từ tạo giọng điệu — chỗ dễ lộ ra là người mới hay người đã vững. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐng ànzhào shùnxù páiduì.","gram":{"t":"连 … 都/也 … — cấu trúc nhấn mạnh","b":"连 + thành phần nhấn mạnh + 都/也 + động từ","d":"Ý: ngay cả trường hợp cực đoan này còn vậy, huống chi cái khác. 连小孩子都懂 (trẻ con còn hiểu). Bắt buộc phải có 都 hoặc 也 — thiếu là sai ngữ pháp.","ex":[["他忙得连饭都没吃。","Anh ấy bận tới mức cơm cũng chưa ăn.","Tā máng de lián fàn dōu méi chī."],["这个字连老师也不认识。","Chữ này ngay cả thầy cũng không biết.","Zhège zì lián lǎoshī yě bú rènshi."]]},"grams":[{"t":"连 … 都/也 … — cấu trúc nhấn mạnh","b":"连 + thành phần nhấn mạnh + 都/也 + động từ","d":"Ý: ngay cả trường hợp cực đoan này còn vậy, huống chi cái khác. 连小孩子都懂 (trẻ con còn hiểu). Bắt buộc phải có 都 hoặc 也 — thiếu là sai ngữ pháp.","ex":[["他忙得连饭都没吃。","Anh ấy bận tới mức cơm cũng chưa ăn.","Tā máng de lián fàn dōu méi chī."],["这个字连老师也不认识。","Chữ này ngay cả thầy cũng không biết.","Zhège zì lián lǎoshī yě bú rènshi."]]},{"t":"对于 và 关于 — đối với hay về","b":"对于 + đối tượng của thái độ · 关于 + chủ đề","d":"对于孩子的教育，父母很重视 (thái độ đối với). 关于中国文化的书 (sách VỀ chủ đề). 关于 đứng được trước danh từ làm định ngữ, 对于 thì không.","ex":[["对于这个决定，我完全支持。","Đối với quyết định này, tôi hoàn toàn ủng hộ.","Duìyú zhège juédìng, wǒ wánquán zhīchí."]]},{"t":"难道 và 千万 — giọng điệu của người bản xứ","b":"难道 … 吗？(hỏi tu từ) · 千万别 … (dặn dò)","d":"Hai phó từ này không thêm nghĩa mà thêm CẢM XÚC. Dùng đúng thì câu tiếng Trung của bạn nghe như người bản xứ chứ không như câu dịch. 难道 mang giọng trách, 千万 mang giọng lo lắng quan tâm.","ex":[["难道这也是我的错吗？","Chẳng lẽ cái này cũng là lỗi của tôi?","Nándào zhè yě shì wǒ de cuò ma?"],["千万别告诉他。","Chớ có nói với anh ấy đấy.","Qiānwàn bié gàosu tā."]]}],"items":[{"zh":"按照","py":"ànzhào","vi":"theo, chiếu theo","hv":"án chiếu","note":"按 (ấn, theo) + 照 (chiếu). Tiếng Việt: \"chiếu theo quy định\". Đi với quy định, kế hoạch, thứ tự.","ex":"请按照顺序排队。","exPy":"Qǐng ànzhào shùnxù páiduì.","exVi":"Xin xếp hàng theo thứ tự.","w":"请 按照 顺序 排队。"},{"zh":"通过","py":"tōngguò","vi":"thông qua; đỗ","hv":"thông quá","note":"Hai vai: giới từ (thông qua cách nào) và động từ (đỗ kỳ thi, được duyệt).","ex":"通过这次经历，我学到了很多。","exPy":"Tōngguò zhè cì jīnglì, wǒ xué dào le hěn duō.","exVi":"Qua lần trải nghiệm này, tôi học được nhiều.","w":"通过 这 次 经历， 我 学 到 了 很 多。"},{"zh":"由","py":"yóu","vi":"do (ai làm)","hv":"do","note":"Chính là \"do\" tiếng Việt. Chỉ người chịu trách nhiệm: 这件事由我负责.","ex":"这项工作由他负责。","exPy":"Zhè xiàng gōngzuò yóu tā fùzé.","exVi":"Công việc này do anh ấy phụ trách.","w":"这 项 工作 由 他 负责。"},{"zh":"对于","py":"duìyú","vi":"đối với","hv":"đối vu","note":"Chính là \"đối với\" tiếng Việt. Nêu đối tượng của thái độ, thường đứng đầu câu.","ex":"对于学生来说，健康最重要。","exPy":"Duìyú xuésheng lái shuō, jiànkāng zuì zhòngyào.","exVi":"Đối với học sinh mà nói, sức khoẻ quan trọng nhất.","w":"对于 学生 来 说， 健康 最 重要。"},{"zh":"随着","py":"suízhe","vi":"cùng với, theo đà","hv":"tuỳ trước","note":"随 (tuỳ, theo) + 着. Diễn tả hai thứ biến đổi song song: 随着时间…, 随着经济发展….","ex":"随着技术的发展，生活更方便了。","exPy":"Suízhe jìshù de fāzhǎn, shēnghuó gèng fāngbiàn le.","exVi":"Cùng với sự phát triển công nghệ, cuộc sống tiện hơn.","w":"随着 技术 的 发展， 生活 更 方便 了。"},{"zh":"连","py":"lián","vi":"ngay cả","hv":"liên","note":"Luôn đi với 都/也: 连他都不知道 (ngay cả anh ấy cũng không biết). Cấu trúc nhấn mạnh quan trọng nhất HSK 4.","ex":"他连一个汉字都不会写。","exPy":"Tā lián yí ge Hànzì dōu bú huì xiě.","exVi":"Anh ấy đến một chữ Hán cũng không biết viết.","w":"他 连 一 个 汉字 都 不 会 写。"},{"zh":"到底","py":"dàodǐ","vi":"rốt cuộc, đến cùng","hv":"đáo để","note":"到 (tới) + 底 (đáy). Trong câu hỏi = rốt cuộc; trong câu kể = làm đến cùng: 坚持到底.","ex":"你到底去还是不去？","exPy":"Nǐ dàodǐ qù háishi bú qù?","exVi":"Rốt cuộc bạn đi hay không đi?","w":"你 到底 去 还是 不 去？"},{"zh":"难道","py":"nándào","vi":"chẳng lẽ","hv":"nan đạo","note":"Hỏi tu từ, thể hiện sự ngạc nhiên hoặc trách móc. Hay kết bằng 吗: 难道你忘了吗？","ex":"难道你一点儿也不担心？","exPy":"Nándào nǐ yìdiǎnr yě bù dānxīn?","exVi":"Chẳng lẽ bạn không lo chút nào?","w":"难道 你 一点儿 也 不 担心？"},{"zh":"千万","py":"qiānwàn","vi":"nhất định phải, chớ có","hv":"thiên vạn","note":"Nghĩa đen \"nghìn vạn\". Dùng dặn dò khẩn thiết, hầu như luôn đi với 别/不要: 千万别忘了.","ex":"千万别忘了带护照。","exPy":"Qiānwàn bié wàng le dài hùzhào.","exVi":"Chớ có quên mang hộ chiếu.","w":"千万 别 忘 了 带 护照。"},{"zh":"无","py":"wú","vi":"không có","hv":"vô","note":"Chính là \"vô\" tiếng Việt. Bản văn ngôn của 没有, chỉ dùng trong từ ghép và biển báo: 无人, 无关, 无所谓.","ex":"去还是不去，我无所谓。","exPy":"Qù háishi bú qù, wǒ wúsuǒwèi.","exVi":"Đi hay không tôi cũng chẳng sao.","w":"去 还是 不 去， 我 无所谓。"}],"newChars":["按","照","通","对","随","着","连","到","底","难","道","千","万"],"outro":"很好！Xong bài 141."};
G.ROOMS["zh-l142"] = {"id":"zh-l142","lang":"zh","level":4,"no":142,"teacher":"wang","title":"HSK4 · Bài 142 · 副词连接 Phó từ nối ý","intro":["首先感谢大家来参加。","Bài 142: Phó từ dẫn dắt mạch nói — biết dùng là kể chuyện trôi chảy, không còn câu rời rạc. Bấm 1 · Học để bắt đầu."],"introPy":"Shǒuxiān gǎnxiè dàjiā lái cānjiā.","gram":{"t":"Bộ khung kể chuyện và trình bày","b":"首先 … 接着／然后 … 最后 …","d":"Đây là bộ khung bắt buộc khi bạn kể lại một việc hoặc trình bày ý kiến trong phần thi nói. Có thể thay 接着 bằng 然后, thay 最后 bằng 总之. Thêm 其次 (bài 101) nếu có ba ý trở lên.","ex":[["首先要有计划，其次要行动，最后要坚持。","Trước hết phải có kế hoạch, tiếp đến phải hành động, cuối cùng phải kiên trì.","Shǒuxiān yào yǒu jìhuà, qícì yào xíngdòng, zuìhòu yào jiānchí."]]},"grams":[{"t":"Bộ khung kể chuyện và trình bày","b":"首先 … 接着／然后 … 最后 …","d":"Đây là bộ khung bắt buộc khi bạn kể lại một việc hoặc trình bày ý kiến trong phần thi nói. Có thể thay 接着 bằng 然后, thay 最后 bằng 总之. Thêm 其次 (bài 101) nếu có ba ý trở lên.","ex":[["首先要有计划，其次要行动，最后要坚持。","Trước hết phải có kế hoạch, tiếp đến phải hành động, cuối cùng phải kiên trì.","Shǒuxiān yào yǒu jìhuà, qícì yào xíngdòng, zuìhòu yào jiānchí."]]},{"t":"Thang độ chắc chắn của phỏng đoán","b":"也许 < 可能 < 大概 < 应该 < 肯定 < 一定","d":"Nắm được thang này là biết cách nói vừa đủ thận trọng. 他也许来 (có lẽ, 40%) → 他应该来 (theo lý thì có, 70%) → 他肯定来 (chắc chắn, 95%).","ex":[["他应该已经到了。","Theo lý thì anh ấy đến rồi.","Tā yīnggāi yǐjīng dào le."],["明天肯定会下雨。","Mai chắc chắn mưa.","Míngtiān kěndìng huì xià yǔ."]]},{"t":"刚 và 刚才 — phó từ hay danh từ?","b":"刚 + động từ (phó từ) · 刚才 + đứng như trạng ngữ thời gian (danh từ)","d":"刚 đứng NGAY TRƯỚC động từ: 我刚吃完. 刚才 là mốc thời gian, đứng đầu câu hoặc sau chủ ngữ, và câu có thể dùng 了: 刚才他打电话了. Nói 我刚才刚到 là thừa.","ex":[["我刚来，还不太熟悉。","Tôi mới tới, còn chưa quen lắm.","Wǒ gāng lái, hái bú tài shúxī."],["刚才谁来了？","Vừa nãy ai đến vậy?","Gāngcái shéi lái le?"]]}],"items":[{"zh":"首先","py":"shǒuxiān","vi":"trước hết","hv":"thủ tiên","note":"首 (đầu) + 先 (trước). Mở đầu chuỗi: 首先… 其次… 最后…. Tiếng Việt: \"thủ\" trong \"thủ đô\", \"nguyên thủ\".","ex":"首先感谢大家来参加。","exPy":"Shǒuxiān gǎnxiè dàjiā lái cānjiā.","exVi":"Trước hết cảm ơn mọi người đã đến dự.","w":"首先 感谢 大家 来 参加。"},{"zh":"接着","py":"jiēzhe","vi":"tiếp đó","hv":"tiếp trước","note":"接 (nối, bài 41) + 着. Nối hành động xảy ra ngay sau: 他吃了饭，接着去上班了.","ex":"他说完，接着大家都笑了。","exPy":"Tā shuō wán, jiēzhe dàjiā dōu xiào le.","exVi":"Anh ấy nói xong, tiếp đó mọi người cùng cười.","w":"他 说 完， 接着 大家 都 笑 了。"},{"zh":"重新","py":"chóngxīn","vi":"làm lại từ đầu","hv":"trùng tân","note":"重 ở đây đọc chóng (trùng, lặp lại) chứ không phải zhòng (nặng) — xem bài 97. 新 = mới.","ex":"这个句子错了，请重新写。","exPy":"Zhège jùzi cuò le, qǐng chóngxīn xiě.","exVi":"Câu này sai rồi, xin viết lại.","w":"这个 句子 错 了， 请 重新 写。"},{"zh":"继续","py":"jìxù","vi":"tiếp tục","hv":"kế tục","note":"Chính là \"kế tục\" tiếng Việt: 继 (kế) + 续 (tục). Cả hai chữ đều bộ 纟 (sợi tơ) — nối sợi cho dài ra.","ex":"别停，继续努力。","exPy":"Bié tíng, jìxù nǔlì.","exVi":"Đừng dừng, tiếp tục cố gắng.","w":"别 停， 继续 努力。"},{"zh":"永远","py":"yǒngyuǎn","vi":"mãi mãi","hv":"vĩnh viễn","note":"Chính là \"vĩnh viễn\" tiếng Việt: 永 (vĩnh) + 远 (viễn, xa).","ex":"我会永远记得这一天。","exPy":"Wǒ huì yǒngyuǎn jìde zhè yì tiān.","exVi":"Tôi sẽ mãi nhớ ngày hôm nay.","w":"我 会 永远 记得 这 一 天。"},{"zh":"也许","py":"yěxǔ","vi":"có lẽ","hv":"dã hứa","note":"Mức chắc chắn thấp, thấp hơn 大概 và 可能. Đặt trước động từ hoặc đầu câu.","ex":"也许我们以后还会见面。","exPy":"Yěxǔ wǒmen yǐhòu hái huì jiànmiàn.","exVi":"Có lẽ sau này chúng ta còn gặp lại.","w":"也许 我们 以后 还 会见 面。"},{"zh":"肯定","py":"kěndìng","vi":"chắc chắn; khẳng định","hv":"khẳng định","note":"Chính là \"khẳng định\" tiếng Việt. Vừa là phó từ (chắc chắn sẽ), vừa là động từ (công nhận).","ex":"这么努力，他肯定能通过考试。","exPy":"Zhème nǔlì, tā kěndìng néng tōngguò kǎoshì.","exVi":"Chăm thế này, cậu ấy chắc chắn đỗ.","w":"这么 努力， 他 肯定 能 通过 考试。"},{"zh":"顺便","py":"shùnbiàn","vi":"tiện thể","hv":"thuận tiện","note":"顺 (thuận, bài 95) + 便 (tiện). Làm thêm việc phụ khi đang làm việc chính: 顺便买点儿菜.","ex":"你出去的时候顺便扔一下垃圾。","exPy":"Nǐ chūqù de shíhou shùnbiàn rēng yíxià lājī.","exVi":"Lúc ra ngoài tiện thể đổ rác giúp.","w":"你 出去 的 时候 顺便 扔 一下 垃圾。"},{"zh":"刚","py":"gāng","vi":"vừa mới","hv":"cương","note":"Chỉ việc vừa xảy ra. Khác 刚才 (là danh từ chỉ thời điểm): 我刚到 và 刚才我在忙.","ex":"我刚看完那本书。","exPy":"Wǒ gāng kàn wán nà běn shū.","exVi":"Tôi vừa đọc xong quyển sách đó.","w":"我 刚 看 完 那 本 书。"},{"zh":"挺","py":"tǐng","vi":"khá, rất","hv":"đĩnh","note":"Rất khẩu ngữ, thường đi với 的 ở cuối: 挺好的, 挺累的. Mức độ ngang 很 nhưng thân mật hơn.","ex":"今天天气挺不错的。","exPy":"Jīntiān tiānqì tǐng búcuò de.","exVi":"Hôm nay thời tiết khá đẹp.","w":"今天 天气 挺 不错 的。"}],"newChars":["首","接","重","新","继","续","永","远","也","肯","定","顺","便","刚","挺"],"outro":"很好！Xong bài 142."};
G.ROOMS["zh-l143"] = {"id":"zh-l143","lang":"zh","level":4,"no":143,"teacher":"wang","title":"HSK4 · Bài 143 · 事情的发生 Sự việc xảy ra","intro":["小心，别把手机掉了。","Bài 143: Kể lại chuyện ngoài ý muốn — lạc đường, hiểu lầm, bị lừa — và nguyên nhân của chúng. Bấm 1 · Học để bắt đầu."],"introPy":"Xiǎoxīn, bié bǎ shǒujī diào le.","gram":{"t":"掉 làm bổ ngữ kết quả","b":"Động từ + 掉 = làm cho mất đi","d":"忘掉 (quên đi), 扔掉 (vứt đi), 卖掉 (bán đi), 改掉 (bỏ được thói quen). Sắc thái là DỨT ĐIỂM, không còn nữa — mạnh hơn động từ đứng một mình.","ex":[["把这些旧衣服扔掉吧。","Vứt mấy bộ đồ cũ này đi.","Bǎ zhèxiē jiù yīfu rēng diào ba."],["他改掉了迟到的习惯。","Anh ấy bỏ được thói quen đi trễ.","Tā gǎi diào le chídào de xíguàn."]]},"grams":[{"t":"掉 làm bổ ngữ kết quả","b":"Động từ + 掉 = làm cho mất đi","d":"忘掉 (quên đi), 扔掉 (vứt đi), 卖掉 (bán đi), 改掉 (bỏ được thói quen). Sắc thái là DỨT ĐIỂM, không còn nữa — mạnh hơn động từ đứng một mình.","ex":[["把这些旧衣服扔掉吧。","Vứt mấy bộ đồ cũ này đi.","Bǎ zhèxiē jiù yīfu rēng diào ba."],["他改掉了迟到的习惯。","Anh ấy bỏ được thói quen đi trễ.","Tā gǎi diào le chídào de xíguàn."]]},{"t":"发生 và 引起 — cái gì tự xảy ra, cái gì gây ra","b":"sự việc + 发生 · nguyên nhân + 引起 + hậu quả","d":"发生 KHÔNG có tân ngữ chỉ người gây ra: nói 发生了交通事故 chứ không nói 他发生了事故. 引起 luôn cần chủ thể gây và hậu quả bị gây: 抽烟会引起很多疾病.","ex":[["昨天发生了一件奇怪的事。","Hôm qua xảy ra một chuyện lạ.","Zuótiān fāshēng le yí jiàn qíguài de shì."],["这个消息引起了很大的讨论。","Tin này gây ra tranh luận lớn.","Zhège xiāoxi yǐnqǐ le hěn dà de tǎolùn."]]},{"t":"Từ ly hợp — chỗ tách được của động từ hai chữ","b":"迷路 → 迷了路 · 见面 → 见过面 · 帮忙 → 帮我的忙","d":"Nhiều động từ hai chữ thực chất là động + tân, nên 了/过 và định ngữ chen vào GIỮA: nói 我迷了路 chứ không nói 我迷路了他. Đây là lỗi kinh điển của người học ở trình độ HSK 4.","ex":[["我们见过一次面。","Chúng tôi từng gặp nhau một lần.","Wǒmen jiàn guo yí cì miàn."]]}],"items":[{"zh":"掉","py":"diào","vi":"rơi; mất","hv":"điệu","note":"Bộ 扌. Vừa là động từ (rơi xuống), vừa là bổ ngữ chỉ kết quả mất đi: 忘掉, 卖掉, 扔掉.","ex":"小心，别把手机掉了。","exPy":"Xiǎoxīn, bié bǎ shǒujī diào le.","exVi":"Cẩn thận, đừng làm rơi điện thoại.","w":"小心， 别 把手 机 掉 了。"},{"zh":"断","py":"duàn","vi":"đứt, gãy","hv":"đoạn","note":"Chính là \"đoạn\" tiếng Việt (\"gián đoạn\", \"đoạn tuyệt\"). 电话断了 = cúp máy giữa chừng.","ex":"刚才电话突然断了。","exPy":"Gāngcái diànhuà tūrán duàn le.","exVi":"Vừa nãy điện thoại đột nhiên cúp.","w":"刚才 电话 突然 断 了。"},{"zh":"骗","py":"piàn","vi":"lừa","hv":"phiến","note":"Bộ 马 (ngựa) — vốn là trò lừa khi mua bán ngựa. 骗人 = lừa người, 上当受骗 = bị lừa.","ex":"他被人骗了很多钱。","exPy":"Tā bèi rén piàn le hěn duō qián.","exVi":"Anh ấy bị người ta lừa mất nhiều tiền.","w":"他 被 人 骗 了 很 多 钱。"},{"zh":"迷路","py":"mílù","vi":"lạc đường","hv":"mê lộ","note":"迷 (mê, lạc lối) + 路 (lộ, đường). Là từ ly hợp: 迷了路.","ex":"第一次来北京，我迷路了两次。","exPy":"Dì-yī cì lái Běijīng, wǒ mílù le liǎng cì.","exVi":"Lần đầu tới Bắc Kinh, tôi lạc đường hai lần.","w":"第一 次 来 北京， 我 迷路 了 两 次。"},{"zh":"误会","py":"wùhuì","vi":"hiểu lầm","hv":"ngộ hội","note":"误 (ngộ, sai — như \"ngộ nhận\") + 会 (hiểu). Vừa là động từ vừa là danh từ: 一场误会.","ex":"这只是一场误会。","exPy":"Zhè zhǐshì yì chǎng wùhuì.","exVi":"Đây chỉ là một sự hiểu lầm.","w":"这 只是 一 场 误会。"},{"zh":"吸引","py":"xīyǐn","vi":"thu hút, hấp dẫn","hv":"hấp dẫn","note":"Chính là \"hấp dẫn\" tiếng Việt: 吸 (hấp, hút — như 吸烟) + 引 (dẫn).","ex":"中国文化深深地吸引了我。","exPy":"Zhōngguó wénhuà shēnshēn de xīyǐn le wǒ.","exVi":"Văn hoá Trung Quốc thu hút tôi sâu sắc.","w":"中国 文化 深 深 地 吸引 了 我。"},{"zh":"引起","py":"yǐnqǐ","vi":"gây ra, dẫn đến","hv":"dẫn khởi","note":"引 (dẫn) + 起 (khởi). Đi với hậu quả trừu tượng: 引起注意, 引起问题, 引起讨论.","ex":"抽烟会引起很多健康问题。","exPy":"Chōuyān huì yǐnqǐ hěn duō jiànkāng wèntí.","exVi":"Hút thuốc gây ra nhiều vấn đề sức khoẻ.","w":"抽烟 会 引起 很 多 健康 问题。"},{"zh":"发生","py":"fāshēng","vi":"xảy ra","hv":"phát sinh","note":"Chính là \"phát sinh\" tiếng Việt. Chủ ngữ là SỰ VIỆC, không phải người: 发生了什么事？","ex":"路上发生了交通事故。","exPy":"Lù shàng fāshēng le jiāotōng shìgù.","exVi":"Trên đường xảy ra tai nạn giao thông.","w":"路上 发生 了 交通 事故。"},{"zh":"发展","py":"fāzhǎn","vi":"phát triển","hv":"phát triển","note":"Chính là \"phát triển\" tiếng Việt: 发 (phát) + 展 (triển).","ex":"这个城市发展得非常快。","exPy":"Zhège chéngshì fāzhǎn de fēicháng kuài.","exVi":"Thành phố này phát triển cực nhanh.","w":"这个 城市 发展 得 非常 快。"},{"zh":"出生","py":"chūshēng","vi":"sinh ra","hv":"xuất sinh","note":"出 (ra) + 生 (sinh). 我出生在河内 = tôi sinh ra ở Hà Nội. 出生日期 = ngày sinh.","ex":"他出生在一个普通家庭。","exPy":"Tā chūshēng zài yí ge pǔtōng jiātíng.","exVi":"Anh ấy sinh ra trong một gia đình bình thường.","w":"他 出生 在 一 个 普通 家庭。"}],"newChars":["掉","断","骗","迷","路","误","吸","引","起","发","展","出"],"outro":"很好！Xong bài 143."};
G.ROOMS["zh-l144"] = {"id":"zh-l144","lang":"zh","level":4,"no":144,"teacher":"wang","title":"HSK4 · Bài 144 · 允许和禁止 Cho phép và cấm đoán","intro":["图书馆里不允许大声说话。","Bài 144: Ngôn ngữ của quy định, biển báo và lời khuyên — đọc được bảng chỉ dẫn ở Trung Quốc. Bấm 1 · Học để bắt đầu."],"introPy":"Túshūguǎn lǐ bù yǔnxǔ dàshēng shuōhuà.","gram":{"t":"只要 … 就 … và 只有 … 才 …","b":"只要 = điều kiện đủ (làm là được) · 只有 = điều kiện cần (không có thì không xong)","d":"只要你来，我就很高兴 (bạn tới là tôi vui — dễ). 只有努力，才能成功 (chỉ có cố gắng mới thành công — bắt buộc). Nhớ cặp cố định: 只要…就, 只有…才. Ghép sai cặp là lỗi thường gặp nhất.","ex":[["只要有时间，我就练习写字。","Chỉ cần có thời gian là tôi luyện viết chữ.","Zhǐyào yǒu shíjiān, wǒ jiù liànxí xiě zì."],["只有多练习，才能写好。","Chỉ có luyện nhiều mới viết đẹp được.","Zhǐyǒu duō liànxí, cái néng xiě hǎo."]]},"grams":[{"t":"只要 … 就 … và 只有 … 才 …","b":"只要 = điều kiện đủ (làm là được) · 只有 = điều kiện cần (không có thì không xong)","d":"只要你来，我就很高兴 (bạn tới là tôi vui — dễ). 只有努力，才能成功 (chỉ có cố gắng mới thành công — bắt buộc). Nhớ cặp cố định: 只要…就, 只有…才. Ghép sai cặp là lỗi thường gặp nhất.","ex":[["只要有时间，我就练习写字。","Chỉ cần có thời gian là tôi luyện viết chữ.","Zhǐyào yǒu shíjiān, wǒ jiù liànxí xiě zì."],["只有多练习，才能写好。","Chỉ có luyện nhiều mới viết đẹp được.","Zhǐyǒu duō liànxí, cái néng xiě hǎo."]]},{"t":"Đọc biển báo tiếng Trung","b":"禁止 + động từ · 请勿 + động từ · 严禁 + động từ","d":"禁止吸烟 (cấm hút thuốc), 禁止拍照 (cấm chụp ảnh), 请勿触摸 (xin đừng chạm vào). 勿 là bản văn ngôn của 别. Học ba mẫu này là đọc được hầu hết biển báo công cộng.","ex":[["馆内禁止拍照。","Trong bảo tàng cấm chụp ảnh.","Guǎn nèi jìnzhǐ pāizhào."]]},{"t":"值得 + động từ","b":"值得 + động từ / 不值得 + động từ","d":"Sau 值得 luôn là ĐỘNG TỪ chứ không phải tính từ: nói 值得学习 chứ không nói 值得好. Phủ định: 不值得生气 (không đáng để bực).","ex":[["为这点小事生气不值得。","Bực mình vì chuyện nhỏ này thì không đáng.","Wèi zhè diǎn xiǎo shì shēngqì bù zhídé."]]}],"items":[{"zh":"允许","py":"yǔnxǔ","vi":"cho phép","hv":"duẫn hứa","note":"允 (duẫn, ưng thuận) + 许 (hứa, cho phép). Trang trọng hơn 让.","ex":"图书馆里不允许大声说话。","exPy":"Túshūguǎn lǐ bù yǔnxǔ dàshēng shuōhuà.","exVi":"Trong thư viện không được nói to.","w":"图书馆 里 不 允许 大 声 说话。"},{"zh":"禁止","py":"jìnzhǐ","vi":"cấm","hv":"cấm chỉ","note":"Tiếng Việt: \"cấm chỉ\", \"nghiêm cấm\". 禁 (cấm) + 止 (chỉ, dừng). Chữ trên mọi biển cấm ở Trung Quốc.","ex":"地铁里禁止吃东西。","exPy":"Dìtiě lǐ jìnzhǐ chī dōngxi.","exVi":"Trong tàu điện cấm ăn uống.","w":"地铁 里 禁止 吃 东西。"},{"zh":"重视","py":"zhòngshì","vi":"coi trọng","hv":"trọng thị","note":"Chính là \"trọng thị\" tiếng Việt: 重 (trọng) + 视 (thị, nhìn). Ở đây 重 đọc zhòng.","ex":"公司很重视员工的意见。","exPy":"Gōngsī hěn zhòngshì yuángōng de yìjiàn.","exVi":"Công ty rất coi trọng ý kiến nhân viên.","w":"公司 很 重视 员工 的 意见。"},{"zh":"专门","py":"zhuānmén","vi":"chuyên, chuyên để","hv":"chuyên môn","note":"Chính là \"chuyên môn\" tiếng Việt, nhưng nghĩa thiên về \"cố ý dành riêng\": 我专门来看你.","ex":"他专门去中国学汉语。","exPy":"Tā zhuānmén qù Zhōngguó xué Hànyǔ.","exVi":"Anh ấy đi hẳn sang Trung Quốc học tiếng Trung.","w":"他 专门 去 中国 学 汉语。"},{"zh":"只要","py":"zhǐyào","vi":"chỉ cần","hv":"chỉ yếu","note":"Điều kiện ĐỦ. Cặp: 只要…就…. Khác 只有 (điều kiện CẦN, đi với 才).","ex":"只要坚持，就一定能学好。","exPy":"Zhǐyào jiānchí, jiù yídìng néng xué hǎo.","exVi":"Chỉ cần kiên trì thì nhất định học tốt được.","w":"只要 坚持， 就 一定 能 学 好。"},{"zh":"有趣","py":"yǒuqù","vi":"thú vị","hv":"hữu thú","note":"有 (có) + 趣 (thú). Tiếng Việt: \"hứng thú\", \"thú vị\". Cùng chữ 趣 với 兴趣.","ex":"学习汉字其实很有趣。","exPy":"Xuéxí Hànzì qíshí hěn yǒuqù.","exVi":"Học chữ Hán thật ra rất thú vị.","w":"学习 汉字 其实 很 有趣。"},{"zh":"著名","py":"zhùmíng","vi":"nổi tiếng","hv":"trứ danh","note":"Chính là \"trứ danh\" tiếng Việt: 著 (trứ, rõ rệt) + 名 (danh). Trang trọng hơn 有名.","ex":"长城是中国著名的景点。","exPy":"Chángchéng shì Zhōngguó zhùmíng de jǐngdiǎn.","exVi":"Vạn Lý Trường Thành là thắng cảnh nổi tiếng của Trung Quốc.","w":"长城 是 中国 著名 的 景点。"},{"zh":"高级","py":"gāojí","vi":"cao cấp","hv":"cao cấp","note":"Chính là \"cao cấp\" tiếng Việt: 高 (cao) + 级 (cấp). Dùng cho hàng hoá và trình độ: 高级班.","ex":"他报了一个高级汉语班。","exPy":"Tā bào le yí ge gāojí Hànyǔ bān.","exVi":"Anh ấy đăng ký một lớp tiếng Trung cao cấp.","w":"他 报 了 一 个 高级 汉语 班。"},{"zh":"免费","py":"miǎnfèi","vi":"miễn phí","hv":"miễn phí","note":"Chính là \"miễn phí\" tiếng Việt: 免 (miễn) + 费 (phí). Từ khiến app này tồn tại!","ex":"这个博物馆对学生免费。","exPy":"Zhège bówùguǎn duì xuésheng miǎnfèi.","exVi":"Bảo tàng này miễn phí cho học sinh.","w":"这个 博物馆 对 学生 免费。"},{"zh":"值得","py":"zhídé","vi":"đáng, xứng đáng","hv":"trị đắc","note":"值 (giá trị) + 得 (được). Theo sau là động từ: 值得学习, 值得去看看.","ex":"他的精神值得我们学习。","exPy":"Tā de jīngshén zhídé wǒmen xuéxí.","exVi":"Tinh thần của anh ấy đáng để chúng ta học tập.","w":"他 的 精神 值得 我们 学习。"}],"newChars":["允","禁","止","视","专","门","趣","著","级","免","费","值","得"],"outro":"很好！Xong bài 144."};
G.ROOMS["zh-l145"] = {"id":"zh-l145","lang":"zh","level":4,"no":145,"teacher":"wang","title":"HSK4 · Bài 145 · 舞台和文艺 Sân khấu và văn nghệ","intro":["京剧的脸谱颜色有特别的意思。","Bài 145: Nói về kinh kịch, phim ảnh, tiểu thuyết — mảng văn hoá làm việc học có chiều sâu. Bấm 1 · Học để bắt đầu."],"introPy":"Jīngjù de liǎnpǔ yánsè yǒu tèbié de yìsi.","gram":{"t":"演出 và 表演 — sự kiện hay hành động?","b":"一场演出 (danh từ, sự kiện) · 表演节目 (động từ, hành động diễn)","d":"Nói 看演出 (xem buổi diễn) và 表演得很好 (diễn hay). 演出 hiếm khi mang tân ngữ, còn 表演 thì có: 表演京剧, 表演功夫.","ex":[["他们表演了一个很精彩的节目。","Họ diễn một tiết mục rất đặc sắc.","Tāmen biǎoyǎn le yí ge hěn jīngcǎi de jiémù."]]},"grams":[{"t":"演出 và 表演 — sự kiện hay hành động?","b":"一场演出 (danh từ, sự kiện) · 表演节目 (động từ, hành động diễn)","d":"Nói 看演出 (xem buổi diễn) và 表演得很好 (diễn hay). 演出 hiếm khi mang tân ngữ, còn 表演 thì có: 表演京剧, 表演功夫.","ex":[["他们表演了一个很精彩的节目。","Họ diễn một tiết mục rất đặc sắc.","Tāmen biǎoyǎn le yí ge hěn jīngcǎi de jiémù."]]},{"t":"下功夫 — thành ngữ đáng nhớ","b":"在 + việc + 上下功夫","d":"Nghĩa: bỏ công sức vào việc gì. 他在发音上下了很多功夫 (anh ấy bỏ nhiều công vào phát âm). Đây là cách nói rất tự nhiên, hay dùng khi bàn về việc học.","ex":[["写汉字要下功夫。","Viết chữ Hán phải bỏ công phu.","Xiě Hànzì yào xià gōngfu."]]},{"t":"门 và 种 — lượng từ cho môn học và loại hình","b":"一门艺术／一门课 · 一种方法／一种语言","d":"门 dùng cho môn học, ngành nghệ thuật (vốn nghĩa là \"cửa\", mỗi môn là một cửa vào). 种 dùng cho chủng loại. 京剧是一门艺术, 京剧是一种表演形式 — cả hai đều đúng, khác góc nhìn.","ex":[["这学期我选了五门课。","Kỳ này tôi chọn năm môn.","Zhè xuéqī wǒ xuǎn le wǔ mén kè."]]}],"items":[{"zh":"京剧","py":"jīngjù","vi":"kinh kịch","hv":"kinh kịch","note":"京 (kinh, Bắc Kinh) + 剧 (kịch). Quốc kịch của Trung Quốc, có mặt nạ vẽ và giọng hát đặc trưng.","ex":"京剧的脸谱颜色有特别的意思。","exPy":"Jīngjù de liǎnpǔ yánsè yǒu tèbié de yìsi.","exVi":"Màu mặt nạ kinh kịch có ý nghĩa riêng.","w":"京剧 的 脸 谱 颜色 有 特别 的 意思。"},{"zh":"演出","py":"yǎnchū","vi":"buổi diễn; biểu diễn","hv":"diễn xuất","note":"演 (diễn) + 出 (ra). Tiếng Trung dùng làm cả DANH TỪ chỉ buổi diễn: 一场演出.","ex":"这场演出的票已经卖完了。","exPy":"Zhè chǎng yǎnchū de piào yǐjīng mài wán le.","exVi":"Vé buổi diễn này đã bán hết.","w":"这 场 演出 的 票 已经 卖 完 了。"},{"zh":"表演","py":"biǎoyǎn","vi":"biểu diễn","hv":"biểu diễn","note":"Chính là \"biểu diễn\" tiếng Việt: 表 (biểu) + 演 (diễn). Nhấn vào HÀNH ĐỘNG diễn, còn 演出 nhấn vào sự kiện.","ex":"孩子们表演了一个小节目。","exPy":"Háizimen biǎoyǎn le yí ge xiǎo jiémù.","exVi":"Bọn trẻ diễn một tiết mục nhỏ.","w":"孩子 们 表演 了 一 个 小 节目。"},{"zh":"小说","py":"xiǎoshuō","vi":"tiểu thuyết","hv":"tiểu thuyết","note":"Chính là \"tiểu thuyết\" tiếng Việt: 小 (tiểu) + 说 (thuyết). Nghĩa gốc: chuyện nhỏ kể chơi.","ex":"这本小说我看了三遍。","exPy":"Zhè běn xiǎoshuō wǒ kàn le sān biàn.","exVi":"Cuốn tiểu thuyết này tôi đọc ba lượt.","w":"这 本 小说 我 看 了 三 遍。"},{"zh":"明星","py":"míngxīng","vi":"ngôi sao, minh tinh","hv":"minh tinh","note":"Chính là \"minh tinh\" tiếng Việt: 明 (minh, sáng) + 星 (tinh, sao).","ex":"很多年轻人都喜欢这个明星。","exPy":"Hěn duō niánqīng rén dōu xǐhuan zhège míngxīng.","exVi":"Nhiều bạn trẻ đều thích ngôi sao này.","w":"很 多 年轻 人 都 喜欢 这个 明星。"},{"zh":"功夫","py":"gōngfu","vi":"công phu, võ thuật","hv":"công phu","note":"Chính là \"công phu\" tiếng Việt. Hai nghĩa: võ thuật Trung Hoa, và công sức bỏ ra: 下了很多功夫.","ex":"中国功夫在世界上很有名。","exPy":"Zhōngguó gōngfu zài shìjiè shàng hěn yǒumíng.","exVi":"Võ thuật Trung Hoa nổi tiếng thế giới.","w":"中国 功夫 在 世界 上 很 有名。"},{"zh":"笑话","py":"xiàohua","vi":"chuyện cười","hv":"tiếu thoại","note":"笑 (cười) + 话 (lời). Là danh từ (chuyện cười) và động từ (chê cười ai): 别笑话我.","ex":"别笑话我，我刚开始学。","exPy":"Bié xiàohua wǒ, wǒ gāng kāishǐ xué.","exVi":"Đừng cười tôi, tôi mới bắt đầu học.","w":"别 笑话 我， 我 刚 开始 学。"},{"zh":"精彩","py":"jīngcǎi","vi":"đặc sắc, xuất sắc","hv":"tinh thái","note":"精 (tinh, tinh tuý) + 彩 (thái, rực rỡ). Chỉ dùng cho biểu diễn, trận đấu, bài nói — không dùng cho người.","ex":"昨天的比赛特别精彩。","exPy":"Zuótiān de bǐsài tèbié jīngcǎi.","exVi":"Trận đấu hôm qua đặc biệt hay.","w":"昨天 的 比赛 特别 精彩。"},{"zh":"广播","py":"guǎngbō","vi":"phát thanh","hv":"quảng bá","note":"广 (quảng, rộng) + 播 (bá, gieo rắc). Tiếng Việt \"quảng bá\" nghĩa hơi khác — ở đây là đài phát thanh.","ex":"听广播是练习听力的好方法。","exPy":"Tīng guǎngbō shì liànxí tīnglì de hǎo fāngfǎ.","exVi":"Nghe đài là cách luyện nghe tốt.","w":"听 广播 是 练习 听力 的 好 方法。"},{"zh":"艺术","py":"yìshù","vi":"nghệ thuật","hv":"nghệ thuật","note":"Chính là \"nghệ thuật\" tiếng Việt: 艺 (nghệ) + 术 (thuật). 书法是一种艺术 = thư pháp là một loại nghệ thuật.","ex":"他对中国艺术很感兴趣。","exPy":"Tā duì Zhōngguó yìshù hěn gǎn xìngqù.","exVi":"Anh ấy rất hứng thú với nghệ thuật Trung Hoa.","w":"他 对 中国 艺术 很 感兴趣。"}],"newChars":["京","剧","演","表","功","夫","笑","精","彩","广","播","艺","术"],"outro":"很好！Xong bài 145."};
G.ROOMS["zh-l146"] = {"id":"zh-l146","lang":"zh","level":4,"no":146,"teacher":"wang","title":"HSK4 · Bài 146 · 精神和意志 Tinh thần và ý chí","intro":["写好一个字的感觉真好。","Bài 146: Nói về cảm giác, tâm trạng, tính khí và ước mơ — từ vựng của đời sống nội tâm. Bấm 1 · Học để bắt đầu."],"introPy":"Xiě hǎo yí ge zì de gǎnjué zhēn hǎo.","gram":{"t":"感觉 · 觉得 · 认为 — ba mức của \"tôi thấy\"","b":"感觉 (cảm nhận cơ thể/trực giác) < 觉得 (ý kiến nhẹ) < 认为 (quan điểm có lập luận)","d":"我感觉有点儿冷 (cảm nhận). 我觉得这个不错 (thấy vậy). 我认为应该这样做 (tôi cho rằng — trang trọng, có lý lẽ). Dùng 认为 cho chuyện vặt sẽ nghe quá nặng nề.","ex":[["我觉得这个方法更好。","Tôi thấy cách này hay hơn.","Wǒ juéde zhège fāngfǎ gèng hǎo."],["我认为学习需要方法。","Tôi cho rằng việc học cần có phương pháp.","Wǒ rènwéi xuéxí xūyào fāngfǎ."]]},"grams":[{"t":"感觉 · 觉得 · 认为 — ba mức của \"tôi thấy\"","b":"感觉 (cảm nhận cơ thể/trực giác) < 觉得 (ý kiến nhẹ) < 认为 (quan điểm có lập luận)","d":"我感觉有点儿冷 (cảm nhận). 我觉得这个不错 (thấy vậy). 我认为应该这样做 (tôi cho rằng — trang trọng, có lý lẽ). Dùng 认为 cho chuyện vặt sẽ nghe quá nặng nề.","ex":[["我觉得这个方法更好。","Tôi thấy cách này hay hơn.","Wǒ juéde zhège fāngfǎ gèng hǎo."],["我认为学习需要方法。","Tôi cho rằng việc học cần có phương pháp.","Wǒ rènwéi xuéxí xūyào fāngfǎ."]]},{"t":"醒 làm bổ ngữ kết quả","b":"Động từ + 醒 = làm cho tỉnh","d":"叫醒 (gọi cho tỉnh), 吵醒 (làm ồn khiến tỉnh giấc), 睡醒 (ngủ đã rồi tỉnh). Đây là mẫu bổ ngữ kết quả rất hay gặp: động từ chỉ cách làm + 醒 chỉ kết quả.","ex":[["请明天七点叫醒我。","Mai bảy giờ gọi tôi dậy nhé.","Qǐng míngtiān qī diǎn jiào xǐng wǒ."],["我被外面的声音吵醒了。","Tôi bị tiếng ồn bên ngoài đánh thức.","Wǒ bèi wàimiàn de shēngyīn chǎo xǐng le."]]},{"t":"对 … 有信心 — mẫu cố định","b":"对 + đối tượng + 有／没有 + 信心／兴趣／办法","d":"Đây là khung câu dùng đi dùng lại: 对汉语有兴趣, 对自己有信心, 对这件事没办法. Nhớ khung là nói được cả chục câu.","ex":[["你要对自己有信心。","Bạn phải tự tin vào bản thân.","Nǐ yào duì zìjǐ yǒu xìnxīn."]]}],"items":[{"zh":"感觉","py":"gǎnjué","vi":"cảm giác; cảm thấy","hv":"cảm giác","note":"Chính là \"cảm giác\" tiếng Việt: 感 (cảm) + 觉 (giác). Vừa danh từ vừa động từ: 我感觉很好.","ex":"写好一个字的感觉真好。","exPy":"Xiě hǎo yí ge zì de gǎnjué zhēn hǎo.","exVi":"Cảm giác viết đẹp được một chữ thật tuyệt.","w":"写 好 一 个 字 的 感觉 真 好。"},{"zh":"心情","py":"xīnqíng","vi":"tâm trạng","hv":"tâm tình","note":"心 (tâm) + 情 (tình). Tiếng Việt \"tâm tình\" nghĩa hơi khác — ở đây là tâm trạng vui buồn.","ex":"听音乐能让心情变好。","exPy":"Tīng yīnyuè néng ràng xīnqíng biàn hǎo.","exVi":"Nghe nhạc khiến tâm trạng tốt lên.","w":"听 音乐 能 让 心情 变 好。"},{"zh":"脾气","py":"píqi","vi":"tính khí, tính nết","hv":"tỳ khí","note":"脾 (tỳ, lá lách — bộ 月 chỉ cơ thể) + 气 (khí). Đông y cho rằng tính khí sinh từ tạng phủ. 发脾气 = nổi nóng.","ex":"他很少发脾气。","exPy":"Tā hěn shǎo fā píqi.","exVi":"Anh ấy rất ít khi nổi nóng.","w":"他 很 少 发 脾气。"},{"zh":"信心","py":"xìnxīn","vi":"niềm tin, sự tự tin","hv":"tín tâm","note":"信 (tín) + 心 (tâm). Dùng với 有/没有: 我对自己有信心.","ex":"失败了几次，我失去了信心。","exPy":"Shībài le jǐ cì, wǒ shīqù le xìnxīn.","exVi":"Thất bại vài lần, tôi mất niềm tin.","w":"失败 了 几 次， 我 失去 了 信心。"},{"zh":"自信","py":"zìxìn","vi":"tự tin","hv":"tự tín","note":"Chính là \"tự tin\" tiếng Việt: 自 (tự) + 信 (tín). Khác 信心: 自信 là TÍNH CÁCH, 信心 là niềm tin vào một việc.","ex":"多练习会让你更自信。","exPy":"Duō liànxí huì ràng nǐ gèng zìxìn.","exVi":"Luyện nhiều sẽ khiến bạn tự tin hơn.","w":"多 练习 会 让 你 更 自信。"},{"zh":"理想","py":"lǐxiǎng","vi":"lý tưởng, hoài bão","hv":"lý tưởng","note":"Chính là \"lý tưởng\" tiếng Việt: 理 (lý) + 想 (tưởng). Vừa là danh từ (hoài bão) vừa là tính từ (lý tưởng).","ex":"他的理想是当一名老师。","exPy":"Tā de lǐxiǎng shì dāng yì míng lǎoshī.","exVi":"Lý tưởng của anh ấy là làm thầy giáo.","w":"他 的 理想 是 当 一 名 老师。"},{"zh":"梦","py":"mèng","vi":"giấc mơ","hv":"mộng","note":"Chính là \"mộng\" tiếng Việt. 做梦 = nằm mơ (là từ ly hợp: 做了一个梦). 梦想 = ước mơ.","ex":"学好汉语是我的梦想。","exPy":"Xué hǎo Hànyǔ shì wǒ de mèngxiǎng.","exVi":"Học giỏi tiếng Trung là ước mơ của tôi.","w":"学 好 汉语 是 我 的 梦想。"},{"zh":"辛苦","py":"xīnkǔ","vi":"vất vả","hv":"tân khổ","note":"辛 (tân, cay) + 苦 (khổ, đắng — bài 97). Cay đắng tức là vất vả. Câu xã giao: 辛苦了！","ex":"父母养大孩子很辛苦。","exPy":"Fùmǔ yǎng dà háizi hěn xīnkǔ.","exVi":"Cha mẹ nuôi con lớn rất vất vả.","w":"父母 养 大 孩子 很 辛苦。"},{"zh":"困","py":"kùn","vi":"buồn ngủ","hv":"khốn","note":"Chữ tượng hình: 木 (cây) bị nhốt trong 囗 (vòng vây) — bị vây khốn. Nghĩa \"buồn ngủ\" là nghĩa mở rộng.","ex":"太困了，我先去睡了。","exPy":"Tài kùn le, wǒ xiān qù shuì le.","exVi":"Buồn ngủ quá, tôi đi ngủ trước đây.","w":"太 困 了， 我 先 去 睡 了。"},{"zh":"醒","py":"xǐng","vi":"tỉnh dậy","hv":"tỉnh","note":"Chính là \"tỉnh\" tiếng Việt. Bộ 酉 (rượu) — tỉnh rượu. 醒来 = tỉnh dậy, 叫醒 = đánh thức.","ex":"他睡醒以后觉得舒服多了。","exPy":"Tā shuì xǐng yǐhòu juéde shūfu duō le.","exVi":"Ngủ dậy anh ấy thấy dễ chịu hơn nhiều.","w":"他 睡 醒 以后 觉得 舒服 多 了。"}],"newChars":["感","心","情","脾","气","信","自","理","梦","辛","苦","困","醒"],"outro":"很好！Xong bài 146."};
G.ROOMS["zh-l147"] = {"id":"zh-l147","lang":"zh","level":4,"no":147,"teacher":"wang","title":"HSK4 · Bài 147 · 爱情和感情 Tình cảm lứa đôi","intro":["这部电影讲了一个美丽的爱情故事。","Bài 147: Từ vựng tình cảm — hẹn hò, lãng mạn, tiếc nuối; cũng là mảng từ hay gặp trong phim và bài hát. Bấm 1 · Học để bắt đầu."],"introPy":"Zhè bù diànyǐng jiǎng le yí ge měilì de àiqíng gùshi.","gram":{"t":"爱情 · 感情 · 爱 — dùng đúng chỗ","b":"爱情 = tình yêu đôi lứa (danh từ) · 感情 = tình cảm nói chung · 爱 = yêu (động từ)","d":"Không nói 我爱情你 — 爱情 là DANH TỪ. Với cha mẹ dùng 感情 chứ không dùng 爱情. Người Trung Quốc ít nói 我爱你 trực tiếp hơn người phương Tây; thường nói gián tiếp qua hành động.","ex":[["我和父母的感情很好。","Tình cảm tôi với cha mẹ rất tốt.","Wǒ hé fùmǔ de gǎnqíng hěn hǎo."]]},"grams":[{"t":"爱情 · 感情 · 爱 — dùng đúng chỗ","b":"爱情 = tình yêu đôi lứa (danh từ) · 感情 = tình cảm nói chung · 爱 = yêu (động từ)","d":"Không nói 我爱情你 — 爱情 là DANH TỪ. Với cha mẹ dùng 感情 chứ không dùng 爱情. Người Trung Quốc ít nói 我爱你 trực tiếp hơn người phương Tây; thường nói gián tiếp qua hành động.","ex":[["我和父母的感情很好。","Tình cảm tôi với cha mẹ rất tốt.","Wǒ hé fùmǔ de gǎnqíng hěn hǎo."]]},{"t":"结果 làm liên từ — cái kết bất ngờ","b":"…，结果 + kết cục ngoài dự tính","d":"Khi kể chuyện, 结果 dẫn vào kết cục thường là trái mong đợi: 我准备了很久，结果没考好. Đây là cách kể chuyện rất tự nhiên, khác hẳn với 结果 làm danh từ.","ex":[["我跑着去车站，结果车已经走了。","Tôi chạy ra bến, rốt cuộc xe đã đi mất.","Wǒ pǎo zhe qù chēzhàn, jiéguǒ chē yǐjīng zǒu le."]]},{"t":"Từ ly hợp trong bài: 约会 · 开玩笑","b":"约会 → 约了一次会 · 开玩笑 → 开个玩笑／跟他开玩笑","d":"Cả hai đều tách được. Đối tượng đùa dùng 跟/和 chứ không đặt sau: nói 别跟我开玩笑 chứ không nói 别开玩笑我. Nhắc lại quy tắc từ ly hợp ở bài 106.","ex":[["他们约过几次会。","Họ hẹn hò vài lần rồi.","Tāmen yuē guo jǐ cì huì."],["别跟老师开玩笑。","Đừng đùa với thầy.","Bié gēn lǎoshī kāi wánxiào."]]}],"items":[{"zh":"爱情","py":"àiqíng","vi":"tình yêu (đôi lứa)","hv":"ái tình","note":"Chính là \"ái tình\" tiếng Việt: 爱 (ái) + 情 (tình). CHỈ dùng cho tình yêu nam nữ, không dùng cho cha mẹ.","ex":"这部电影讲了一个美丽的爱情故事。","exPy":"Zhè bù diànyǐng jiǎng le yí ge měilì de àiqíng gùshi.","exVi":"Bộ phim này kể một chuyện tình đẹp.","w":"这 部 电影 讲 了 一 个 美丽 的 爱情 故事。"},{"zh":"感情","py":"gǎnqíng","vi":"tình cảm","hv":"cảm tình","note":"Rộng hơn 爱情 — dùng cho mọi mối quan hệ: 我们的感情很好 (tình cảm chúng tôi rất tốt).","ex":"时间会让感情变得更深。","exPy":"Shíjiān huì ràng gǎnqíng biàn de gèng shēn.","exVi":"Thời gian sẽ khiến tình cảm sâu đậm hơn.","w":"时间 会 让 感情 变 得 更 深。"},{"zh":"浪漫","py":"làngmàn","vi":"lãng mạn","hv":"lãng mạn","note":"Chính là \"lãng mạn\" tiếng Việt — cả hai đều phiên âm từ \"romantic\" qua chữ Hán 浪漫.","ex":"他给她准备了一个浪漫的晚餐。","exPy":"Tā gěi tā zhǔnbèi le yí ge làngmàn de wǎncān.","exVi":"Anh ấy chuẩn bị cho cô ấy một bữa tối lãng mạn.","w":"他 给 她 准备 了 一 个 浪漫 的 晚餐。"},{"zh":"约会","py":"yuēhuì","vi":"hẹn hò; cuộc hẹn","hv":"ước hội","note":"约 (ước, hẹn — cùng chữ với 大约 bài 99) + 会 (gặp). Là từ ly hợp: 约过一次会.","ex":"他们第一次约会是在公园。","exPy":"Tāmen dì-yī cì yuēhuì shì zài gōngyuán.","exVi":"Lần hẹn đầu của họ là ở công viên.","w":"他们 第一 次 约会 是 在 公园。"},{"zh":"美丽","py":"měilì","vi":"xinh đẹp","hv":"mỹ lệ","note":"Chính là \"mỹ lệ\" tiếng Việt: 美 (mỹ) + 丽 (lệ). Văn vẻ hơn 漂亮, dùng cho phong cảnh và người.","ex":"西湖的风景非常美丽。","exPy":"Xīhú de fēngjǐng fēicháng měilì.","exVi":"Phong cảnh Tây Hồ vô cùng đẹp.","w":"西 湖 的 风景 非常 美丽。"},{"zh":"流泪","py":"liúlèi","vi":"rơi nước mắt","hv":"lưu lệ","note":"流 (lưu, chảy) + 泪 (lệ, nước mắt). Tiếng Việt: \"lệ\" trong \"giọt lệ\". Cả hai chữ đều bộ 氵.","ex":"听完这首歌，很多人都流泪了。","exPy":"Tīng wán zhè shǒu gē, hěn duō rén dōu liúlèi le.","exVi":"Nghe xong bài hát này, nhiều người rơi nước mắt.","w":"听 完 这 首 歌， 很 多 人 都 流泪 了。"},{"zh":"礼貌","py":"lǐmào","vi":"lễ phép, lịch sự","hv":"lễ mạo","note":"礼 (lễ) + 貌 (mạo, dáng vẻ). Dùng với 有/没有: 他很有礼貌.","ex":"对长辈说话要有礼貌。","exPy":"Duì zhǎngbèi shuōhuà yào yǒu lǐmào.","exVi":"Nói với người lớn phải lễ phép.","w":"对 长辈 说话 要 有 礼貌。"},{"zh":"开玩笑","py":"kāi wánxiào","vi":"đùa, nói giỡn","hv":"khai ngoạn tiếu","note":"开 (mở) + 玩笑 (trò đùa). Là từ ly hợp: 开了个玩笑, 别跟我开玩笑.","ex":"他喜欢跟朋友开玩笑。","exPy":"Tā xǐhuan gēn péngyou kāi wánxiào.","exVi":"Anh ấy thích đùa với bạn bè.","w":"他 喜欢 跟 朋友 开玩笑。"},{"zh":"可惜","py":"kěxī","vi":"tiếc là, đáng tiếc","hv":"khả tích","note":"可 (đáng) + 惜 (tích, tiếc). Tiếng Việt: \"thương tiếc\", \"trân tích\". Đặt đầu câu: 可惜他没来.","ex":"可惜那天我有事，没能参加。","exPy":"Kěxī nà tiān wǒ yǒu shì, méi néng cānjiā.","exVi":"Tiếc là hôm đó tôi bận, không dự được.","w":"可惜 那 天 我 有 事， 没 能 参加。"},{"zh":"结果","py":"jiéguǒ","vi":"kết quả; rốt cuộc","hv":"kết quả","note":"Chính là \"kết quả\" tiếng Việt. Còn dùng làm liên từ kể chuyện, ý bất ngờ: 我等了两小时，结果他没来.","ex":"他准备了很久，结果还是紧张了。","exPy":"Tā zhǔnbèi le hěn jiǔ, jiéguǒ háishi jǐnzhāng le.","exVi":"Anh ấy chuẩn bị rất lâu, rốt cuộc vẫn hồi hộp.","w":"他 准备 了 很 久， 结果 还是 紧张 了。"}],"newChars":["爱","浪","漫","约","美","丽","流","泪","礼","貌","开","玩","惜","结"],"outro":"很好！Xong bài 147."};
G.ROOMS["zh-l148"] = {"id":"zh-l148","lang":"zh","level":4,"no":148,"teacher":"wang","title":"HSK4 · Bài 148 · 语言和信息 Ngôn ngữ và thông tin","intro":["他给我发来一个好消息。","Bài 148: Từ vựng để nói về chính việc học ngôn ngữ — dịch, đối thoại, tin tức, con số. Bấm 1 · Học để bắt đầu."],"introPy":"Tā gěi wǒ fā lái yí ge hǎo xiāoxi.","gram":{"t":"把 … 翻译成 … — mẫu câu chuyển đổi","b":"把 + A + động từ + 成 + B","d":"成 làm bổ ngữ chỉ kết quả biến thành: 翻译成中文, 改成星期六, 换成人民币, 写成大写. Đây là mẫu câu 把 hay dùng nhất ở HSK 4.","ex":[["请把会议改成下午三点。","Xin đổi cuộc họp thành ba giờ chiều.","Qǐng bǎ huìyì gǎi chéng xiàwǔ sān diǎn."],["我把美元换成了人民币。","Tôi đổi đô la sang nhân dân tệ.","Wǒ bǎ měiyuán huàn chéng le rénmínbì."]]},"grams":[{"t":"把 … 翻译成 … — mẫu câu chuyển đổi","b":"把 + A + động từ + 成 + B","d":"成 làm bổ ngữ chỉ kết quả biến thành: 翻译成中文, 改成星期六, 换成人民币, 写成大写. Đây là mẫu câu 把 hay dùng nhất ở HSK 4.","ex":[["请把会议改成下午三点。","Xin đổi cuộc họp thành ba giờ chiều.","Qǐng bǎ huìyì gǎi chéng xiàwǔ sān diǎn."],["我把美元换成了人民币。","Tôi đổi đô la sang nhân dân tệ.","Wǒ bǎ měiyuán huàn chéng le rénmínbì."]]},{"t":"其中 — nói về một phần của tập đã nêu","b":"Tập hợp，其中 + số/phần","d":"其中 phải có tập hợp nêu TRƯỚC đó, không dùng mở đầu câu: 班里有二十个学生，其中五个是留学生. Đây là cách nói số liệu chuẩn trong bài viết.","ex":[["我买了三本书，其中一本是词典。","Tôi mua ba quyển sách, trong đó một quyển là từ điển.","Wǒ mǎi le sān běn shū, qízhōng yì běn shì cídiǎn."]]},{"t":"内 và 里 — phạm vi trừu tượng hay không gian thật","b":"内 (thời hạn, phạm vi) · 里 (không gian cụ thể)","d":"一个月内 (trong vòng một tháng), 国内 (trong nước) — dùng 内. 房间里, 包里 (trong phòng, trong túi) — dùng 里. Nói 房间内 vẫn đúng nhưng nghe rất văn bản hành chính.","ex":[["请在一周内交作业。","Xin nộp bài trong vòng một tuần.","Qǐng zài yì zhōu nèi jiāo zuòyè."]]}],"items":[{"zh":"消息","py":"xiāoxi","vi":"tin tức","hv":"tiêu tức","note":"消 (tiêu) + 息 (tức). Tin về một sự việc cụ thể. Khác 新闻 (bản tin thời sự trên báo đài).","ex":"他给我发来一个好消息。","exPy":"Tā gěi wǒ fā lái yí ge hǎo xiāoxi.","exVi":"Anh ấy gửi cho tôi một tin vui.","w":"他 给 我 发 来 一 个 好 消息。"},{"zh":"信息","py":"xìnxī","vi":"thông tin","hv":"tín tức","note":"信 (tín) + 息 (tức). Thông tin theo nghĩa dữ liệu: 信息技术 = công nghệ thông tin.","ex":"手机让我们获得信息更方便。","exPy":"Shǒujī ràng wǒmen huòdé xìnxī gèng fāngbiàn.","exVi":"Điện thoại khiến việc lấy thông tin tiện hơn.","w":"手机 让 我们 获得 信息 更 方便。"},{"zh":"语言","py":"yǔyán","vi":"ngôn ngữ","hv":"ngữ ngôn","note":"Tiếng Việt đảo ngược thành \"ngôn ngữ\". 语 (ngữ) + 言 (ngôn) — hiện tượng đảo trật tự khá thường gặp.","ex":"学一门语言需要时间和耐心。","exPy":"Xué yì mén yǔyán xūyào shíjiān hé nàixīn.","exVi":"Học một ngôn ngữ cần thời gian và kiên nhẫn.","w":"学 一 门 语言 需要 时间 和 耐心。"},{"zh":"词语","py":"cíyǔ","vi":"từ ngữ","hv":"từ ngữ","note":"Chính là \"từ ngữ\" tiếng Việt: 词 (từ) + 语 (ngữ).","ex":"这一课的词语我都记住了。","exPy":"Zhè yí kè de cíyǔ wǒ dōu jì zhù le.","exVi":"Từ ngữ bài này tôi nhớ hết rồi.","w":"这 一 课 的 词语 我 都 记 住 了。"},{"zh":"对话","py":"duìhuà","vi":"đối thoại, hội thoại","hv":"đối thoại","note":"Chính là \"đối thoại\" tiếng Việt: 对 (đối) + 话 (thoại).","ex":"我们来练习这段对话。","exPy":"Wǒmen lái liànxí zhè duàn duìhuà.","exVi":"Chúng ta luyện đoạn hội thoại này nào.","w":"我们 来 练习 这 段 对话。"},{"zh":"翻译","py":"fānyì","vi":"phiên dịch, dịch","hv":"phiên dịch","note":"Chính là \"phiên dịch\" tiếng Việt: 翻 (phiên, lật) + 译 (dịch). Vừa là hành động vừa là nghề.","ex":"他做过五年的翻译工作。","exPy":"Tā zuò guo wǔ nián de fānyì gōngzuò.","exVi":"Anh ấy làm phiên dịch năm năm.","w":"他 做 过 五 年 的 翻译 工作。"},{"zh":"数字","py":"shùzì","vi":"con số, chữ số","hv":"số tự","note":"数 (số) + 字 (tự, chữ). Người Trung Quốc thích số 8 (谐音 phát, giàu) và tránh số 4 (谐音 tử).","ex":"这些数字说明了问题。","exPy":"Zhèxiē shùzì shuōmíng le wèntí.","exVi":"Những con số này nói lên vấn đề.","w":"这些 数字 说明 了 问题。"},{"zh":"内","py":"nèi","vi":"trong, nội bộ","hv":"nội","note":"Chính là \"nội\" tiếng Việt. Bản trang trọng của 里, dùng cho phạm vi trừu tượng: 一周内, 国内.","ex":"请在两天内给我答复。","exPy":"Qǐng zài liǎng tiān nèi gěi wǒ dáfù.","exVi":"Xin trả lời tôi trong hai ngày.","w":"请 在 两 天 内 给 我 答复。"},{"zh":"其中","py":"qízhōng","vi":"trong đó","hv":"kỳ trung","note":"其 (cái đó) + 中 (trong). Chỉ một phần của tập đã nêu: 十个人，其中三个是老师.","ex":"我认识很多汉字，其中一些不会写。","exPy":"Wǒ rènshi hěn duō Hànzì, qízhōng yìxiē bú huì xiě.","exVi":"Tôi biết nhiều chữ Hán, trong đó một số không viết được.","w":"我 认识 很 多 汉字， 其中 一些 不 会 写。"},{"zh":"所有","py":"suǒyǒu","vi":"tất cả","hv":"sở hữu","note":"Tiếng Việt \"sở hữu\" nghĩa khác — ở đây là \"tất cả\". Thường có 的: 所有的学生都来了.","ex":"感谢所有帮助过我的人。","exPy":"Gǎnxiè suǒyǒu bāngzhù guo wǒ de rén.","exVi":"Cảm ơn tất cả những người từng giúp tôi.","w":"感谢 所有 帮助 过 我 的 人。"}],"newChars":["消","息","言","词","翻","译","数","内","所"],"outro":"很好！Xong bài 148."};
G.ROOMS["zh-l149"] = {"id":"zh-l149","lang":"zh","level":4,"no":149,"teacher":"wang","title":"HSK4 · Bài 149 · 方法和目的 Phương pháp và mục đích","intro":["每个人都有自己的学习方法。","Bài 149: Bộ từ trừu tượng để bàn về cách làm, điều kiện, đặc điểm và hiệu quả — ngôn ngữ của bài luận. Bấm 1 · Học để bắt đầu."],"introPy":"Měi ge rén dōu yǒu zìjǐ de xuéxí fāngfǎ.","gram":{"t":"一方面 … 另一方面 … — trình bày hai mặt","b":"一方面 + ý 1，另一方面 + ý 2","d":"Khung câu quan trọng nhất khi viết đoạn văn nêu ý kiến: 学汉语，一方面能了解文化，另一方面对工作也有帮助. Đây chính là kiểu câu giám khảo HSK muốn thấy.","ex":[["一方面工作很忙，另一方面身体也不太好。","Một mặt công việc bận, mặt khác sức khoẻ cũng không tốt lắm.","Yì fāngmiàn gōngzuò hěn máng, lìng yì fāngmiàn shēntǐ yě bú tài hǎo."]]},"grams":[{"t":"一方面 … 另一方面 … — trình bày hai mặt","b":"一方面 + ý 1，另一方面 + ý 2","d":"Khung câu quan trọng nhất khi viết đoạn văn nêu ý kiến: 学汉语，一方面能了解文化，另一方面对工作也有帮助. Đây chính là kiểu câu giám khảo HSK muốn thấy.","ex":[["一方面工作很忙，另一方面身体也不太好。","Một mặt công việc bận, mặt khác sức khoẻ cũng không tốt lắm.","Yì fāngmiàn gōngzuò hěn máng, lìng yì fāngmiàn shēntǐ yě bú tài hǎo."]]},{"t":"为了 và 目的 — nói về mục đích","b":"为了 + mục đích，+ hành động · … 的目的是 …","d":"为了学好汉语，我每天练习 (vì mục đích). 我学汉语的目的是了解中国文化 (nêu thẳng mục đích). Cách một dùng khi nói, cách hai trang trọng hơn.","ex":[["为了参加考试，他复习了三个月。","Để dự thi, anh ấy ôn ba tháng.","Wèile cānjiā kǎoshì, tā fùxí le sān ge yuè."]]},{"t":"效果 · 有效 · 效率 — ba từ dễ lẫn","b":"效果 (danh từ: tác dụng) · 有效 (tính từ: hiệu quả) · 效率 (danh từ: hiệu suất)","d":"这个方法效果很好 hoặc 这个方法很有效 — cả hai đúng, khác từ loại. 效率 chỉ tốc độ làm việc: 他工作效率很高.","ex":[["早上学习效率最高。","Buổi sáng học hiệu suất cao nhất.","Zǎoshang xuéxí xiàolǜ zuì gāo."]]}],"items":[{"zh":"方法","py":"fāngfǎ","vi":"phương pháp","hv":"phương pháp","note":"Chính là \"phương pháp\" tiếng Việt: 方 (phương) + 法 (pháp).","ex":"每个人都有自己的学习方法。","exPy":"Měi ge rén dōu yǒu zìjǐ de xuéxí fāngfǎ.","exVi":"Ai cũng có cách học riêng.","w":"每 个人 都 有 自己 的 学习 方法。"},{"zh":"方面","py":"fāngmiàn","vi":"phương diện, mặt","hv":"phương diện","note":"Chính là \"phương diện\" tiếng Việt. Mẫu quen: 一方面…，另一方面… (một mặt…, mặt khác…).","ex":"他在很多方面都比我强。","exPy":"Tā zài hěn duō fāngmiàn dōu bǐ wǒ qiáng.","exVi":"Anh ấy giỏi hơn tôi ở nhiều mặt.","w":"他 在 很 多 方面 都 比 我 强。"},{"zh":"过程","py":"guòchéng","vi":"quá trình","hv":"quá trình","note":"Chính là \"quá trình\" tiếng Việt: 过 (quá) + 程 (trình).","ex":"在学习过程中，犯错很正常。","exPy":"Zài xuéxí guòchéng zhōng, fàncuò hěn zhèngcháng.","exVi":"Trong quá trình học, mắc lỗi là bình thường.","w":"在 学习 过程 中， 犯 错 很 正常。"},{"zh":"条件","py":"tiáojiàn","vi":"điều kiện","hv":"điều kiện","note":"Chính là \"điều kiện\" tiếng Việt: 条 (điều) + 件 (kiện).","ex":"只要条件允许，我就去留学。","exPy":"Zhǐyào tiáojiàn yǔnxǔ, wǒ jiù qù liúxué.","exVi":"Chỉ cần điều kiện cho phép là tôi đi du học.","w":"只要 条件 允许， 我 就 去 留学。"},{"zh":"规定","py":"guīdìng","vi":"quy định","hv":"quy định","note":"Chính là \"quy định\" tiếng Việt: 规 (quy) + 定 (định). Đi với 按照 (bài 104): 按照规定.","ex":"按照规定，这里不能停车。","exPy":"Ànzhào guīdìng, zhèlǐ bù néng tíngchē.","exVi":"Theo quy định, ở đây không được đỗ xe.","w":"按照 规定， 这里 不 能 停车。"},{"zh":"顺序","py":"shùnxù","vi":"thứ tự, trình tự","hv":"thuận tự","note":"顺 (thuận) + 序 (tự). Với app này thì rất quen: 笔画顺序 = thứ tự nét bút.","ex":"笔画顺序写错了，字就不好看。","exPy":"Bǐhuà shùnxù xiě cuò le, zì jiù bù hǎokàn.","exVi":"Viết sai thứ tự nét thì chữ không đẹp.","w":"笔 画 顺序 写 错 了， 字 就 不 好看。"},{"zh":"排列","py":"páiliè","vi":"sắp xếp, xếp thứ tự","hv":"bài liệt","note":"排 (bài, xếp hàng — cùng chữ với 安排, 排队) + 列 (liệt, dãy).","ex":"请把这些句子重新排列。","exPy":"Qǐng bǎ zhèxiē jùzi chóngxīn páiliè.","exVi":"Xin sắp xếp lại những câu này.","w":"请 把 这些 句子 重新 排列。"},{"zh":"特点","py":"tèdiǎn","vi":"đặc điểm","hv":"đặc điểm","note":"Chính là \"đặc điểm\" tiếng Việt: 特 (đặc) + 点 (điểm).","ex":"这个城市最大的特点是安静。","exPy":"Zhège chéngshì zuì dà de tèdiǎn shì ānjìng.","exVi":"Đặc điểm lớn nhất của thành phố này là yên tĩnh.","w":"这个 城市 最 大 的 特点 是 安静。"},{"zh":"效果","py":"xiàoguǒ","vi":"hiệu quả, tác dụng","hv":"hiệu quả","note":"Chính là \"hiệu quả\" tiếng Việt: 效 (hiệu) + 果 (quả). Là DANH TỪ; muốn nói tính từ dùng 有效.","ex":"每天写十个字，效果很明显。","exPy":"Měi tiān xiě shí ge zì, xiàoguǒ hěn míngxiǎn.","exVi":"Mỗi ngày viết mười chữ, hiệu quả rất rõ.","w":"每 天 写 十 个 字， 效果 很 明显。"},{"zh":"目的","py":"mùdì","vi":"mục đích","hv":"mục đích","note":"Chính là \"mục đích\" tiếng Việt: 目 (mục, mắt) + 的 (đích, cái bia bắn). Lưu ý 的 ở đây đọc dì.","ex":"我来的目的是想跟您商量一件事。","exPy":"Wǒ lái de mùdì shì xiǎng gēn nín shāngliang yí jiàn shì.","exVi":"Mục đích tôi đến là muốn bàn với ngài một việc.","w":"我 来 的 目的 是 想 跟 您 商量 一 件 事。"}],"newChars":["方","法","程","条","件","规","序","排","列","特","效","目"],"outro":"很好！Xong bài 149."};
G.ROOMS["zh-l150"] = {"id":"zh-l150","lang":"zh","level":4,"no":150,"teacher":"wang","title":"HSK4 · Bài 150 · 改变和收发 Thay đổi và trao nhận","intro":["学汉语改变了我的生活。","Bài 150: Động từ chỉ sự biến đổi và việc trao — nhận, gồm nhiều động từ một chữ rất hay dùng. Bấm 1 · Học để bắt đầu."],"introPy":"Xué Hànyǔ gǎibiàn le wǒ de shēnghuó.","gram":{"t":"成为 và 变成 — trở thành hay biến thành","b":"成为 + danh từ (địa vị mới) · 变成 + danh từ (hình dạng mới)","d":"他成为了老师 (đạt được vị trí). 冰变成了水 (chất đổi hình). Nói về người và sự nghiệp thì dùng 成为; nói về sự biến đổi vật chất hoặc tình trạng thì dùng 变成.","ex":[["他从一个学生成为了老师。","Từ một học sinh, anh ấy trở thành giáo viên.","Tā cóng yí ge xuésheng chéngwéi le lǎoshī."],["天气变成阴天了。","Trời chuyển thành âm u.","Tiānqì biàn chéng yīntiān le."]]},"grams":[{"t":"成为 và 变成 — trở thành hay biến thành","b":"成为 + danh từ (địa vị mới) · 变成 + danh từ (hình dạng mới)","d":"他成为了老师 (đạt được vị trí). 冰变成了水 (chất đổi hình). Nói về người và sự nghiệp thì dùng 成为; nói về sự biến đổi vật chất hoặc tình trạng thì dùng 变成.","ex":[["他从一个学生成为了老师。","Từ một học sinh, anh ấy trở thành giáo viên.","Tā cóng yí ge xuésheng chéngwéi le lǎoshī."],["天气变成阴天了。","Trời chuyển thành âm u.","Tiānqì biàn chéng yīntiān le."]]},{"t":"Các cặp trái nghĩa của sự tăng giảm","b":"提高 ↔ 降低 · 扩大 ↔ 缩小 · 增加 ↔ 减少","d":"Ba cặp này luôn đi cùng những tân ngữ nhất định: 提高水平／降低价格, 扩大影响／缩小范围, 增加收入／减少压力. Học theo cặp và theo cụm cố định, đừng học rời.","ex":[["我要提高我的汉语水平。","Tôi muốn nâng cao trình độ tiếng Trung.","Wǒ yào tígāo wǒ de Hànyǔ shuǐpíng."]]},{"t":"Ba động từ \"gửi\": 寄 · 发 · 送","b":"寄 (bưu điện) · 发 (tin nhắn, email) · 送 (đưa tận nơi, tặng)","d":"寄信/寄包裹 qua bưu điện. 发短信/发邮件 qua điện tử. 送 vừa là tặng quà (送礼物) vừa là đưa tiễn ai đó (送你回家). Chọn sai động từ là lỗi rất hay gặp.","ex":[["我给他发了一条短信。","Tôi gửi cho anh ấy một tin nhắn.","Wǒ gěi tā fā le yì tiáo duǎnxìn."],["我送你回家吧。","Để tôi đưa bạn về nhà.","Wǒ sòng nǐ huí jiā ba."]]}],"items":[{"zh":"改变","py":"gǎibiàn","vi":"thay đổi","hv":"cải biến","note":"Chính là \"cải biến\" tiếng Việt: 改 (cải) + 变 (biến). Cần tân ngữ: 改变习惯, 改变主意.","ex":"学汉语改变了我的生活。","exPy":"Xué Hànyǔ gǎibiàn le wǒ de shēnghuó.","exVi":"Học tiếng Trung đã thay đổi cuộc sống của tôi.","w":"学 汉语 改变 了 我 的 生活。"},{"zh":"成为","py":"chéngwéi","vi":"trở thành","hv":"thành vi","note":"成 (thành) + 为 (vi, làm). Bắt buộc có tân ngữ: 成为老师. Khác 变成 (biến thành, nhấn quá trình đổi).","ex":"他的梦想是成为一名翻译。","exPy":"Tā de mèngxiǎng shì chéngwéi yì míng fānyì.","exVi":"Ước mơ của anh ấy là trở thành phiên dịch.","w":"他 的 梦想 是 成为 一 名 翻译。"},{"zh":"出发","py":"chūfā","vi":"xuất phát, khởi hành","hv":"xuất phát","note":"Chính là \"xuất phát\" tiếng Việt: 出 (xuất) + 发 (phát).","ex":"我们六点出发，别迟到。","exPy":"Wǒmen liù diǎn chūfā, bié chídào.","exVi":"Sáu giờ ta xuất phát, đừng trễ.","w":"我们 六 点 出发， 别 迟到。"},{"zh":"降低","py":"jiàngdī","vi":"hạ xuống, giảm","hv":"giáng đê","note":"降 (giáng, hạ — như \"giáng chức\") + 低 (thấp). Trái nghĩa là 提高.","ex":"多睡觉可以降低压力。","exPy":"Duō shuìjiào kěyǐ jiàngdī yālì.","exVi":"Ngủ nhiều có thể giảm áp lực.","w":"多 睡觉 可以 降低 压力。"},{"zh":"扩大","py":"kuòdà","vi":"mở rộng","hv":"khoách đại","note":"扩 (khoách, mở rộng) + 大 (lớn). Đi với 范围, 影响, 规模. Trái nghĩa là 缩小.","ex":"读书能扩大我们的知识面。","exPy":"Dú shū néng kuòdà wǒmen de zhīshi miàn.","exVi":"Đọc sách giúp mở rộng hiểu biết.","w":"读书 能 扩大 我们 的 知识 面。"},{"zh":"留","py":"liú","vi":"để lại, ở lại","hv":"lưu","note":"Chính là \"lưu\" tiếng Việt (\"lưu lại\", \"lưu học sinh\"). 留学 = du học, 留下 = để lại.","ex":"请把你的电话号码留给我。","exPy":"Qǐng bǎ nǐ de diànhuà hàomǎ liú gěi wǒ.","exVi":"Xin để lại số điện thoại cho tôi.","w":"请 把 你 的 电话 号码 留 给 我。"},{"zh":"取","py":"qǔ","vi":"lấy, rút","hv":"thủ","note":"Chữ hội ý: 耳 (tai) + 又 (tay) — thời xưa lính lấy tai địch làm chứng công. 取钱 = rút tiền.","ex":"包裹到了，你去取一下。","exPy":"Bāoguǒ dào le, nǐ qù qǔ yíxià.","exVi":"Bưu kiện đến rồi, bạn đi lấy nhé.","w":"包裹 到 了， 你 去 取 一下。"},{"zh":"交","py":"jiāo","vi":"nộp, giao; kết bạn","hv":"giao","note":"Chính là \"giao\" tiếng Việt. 交作业 = nộp bài, 交朋友 = kết bạn, 交给我 = giao cho tôi.","ex":"在中国我交了很多朋友。","exPy":"Zài Zhōngguó wǒ jiāo le hěn duō péngyou.","exVi":"Ở Trung Quốc tôi kết được nhiều bạn.","w":"在 中国 我 交 了 很 多 朋友。"},{"zh":"寄","py":"jì","vi":"gửi (bưu điện)","hv":"ký","note":"Tiếng Việt: \"ký gửi\", \"ký thác\". Bộ 宀 (mái nhà). Chỉ dùng cho gửi qua bưu điện, khác 发 (gửi tin nhắn).","ex":"这封信要寄到北京。","exPy":"Zhè fēng xìn yào jì dào Běijīng.","exVi":"Lá thư này gửi tới Bắc Kinh.","w":"这 封 信 要 寄 到 北京。"},{"zh":"剩","py":"shèng","vi":"còn thừa, còn lại","hv":"thặng","note":"Tiếng Việt: \"thặng dư\". Thường đi với 下: 剩下 = còn lại.","ex":"钱花完了，只剩下一点儿。","exPy":"Qián huā wán le, zhǐ shèng xià yìdiǎnr.","exVi":"Tiền tiêu hết rồi, chỉ còn lại một ít.","w":"钱 花 完 了， 只 剩 下 一点儿。"}],"newChars":["改","变","成","为","降","低","扩","大","留","取","交","寄","剩"],"outro":"很好！Xong bài 150."};
G.ROOMS["zh-l151"] = {"id":"zh-l151","lang":"zh","level":4,"no":151,"teacher":"wang","title":"HSK4 · Bài 151 · 日常生活 Sinh hoạt thường nhật","intro":["现在很多人喜欢网上购物。","Bài 151: Từ khẩu ngữ dùng hằng ngày — mua sắm, phiền phức, vừa hay, tuỳ tiện. Bấm 1 · Học để bắt đầu."],"introPy":"Xiànzài hěn duō rén xǐhuan wǎng shàng gòuwù.","gram":{"t":"麻烦 — ba cách dùng trong một từ","b":"麻烦 + người + động từ (nhờ vả) · 很麻烦 (tính từ) · 遇到麻烦 (danh từ)","d":"Đây là từ đa năng nhất của khẩu ngữ tiếng Trung. Khi nhờ ai, 麻烦你… lịch sự hơn 请你… nhiều, vì thể hiện mình biết là đang làm phiền họ.","ex":[["麻烦您让一下。","Phiền ngài nhường chút.","Máfan nín ràng yíxià."],["他遇到了一点儿麻烦。","Anh ấy gặp chút rắc rối.","Tā yù dào le yìdiǎnr máfan."]]},"grams":[{"t":"麻烦 — ba cách dùng trong một từ","b":"麻烦 + người + động từ (nhờ vả) · 很麻烦 (tính từ) · 遇到麻烦 (danh từ)","d":"Đây là từ đa năng nhất của khẩu ngữ tiếng Trung. Khi nhờ ai, 麻烦你… lịch sự hơn 请你… nhiều, vì thể hiện mình biết là đang làm phiền họ.","ex":[["麻烦您让一下。","Phiền ngài nhường chút.","Máfan nín ràng yíxià."],["他遇到了一点儿麻烦。","Anh ấy gặp chút rắc rối.","Tā yù dào le yìdiǎnr máfan."]]},{"t":"行 · 可以 · 好 — ba cách nói \"được\"","b":"行 (khẩu ngữ, đồng ý) · 可以 (được phép) · 好 (đồng ý làm)","d":"Ai xin phép: 我可以进来吗？— trả lời 可以. Ai đề nghị: 我们六点走吧 — trả lời 行 hoặc 好. 不行 mang giọng dứt khoát hơn 不可以.","ex":[["这样行不行？","Thế này được không?","Zhèyàng xíng bu xíng?"]]},{"t":"乱 làm phó từ — làm việc gì đó một cách bừa bãi","b":"乱 + động từ","d":"乱说 (nói bừa), 乱写 (viết bừa), 乱花钱 (tiêu tiền bừa), 乱扔垃圾 (vứt rác bừa). Mẫu này rất hay gặp trong lời nhắc nhở và biển báo.","ex":[["请不要乱扔垃圾。","Xin đừng vứt rác bừa bãi.","Qǐng búyào luàn rēng lājī."]]}],"items":[{"zh":"购物","py":"gòuwù","vi":"mua sắm","hv":"cấu vật","note":"购 (cấu, mua) + 物 (vật). Trang trọng hơn 买东西, hay thấy trong 网上购物 (mua sắm online).","ex":"现在很多人喜欢网上购物。","exPy":"Xiànzài hěn duō rén xǐhuan wǎng shàng gòuwù.","exVi":"Bây giờ nhiều người thích mua sắm online.","w":"现在 很 多 人 喜欢 网上 购物。"},{"zh":"活动","py":"huódòng","vi":"hoạt động, sự kiện","hv":"hoạt động","note":"Chính là \"hoạt động\" tiếng Việt: 活 (hoạt, sống) + 动 (động).","ex":"这次活动有一百多人参加。","exPy":"Zhè cì huódòng yǒu yìbǎi duō rén cānjiā.","exVi":"Hoạt động lần này có hơn trăm người dự.","w":"这 次 活动 有 一 百 多 人 参加。"},{"zh":"麻烦","py":"máfan","vi":"phiền phức; làm phiền","hv":"ma phiền","note":"Ba vai. Câu lịch sự cực hay dùng: 麻烦你了 (làm phiền bạn rồi), 麻烦您帮我… (phiền ngài giúp tôi…).","ex":"麻烦你了，真不好意思。","exPy":"Máfan nǐ le, zhēn bù hǎoyìsi.","exVi":"Làm phiền bạn rồi, thật ngại quá.","w":"麻烦 你 了， 真 不好意思。"},{"zh":"随便","py":"suíbiàn","vi":"tuỳ ý, sao cũng được","hv":"tuỳ tiện","note":"随 (tuỳ) + 便 (tiện). Trả lời 随便 khi ai hỏi ăn gì. Nhưng tả người 他很随便 lại mang nghĩa xấu (cẩu thả).","ex":"你随便坐，别客气。","exPy":"Nǐ suíbiàn zuò, bié kèqi.","exVi":"Bạn cứ ngồi tự nhiên, đừng khách sáo.","w":"你 随便 坐， 别 客气。"},{"zh":"正好","py":"zhènghǎo","vi":"vừa hay, vừa vặn","hv":"chính hảo","note":"Hai nghĩa: vừa vặn kích cỡ (这双鞋正好) và tình cờ đúng lúc (我正好也要去).","ex":"这件衣服的大小正好。","exPy":"Zhè jiàn yīfu de dàxiǎo zhènghǎo.","exVi":"Bộ đồ này vừa vặn.","w":"这 件 衣服 的 大小 正好。"},{"zh":"最好","py":"zuìhǎo","vi":"tốt nhất là, nên","hv":"tối hảo","note":"Dùng để khuyên nhẹ nhàng: 你最好早点儿去 (bạn nên đi sớm chút). Mềm hơn 应该.","ex":"你最好带把伞，可能会下雨。","exPy":"Nǐ zuìhǎo dài bǎ sǎn, kěnéng huì xià yǔ.","exVi":"Bạn nên mang ô, có thể mưa đấy.","w":"你 最好 带 把 伞， 可能 会 下雨。"},{"zh":"行","py":"xíng","vi":"được, ổn","hv":"hành","note":"Chính là \"hành\" tiếng Việt (\"hành động\", \"ngân hàng\" đọc háng). Khẩu ngữ: 行！= được!","ex":"明天见面行吗？","exPy":"Míngtiān jiànmiàn xíng ma?","exVi":"Mai gặp được không?","w":"明天 见面 行 吗？"},{"zh":"热闹","py":"rènao","vi":"náo nhiệt, đông vui","hv":"nhiệt náo","note":"热 (nhiệt) + 闹 (náo). Là từ mang nghĩa TỐT trong tiếng Trung — đông vui, không phải ồn ào khó chịu.","ex":"节日的街上非常热闹。","exPy":"Jiérì de jiē shàng fēicháng rènao.","exVi":"Phố ngày lễ vô cùng náo nhiệt.","w":"节日 的 街 上 非常 热闹。"},{"zh":"乱","py":"luàn","vi":"lộn xộn; bừa","hv":"loạn","note":"Chính là \"loạn\" tiếng Việt. Làm phó từ nghĩa là làm bừa: 别乱说 (đừng nói bừa), 乱扔 (vứt bừa).","ex":"别把东西放得乱七八糟。","exPy":"Bié bǎ dōngxi fàng de luànqībāzāo.","exVi":"Đừng để đồ đạc bừa bộn lung tung.","w":"别 把 东西 放 得 乱七八糟。"},{"zh":"假","py":"jiǎ","vi":"giả, không thật","hv":"giả","note":"Chính là \"giả\" tiếng Việt. Đọc jiǎ là giả dối; đọc jià là kỳ nghỉ (放假, 假期) — một chữ hai âm.","ex":"买东西要小心买到假货。","exPy":"Mǎi dōngxi yào xiǎoxīn mǎi dào jiǎ huò.","exVi":"Mua đồ phải cẩn thận kẻo mua phải hàng giả.","w":"买 东西 要 小心 买 到 假 货。"}],"newChars":["购","物","活","动","麻","烦","正","最","行","热","闹","乱"],"outro":"很好！Xong bài 151."};
G.ROOMS["zh-l152"] = {"id":"zh-l152","lang":"zh","level":4,"no":152,"teacher":"wang","title":"HSK4 · Bài 152 · 空气和周围 Không khí và xung quanh","intro":["下雨以后空气特别好。","Bài 152: Thời tiết, môi trường xung quanh và một nhóm chữ đơn đa nghĩa hay gặp. Bấm 1 · Học để bắt đầu."],"introPy":"Xià yǔ yǐhòu kōngqì tèbié hǎo.","gram":{"t":"当 … 的时候 — khung câu chỉ thời điểm","b":"当 + mệnh đề + 的时候，…","d":"当我第一次去中国的时候，我一句汉语也不会说. Có thể bỏ 当 mà vẫn đúng, nhưng có 当 thì câu trang trọng và rõ ràng hơn — hay dùng khi kể chuyện hoặc viết văn.","ex":[["当我遇到困难的时候，朋友都会帮我。","Khi tôi gặp khó khăn, bạn bè đều giúp tôi.","Dāng wǒ yù dào kùnnan de shíhou, péngyou dōu huì bāng wǒ."]]},"grams":[{"t":"当 … 的时候 — khung câu chỉ thời điểm","b":"当 + mệnh đề + 的时候，…","d":"当我第一次去中国的时候，我一句汉语也不会说. Có thể bỏ 当 mà vẫn đúng, nhưng có 当 thì câu trang trọng và rõ ràng hơn — hay dùng khi kể chuyện hoặc viết văn.","ex":[["当我遇到困难的时候，朋友都会帮我。","Khi tôi gặp khó khăn, bạn bè đều giúp tôi.","Dāng wǒ yù dào kùnnan de shíhou, péngyou dōu huì bāng wǒ."]]},{"t":"当 · 做 · 成为 — ba cách nói \"làm nghề\"","b":"当老师 (khẩu ngữ) · 做老师 (trung tính) · 成为老师 (trang trọng, nhấn quá trình)","d":"Cả ba đều đúng, khác sắc thái. 当 nhấn vào việc đảm nhận vai trò, 做 nhấn vào công việc thường ngày, 成为 nhấn vào việc TRỞ THÀNH sau một quá trình.","ex":[["我姐姐在中学当老师。","Chị tôi làm giáo viên cấp hai.","Wǒ jiějie zài zhōngxué dāng lǎoshī."]]},{"t":"Cấu trúc \"nơi chốn + 有\" tả cảnh vật xung quanh","b":"địa điểm + 周围／附近 + 有 + sự vật","d":"Đây là mẫu câu tả cảnh cơ bản, hay dùng khi giới thiệu nơi ở: 我家附近有一个公园，公园周围有很多树. Ghi nhớ: 周围 là vòng quanh, 附近 là gần đó (không nhất thiết bao quanh).","ex":[["我家周围很安静。","Xung quanh nhà tôi rất yên tĩnh.","Wǒ jiā zhōuwéi hěn ānjìng."]]}],"items":[{"zh":"空气","py":"kōngqì","vi":"không khí","hv":"không khí","note":"Chính là \"không khí\" tiếng Việt: 空 (không, bài 97) + 气 (khí).","ex":"下雨以后空气特别好。","exPy":"Xià yǔ yǐhòu kōngqì tèbié hǎo.","exVi":"Sau mưa không khí đặc biệt trong lành.","w":"下雨 以后 空气 特别 好。"},{"zh":"凉快","py":"liángkuai","vi":"mát mẻ","hv":"lương khoái","note":"凉 (lương, mát — bộ 冫 hai chấm băng) + 快. Tiếng Việt: \"lương\" trong \"thanh lương\".","ex":"今天比昨天凉快多了。","exPy":"Jīntiān bǐ zuótiān liángkuai duō le.","exVi":"Hôm nay mát hơn hôm qua nhiều.","w":"今天 比 昨天 凉快 多 了。"},{"zh":"暖和","py":"nuǎnhuo","vi":"ấm áp","hv":"noãn hoà","note":"暖 (noãn, ấm — bộ 日 mặt trời) + 和. Trái nghĩa với 凉快. Chú ý 和 ở đây đọc nhẹ huo.","ex":"南方的冬天比较暖和。","exPy":"Nánfāng de dōngtiān bǐjiào nuǎnhuo.","exVi":"Mùa đông miền Nam khá ấm.","w":"南方 的 冬天 比较 暖和。"},{"zh":"严重","py":"yánzhòng","vi":"nghiêm trọng","hv":"nghiêm trọng","note":"Chính là \"nghiêm trọng\" tiếng Việt: 严 (nghiêm) + 重 (trọng, đọc zhòng).","ex":"他的病很严重，要住院。","exPy":"Tā de bìng hěn yánzhòng, yào zhùyuàn.","exVi":"Bệnh của anh ấy nặng, phải nhập viện.","w":"他 的 病 很 严重， 要 住院。"},{"zh":"自然","py":"zìrán","vi":"tự nhiên; thiên nhiên","hv":"tự nhiên","note":"Chính là \"tự nhiên\" tiếng Việt: 自 (tự) + 然 (nhiên). Hai nghĩa: thiên nhiên và không gượng ép.","ex":"我们应该保护自然环境。","exPy":"Wǒmen yīnggāi bǎohù zìrán huánjìng.","exVi":"Chúng ta nên bảo vệ môi trường tự nhiên.","w":"我们 应该 保护 自然 环境。"},{"zh":"周围","py":"zhōuwéi","vi":"xung quanh","hv":"chu vi","note":"周 (chu, vòng quanh) + 围 (vi, vây). Tiếng Việt \"chu vi\" là thuật ngữ toán học, nghĩa gốc giống nhau.","ex":"他周围的朋友都很热情。","exPy":"Tā zhōuwéi de péngyou dōu hěn rèqíng.","exVi":"Bạn bè xung quanh anh ấy đều rất nhiệt tình.","w":"他 周围 的 朋友 都 很 热情。"},{"zh":"毛","py":"máo","vi":"lông; hào (tiền)","hv":"mao","note":"Chính là \"mao\" tiếng Việt (\"lông mao\"). Hai nghĩa: lông (羊毛 len) và đơn vị tiền = 1/10 nguyên.","ex":"这件毛衣是羊毛的。","exPy":"Zhè jiàn máoyī shì yángmáo de.","exVi":"Cái áo len này bằng lông cừu.","w":"这 件 毛衣 是 羊 毛 的。"},{"zh":"响","py":"xiǎng","vi":"kêu, vang; to (tiếng)","hv":"hưởng","note":"Tiếng Việt: \"âm hưởng\", \"ảnh hưởng\". Vừa là động từ (电话响了) vừa là tính từ (声音很响).","ex":"外面的声音太响了。","exPy":"Wàimiàn de shēngyīn tài xiǎng le.","exVi":"Tiếng ngoài kia to quá.","w":"外面 的 声音 太 响 了。"},{"zh":"底","py":"dǐ","vi":"đáy; cuối","hv":"để","note":"Bộ 广. Đã gặp trong 到底 (bài 104). Chỉ thời gian: 月底 (cuối tháng), 年底 (cuối năm).","ex":"年底公司会给大家发奖金。","exPy":"Niándǐ gōngsī huì gěi dàjiā fā jiǎngjīn.","exVi":"Cuối năm công ty sẽ phát thưởng cho mọi người.","w":"年底 公司 会 给 大家 发 奖金。"},{"zh":"当","py":"dāng","vi":"làm (nghề); khi","hv":"đương","note":"Chính là \"đương\" tiếng Việt (\"đương thời\", \"đảm đương\"). 当老师 = làm thầy giáo; 当…的时候 = khi….","ex":"当我看到那封信的时候，我哭了。","exPy":"Dāng wǒ kàn dào nà fēng xìn de shíhou, wǒ kū le.","exVi":"Khi tôi nhìn thấy lá thư đó, tôi đã khóc.","w":"当 我 看 到 那 封 信 的 时候， 我 哭 了。"}],"newChars":["空","凉","快","暖","和","严","周","围","毛","响","当"],"outro":"很好！Xong bài 152."};
G.ROOMS["zh-l153"] = {"id":"zh-l153","lang":"zh","level":4,"no":153,"teacher":"wang","title":"HSK4 · Bài 153 · 人和社会 Con người và xã hội","intro":["一百人民币大约是多少越南盾？","Bài 153: Từ vựng khai báo thông tin cá nhân và nói về xã hội — cần cho mọi biểu mẫu tiếng Trung. Bấm 1 · Học để bắt đầu."],"introPy":"Yìbǎi rénmínbì dàyuē shì duōshao Yuènán dùn?","gram":{"t":"BẠN GIẢ Hán Việt: 困难 KHÔNG phải \"khốn nạn\"","b":"困难 = khó khăn (trung tính) · \"khốn nạn\" tiếng Việt = xấu xa, đê tiện","d":"Đây là một trong những cái bẫy Hán Việt nguy hiểm nhất. 生活很困难 nghĩa là cuộc sống khó khăn, hoàn toàn không có ý chê bai. Bổ sung danh sách bẫy đã học: 紧张 ≠ khẩn trương, 同情 ≠ đồng tình, 仔细 ≠ tử tế, 博士 ≠ bác sĩ, 方便 ≠ phương tiện.","ex":[["他家生活比较困难。","Cuộc sống nhà anh ấy khá khó khăn.","Tā jiā shēnghuó bǐjiào kùnnan."]]},"grams":[{"t":"BẠN GIẢ Hán Việt: 困难 KHÔNG phải \"khốn nạn\"","b":"困难 = khó khăn (trung tính) · \"khốn nạn\" tiếng Việt = xấu xa, đê tiện","d":"Đây là một trong những cái bẫy Hán Việt nguy hiểm nhất. 生活很困难 nghĩa là cuộc sống khó khăn, hoàn toàn không có ý chê bai. Bổ sung danh sách bẫy đã học: 紧张 ≠ khẩn trương, 同情 ≠ đồng tình, 仔细 ≠ tử tế, 博士 ≠ bác sĩ, 方便 ≠ phương tiện.","ex":[["他家生活比较困难。","Cuộc sống nhà anh ấy khá khó khăn.","Tā jiā shēnghuó bǐjiào kùnnan."]]},{"t":"合适 và 适合 — tính từ hay động từ?","b":"合适 = tính từ (không mang tân ngữ) · 适合 = động từ (phải có tân ngữ)","d":"这个工作很合适 (đúng). 这个工作很适合你 (đúng). Nhưng 这个工作很合适你 là SAI. Nhớ: chữ nào đứng sau thì quyết định từ loại — 合适 đuôi 适 là tính từ, 适合 đuôi 合 là động từ.","ex":[["这本书很适合初学者。","Quyển sách này rất hợp với người mới học.","Zhè běn shū hěn shìhé chūxuézhě."]]},{"t":"Hậu tố 者 và 员 — hai cách gọi tên người","b":"者 (người có tính chất đó) · 员 (thành viên của tổ chức)","d":"作者, 读者, 记者, 志愿者, 初学者 — dùng 者. 服务员, 售货员, 演员, 运动员 — dùng 员. Nhận ra hai hậu tố này giúp bạn đoán nghĩa hàng trăm từ chỉ nghề nghiệp.","ex":[["我还是一个初学者。","Tôi vẫn là người mới học.","Wǒ háishi yí ge chūxuézhě."]]}],"items":[{"zh":"人民币","py":"rénmínbì","vi":"nhân dân tệ (RMB)","hv":"nhân dân tệ","note":"人民 (nhân dân) + 币 (tệ, tiền). Đơn vị đọc là 元 (viết) hay 块 (nói).","ex":"一百人民币大约是多少越南盾？","exPy":"Yìbǎi rénmínbì dàyuē shì duōshao Yuènán dùn?","exVi":"Một trăm nhân dân tệ khoảng bao nhiêu tiền Việt?","w":"一 百 人民币 大约 是 多少 越 南 盾？"},{"zh":"志愿者","py":"zhìyuànzhě","vi":"tình nguyện viên","hv":"chí nguyện giả","note":"志愿 (chí nguyện) + 者 (giả, người). Hậu tố 者 tạo danh từ chỉ người: 作者, 读者, 记者.","ex":"很多大学生假期去当志愿者。","exPy":"Hěn duō dàxuéshēng jiàqī qù dāng zhìyuànzhě.","exVi":"Nhiều sinh viên đi làm tình nguyện viên dịp nghỉ.","w":"很 多 大学生 假期 去 当 志愿者。"},{"zh":"性别","py":"xìngbié","vi":"giới tính","hv":"tính biệt","note":"性 (tính) + 别 (biệt, phân biệt). Trường bắt buộc trên mọi biểu mẫu Trung Quốc.","ex":"表格上要填姓名和性别。","exPy":"Biǎogé shàng yào tián xìngmíng hé xìngbié.","exVi":"Trên biểu mẫu phải điền họ tên và giới tính.","w":"表格 上 要 填 姓名 和 性别。"},{"zh":"年龄","py":"niánlíng","vi":"tuổi, độ tuổi","hv":"niên linh","note":"年 (niên) + 龄 (linh, tuổi — bộ 齿 răng, vì xưa xem răng đoán tuổi). Trang trọng hơn 岁.","ex":"他看起来比实际年龄小。","exPy":"Tā kàn qǐlái bǐ shíjì niánlíng xiǎo.","exVi":"Anh ấy trông trẻ hơn tuổi thật.","w":"他 看 起来 比 实际 年龄 小。"},{"zh":"国际","py":"guójì","vi":"quốc tế","hv":"quốc tế","note":"Chính là \"quốc tế\" tiếng Việt: 国 (quốc) + 际 (tế). 国际机场 = sân bay quốc tế.","ex":"汉语现在是一门国际语言。","exPy":"Hànyǔ xiànzài shì yì mén guójì yǔyán.","exVi":"Tiếng Trung nay là một ngôn ngữ quốc tế.","w":"汉语 现在 是 一 门 国际 语言。"},{"zh":"熟悉","py":"shúxī","vi":"quen thuộc, thông thạo","hv":"thục tất","note":"熟 (thục, chín, thành thạo) + 悉 (tất, biết rõ). Tiếng Việt: \"thành thục\", \"tường tất\".","ex":"刚来的时候我谁也不熟悉。","exPy":"Gāng lái de shíhou wǒ shéi yě bù shúxī.","exVi":"Lúc mới đến tôi chẳng quen ai.","w":"刚 来 的 时候 我 谁 也 不 熟悉。"},{"zh":"合适","py":"héshì","vi":"phù hợp, vừa","hv":"hợp thích","note":"合 (hợp) + 适 (thích, thích hợp). Là TÍNH TỪ, không mang tân ngữ — khác 适合 là động từ.","ex":"这个时间对你合适吗？","exPy":"Zhège shíjiān duì nǐ héshì ma?","exVi":"Giờ này với bạn có tiện không?","w":"这个 时间 对 你 合适 吗？"},{"zh":"困难","py":"kùnnan","vi":"khó khăn","hv":"khốn nan","note":"困 (khốn, bài 109) + 难 (nan). Tiếng Việt \"khốn nạn\" đã đổi nghĩa hoàn toàn — đây là BẠN GIẢ, đừng dịch bừa!","ex":"学习中遇到困难是很正常的。","exPy":"Xuéxí zhōng yù dào kùnnan shì hěn zhèngcháng de.","exVi":"Học mà gặp khó khăn là chuyện bình thường.","w":"学习 中 遇到 困难 是 很 正常 的。"},{"zh":"不仅","py":"bùjǐn","vi":"không chỉ","hv":"bất cận","note":"Đồng nghĩa 不但 nhưng trang trọng hơn. Cặp: 不仅…，而且／还….","ex":"他不仅聪明，而且很努力。","exPy":"Tā bùjǐn cōngming, érqiě hěn nǔlì.","exVi":"Cậu ấy không chỉ thông minh mà còn chăm.","w":"他 不仅 聪明， 而且 很 努力。"},{"zh":"来自","py":"láizì","vi":"đến từ","hv":"lai tự","note":"来 (lai, đến) + 自 (tự, từ). Trang trọng hơn 从…来: 我来自越南.","ex":"我们班的学生来自十个国家。","exPy":"Wǒmen bān de xuésheng láizì shí ge guójiā.","exVi":"Học sinh lớp tôi đến từ mười nước.","w":"我们 班 的 学生 来自 十 个 国家。"}],"newChars":["民","币","志","愿","者","性","龄","际","熟","悉","合","适","仅","来"],"outro":"很好！Xong bài 153."};
G.ROOMS["zh-l154"] = {"id":"zh-l154","lang":"zh","level":4,"no":154,"teacher":"wang","title":"HSK4 · Bài 154 · 运动和习惯 Thể thao và rèn thói quen","intro":["周末我们一起去打网球吧。","Bài 154: Thể thao và cách nói về việc rèn luyện — bài áp chót, cũng là lời khuyên cho chính việc học của bạn. Bấm 1 · Học để bắt đầu."],"introPy":"Zhōumò wǒmen yìqǐ qù dǎ wǎngqiú ba.","gram":{"t":"打 · 踢 · 做 — chọn động từ đúng cho từng môn","b":"打 (dùng tay): 打篮球／打网球／打乒乓球 · 踢 (dùng chân): 踢足球 · 做／练 (vận động chung): 做运动／练太极","d":"Nói 打足球 là sai — bóng đá phải dùng 踢. Bơi và chạy có động từ riêng: 游泳, 跑步. Đây là kiến thức nhỏ nhưng lộ trình độ ngay lập tức.","ex":[["他喜欢踢足球，我喜欢打篮球。","Anh ấy thích đá bóng, tôi thích chơi bóng rổ.","Tā xǐhuan tī zúqiú, wǒ xǐhuan dǎ lánqiú."]]},"grams":[{"t":"打 · 踢 · 做 — chọn động từ đúng cho từng môn","b":"打 (dùng tay): 打篮球／打网球／打乒乓球 · 踢 (dùng chân): 踢足球 · 做／练 (vận động chung): 做运动／练太极","d":"Nói 打足球 là sai — bóng đá phải dùng 踢. Bơi và chạy có động từ riêng: 游泳, 跑步. Đây là kiến thức nhỏ nhưng lộ trình độ ngay lập tức.","ex":[["他喜欢踢足球，我喜欢打篮球。","Anh ấy thích đá bóng, tôi thích chơi bóng rổ.","Tā xǐhuan tī zúqiú, wǒ xǐhuan dǎ lánqiú."]]},{"t":"养成 … 的习惯 — mẫu câu nói về thói quen","b":"养成 + 动词 + 的习惯","d":"养成每天写汉字的习惯 (rèn thói quen mỗi ngày viết chữ Hán). Đây chính là điều quan trọng nhất khi học tiếng Trung: mỗi ngày một ít, hơn hẳn học dồn một buổi dài.","ex":[["我养成了每天听中文的习惯。","Tôi đã rèn được thói quen mỗi ngày nghe tiếng Trung.","Wǒ yǎngchéng le měi tiān tīng Zhōngwén de xíguàn."]]},{"t":"对 … 有好处 — nói về lợi ích","b":"A 对 B 有好处／没有好处","d":"运动对身体有好处 (vận động có lợi cho sức khoẻ). 熬夜对健康没有好处. Cấu trúc song song: 对…有帮助, 对…有影响. Ba khung này bao trọn cách nói về ảnh hưởng.","ex":[["多写多练对记汉字很有帮助。","Viết nhiều luyện nhiều rất giúp ích cho việc nhớ chữ Hán.","Duō xiě duō liàn duì jì Hànzì hěn yǒu bāngzhù."]]}],"items":[{"zh":"网球","py":"wǎngqiú","vi":"quần vợt","hv":"võng cầu","note":"网 (võng, lưới) + 球 (cầu, bóng). Quy tắc: môn bóng nào cũng là X + 球 — 篮球, 足球, 排球.","ex":"周末我们一起去打网球吧。","exPy":"Zhōumò wǒmen yìqǐ qù dǎ wǎngqiú ba.","exVi":"Cuối tuần chúng ta đi chơi quần vợt nhé.","w":"周末 我们 一起 去 打 网球 吧。"},{"zh":"乒乓球","py":"pīngpāngqiú","vi":"bóng bàn","hv":"banh bàng cầu","note":"乒乓 là từ TƯỢNG THANH — đọc lên nghe đúng tiếng bóng nảy. Môn thể thao quốc dân của Trung Quốc.","ex":"学校里有三张乒乓球台。","exPy":"Xuéxiào lǐ yǒu sān zhāng pīngpāngqiú tái.","exVi":"Trong trường có ba bàn bóng bàn.","w":"学校 里 有 三 张 乒乓球 台。"},{"zh":"棒","py":"bàng","vi":"giỏi, tuyệt; gậy","hv":"bổng","note":"Tiếng Việt: \"bổng\" trong \"côn bổng\". Khẩu ngữ khen ngợi: 你真棒！= bạn giỏi thật!","ex":"他写的字真棒。","exPy":"Tā xiě de zì zhēn bàng.","exVi":"Chữ anh ấy viết đẹp thật.","w":"他 写 的 字 真 棒。"},{"zh":"流行","py":"liúxíng","vi":"thịnh hành, phổ biến","hv":"lưu hành","note":"Chính là \"lưu hành\" tiếng Việt: 流 (lưu, chảy) + 行 (hành). 流行音乐 = nhạc pop.","ex":"今年流行这种颜色。","exPy":"Jīnnián liúxíng zhè zhǒng yánsè.","exVi":"Năm nay thịnh hành màu này.","w":"今年 流行 这 种 颜色。"},{"zh":"养成","py":"yǎngchéng","vi":"rèn thành, tạo thành","hv":"dưỡng thành","note":"养 (dưỡng, nuôi) + 成 (thành). Hầu như luôn đi với 习惯: 养成好习惯.","ex":"养成早睡早起的习惯很重要。","exPy":"Yǎngchéng zǎo shuì zǎo qǐ de xíguàn hěn zhòngyào.","exVi":"Rèn thói quen ngủ sớm dậy sớm rất quan trọng.","w":"养成 早 睡 早 起 的 习惯 很 重要。"},{"zh":"放松","py":"fàngsōng","vi":"thư giãn","hv":"phóng tùng","note":"放 (buông) + 松 (tùng, lỏng). Trái nghĩa với 紧张. Nhớ: 紧张 là hồi hộp, không phải \"khẩn trương\".","ex":"写字的时候手要放松。","exPy":"Xiě zì de shíhou shǒu yào fàngsōng.","exVi":"Lúc viết chữ tay phải thả lỏng.","w":"写 字 的 时候 手 要 放松。"},{"zh":"动作","py":"dòngzuò","vi":"động tác","hv":"động tác","note":"Chính là \"động tác\" tiếng Việt: 动 (động) + 作 (tác).","ex":"老师又做了一遍这个动作。","exPy":"Lǎoshī yòu zuò le yí biàn zhège dòngzuò.","exVi":"Thầy làm lại động tác này một lượt nữa.","w":"老师 又 做 了 一 遍 这个 动作。"},{"zh":"对面","py":"duìmiàn","vi":"đối diện, phía trước mặt","hv":"đối diện","note":"Chính là \"đối diện\" tiếng Việt: 对 (đối) + 面 (diện).","ex":"我家对面就是超市。","exPy":"Wǒ jiā duìmiàn jiù shì chāoshì.","exVi":"Đối diện nhà tôi chính là siêu thị.","w":"我 家 对面 就是 超市。"},{"zh":"重点","py":"zhòngdiǎn","vi":"trọng điểm, điểm chính","hv":"trọng điểm","note":"Chính là \"trọng điểm\" tiếng Việt: 重 (trọng, đọc zhòng) + 点 (điểm).","ex":"复习的时候要抓住重点。","exPy":"Fùxí de shíhou yào zhuā zhù zhòngdiǎn.","exVi":"Lúc ôn tập phải nắm trọng điểm.","w":"复习 的 时候 要 抓 住 重点。"},{"zh":"好处","py":"hǎochù","vi":"lợi ích, cái lợi","hv":"hảo xứ","note":"好 (tốt) + 处 (xứ, chỗ). Trái nghĩa là 坏处. Dùng với 有: 运动有很多好处.","ex":"每天运动对身体有很多好处。","exPy":"Měi tiān yùndòng duì shēntǐ yǒu hěn duō hǎochù.","exVi":"Vận động mỗi ngày rất có lợi cho sức khoẻ.","w":"每 天 运动 对 身体 有 很 多 好处。"}],"newChars":["网","球","乒","乓","棒","养","放","松","处"],"outro":"很好！Xong bài 154."};
G.ROOMS["zh-l155"] = {"id":"zh-l155","lang":"zh","level":4,"no":155,"teacher":"wang","title":"HSK4 · Bài 155 · 四级总结 Tổng kết HSK 4","intro":["临时有事，我不得不取消约会。","Bài 155: Bài cuối cùng của HSK 4 — mười từ còn lại và lời tổng kết cho cả chặng đường 1180 từ. Bấm 1 · Học để bắt đầu."],"introPy":"Línshí yǒu shì, wǒ bùdébù qǔxiāo yuēhuì.","gram":{"t":"不得不 — hai phủ định thành một khẳng định","b":"不得不 + động từ = buộc phải","d":"Khác 必须 (bắt buộc theo quy định) và 得 (cần phải): 不得不 mang sắc thái BẤT ĐẮC DĨ, không muốn nhưng hoàn cảnh ép. 他病了，我不得不一个人去.","ex":[["钱不够，我不得不放弃这次旅行。","Không đủ tiền, tôi đành bỏ chuyến đi này.","Qián bú gòu, wǒ bùdébù fàngqì zhè cì lǚxíng."]]},"grams":[{"t":"不得不 — hai phủ định thành một khẳng định","b":"不得不 + động từ = buộc phải","d":"Khác 必须 (bắt buộc theo quy định) và 得 (cần phải): 不得不 mang sắc thái BẤT ĐẮC DĨ, không muốn nhưng hoàn cảnh ép. 他病了，我不得不一个人去.","ex":[["钱不够，我不得不放弃这次旅行。","Không đủ tiền, tôi đành bỏ chuyến đi này.","Qián bú gòu, wǒ bùdébù fàngqì zhè cì lǚxíng."]]},{"t":"经历 và 经验 — trải qua và rút ra","b":"经历 = việc đã trải qua · 经验 = kinh nghiệm rút ra được","d":"留学是一次很好的经历 (một chuyến trải nghiệm). 他有很多教学经验 (có nhiều kinh nghiệm giảng dạy). 经历 đếm bằng 次, 经验 thì không đếm được — nói 很多经验 chứ không nói 三个经验.","ex":[["这次经历让我学到了很多经验。","Lần trải nghiệm này cho tôi học được nhiều kinh nghiệm.","Zhè cì jīnglì ràng wǒ xué dào le hěn duō jīngyàn."]]},{"t":"Bạn đã đi tới đâu — và đi tiếp thế nào","b":"HSK 1–4: 118 bài · 1180 từ · hơn 1200 chữ Hán","d":"Với vốn này bạn đọc hiểu được phần lớn văn bản đời thường, nói được về hầu hết chủ đề sinh hoạt, và quan trọng nhất: bạn VIẾT được chữ Hán bằng tay, đúng thứ tự nét — điều mà rất nhiều người học nhiều năm vẫn không làm được. Từ đây, cách tiến bộ nhanh nhất không phải là học thêm từ mới, mà là ÔN đều mỗi ngày bằng mục Ôn tập, và bắt đầu đọc truyện ngắn, xem phim có phụ đề tiếng Trung.","ex":[["学习是一辈子的事。","Học là chuyện cả đời.","Xuéxí shì yíbèizi de shì."],["只要每天坚持，一定会有进步。","Chỉ cần mỗi ngày kiên trì, nhất định sẽ tiến bộ.","Zhǐyào měi tiān jiānchí, yídìng huì yǒu jìnbù."]]}],"items":[{"zh":"不得不","py":"bùdébù","vi":"buộc phải, đành phải","hv":"bất đắc bất","note":"Tiếng Việt: \"bất đắc dĩ\". Hai lần phủ định thành khẳng định mạnh: không thể không → buộc phải.","ex":"临时有事，我不得不取消约会。","exPy":"Línshí yǒu shì, wǒ bùdébù qǔxiāo yuēhuì.","exVi":"Có việc đột xuất, tôi đành huỷ cuộc hẹn.","w":"临时 有 事， 我 不得不 取消 约会。"},{"zh":"占线","py":"zhànxiàn","vi":"máy bận (điện thoại)","hv":"chiếm tuyến","note":"占 (chiếm) + 线 (tuyến, đường dây). Câu quen: 电话一直占线.","ex":"我打了三次，一直占线。","exPy":"Wǒ dǎ le sān cì, yìzhí zhànxiàn.","exVi":"Tôi gọi ba lần, cứ bận máy.","w":"我 打 了 三 次， 一直 占线。"},{"zh":"情况","py":"qíngkuàng","vi":"tình hình","hv":"tình huống","note":"情 (tình) + 况 (huống). Tiếng Việt \"tình huống\" thiên về một cảnh cụ thể, còn 情况 rộng hơn: tình hình chung.","ex":"请把这里的情况告诉我。","exPy":"Qǐng bǎ zhèlǐ de qíngkuàng gàosu wǒ.","exVi":"Xin cho tôi biết tình hình ở đây.","w":"请 把 这里 的 情况 告诉 我。"},{"zh":"原因","py":"yuányīn","vi":"nguyên nhân","hv":"nguyên nhân","note":"Chính là \"nguyên nhân\" tiếng Việt: 原 (nguyên) + 因 (nhân). Trái với 结果 (bài 110).","ex":"他迟到的原因是堵车。","exPy":"Tā chídào de yuányīn shì dǔchē.","exVi":"Nguyên nhân anh ấy trễ là tắc đường.","w":"他 迟到 的 原因 是 堵车。"},{"zh":"礼拜天","py":"lǐbàitiān","vi":"chủ nhật","hv":"lễ bái thiên","note":"礼拜 (lễ bái) vốn chỉ việc đi lễ nhà thờ. Khẩu ngữ, đồng nghĩa 星期天. 礼拜一 = thứ hai.","ex":"礼拜天你有什么安排？","exPy":"Lǐbàitiān nǐ yǒu shénme ānpái?","exVi":"Chủ nhật bạn có kế hoạch gì?","w":"礼拜天 你 有 什么 安排？"},{"zh":"速度","py":"sùdù","vi":"tốc độ","hv":"tốc độ","note":"Chính là \"tốc độ\" tiếng Việt: 速 (tốc) + 度 (độ).","ex":"请说慢一点儿，速度太快我听不懂。","exPy":"Qǐng shuō màn yìdiǎnr, sùdù tài kuài wǒ tīng bu dǒng.","exVi":"Xin nói chậm chút, nhanh quá tôi không hiểu.","w":"请 说 慢 一点儿， 速度 太 快 我 听 不 懂。"},{"zh":"丰富","py":"fēngfù","vi":"phong phú","hv":"phong phú","note":"Chính là \"phong phú\" tiếng Việt: 丰 (phong) + 富 (phú). Còn làm động từ: 丰富自己的知识.","ex":"中国的历史文化非常丰富。","exPy":"Zhōngguó de lìshǐ wénhuà fēicháng fēngfù.","exVi":"Lịch sử văn hoá Trung Quốc vô cùng phong phú.","w":"中国 的 历史 文化 非常 丰富。"},{"zh":"符合","py":"fúhé","vi":"phù hợp với, khớp với","hv":"phù hợp","note":"Chính là \"phù hợp\" tiếng Việt. Là ĐỘNG TỪ, cần tân ngữ: 符合条件, 符合要求. Khác 合适 (tính từ, bài 116).","ex":"他的条件完全符合规定。","exPy":"Tā de tiáojiàn wánquán fúhé guīdìng.","exVi":"Điều kiện của anh ấy hoàn toàn phù hợp quy định.","w":"他 的 条件 完全 符合 规定。"},{"zh":"经历","py":"jīnglì","vi":"trải nghiệm; từng trải qua","hv":"kinh lịch","note":"经 (kinh, trải qua) + 历 (lịch). Tiếng Việt: \"lịch duyệt\", \"từng trải\". Khác 经验 (kinh nghiệm rút ra được).","ex":"学汉语是我最难忘的经历之一。","exPy":"Xué Hànyǔ shì wǒ zuì nánwàng de jīnglì zhī yī.","exVi":"Học tiếng Trung là một trong những trải nghiệm khó quên nhất của tôi.","w":"学 汉语 是 我 最 难忘 的 经历 之 一。"},{"zh":"呀","py":"ya","vi":"à, nhé (trợ từ)","hv":"nha","note":"Biến âm của 啊 khi chữ trước kết thúc bằng a/e/i/o/ü. 你好啊 → 是你呀！Làm câu nói mềm và thân mật.","ex":"你终于写完一千多个汉字了呀！","exPy":"Nǐ zhōngyú xiě wán yìqiān duō ge Hànzì le ya!","exVi":"Cuối cùng bạn cũng viết xong hơn nghìn chữ Hán rồi đấy!","w":"你 终于 写 完 一 千 多 个 汉字 了 呀！"}],"newChars":["占","线","况","原","拜","速","度","丰","富","符","经","历","呀"],"outro":"很好！Xong bài 155."};
G.ROOMS["zh-l156"] = {"id":"zh-l156","lang":"zh","level":4,"no":156,"teacher":"wang","title":"HSK4 · Bài 156 · 登机 Ở sân bay và nhà ga","intro":["安检排了很长的队。","Bài 156: Nói về kiểm tra an ninh, lên máy bay, nối chuyến, đi tàu xe, đổi tuyến và hành khách. Bấm 1 · Học để bắt đầu."],"introPy":"Ānjiǎn pái le hěn cháng de duì.","gram":{"t":"Ngôn ngữ thông báo trang trọng","b":"各位乘客 · 乘坐 · 请…","d":"Thông báo ở sân bay, nhà ga dùng từ trang trọng: 乘坐 thay 坐, 各位乘客 thay 大家.","ex":[["请旅客们到三号口登机。","Mời hành khách đến cửa số ba lên máy bay.","Qǐng lǚkèmen dào sān hào kǒu dēngjī."],["本次航班将在十分钟后起飞。","Chuyến bay này sẽ cất cánh sau mười phút.","Běn cì hángbān jiāng zài shí fēnzhōng hòu qǐfēi."]]},"grams":[{"t":"Ngôn ngữ thông báo trang trọng","b":"各位乘客 · 乘坐 · 请…","d":"Thông báo ở sân bay, nhà ga dùng từ trang trọng: 乘坐 thay 坐, 各位乘客 thay 大家.","ex":[["请旅客们到三号口登机。","Mời hành khách đến cửa số ba lên máy bay.","Qǐng lǚkèmen dào sān hào kǒu dēngjī."],["本次航班将在十分钟后起飞。","Chuyến bay này sẽ cất cánh sau mười phút.","Běn cì hángbān jiāng zài shí fēnzhōng hòu qǐfēi."]]},{"t":"在 + nơi + 换乘 / 转机","b":"在北京转机 · 在这站换乘","d":"Nơi đổi chuyến đứng trước động từ.","ex":[["你在哪儿转机？","Bạn nối chuyến ở đâu?","Nǐ zài nǎr zhuǎnjī?"],["我们在人民广场换乘。","Chúng ta đổi tuyến ở Quảng trường Nhân Dân.","Wǒmen zài Rénmín Guǎngchǎng huànchéng."]]}],"items":[{"zh":"安检","py":"ānjiǎn","vi":"kiểm tra an ninh","hv":"an kiểm","note":"Viết tắt của 安全检查 (kiểm tra an toàn).","ex":"安检排了很长的队。","exPy":"Ānjiǎn pái le hěn cháng de duì.","exVi":"Chỗ kiểm tra an ninh xếp hàng rất dài.","w":"安检 排 了 很 长 的 队。"},{"zh":"登机","py":"dēngjī","vi":"lên máy bay","hv":"đăng cơ","note":"登 = \"đăng\" (lên, trèo) + 机. Thẻ lên máy bay là 登机牌.","ex":"登机以前请关机。","exPy":"Dēngjī yǐqián qǐng guānjī.","exVi":"Trước khi lên máy bay xin tắt máy.","w":"登机 以前 请 关机。"},{"zh":"转机","py":"zhuǎnjī","vi":"nối chuyến bay","hv":"chuyển cơ","note":"转 (chuyển) + 机.","ex":"我们要在广州转机。","exPy":"Wǒmen yào zài Guǎngzhōu zhuǎnjī.","exVi":"Chúng tôi phải nối chuyến ở Quảng Châu.","w":"我们 要 在 广 州 转机。"},{"zh":"乘","py":"chéng","vi":"đi (phương tiện)","hv":"thừa","note":"\"Thừa\" trong \"thừa cơ\". Trang trọng, nghĩa như 坐.","ex":"乘客们都上车了。","exPy":"Chéngkèmen dōu shàng chē le.","exVi":"Hành khách đều lên xe rồi.","w":"乘客 们 都 上 车 了。"},{"zh":"乘客","py":"chéngkè","vi":"hành khách","hv":"thừa khách","note":"Người đi tàu xe, máy bay.","ex":"各位乘客，请系好安全带。","exPy":"Gèwèi chéngkè, qǐng jì hǎo ānquándài.","exVi":"Quý hành khách, xin thắt dây an toàn.","w":"各位 乘客， 请 系 好 安全带。"},{"zh":"乘坐","py":"chéngzuò","vi":"đi, ngồi (tàu xe)","hv":"thừa toạ","note":"Trang trọng, hay gặp trong thông báo.","ex":"欢迎乘坐本次列车。","exPy":"Huānyíng chéngzuò běn cì lièchē.","exVi":"Chào mừng quý khách đi chuyến tàu này.","w":"欢迎 乘坐 本 次 列车。"},{"zh":"换乘","py":"huànchéng","vi":"đổi tuyến, chuyển xe","hv":"hoán thừa","note":"换 (đổi) + 乘. Hay dùng cho tàu điện ngầm.","ex":"在这一站可以换乘二号线。","exPy":"Zài zhè yí zhàn kěyǐ huànchéng èr hào xiàn.","exVi":"Ở ga này có thể chuyển sang tuyến số hai.","w":"在 这 一 站 可以 换乘 二 号 线。"},{"zh":"动车","py":"dòngchē","vi":"tàu tốc hành (điện)","hv":"động xa","note":"Tàu nhanh chạy điện, chậm hơn 高铁 một chút.","ex":"坐动车去杭州很方便。","exPy":"Zuò dòngchē qù Hángzhōu hěn fāngbiàn.","exVi":"Đi tàu tốc hành đến Hàng Châu rất tiện.","w":"坐 动车 去 杭 州 很 方便。"},{"zh":"大巴","py":"dàbā","vi":"xe khách lớn","hv":"đại ba","note":"巴 phiên âm từ \"bus\".","ex":"坐大巴比打车便宜多了。","exPy":"Zuò dàbā bǐ dǎchē piányi duō le.","exVi":"Đi xe khách rẻ hơn gọi taxi nhiều.","w":"坐 大巴 比 打车 便宜 多 了。"},{"zh":"旅客","py":"lǚkè","vi":"hành khách, lữ khách","hv":"lữ khách","note":"Chính là \"lữ khách\".","ex":"春节期间旅客很多。","exPy":"Chūnjié qījiān lǚkè hěn duō.","exVi":"Dịp Tết hành khách rất đông.","w":"春 节 期间 旅客 很 多。"}],"newChars":["乘","巴"],"outro":"很好！Xong bài 156."};
G.ROOMS["zh-l157"] = {"id":"zh-l157","lang":"zh","level":4,"no":157,"teacher":"wang","title":"HSK4 · Bài 157 · 开车要小心 Đường sá và lái xe","intro":["开车的时候不要看手机。","Bài 157: Nói về tốc độ, chỗ đỗ, bãi đỗ xe, xe điện, cảnh sát giao thông, ngã tư, đường lớn và cao tốc. Bấm 1 · Học để bắt đầu."],"introPy":"Kāichē de shíhou búyào kàn shǒujī.","gram":{"t":"让 + người + động từ: bảo ai làm gì","b":"交警让他停车 · 妈妈让我早点儿回家","d":"让 nghĩa là \"bảo, để cho\"; người bị bảo đứng ngay sau 让.","ex":[["老师让我们写作文。","Cô giáo bảo chúng tôi viết bài văn.","Lǎoshī ràng wǒmen xiě zuòwén."],["请让我想一想。","Để tôi nghĩ một chút.","Qǐng ràng wǒ xiǎng yi xiǎng."]]},"grams":[{"t":"让 + người + động từ: bảo ai làm gì","b":"交警让他停车 · 妈妈让我早点儿回家","d":"让 nghĩa là \"bảo, để cho\"; người bị bảo đứng ngay sau 让.","ex":[["老师让我们写作文。","Cô giáo bảo chúng tôi viết bài văn.","Lǎoshī ràng wǒmen xiě zuòwén."],["请让我想一想。","Để tôi nghĩ một chút.","Qǐng ràng wǒ xiǎng yi xiǎng."]]},{"t":"越来越 + tính từ: ngày càng","b":"越来越宽 · 越来越多","d":"Diễn tả mức độ tăng dần theo thời gian.","ex":[["电动车越来越多了。","Xe điện ngày càng nhiều.","Diàndòngchē yuèláiyuè duō le."],["天气越来越冷。","Thời tiết ngày càng lạnh.","Tiānqì yuèláiyuè lěng."]]}],"items":[{"zh":"车速","py":"chēsù","vi":"tốc độ xe","hv":"xa tốc","note":"车 + 速 (\"tốc\" trong \"tốc độ\").","ex":"高速公路上车速很快。","exPy":"Gāosù gōnglù shang chēsù hěn kuài.","exVi":"Trên đường cao tốc xe chạy rất nhanh.","w":"高速 公路 上 车速 很 快。"},{"zh":"车位","py":"chēwèi","vi":"chỗ đỗ xe","hv":"xa vị","note":"车 + 位 (chỗ, vị trí).","ex":"下班的时候很难找到车位。","exPy":"Xiàbān de shíhou hěn nán zhǎodào chēwèi.","exVi":"Giờ tan làm rất khó tìm chỗ đỗ xe.","w":"下班 的 时候 很 难 找 到 车位。"},{"zh":"停车","py":"tíngchē","vi":"đỗ xe","hv":"đình xa","note":"停 = \"đình\" trong \"đình chỉ\".","ex":"商场的停车场很大。","exPy":"Shāngchǎng de tíngchēchǎng hěn dà.","exVi":"Bãi đỗ xe của trung tâm thương mại rất rộng.","w":"商场 的 停车场 很 大。"},{"zh":"停车场","py":"tíngchēchǎng","vi":"bãi đỗ xe","hv":"đình xa trường","note":"停车 + 场 (bãi).","ex":"停车场在大楼下面。","exPy":"Tíngchēchǎng zài dàlóu xiàmian.","exVi":"Bãi đỗ xe ở dưới toà nhà.","w":"停车场 在 大 楼 下面。"},{"zh":"电动车","py":"diàndòngchē","vi":"xe điện","hv":"điện động xa","note":"电动 (chạy điện) + 车. Ở Trung Quốc thường là xe máy điện.","ex":"很多人骑电动车上班。","exPy":"Hěn duō rén qí diàndòngchē shàngbān.","exVi":"Nhiều người đi xe máy điện đi làm.","w":"很 多 人 骑 电动车 上班。"},{"zh":"交警","py":"jiāojǐng","vi":"cảnh sát giao thông","hv":"giao cảnh","note":"Viết tắt của 交通警察.","ex":"交警让他停车。","exPy":"Jiāojǐng ràng tā tíngchē.","exVi":"Cảnh sát giao thông bảo anh ấy dừng xe.","w":"交警 让 他 停车。"},{"zh":"十字路口","py":"shízì lùkǒu","vi":"ngã tư","hv":"thập tự lộ khẩu","note":"Nghĩa đen \"ngã đường hình chữ 十\".","ex":"在十字路口往左拐。","exPy":"Zài shízì lùkǒu wǎng zuǒ guǎi.","exVi":"Đến ngã tư thì rẽ trái.","w":"在 十字路口 往 左 拐。"},{"zh":"公路","py":"gōnglù","vi":"quốc lộ, đường lớn","hv":"công lộ","note":"Đường ô tô nối các thành phố.","ex":"这条公路通到海边。","exPy":"Zhè tiáo gōnglù tōng dào hǎibiān.","exVi":"Con đường này dẫn ra biển.","w":"这 条 公路 通 到 海 边。"},{"zh":"道路","py":"dàolù","vi":"đường sá","hv":"đạo lộ","note":"Trang trọng hơn 路.","ex":"城市的道路越来越宽了。","exPy":"Chéngshì de dàolù yuèláiyuè kuān le.","exVi":"Đường sá thành phố ngày càng rộng.","w":"城市 的 道路 越 来 越 宽 了。"},{"zh":"高速","py":"gāosù","vi":"tốc độ cao; đường cao tốc","hv":"cao tốc","note":"Chính là \"cao tốc\". Đường cao tốc là 高速公路.","ex":"我们走高速，两个小时就到。","exPy":"Wǒmen zǒu gāosù, liǎng ge xiǎoshí jiù dào.","exVi":"Mình đi cao tốc, hai tiếng là tới.","w":"我们 走 高速， 两 个 小时 就 到。"}],"newChars":["警"],"outro":"很好！Xong bài 157."};
G.ROOMS["zh-l158"] = {"id":"zh-l158","lang":"zh","level":4,"no":158,"teacher":"wang","title":"HSK4 · Bài 158 · 去哪儿度假？ Du lịch","intro":["下龙湾是越南有名的景点。","Bài 158: Nói về điểm tham quan, khu du lịch, cảnh đẹp, đi chơi, nghỉ dưỡng, nhà nghỉ, nhận phòng, điểm đến và đi lại. Bấm 1 · Học để bắt đầu."],"introPy":"Xiàlóng Wān shì Yuènán yǒumíng de jǐngdiǎn.","gram":{"t":"让人 + tính từ / động từ: khiến người ta","b":"让人难忘 · 让人高兴","d":"Chủ ngữ là sự vật, 让人 nghĩa \"khiến người ta…\".","ex":[["这个故事让人很感动。","Câu chuyện này khiến người ta rất cảm động.","Zhège gùshi ràng rén hěn gǎndòng."],["那里的美食让人难忘。","Món ngon ở đó khiến người ta khó quên.","Nàlǐ de měishí ràng rén nánwàng."]]},"grams":[{"t":"让人 + tính từ / động từ: khiến người ta","b":"让人难忘 · 让人高兴","d":"Chủ ngữ là sự vật, 让人 nghĩa \"khiến người ta…\".","ex":[["这个故事让人很感动。","Câu chuyện này khiến người ta rất cảm động.","Zhège gùshi ràng rén hěn gǎndòng."],["那里的美食让人难忘。","Món ngon ở đó khiến người ta khó quên.","Nàlǐ de měishí ràng rén nánwàng."]]},{"t":"终于: cuối cùng cũng","b":"终于 + động từ + 了","d":"Nhấn mạnh việc đạt được sau một thời gian chờ đợi.","ex":[["我终于找到旅馆了。","Cuối cùng tôi cũng tìm được nhà nghỉ.","Wǒ zhōngyú zhǎodào lǚguǎn le."],["假期终于到了！","Kỳ nghỉ cuối cùng cũng đến!","Jiàqī zhōngyú dào le!"]]}],"items":[{"zh":"景点","py":"jǐngdiǎn","vi":"điểm tham quan","hv":"cảnh điểm","note":"景 = \"cảnh\" trong \"phong cảnh\".","ex":"下龙湾是越南有名的景点。","exPy":"Xiàlóng Wān shì Yuènán yǒumíng de jǐngdiǎn.","exVi":"Vịnh Hạ Long là điểm tham quan nổi tiếng của Việt Nam.","w":"下 龙 湾 是 越 南 有名 的 景点。"},{"zh":"景区","py":"jǐngqū","vi":"khu du lịch","hv":"cảnh khu","note":"景 + 区 (khu).","ex":"景区里游客太多了。","exPy":"Jǐngqū lǐ yóukè tài duō le.","exVi":"Trong khu du lịch đông khách quá.","w":"景区 里 游客 太 多 了。"},{"zh":"美景","py":"měijǐng","vi":"cảnh đẹp","hv":"mỹ cảnh","note":"美 (đẹp) + 景.","ex":"山上的美景让人难忘。","exPy":"Shān shang de měijǐng ràng rén nánwàng.","exVi":"Cảnh đẹp trên núi làm người ta khó quên.","w":"山 上 的 美景 让 人 难忘。"},{"zh":"游玩","py":"yóuwán","vi":"đi chơi, du ngoạn","hv":"du ngoạn","note":"Chính là \"du ngoạn\".","ex":"周末我们去海边游玩。","exPy":"Zhōumò wǒmen qù hǎibiān yóuwán.","exVi":"Cuối tuần chúng tôi ra biển chơi.","w":"周末 我们 去 海 边 游玩。"},{"zh":"度假","py":"dùjià","vi":"đi nghỉ","hv":"độ giả","note":"度 (trải qua) + 假 (kỳ nghỉ).","ex":"他们去海南度假了。","exPy":"Tāmen qù Hǎinán dùjià le.","exVi":"Họ đi nghỉ ở Hải Nam rồi.","w":"他们 去 海 南 度假 了。"},{"zh":"旅行","py":"lǚxíng","vi":"du lịch, đi xa","hv":"lữ hành","note":"Chính là \"lữ hành\". Gần nghĩa 旅游.","ex":"这次旅行的目的地是西安。","exPy":"Zhè cì lǚxíng de mùdìdì shì Xī'ān.","exVi":"Điểm đến của chuyến đi này là Tây An.","w":"这 次 旅行 的 目的地 是 西 安。"},{"zh":"旅馆","py":"lǚguǎn","vi":"nhà nghỉ, khách sạn nhỏ","hv":"lữ quán","note":"Chính là \"lữ quán\".","ex":"我们先去旅馆入住吧。","exPy":"Wǒmen xiān qù lǚguǎn rùzhù ba.","exVi":"Chúng ta về nhà nghỉ nhận phòng trước nhé.","w":"我们 先 去 旅馆 入住 吧。"},{"zh":"入住","py":"rùzhù","vi":"nhận phòng, vào ở","hv":"nhập trú","note":"入 (vào) + 住 (ở).","ex":"下午两点以后可以入住。","exPy":"Xiàwǔ liǎng diǎn yǐhòu kěyǐ rùzhù.","exVi":"Sau hai giờ chiều mới được nhận phòng.","w":"下午 两 点 以后 可以 入住。"},{"zh":"目的地","py":"mùdìdì","vi":"điểm đến","hv":"mục đích địa","note":"目的 (mục đích) + 地 (nơi).","ex":"我们终于到了目的地。","exPy":"Wǒmen zhōngyú dào le mùdìdì.","exVi":"Cuối cùng chúng tôi đã đến nơi.","w":"我们 终于 到 了 目的地。"},{"zh":"出行","py":"chūxíng","vi":"đi lại, ra ngoài đi xa","hv":"xuất hành","note":"Chính là \"xuất hành\".","ex":"节假日出行的人很多。","exPy":"Jiéjiàrì chūxíng de rén hěn duō.","exVi":"Ngày lễ người đi lại rất đông.","w":"节假日 出行 的 人 很 多。"}],"newChars":[],"outro":"很好！Xong bài 158."};
G.ROOMS["zh-l159"] = {"id":"zh-l159","lang":"zh","level":4,"no":159,"teacher":"wang","title":"HSK4 · Bài 159 · 网购 Mua sắm và thanh toán","intro":["网购很方便，但是有时候质量不好。","Bài 159: Nói về mua, hàng hoá, giá cả, giá rẻ, giá cao, giảm giá, mua trên mạng, tính tiền và trả tiền. Bấm 1 · Học để bắt đầu."],"introPy":"Wǎnggòu hěn fāngbiàn, dànshì yǒushíhou zhìliàng bù hǎo.","gram":{"t":"用 + phương tiện + động từ","b":"用手机支付 · 用低价卖","d":"用 nói công cụ hay cách thức, đứng trước động từ chính.","ex":[["可以用银行卡付钱吗？","Có thể trả bằng thẻ ngân hàng không?","Kěyǐ yòng yínhángkǎ fù qián ma?"],["我用手机买票。","Tôi mua vé bằng điện thoại.","Wǒ yòng shǒujī mǎi piào."]]},"grams":[{"t":"用 + phương tiện + động từ","b":"用手机支付 · 用低价卖","d":"用 nói công cụ hay cách thức, đứng trước động từ chính.","ex":[["可以用银行卡付钱吗？","Có thể trả bằng thẻ ngân hàng không?","Kěyǐ yòng yínhángkǎ fù qián ma?"],["我用手机买票。","Tôi mua vé bằng điện thoại.","Wǒ yòng shǒujī mǎi piào."]]},{"t":"我来 + động từ: để tôi làm","b":"我来付 · 我来介绍","d":"来 trước động từ thể hiện chủ động nhận việc.","ex":[["我来介绍一下。","Để tôi giới thiệu một chút.","Wǒ lái jièshào yíxià."],["这次我来结账吧。","Lần này để tôi trả nhé.","Zhè cì wǒ lái jiézhàng ba."]]}],"items":[{"zh":"购买","py":"gòumǎi","vi":"mua","hv":"cấu mãi","note":"Trang trọng hơn 买.","ex":"你可以在网上购买门票。","exPy":"Nǐ kěyǐ zài wǎngshang gòumǎi ménpiào.","exVi":"Bạn có thể mua vé trên mạng.","w":"你 可以 在 网上 购买 门票。"},{"zh":"商品","py":"shāngpǐn","vi":"hàng hoá","hv":"thương phẩm","note":"Chính là \"thương phẩm\".","ex":"周末商场的商品都降价了。","exPy":"Zhōumò shāngchǎng de shāngpǐn dōu jiàngjià le.","exVi":"Cuối tuần hàng ở trung tâm thương mại đều giảm giá.","w":"周末 商场 的 商品 都 降价 了。"},{"zh":"价钱","py":"jiàqián","vi":"giá cả","hv":"giá tiền","note":"Khẩu ngữ, nghĩa như 价格.","ex":"这个价钱可以便宜一点儿吗？","exPy":"Zhège jiàqián kěyǐ piányi yìdiǎnr ma?","exVi":"Giá này có thể bớt chút không?","w":"这个 价钱 可以 便宜 一点儿 吗？"},{"zh":"低价","py":"dījià","vi":"giá thấp","hv":"đê giá","note":"低 (thấp) + 价.","ex":"他们用低价卖旧手机。","exPy":"Tāmen yòng dījià mài jiù shǒujī.","exVi":"Họ bán điện thoại cũ với giá thấp.","w":"他们 用 低价 卖 旧 手机。"},{"zh":"高价","py":"gāojià","vi":"giá cao","hv":"cao giá","note":"高 + 价.","ex":"他高价买了一张票。","exPy":"Tā gāojià mǎi le yì zhāng piào.","exVi":"Anh ấy mua một vé với giá cao.","w":"他 高价 买 了 一 张 票。"},{"zh":"降价","py":"jiàngjià","vi":"giảm giá","hv":"giáng giá","note":"降 (hạ) + 价.","ex":"这些衣服都降价了。","exPy":"Zhèxiē yīfu dōu jiàngjià le.","exVi":"Những bộ quần áo này đều giảm giá rồi.","w":"这些 衣服 都 降价 了。"},{"zh":"网购","py":"wǎnggòu","vi":"mua hàng trên mạng","hv":"võng cấu","note":"Viết tắt của 网上购物.","ex":"网购很方便，但是有时候质量不好。","exPy":"Wǎnggòu hěn fāngbiàn, dànshì yǒushíhou zhìliàng bù hǎo.","exVi":"Mua trên mạng rất tiện, nhưng đôi khi chất lượng không tốt.","w":"网购 很 方便， 但是 有时 候 质量 不 好。"},{"zh":"结账","py":"jiézhàng","vi":"tính tiền, thanh toán","hv":"kết trướng","note":"Ăn xong gọi tính tiền: 服务员，结账！","ex":"吃完饭我们去前台结账。","exPy":"Chī wán fàn wǒmen qù qiántái jiézhàng.","exVi":"Ăn xong chúng ta ra quầy tính tiền.","w":"吃 完 饭 我们 去 前台 结账。"},{"zh":"付","py":"fù","vi":"trả (tiền)","hv":"phó","note":"\"Phó\" trong \"giao phó\". 付钱 là trả tiền.","ex":"我来付钱。","exPy":"Wǒ lái fù qián.","exVi":"Để tôi trả tiền.","w":"我 来 付 钱。"},{"zh":"支付","py":"zhīfù","vi":"thanh toán","hv":"chi phó","note":"Trang trọng. Thanh toán bằng điện thoại: 手机支付.","ex":"在中国很多人用手机支付。","exPy":"Zài Zhōngguó hěn duō rén yòng shǒujī zhīfù.","exVi":"Ở Trung Quốc nhiều người thanh toán bằng điện thoại.","w":"在 中国 很 多 人 用 手机 支付。"}],"newChars":["品","账","支"],"outro":"很好！Xong bài 159."};
G.ROOMS["zh-l160"] = {"id":"zh-l160","lang":"zh","level":4,"no":160,"teacher":"wang","title":"HSK4 · Bài 160 · 去餐厅吃饭 Bữa ăn và nhà hàng","intro":["公司食堂的午餐很好吃。","Bài 160: Nói về nhà hàng, đồ ăn nhanh, món Trung, bữa sáng, trưa, tối (trang trọng), nhà ăn, món ngon, thức ăn và thực phẩm. Bấm 1 · Học để bắt đầu."],"introPy":"Gōngsī shítáng de wǔcān hěn hǎochī.","gram":{"t":"Bữa ăn: 饭 (khẩu ngữ) và 餐 (trang trọng)","b":"早饭 / 早餐 · 午饭 / 午餐 · 晚饭 / 晚餐","d":"Nói chuyện hằng ngày dùng 饭, trên thực đơn, thông báo dùng 餐.","ex":[["早餐几点开始？","Bữa sáng mấy giờ bắt đầu?","Zǎocān jǐ diǎn kāishǐ?"],["你吃早饭了吗？","Bạn ăn sáng chưa?","Nǐ chī zǎofàn le ma?"]]},"grams":[{"t":"Bữa ăn: 饭 (khẩu ngữ) và 餐 (trang trọng)","b":"早饭 / 早餐 · 午饭 / 午餐 · 晚饭 / 晚餐","d":"Nói chuyện hằng ngày dùng 饭, trên thực đơn, thông báo dùng 餐.","ex":[["早餐几点开始？","Bữa sáng mấy giờ bắt đầu?","Zǎocān jǐ diǎn kāishǐ?"],["你吃早饭了吗？","Bạn ăn sáng chưa?","Nǐ chī zǎofàn le ma?"]]},{"t":"对 + người / việc + 好 / 不好","b":"对身体好 · 对学习不好","d":"Nói điều gì tốt hay xấu cho ai, cho việc gì.","ex":[["多吃水果对身体好。","Ăn nhiều hoa quả tốt cho sức khoẻ.","Duō chī shuǐguǒ duì shēntǐ hǎo."],["熬夜对眼睛不好。","Thức khuya không tốt cho mắt.","Áoyè duì yǎnjing bù hǎo."]]}],"items":[{"zh":"餐厅","py":"cāntīng","vi":"nhà hàng, phòng ăn","hv":"xan sảnh","note":"餐 = bữa ăn (\"xan\"), 厅 = sảnh.","ex":"这家餐厅的中餐很有名。","exPy":"Zhè jiā cāntīng de zhōngcān hěn yǒumíng.","exVi":"Món Trung của nhà hàng này rất nổi tiếng.","w":"这 家 餐厅 的 中餐 很 有名。"},{"zh":"快餐","py":"kuàicān","vi":"đồ ăn nhanh","hv":"khoái xan","note":"快 (nhanh) + 餐.","ex":"别总吃快餐，对身体不好。","exPy":"Bié zǒng chī kuàicān, duì shēntǐ bù hǎo.","exVi":"Đừng ăn đồ ăn nhanh suốt, không tốt cho sức khoẻ.","w":"别 总 吃 快餐， 对 身体 不 好。"},{"zh":"中餐","py":"zhōngcān","vi":"món Trung Quốc","hv":"trung xan","note":"Món Tây là 西餐.","ex":"你喜欢中餐还是西餐？","exPy":"Nǐ xǐhuan zhōngcān háishi xīcān?","exVi":"Bạn thích món Trung hay món Tây?","w":"你 喜欢 中餐 还是 西餐？"},{"zh":"早餐","py":"zǎocān","vi":"bữa sáng","hv":"tảo xan","note":"Trang trọng hơn 早饭, hay gặp ở khách sạn.","ex":"酒店的早餐是免费的。","exPy":"Jiǔdiàn de zǎocān shì miǎnfèi de.","exVi":"Bữa sáng ở khách sạn miễn phí.","w":"酒店 的 早餐 是 免费 的。"},{"zh":"午餐","py":"wǔcān","vi":"bữa trưa","hv":"ngọ xan","note":"Trang trọng hơn 午饭.","ex":"公司食堂的午餐很好吃。","exPy":"Gōngsī shítáng de wǔcān hěn hǎochī.","exVi":"Bữa trưa ở nhà ăn công ty rất ngon.","w":"公司 食堂 的 午餐 很 好吃。"},{"zh":"晚餐","py":"wǎncān","vi":"bữa tối","hv":"vãn xan","note":"Trang trọng hơn 晚饭.","ex":"我们一起吃晚餐吧。","exPy":"Wǒmen yìqǐ chī wǎncān ba.","exVi":"Chúng ta cùng ăn tối nhé.","w":"我们 一起 吃 晚餐 吧。"},{"zh":"食堂","py":"shítáng","vi":"nhà ăn (tập thể)","hv":"thực đường","note":"Nhà ăn của trường, công ty.","ex":"学校食堂的饭很便宜。","exPy":"Xuéxiào shítáng de fàn hěn piányi.","exVi":"Cơm ở nhà ăn trường rất rẻ.","w":"学校 食堂 的 饭 很 便宜。"},{"zh":"美食","py":"měishí","vi":"món ngon, ẩm thực","hv":"mỹ thực","note":"Chính là \"mỹ thực\".","ex":"旅行的时候我喜欢吃当地美食。","exPy":"Lǚxíng de shíhou wǒ xǐhuan chī dāngdì měishí.","exVi":"Khi đi du lịch tôi thích ăn món ngon địa phương.","w":"旅行 的 时候 我 喜欢 吃 当地 美食。"},{"zh":"食物","py":"shíwù","vi":"thức ăn","hv":"thực vật","note":"Chú ý: tiếng Việt \"thực vật\" là cây cỏ (植物), còn 食物 là đồ ăn.","ex":"冰箱里没有食物了。","exPy":"Bīngxiāng lǐ méiyǒu shíwù le.","exVi":"Trong tủ lạnh hết đồ ăn rồi.","w":"冰箱 里 没有 食物 了。"},{"zh":"食品","py":"shípǐn","vi":"thực phẩm","hv":"thực phẩm","note":"Chính là \"thực phẩm\", thường là đồ ăn đóng gói.","ex":"这种食品对身体不好。","exPy":"Zhè zhǒng shípǐn duì shēntǐ bù hǎo.","exVi":"Loại thực phẩm này không tốt cho sức khoẻ.","w":"这 种 食品 对 身体 不 好。"}],"newChars":["餐","食","堂"],"outro":"很好！Xong bài 160."};
G.ROOMS["zh-l161"] = {"id":"zh-l161","lang":"zh","level":4,"no":161,"teacher":"wang","title":"HSK4 · Bài 161 · 中秋节吃月饼 Đồ ăn thức uống","intro":["中国的茶叶很有名。","Bài 161: Nói về lá trà, rượu trắng, rượu vang, nước ngọt, sữa chua, đồ ăn vặt, màn thầu, bánh trung thu, nướng và tươi. Bấm 1 · Học để bắt đầu."],"introPy":"Zhōngguó de cháyè hěn yǒumíng.","gram":{"t":"少 / 多 + động từ: làm ít / làm nhiều","b":"少喝点儿 · 多吃点儿","d":"少, 多 đứng trước động từ để khuyên: làm ít đi, làm nhiều lên.","ex":[["你太累了，多休息。","Bạn mệt quá rồi, nghỉ nhiều vào.","Nǐ tài lèi le, duō xiūxi."],["少喝汽水，多喝水。","Uống ít nước ngọt, uống nhiều nước lọc.","Shǎo hē qìshuǐ, duō hē shuǐ."]]},"grams":[{"t":"少 / 多 + động từ: làm ít / làm nhiều","b":"少喝点儿 · 多吃点儿","d":"少, 多 đứng trước động từ để khuyên: làm ít đi, làm nhiều lên.","ex":[["你太累了，多休息。","Bạn mệt quá rồi, nghỉ nhiều vào.","Nǐ tài lèi le, duō xiūxi."],["少喝汽水，多喝水。","Uống ít nước ngọt, uống nhiều nước lọc.","Shǎo hē qìshuǐ, duō hē shuǐ."]]},{"t":"Lượng từ cho đồ uống","b":"一杯茶 · 一瓶酒 · 一盒酸奶","d":"杯 (cốc), 瓶 (chai), 盒 (hộp), 碗 (bát).","ex":[["请给我一杯茶。","Cho tôi một cốc trà.","Qǐng gěi wǒ yì bēi chá."],["他买了两瓶葡萄酒。","Anh ấy mua hai chai rượu vang.","Tā mǎi le liǎng píng pútaojiǔ."]]}],"items":[{"zh":"茶叶","py":"cháyè","vi":"lá trà","hv":"trà diệp","note":"茶 + 叶 (lá).","ex":"中国的茶叶很有名。","exPy":"Zhōngguó de cháyè hěn yǒumíng.","exVi":"Trà Trung Quốc rất nổi tiếng.","w":"中国 的 茶叶 很 有名。"},{"zh":"白酒","py":"báijiǔ","vi":"rượu trắng","hv":"bạch tửu","note":"Rượu mạnh trong suốt của Trung Quốc.","ex":"白酒很厉害，少喝点儿。","exPy":"Báijiǔ hěn lìhai, shǎo hē diǎnr.","exVi":"Rượu trắng mạnh lắm, uống ít thôi.","w":"白酒 很 厉害， 少 喝 点 儿。"},{"zh":"葡萄酒","py":"pútaojiǔ","vi":"rượu vang","hv":"bồ đào tửu","note":"葡萄 (nho, \"bồ đào\") + 酒.","ex":"我们喝一杯葡萄酒吧。","exPy":"Wǒmen hē yì bēi pútaojiǔ ba.","exVi":"Mình uống một ly rượu vang nhé.","w":"我们 喝 一 杯 葡萄酒 吧。"},{"zh":"汽水","py":"qìshuǐ","vi":"nước ngọt có ga","hv":"khí thuỷ","note":"汽 (hơi) + 水.","ex":"孩子们喜欢喝汽水。","exPy":"Háizimen xǐhuan hē qìshuǐ.","exVi":"Bọn trẻ thích uống nước ngọt.","w":"孩子 们 喜欢 喝 汽水。"},{"zh":"酸奶","py":"suānnǎi","vi":"sữa chua","hv":"toan nãi","note":"酸 (chua) + 奶 (sữa).","ex":"早上我喝一瓶酸奶。","exPy":"Zǎoshang wǒ hē yì píng suānnǎi.","exVi":"Buổi sáng tôi uống một chai sữa chua.","w":"早上 我 喝 一 瓶 酸奶。"},{"zh":"零食","py":"língshí","vi":"đồ ăn vặt","hv":"linh thực","note":"零 (lẻ) + 食 (ăn).","ex":"少吃零食，多吃饭。","exPy":"Shǎo chī língshí, duō chī fàn.","exVi":"Ăn ít đồ vặt, ăn nhiều cơm.","w":"少 吃 零食， 多 吃 饭。"},{"zh":"馒头","py":"mántou","vi":"bánh bao không nhân, màn thầu","hv":"man đầu","note":"Món chính của người miền Bắc Trung Quốc.","ex":"北方人常吃馒头。","exPy":"Běifāng rén cháng chī mántou.","exVi":"Người miền Bắc hay ăn màn thầu.","w":"北方 人 常 吃 馒头。"},{"zh":"月饼","py":"yuèbing","vi":"bánh trung thu","hv":"nguyệt bính","note":"月 (trăng) + 饼 (bánh).","ex":"每年中秋节，奶奶都自己做月饼。","exPy":"Měi nián Zhōngqiū Jié, nǎinai dōu zìjǐ zuò yuèbing.","exVi":"Năm nào Trung thu bà cũng tự làm bánh trung thu.","w":"每 年 中 秋 节， 奶奶 都 自己 做 月饼。"},{"zh":"烤","py":"kǎo","vi":"nướng","hv":"khảo","note":"Có bộ 火. Vịt quay Bắc Kinh là 北京烤鸭.","ex":"这家店的烤鸭特别好吃。","exPy":"Zhè jiā diàn de kǎoyā tèbié hǎochī.","exVi":"Vịt quay quán này đặc biệt ngon.","w":"这 家 店 的 烤鸭 特别 好吃。"},{"zh":"鲜","py":"xiān","vi":"tươi","hv":"tiên","note":"\"Tiên\" trong \"tân tiên\" (tươi mới). Hải sản tươi là 海鲜.","ex":"海鲜要吃新鲜的。","exPy":"Hǎixiān yào chī xīnxiān de.","exVi":"Hải sản phải ăn đồ tươi.","w":"海鲜 要 吃 新鲜 的。"}],"newChars":["馒"],"outro":"很好！Xong bài 161."};
G.ROOMS["zh-l162"] = {"id":"zh-l162","lang":"zh","level":4,"no":162,"teacher":"wang","title":"HSK4 · Bài 162 · 准备考试 Thi cử","intro":["HSK考试有听力、阅读和写作。","Bài 162: Nói về đăng ký thi, thi đại học, thí sinh, thi viết, phỏng vấn, đề thi, điểm số, nghe, nói và viết văn. Bấm 1 · Học để bắt đầu."],"introPy":"HSK kǎoshì yǒu tīnglì, yuèdú hé xiězuò.","gram":{"t":"先…再…: trước… rồi…","b":"先 + việc 1，再 + việc 2","d":"Diễn tả thứ tự hai việc. 再 nhấn mạnh việc sau xảy ra sau việc trước.","ex":[["先做练习，再看电视。","Làm bài tập trước, rồi xem TV.","Xiān zuò liànxí, zài kàn diànshì."],["我们先吃饭，再去看电影。","Chúng ta ăn cơm trước rồi đi xem phim.","Wǒmen xiān chīfàn, zài qù kàn diànyǐng."]]},"grams":[{"t":"先…再…: trước… rồi…","b":"先 + việc 1，再 + việc 2","d":"Diễn tả thứ tự hai việc. 再 nhấn mạnh việc sau xảy ra sau việc trước.","ex":[["先做练习，再看电视。","Làm bài tập trước, rồi xem TV.","Xiān zuò liànxí, zài kàn diànshì."],["我们先吃饭，再去看电影。","Chúng ta ăn cơm trước rồi đi xem phim.","Wǒmen xiān chīfàn, zài qù kàn diànyǐng."]]},{"t":"Lượng từ 篇 cho bài viết","b":"一篇作文 · 一篇文章","d":"Bài văn, bài báo, bài luận đều đếm bằng 篇.","ex":[["这篇文章很有意思。","Bài báo này rất thú vị.","Zhè piān wénzhāng hěn yǒu yìsi."],["我每周写一篇作文。","Mỗi tuần tôi viết một bài văn.","Wǒ měi zhōu xiě yì piān zuòwén."]]}],"items":[{"zh":"报考","py":"bàokǎo","vi":"đăng ký thi","hv":"báo khảo","note":"报 (báo, đăng ký) + 考.","ex":"他报考了北京大学。","exPy":"Tā bàokǎo le Běijīng Dàxué.","exVi":"Cậu ấy đăng ký thi vào Đại học Bắc Kinh.","w":"他 报考 了 北京 大学。"},{"zh":"高考","py":"gāokǎo","vi":"kỳ thi đại học","hv":"cao khảo","note":"Kỳ thi quan trọng nhất với học sinh Trung Quốc.","ex":"高考的时候，考生都很紧张。","exPy":"Gāokǎo de shíhou, kǎoshēng dōu hěn jǐnzhāng.","exVi":"Khi thi đại học, thí sinh đều rất căng thẳng.","w":"高考 的 时候， 考生 都 很 紧张。"},{"zh":"考生","py":"kǎoshēng","vi":"thí sinh","hv":"khảo sinh","note":"Chính là \"khảo sinh\", \"thí sinh\".","ex":"考生请带好身份证。","exPy":"Kǎoshēng qǐng dài hǎo shēnfènzhèng.","exVi":"Thí sinh xin mang theo căn cước.","w":"考生 请 带 好 身份证。"},{"zh":"笔试","py":"bǐshì","vi":"thi viết","hv":"bút thí","note":"笔 (bút) + 试 (thi).","ex":"先笔试，再面试。","exPy":"Xiān bǐshì, zài miànshì.","exVi":"Thi viết trước, rồi phỏng vấn.","w":"先 笔试， 再 面试。"},{"zh":"面试","py":"miànshì","vi":"phỏng vấn","hv":"diện thí","note":"面 (mặt đối mặt) + 试.","ex":"面试的时候要有礼貌。","exPy":"Miànshì de shíhou yào yǒu lǐmào.","exVi":"Khi phỏng vấn phải lịch sự.","w":"面试 的 时候 要 有 礼貌。"},{"zh":"试题","py":"shìtí","vi":"đề thi","hv":"thí đề","note":"Chính là \"thí đề\".","ex":"这次的试题不太难。","exPy":"Zhè cì de shìtí bú tài nán.","exVi":"Đề thi lần này không khó lắm.","w":"这 次 的 试题 不 太 难。"},{"zh":"分数","py":"fēnshù","vi":"điểm số","hv":"phân số","note":"Ở đây không phải \"phân số\" toán học, mà là điểm số bài thi.","ex":"你考了多少分数？","exPy":"Nǐ kǎo le duōshao fēnshù?","exVi":"Bạn thi được bao nhiêu điểm?","w":"你 考 了 多少 分数？"},{"zh":"听力","py":"tīnglì","vi":"(kỹ năng) nghe","hv":"thính lực","note":"Phần nghe trong kỳ thi.","ex":"HSK考试有听力、阅读和写作。","exPy":"HSK kǎoshì yǒu tīnglì, yuèdú hé xiězuò.","exVi":"Kỳ thi HSK có nghe, đọc và viết.","w":"HSK 考试 有 听力、 阅读 和 写作。"},{"zh":"口语","py":"kǒuyǔ","vi":"(kỹ năng) nói, khẩu ngữ","hv":"khẩu ngữ","note":"Chính là \"khẩu ngữ\".","ex":"多练口语，你的汉语会越来越好。","exPy":"Duō liàn kǒuyǔ, nǐ de Hànyǔ huì yuèláiyuè hǎo.","exVi":"Luyện nói nhiều, tiếng Trung của bạn sẽ ngày càng giỏi.","w":"多 练 口语， 你 的 汉语 会 越 来 越 好。"},{"zh":"作文","py":"zuòwén","vi":"bài văn; viết văn","hv":"tác văn","note":"Bài văn ở trường, phần viết trong kỳ thi.","ex":"老师让我们写一篇作文。","exPy":"Lǎoshī ràng wǒmen xiě yì piān zuòwén.","exVi":"Cô giáo bảo chúng tôi viết một bài văn.","w":"老师 让 我们 写 一 篇 作文。"}],"newChars":[],"outro":"很好！Xong bài 162."};
G.ROOMS["zh-l163"] = {"id":"zh-l163","lang":"zh","level":4,"no":163,"teacher":"wang","title":"HSK4 · Bài 163 · 上课和自习 Học trên lớp và tự học","intro":["期末考试以后就放假了。","Bài 163: Nói về chương trình học, lớp học, bài tập, tự học, giảng dạy, giáo viên, thầy trò, giữa kỳ và cuối kỳ. Bấm 1 · Học để bắt đầu."],"introPy":"Qīmò kǎoshì yǐhòu jiù fàngjià le.","gram":{"t":"动词 + 完: làm xong","b":"做完 · 吃完 · 看完","d":"完 sau động từ báo việc đã làm xong hết. Phủ định: 没做完.","ex":[["作业你写完了吗？","Bài tập bạn viết xong chưa?","Zuòyè nǐ xiě wán le ma?"],["这本书我还没看完。","Cuốn sách này tôi chưa đọc xong.","Zhè běn shū wǒ hái méi kàn wán."]]},"grams":[{"t":"动词 + 完: làm xong","b":"做完 · 吃完 · 看完","d":"完 sau động từ báo việc đã làm xong hết. Phủ định: 没做完.","ex":[["作业你写完了吗？","Bài tập bạn viết xong chưa?","Zuòyè nǐ xiě wán le ma?"],["这本书我还没看完。","Cuốn sách này tôi chưa đọc xong.","Zhè běn shū wǒ hái méi kàn wán."]]},{"t":"自习 và 自学","b":"自习 = tự học trong giờ, ở trường · 自学 = tự học một mình, không có thầy","d":"Hai từ dễ nhầm. Học sinh \"giờ tự học\" dùng 自习; người tự mày mò học dùng 自学.","ex":[["我是自学汉语的。","Tôi tự học tiếng Trung.","Wǒ shì zìxué Hànyǔ de."],["下午第三节是自习课。","Tiết ba buổi chiều là giờ tự học.","Xiàwǔ dì sān jié shì zìxíkè."]]}],"items":[{"zh":"课程","py":"kèchéng","vi":"chương trình học, môn học","hv":"khoá trình","note":"Chính là \"khoá trình\".","ex":"这门课程对我很有用。","exPy":"Zhè mén kèchéng duì wǒ hěn yǒuyòng.","exVi":"Môn học này rất có ích với tôi.","w":"这 门 课程 对 我 很 有用。"},{"zh":"课堂","py":"kètáng","vi":"lớp học, giờ học","hv":"khoá đường","note":"课 + 堂 (nhà, phòng).","ex":"课堂上老师和学生常常一起讨论。","exPy":"Kètáng shang lǎoshī hé xuésheng chángcháng yìqǐ tǎolùn.","exVi":"Trong lớp thầy và trò hay cùng thảo luận.","w":"课堂 上 老师 和 学生 常常 一起 讨论。"},{"zh":"功课","py":"gōngkè","vi":"bài tập; bài học","hv":"công khoá","note":"Gần nghĩa 作业.","ex":"做完功课再玩儿。","exPy":"Zuò wán gōngkè zài wánr.","exVi":"Làm xong bài tập rồi hãy chơi.","w":"做 完 功课 再 玩 儿。"},{"zh":"自习","py":"zìxí","vi":"tự học (ở lớp, thư viện)","hv":"tự tập","note":"Giờ tự học ở trường gọi là 自习课.","ex":"晚上我们在教室自习。","exPy":"Wǎnshang wǒmen zài jiàoshì zìxí.","exVi":"Buổi tối chúng tôi tự học ở lớp.","w":"晚上 我们 在 教室 自习。"},{"zh":"自学","py":"zìxué","vi":"tự học (không có thầy)","hv":"tự học","note":"Học một mình, không theo lớp.","ex":"他自学了日语。","exPy":"Tā zìxué le Rìyǔ.","exVi":"Anh ấy tự học tiếng Nhật.","w":"他 自学 了 日 语。"},{"zh":"教学","py":"jiàoxué","vi":"giảng dạy, dạy học","hv":"giáo học","note":"教 (dạy) + 学 (học).","ex":"这个学校的教学质量很高。","exPy":"Zhège xuéxiào de jiàoxué zhìliàng hěn gāo.","exVi":"Chất lượng giảng dạy trường này rất cao.","w":"这个 学校 的 教学 质量 很 高。"},{"zh":"教师","py":"jiàoshī","vi":"giáo viên","hv":"giáo sư","note":"Chú ý: 教师 là giáo viên nói chung, không phải \"giáo sư\" (教授).","ex":"我想当一名教师。","exPy":"Wǒ xiǎng dāng yì míng jiàoshī.","exVi":"Tôi muốn làm giáo viên.","w":"我 想 当 一 名 教师。"},{"zh":"师生","py":"shīshēng","vi":"thầy và trò","hv":"sư sinh","note":"师 (thầy) + 生 (trò).","ex":"全校师生都参加了运动会。","exPy":"Quán xiào shīshēng dōu cānjiā le yùndònghuì.","exVi":"Toàn thể thầy trò đều tham gia hội thao.","w":"全 校 师生 都 参加 了 运动会。"},{"zh":"期中","py":"qīzhōng","vi":"giữa kỳ","hv":"kỳ trung","note":"Thi giữa kỳ là 期中考试.","ex":"下周有期中考试。","exPy":"Xià zhōu yǒu qīzhōng kǎoshì.","exVi":"Tuần sau có thi giữa kỳ.","w":"下 周 有 期中 考试。"},{"zh":"期末","py":"qīmò","vi":"cuối kỳ","hv":"kỳ mạt","note":"末 = \"mạt\" (cuối). Thi cuối kỳ là 期末考试.","ex":"期末考试以后就放假了。","exPy":"Qīmò kǎoshì yǐhòu jiù fàngjià le.","exVi":"Thi cuối kỳ xong là được nghỉ.","w":"期末 考试 以后 就 放假 了。"}],"newChars":[],"outro":"很好！Xong bài 163."};
G.ROOMS["zh-l164"] = {"id":"zh-l164","lang":"zh","level":4,"no":164,"teacher":"wang","title":"HSK4 · Bài 164 · 读研究生 Đại học và học bổng","intro":["他是我们学院的研究生。","Bài 164: Nói về đại học hệ chính quy, nghiên cứu sinh, học viện, sinh viên tốt nghiệp, nhập học, học phí, học bổng, viện trưởng, nghỉ hè và tri thức. Bấm 1 · Học để bắt đầu."],"introPy":"Tā shì wǒmen xuéyuàn de yánjiūshēng.","gram":{"t":"是…的: nhấn mạnh thông tin","b":"我本科学的是经济 · 我是去年毕业的","d":"Dùng để nhấn mạnh một chi tiết (thời gian, cách thức, đối tượng) của việc đã xảy ra.","ex":[["我是二零二二年毕业的。","Tôi tốt nghiệp năm 2022.","Wǒ shì èr líng èr èr nián bìyè de."],["你是怎么来的？","Bạn đến bằng cách nào?","Nǐ shì zěnme lái de?"]]},"grams":[{"t":"是…的: nhấn mạnh thông tin","b":"我本科学的是经济 · 我是去年毕业的","d":"Dùng để nhấn mạnh một chi tiết (thời gian, cách thức, đối tượng) của việc đã xảy ra.","ex":[["我是二零二二年毕业的。","Tôi tốt nghiệp năm 2022.","Wǒ shì èr líng èr èr nián bìyè de."],["你是怎么来的？","Bạn đến bằng cách nào?","Nǐ shì zěnme lái de?"]]},{"t":"打算 + động từ: định làm","b":"打算 + 做 / 去 / 学","d":"Nói kế hoạch sắp tới.","ex":[["我打算明年读研究生。","Tôi định năm sau học cao học.","Wǒ dǎsuàn míngnián dú yánjiūshēng."],["暑假我打算去打工。","Nghỉ hè tôi định đi làm thêm.","Shǔjià wǒ dǎsuàn qù dǎgōng."]]}],"items":[{"zh":"本科","py":"běnkē","vi":"đại học (hệ cử nhân)","hv":"bản khoa","note":"Bậc đại học bốn năm. Sinh viên là 本科生.","ex":"我本科学的是经济。","exPy":"Wǒ běnkē xué de shì jīngjì.","exVi":"Đại học tôi học ngành kinh tế.","w":"我 本科 学 的 是 经济。"},{"zh":"研究生","py":"yánjiūshēng","vi":"học viên cao học","hv":"nghiên cứu sinh","note":"Ở Trung Quốc, 研究生 gồm thạc sĩ và tiến sĩ.","ex":"他是我们学院的研究生。","exPy":"Tā shì wǒmen xuéyuàn de yánjiūshēng.","exVi":"Anh ấy là học viên cao học của khoa chúng tôi.","w":"他 是 我们 学院 的 研究生。"},{"zh":"学院","py":"xuéyuàn","vi":"học viện; khoa","hv":"học viện","note":"Chính là \"học viện\". Trong đại học, 学院 cũng là một khoa lớn.","ex":"他在外语学院学习。","exPy":"Tā zài wàiyǔ xuéyuàn xuéxí.","exVi":"Anh ấy học ở khoa ngoại ngữ.","w":"他 在 外语 学院 学习。"},{"zh":"毕业生","py":"bìyèshēng","vi":"sinh viên tốt nghiệp","hv":"tất nghiệp sinh","note":"毕业 (tốt nghiệp) + 生.","ex":"今年的毕业生很难找工作。","exPy":"Jīnnián de bìyèshēng hěn nán zhǎo gōngzuò.","exVi":"Sinh viên tốt nghiệp năm nay rất khó tìm việc.","w":"今年 的 毕业生 很 难 找 工作。"},{"zh":"入学","py":"rùxué","vi":"nhập học","hv":"nhập học","note":"Chính là \"nhập học\".","ex":"新生九月入学。","exPy":"Xīnshēng jiǔ yuè rùxué.","exVi":"Tân sinh viên nhập học tháng chín.","w":"新生 九 月 入学。"},{"zh":"学费","py":"xuéfèi","vi":"học phí","hv":"học phí","note":"Chính là \"học phí\".","ex":"有了奖学金，我不用担心学费了。","exPy":"Yǒu le jiǎngxuéjīn, wǒ búyòng dānxīn xuéfèi le.","exVi":"Có học bổng rồi, tôi không phải lo học phí nữa.","w":"有 了 奖学金， 我 不用 担心 学费 了。"},{"zh":"奖学金","py":"jiǎngxuéjīn","vi":"học bổng","hv":"tưởng học kim","note":"奖 (thưởng) + 学 + 金 (tiền).","ex":"她拿到了全额奖学金。","exPy":"Tā ná dào le quán'é jiǎngxuéjīn.","exVi":"Cô ấy nhận được học bổng toàn phần.","w":"她 拿 到 了 全 额 奖学金。"},{"zh":"院长","py":"yuànzhǎng","vi":"viện trưởng, trưởng khoa","hv":"viện trưởng","note":"院 + 长 (trưởng).","ex":"院长在大会上讲了话。","exPy":"Yuànzhǎng zài dàhuì shang jiǎng le huà.","exVi":"Trưởng khoa đã phát biểu tại đại hội.","w":"院长 在 大会 上 讲 了 话。"},{"zh":"暑假","py":"shǔjià","vi":"nghỉ hè","hv":"thử giả","note":"暑 = nóng (\"thử\"). Nghỉ đông là 寒假.","ex":"暑假一共有两个月。","exPy":"Shǔjià yígòng yǒu liǎng ge yuè.","exVi":"Nghỉ hè tổng cộng hai tháng.","w":"暑假 一共 有 两 个 月。"},{"zh":"知识","py":"zhīshi","vi":"kiến thức, tri thức","hv":"tri thức","note":"Chính là \"tri thức\".","ex":"知识可以改变命运。","exPy":"Zhīshi kěyǐ gǎibiàn mìngyùn.","exVi":"Tri thức có thể thay đổi số phận.","w":"知识 可以 改变 命运。"}],"newChars":[],"outro":"很好！Xong bài 164."};
G.ROOMS["zh-l165"] = {"id":"zh-l165","lang":"zh","level":4,"no":165,"teacher":"wang","title":"HSK4 · Bài 165 · 我的家庭 Gia đình","intro":["父母是孩子最好的老师。","Bài 165: Gọi các quan hệ gia đình trang trọng: cha, cha mẹ, cha con, mẹ con, anh em, cháu gái, phụ huynh và gia đình. Bấm 1 · Học để bắt đầu."],"introPy":"Fùmǔ shì háizi zuì hǎo de lǎoshī.","gram":{"t":"长得 + 像 / 好看: ngoại hình","b":"A + 长得 + 很像 + B · 长得很高","d":"长得 (zhǎng de) dùng để tả ngoại hình.","ex":[["你长得很像你妈妈。","Bạn trông rất giống mẹ.","Nǐ zhǎng de hěn xiàng nǐ māma."],["他长得又高又帅。","Anh ấy vừa cao vừa đẹp trai.","Tā zhǎng de yòu gāo yòu shuài."]]},"grams":[{"t":"长得 + 像 / 好看: ngoại hình","b":"A + 长得 + 很像 + B · 长得很高","d":"长得 (zhǎng de) dùng để tả ngoại hình.","ex":[["你长得很像你妈妈。","Bạn trông rất giống mẹ.","Nǐ zhǎng de hěn xiàng nǐ māma."],["他长得又高又帅。","Anh ấy vừa cao vừa đẹp trai.","Tā zhǎng de yòu gāo yòu shuài."]]},{"t":"俩: hai người","b":"我们俩 · 母子俩 · 夫妻俩","d":"俩 (liǎ) = 两个, đứng sau danh từ chỉ người, không thêm 个.","ex":[["我们俩是同学。","Hai chúng tôi là bạn cùng lớp.","Wǒmen liǎ shì tóngxué."],["他们兄弟俩都很高。","Hai anh em họ đều rất cao.","Tāmen xiōngdì liǎ dōu hěn gāo."]]}],"items":[{"zh":"父亲","py":"fùqīn","vi":"cha, bố","hv":"phụ thân","note":"Chính là \"phụ thân\". Trang trọng hơn 爸爸.","ex":"我父亲年轻的时候当过兵。","exPy":"Wǒ fùqīn niánqīng de shíhou dāng guo bīng.","exVi":"Hồi trẻ cha tôi từng đi lính.","w":"我 父亲 年轻 的 时候 当 过 兵。"},{"zh":"父母","py":"fùmǔ","vi":"cha mẹ","hv":"phụ mẫu","note":"Chính là \"phụ mẫu\".","ex":"父母是孩子最好的老师。","exPy":"Fùmǔ shì háizi zuì hǎo de lǎoshī.","exVi":"Cha mẹ là người thầy tốt nhất của con.","w":"父母 是 孩子 最好 的 老师。"},{"zh":"父子","py":"fùzǐ","vi":"cha con (trai)","hv":"phụ tử","note":"Chính là \"phụ tử\".","ex":"他们父子长得很像。","exPy":"Tāmen fùzǐ zhǎng de hěn xiàng.","exVi":"Hai cha con họ trông rất giống nhau.","w":"他们 父子 长 得 很 像。"},{"zh":"父女","py":"fùnǚ","vi":"cha con (gái)","hv":"phụ nữ","note":"Chú ý: không phải \"phụ nữ\" tiếng Việt (女人), mà là cha và con gái.","ex":"那对父女在公园散步。","exPy":"Nà duì fùnǚ zài gōngyuán sànbù.","exVi":"Hai cha con gái kia đang đi dạo trong công viên.","w":"那 对 父女 在 公园 散步。"},{"zh":"母子","py":"mǔzǐ","vi":"mẹ con (trai)","hv":"mẫu tử","note":"Chính là \"mẫu tử\".","ex":"母子俩一起去旅行了。","exPy":"Mǔzǐ liǎ yìqǐ qù lǚxíng le.","exVi":"Hai mẹ con cùng đi du lịch rồi.","w":"母子 俩 一起 去 旅行 了。"},{"zh":"母女","py":"mǔnǚ","vi":"mẹ con (gái)","hv":"mẫu nữ","note":"Mẹ và con gái.","ex":"她们母女关系很好。","exPy":"Tāmen mǔnǚ guānxì hěn hǎo.","exVi":"Hai mẹ con cô ấy rất thân nhau.","w":"她们 母女 关系 很 好。"},{"zh":"兄弟","py":"xiōngdì","vi":"anh em trai","hv":"huynh đệ","note":"Chính là \"huynh đệ\". Bạn thân nam cũng gọi nhau là 兄弟.","ex":"我们是好兄弟。","exPy":"Wǒmen shì hǎo xiōngdì.","exVi":"Chúng tôi là anh em tốt.","w":"我们 是 好 兄弟。"},{"zh":"孙女","py":"sūnnǚ","vi":"cháu gái (nội)","hv":"tôn nữ","note":"孙 = \"tôn\" (cháu). Cháu trai là 孙子.","ex":"奶奶很爱她的孙女。","exPy":"Nǎinai hěn ài tā de sūnnǚ.","exVi":"Bà rất thương cháu gái.","w":"奶奶 很 爱 她 的 孙女。"},{"zh":"家长","py":"jiāzhǎng","vi":"phụ huynh","hv":"gia trưởng","note":"Ở trường, 家长 là phụ huynh học sinh. Họp phụ huynh: 家长会.","ex":"家长会上，老师和家长谈了很多。","exPy":"Jiāzhǎnghuì shang, lǎoshī hé jiāzhǎng tán le hěn duō.","exVi":"Tại buổi họp phụ huynh, thầy cô và phụ huynh nói chuyện rất nhiều.","w":"家长 会 上， 老师 和 家长 谈 了 很 多。"},{"zh":"家庭","py":"jiātíng","vi":"gia đình","hv":"gia đình","note":"Chính là \"gia đình\".","ex":"每个家庭都有自己的故事。","exPy":"Měi ge jiātíng dōu yǒu zìjǐ de gùshi.","exVi":"Mỗi gia đình đều có câu chuyện riêng.","w":"每 个 家庭 都 有 自己 的 故事。"}],"newChars":["父","兄","庭"],"outro":"很好！Xong bài 165."};
G.ROOMS["zh-l166"] = {"id":"zh-l166","lang":"zh","level":4,"no":166,"teacher":"wang","title":"HSK4 · Bài 166 · 青年和老年 Các lứa tuổi","intro":["每个人都有难忘的童年。","Bài 166: Gọi người theo tuổi và giới: cô gái, thanh niên, thiếu niên, trung niên, người già, quý ông, nam giới, nữ giới, tuổi thơ, cả đời. Bấm 1 · Học để bắt đầu."],"introPy":"Měi ge rén dōu yǒu nánwàng de tóngnián.","gram":{"t":"比较 + tính từ: tương đối","b":"比较多 · 比较难","d":"Diễn tả mức độ vừa phải, không so sánh với ai cụ thể.","ex":[["今天比较冷。","Hôm nay tương đối lạnh.","Jīntiān bǐjiào lěng."],["这个问题比较复杂。","Vấn đề này khá phức tạp.","Zhège wèntí bǐjiào fùzá."]]},"grams":[{"t":"比较 + tính từ: tương đối","b":"比较多 · 比较难","d":"Diễn tả mức độ vừa phải, không so sánh với ai cụ thể.","ex":[["今天比较冷。","Hôm nay tương đối lạnh.","Jīntiān bǐjiào lěng."],["这个问题比较复杂。","Vấn đề này khá phức tạp.","Zhège wèntí bǐjiào fùzá."]]},{"t":"是在…过的: tuổi thơ, thời gian trải qua ở đâu","b":"童年是在 + nơi + 过的","d":"Dùng 是…的 nhấn mạnh nơi chốn của việc đã qua.","ex":[["我的大学时光是在北京过的。","Thời đại học của tôi trải qua ở Bắc Kinh.","Wǒ de dàxué shíguāng shì zài Běijīng guò de."],["他的童年是在海边过的。","Tuổi thơ anh ấy trải qua bên bờ biển.","Tā de tóngnián shì zài hǎibiān guò de."]]}],"items":[{"zh":"姑娘","py":"gūniang","vi":"cô gái","hv":"cô nương","note":"Chính là \"cô nương\". Gọi cô gái trẻ một cách thân mật.","ex":"那个姑娘是谁？","exPy":"Nàge gūniang shì shéi?","exVi":"Cô gái kia là ai?","w":"那个 姑娘 是 谁？"},{"zh":"青年","py":"qīngnián","vi":"thanh niên","hv":"thanh niên","note":"Chính là \"thanh niên\".","ex":"青年人要有梦想。","exPy":"Qīngnián rén yào yǒu mèngxiǎng.","exVi":"Người trẻ phải có ước mơ.","w":"青年 人 要 有 梦想。"},{"zh":"少年","py":"shàonián","vi":"thiếu niên","hv":"thiếu niên","note":"Chính là \"thiếu niên\". Chú ý 少 đọc thanh 4 (shào).","ex":"他少年时就很喜欢画画。","exPy":"Tā shàonián shí jiù hěn xǐhuan huà huà.","exVi":"Từ thời thiếu niên anh ấy đã rất thích vẽ.","w":"他 少年 时 就 很 喜欢 画 画。"},{"zh":"中年","py":"zhōngnián","vi":"trung niên","hv":"trung niên","note":"Chính là \"trung niên\".","ex":"一位中年男人走了进来。","exPy":"Yí wèi zhōngnián nánrén zǒu le jìnlai.","exVi":"Một người đàn ông trung niên bước vào.","w":"一 位 中年 男人 走 了 进来。"},{"zh":"老年","py":"lǎonián","vi":"tuổi già","hv":"lão niên","note":"Người già là 老年人.","ex":"老年人要多注意身体。","exPy":"Lǎonián rén yào duō zhùyì shēntǐ.","exVi":"Người già phải chú ý sức khoẻ nhiều hơn.","w":"老年 人 要 多 注意 身体。"},{"zh":"男士","py":"nánshì","vi":"quý ông","hv":"nam sĩ","note":"Cách gọi lịch sự, đối xứng với 女士.","ex":"这是男士用的。","exPy":"Zhè shì nánshì yòng de.","exVi":"Cái này dành cho nam.","w":"这 是 男士 用 的。"},{"zh":"男性","py":"nánxìng","vi":"nam giới","hv":"nam tính","note":"Chú ý: không phải \"nam tính\" (vẻ đàn ông) tiếng Việt, mà là giới nam, dùng trong văn bản.","ex":"这个工作男性比较多。","exPy":"Zhège gōngzuò nánxìng bǐjiào duō.","exVi":"Công việc này nam giới tương đối nhiều.","w":"这个 工作 男性 比较 多。"},{"zh":"女性","py":"nǚxìng","vi":"nữ giới","hv":"nữ tính","note":"Giới nữ, dùng trong văn bản, thống kê.","ex":"越来越多的女性当了领导。","exPy":"Yuèláiyuè duō de nǚxìng dāng le lǐngdǎo.","exVi":"Ngày càng nhiều phụ nữ làm lãnh đạo.","w":"越 来 越 多 的 女性 当 了 领导。"},{"zh":"童年","py":"tóngnián","vi":"tuổi thơ","hv":"đồng niên","note":"童 = \"đồng\" trong \"nhi đồng\".","ex":"每个人都有难忘的童年。","exPy":"Měi ge rén dōu yǒu nánwàng de tóngnián.","exVi":"Ai cũng có một tuổi thơ khó quên.","w":"每 个人 都 有 难忘 的 童年。"},{"zh":"一生","py":"yìshēng","vi":"cả đời","hv":"nhất sinh","note":"Chính là \"nhất sinh\" (một đời).","ex":"她把一生都献给了教育。","exPy":"Tā bǎ yìshēng dōu xiàn gěi le jiàoyù.","exVi":"Bà ấy cống hiến cả đời cho giáo dục.","w":"她 把 一生 都 献 给 了 教育。"}],"newChars":["姑","娘","青"],"outro":"很好！Xong bài 166."};
G.ROOMS["zh-l167"] = {"id":"zh-l167","lang":"zh","level":4,"no":167,"teacher":"wang","title":"HSK4 · Bài 167 · 在工厂打工 Nơi làm việc","intro":["很多大学生周末去打工。","Bài 167: Nói về làm việc văn phòng, phòng ban, cơ quan, phụ trách, người phụ trách, nhân viên, công nhân, nhà máy và làm thêm. Bấm 1 · Học để bắt đầu."],"introPy":"Hěn duō dàxuéshēng zhōumò qù dǎgōng.","gram":{"t":"由 + người + 负责: do ai phụ trách","b":"这件事由他负责","d":"由 giới thiệu người chịu trách nhiệm, trang trọng hơn 让.","ex":[["这次活动由小王负责。","Hoạt động lần này do Tiểu Vương phụ trách.","Zhè cì huódòng yóu Xiǎo Wáng fùzé."],["会议由经理主持。","Cuộc họp do giám đốc chủ trì.","Huìyì yóu jīnglǐ zhǔchí."]]},"grams":[{"t":"由 + người + 负责: do ai phụ trách","b":"这件事由他负责","d":"由 giới thiệu người chịu trách nhiệm, trang trọng hơn 让.","ex":[["这次活动由小王负责。","Hoạt động lần này do Tiểu Vương phụ trách.","Zhè cì huódòng yóu Xiǎo Wáng fùzé."],["会议由经理主持。","Cuộc họp do giám đốc chủ trì.","Huìyì yóu jīnglǐ zhǔchí."]]},{"t":"对…负责: chịu trách nhiệm với","b":"对自己负责 · 对工作负责","d":"Đối tượng chịu trách nhiệm đặt sau 对.","ex":[["每个人都要对自己负责。","Ai cũng phải chịu trách nhiệm với bản thân.","Měi ge rén dōu yào duì zìjǐ fùzé."],["他对工作非常负责。","Anh ấy rất có trách nhiệm với công việc.","Tā duì gōngzuò fēicháng fùzé."]]}],"items":[{"zh":"办公","py":"bàngōng","vi":"làm việc (văn phòng)","hv":"biện công","note":"Văn phòng là 办公室.","ex":"他在楼上办公。","exPy":"Tā zài lóu shang bàngōng.","exVi":"Anh ấy làm việc ở tầng trên.","w":"他 在 楼 上 办公。"},{"zh":"部门","py":"bùmén","vi":"phòng ban","hv":"bộ môn","note":"Khác \"bộ môn\" ở trường tiếng Việt: 部门 là phòng ban trong cơ quan.","ex":"我们部门一共有十个人。","exPy":"Wǒmen bùmén yígòng yǒu shí ge rén.","exVi":"Phòng chúng tôi tổng cộng có mười người.","w":"我们 部门 一共 有 十 个人。"},{"zh":"单位","py":"dānwèi","vi":"cơ quan, đơn vị công tác","hv":"đơn vị","note":"Chính là \"đơn vị\".","ex":"我们单位有两百多人。","exPy":"Wǒmen dānwèi yǒu liǎng bǎi duō rén.","exVi":"Cơ quan chúng tôi có hơn hai trăm người.","w":"我们 单位 有 两 百 多 人。"},{"zh":"负责","py":"fùzé","vi":"phụ trách, chịu trách nhiệm","hv":"phụ trách","note":"Chính là \"phụ trách\". Còn là tính từ: 他很负责 (anh ấy rất có trách nhiệm).","ex":"这件事由我负责。","exPy":"Zhè jiàn shì yóu wǒ fùzé.","exVi":"Việc này do tôi phụ trách.","w":"这 件 事 由 我 负责。"},{"zh":"负责人","py":"fùzérén","vi":"người phụ trách","hv":"phụ trách nhân","note":"负责 + 人.","ex":"请问这里的负责人是谁？","exPy":"Qǐngwèn zhèlǐ de fùzérén shì shéi?","exVi":"Cho hỏi người phụ trách ở đây là ai?","w":"请问 这里 的 负责人 是 谁？"},{"zh":"人员","py":"rényuán","vi":"nhân sự, người (làm việc)","hv":"nhân viên","note":"Hay ghép: 工作人员 (nhân viên), 服务人员.","ex":"有问题可以问工作人员。","exPy":"Yǒu wèntí kěyǐ wèn gōngzuò rényuán.","exVi":"Có vấn đề có thể hỏi nhân viên.","w":"有 问题 可以 问 工作 人员。"},{"zh":"工人","py":"gōngrén","vi":"công nhân","hv":"công nhân","note":"Chính là \"công nhân\".","ex":"工厂里的工人都很辛苦。","exPy":"Gōngchǎng lǐ de gōngrén dōu hěn xīnkǔ.","exVi":"Công nhân trong nhà máy đều rất vất vả.","w":"工厂 里 的 工人 都 很 辛苦。"},{"zh":"工厂","py":"gōngchǎng","vi":"nhà máy","hv":"công xưởng","note":"Chính là \"công xưởng\".","ex":"他在汽车工厂工作。","exPy":"Tā zài qìchē gōngchǎng gōngzuò.","exVi":"Anh ấy làm ở nhà máy ô tô.","w":"他 在 汽车 工厂 工作。"},{"zh":"厂","py":"chǎng","vi":"xưởng, nhà máy","hv":"xưởng","note":"Gọn hơn 工厂. Ghép: 厂长 (giám đốc nhà máy).","ex":"我爸爸在厂里上班。","exPy":"Wǒ bàba zài chǎng lǐ shàngbān.","exVi":"Bố tôi làm ở nhà máy.","w":"我 爸爸 在 厂 里 上班。"},{"zh":"打工","py":"dǎgōng","vi":"làm thuê, làm thêm","hv":"đả công","note":"Sinh viên làm thêm cũng gọi là 打工.","ex":"很多大学生周末去打工。","exPy":"Hěn duō dàxuéshēng zhōumò qù dǎgōng.","exVi":"Nhiều sinh viên cuối tuần đi làm thêm.","w":"很 多 大学生 周末 去 打工。"}],"newChars":["负","厂"],"outro":"很好！Xong bài 167."};
G.ROOMS["zh-l168"] = {"id":"zh-l168","lang":"zh","level":4,"no":168,"teacher":"wang","title":"HSK4 · Bài 168 · 办手续 Giấy tờ thủ tục","intro":["办理手续要带身份证。","Bài 168: Nói về làm thủ tục, lo việc, điền đơn, giấy chứng nhận, giấy tờ, căn cước, đại sứ quán, văn bản, tài liệu và sách hướng dẫn. Bấm 1 · Học để bắt đầu."],"introPy":"Bànlǐ shǒuxù yào dài shēnfènzhèng.","gram":{"t":"把 + vật + động từ + 给 + người","b":"把文件发给我 · 把书还给他","d":"Câu chữ 把 nhấn mạnh việc xử lý một vật cụ thể; vật đã xác định đứng sau 把.","ex":[["请把护照给我看一下。","Xin cho tôi xem hộ chiếu.","Qǐng bǎ hùzhào gěi wǒ kàn yíxià."],["我把资料放在桌子上了。","Tôi để tài liệu trên bàn rồi.","Wǒ bǎ zīliào fàng zài zhuōzi shang le."]]},"grams":[{"t":"把 + vật + động từ + 给 + người","b":"把文件发给我 · 把书还给他","d":"Câu chữ 把 nhấn mạnh việc xử lý một vật cụ thể; vật đã xác định đứng sau 把.","ex":[["请把护照给我看一下。","Xin cho tôi xem hộ chiếu.","Qǐng bǎ hùzhào gěi wǒ kàn yíxià."],["我把资料放在桌子上了。","Tôi để tài liệu trên bàn rồi.","Wǒ bǎ zīliào fàng zài zhuōzi shang le."]]},{"t":"张 cho vật mỏng phẳng","b":"一张表 · 一张纸 · 一张票 · 一张照片","d":"Giấy tờ, vé, ảnh, bàn đều đếm bằng 张.","ex":[["请再给我一张表。","Xin cho tôi thêm một tờ khai.","Qǐng zài gěi wǒ yì zhāng biǎo."],["我买了两张票。","Tôi mua hai vé.","Wǒ mǎi le liǎng zhāng piào."]]}],"items":[{"zh":"办理","py":"bànlǐ","vi":"làm (thủ tục), giải quyết","hv":"biện lý","note":"Trang trọng hơn 办.","ex":"办理手续要带身份证。","exPy":"Bànlǐ shǒuxù yào dài shēnfènzhèng.","exVi":"Làm thủ tục phải mang căn cước.","w":"办理 手续 要 带 身份证。"},{"zh":"办事","py":"bànshì","vi":"làm việc, lo việc","hv":"biện sự","note":"办 + 事.","ex":"他办事很认真。","exPy":"Tā bànshì hěn rènzhēn.","exVi":"Anh ấy làm việc rất cẩn thận.","w":"他 办事 很 认真。"},{"zh":"填写","py":"tiánxiě","vi":"điền (vào mẫu)","hv":"điền tả","note":"填 (điền) + 写 (viết).","ex":"请填写这张表。","exPy":"Qǐng tiánxiě zhè zhāng biǎo.","exVi":"Xin điền vào tờ khai này.","w":"请 填写 这 张 表。"},{"zh":"证","py":"zhèng","vi":"giấy chứng nhận, thẻ","hv":"chứng","note":"\"Chứng\" trong \"chứng chỉ\". Ghép: 学生证, 工作证.","ex":"请出示你的学生证。","exPy":"Qǐng chūshì nǐ de xuéshengzhèng.","exVi":"Xin xuất trình thẻ sinh viên.","w":"请 出示 你 的 学生 证。"},{"zh":"证件","py":"zhèngjiàn","vi":"giấy tờ tuỳ thân","hv":"chứng kiện","note":"Hộ chiếu, căn cước… đều là 证件.","ex":"坐飞机要带证件。","exPy":"Zuò fēijī yào dài zhèngjiàn.","exVi":"Đi máy bay phải mang giấy tờ.","w":"坐 飞机 要 带 证件。"},{"zh":"身份证","py":"shēnfènzhèng","vi":"căn cước, chứng minh thư","hv":"thân phận chứng","note":"身份 (thân phận) + 证.","ex":"我的身份证丢了。","exPy":"Wǒ de shēnfènzhèng diū le.","exVi":"Tôi mất căn cước rồi.","w":"我 的 身份证 丢 了。"},{"zh":"使馆","py":"shǐguǎn","vi":"đại sứ quán","hv":"sứ quán","note":"Viết tắt của 大使馆. Chính là \"sứ quán\".","ex":"我去使馆办签证。","exPy":"Wǒ qù shǐguǎn bàn qiānzhèng.","exVi":"Tôi đến sứ quán làm thị thực.","w":"我 去 使馆 办 签证。"},{"zh":"文件","py":"wénjiàn","vi":"văn bản, tài liệu, tệp","hv":"văn kiện","note":"Cũng là \"tệp\" trên máy tính.","ex":"这份文件很重要，别丢了。","exPy":"Zhè fèn wénjiàn hěn zhòngyào, bié diū le.","exVi":"Văn bản này rất quan trọng, đừng làm mất.","w":"这 份 文件 很 重要， 别 丢 了。"},{"zh":"资料","py":"zīliào","vi":"tài liệu, tư liệu","hv":"tư liệu","note":"Chính là \"tư liệu\".","ex":"我在网上找到了很多资料。","exPy":"Wǒ zài wǎngshang zhǎodào le hěn duō zīliào.","exVi":"Tôi tìm được nhiều tài liệu trên mạng.","w":"我 在 网上 找 到 了 很 多 资料。"},{"zh":"说明书","py":"shuōmíngshū","vi":"sách hướng dẫn sử dụng","hv":"thuyết minh thư","note":"说明 (giải thích) + 书.","ex":"说明书上写得很清楚。","exPy":"Shuōmíngshū shang xiě de hěn qīngchu.","exVi":"Sách hướng dẫn viết rất rõ ràng.","w":"说明书 上 写 得 很 清楚。"}],"newChars":[],"outro":"很好！Xong bài 168."};
G.ROOMS["zh-l169"] = {"id":"zh-l169","lang":"zh","level":4,"no":169,"teacher":"wang","title":"HSK4 · Bài 169 · 转发视频 Trên mạng xã hội","intro":["这个视频已经有一百万人看过了。","Bài 169: Nói về video, trang web, bạn trên mạng, địa chỉ web, chia sẻ, gửi, trả lời, hồi âm, tín hiệu và quét mã. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège shìpín yǐjīng yǒu yìbǎi wàn rén kàn guo le.","gram":{"t":"Động từ + 不 / 得 + bổ ngữ: có thể hay không","b":"打不开 · 看得懂 · 听不清楚","d":"Chèn 得 (được) hoặc 不 (không) giữa động từ và kết quả để nói khả năng.","ex":[["这个字太小，我看不清楚。","Chữ nhỏ quá, tôi nhìn không rõ.","Zhège zì tài xiǎo, wǒ kàn bu qīngchu."],["你听得懂上海话吗？","Bạn nghe hiểu tiếng Thượng Hải không?","Nǐ tīng de dǒng Shànghǎi huà ma?"]]},"grams":[{"t":"Động từ + 不 / 得 + bổ ngữ: có thể hay không","b":"打不开 · 看得懂 · 听不清楚","d":"Chèn 得 (được) hoặc 不 (không) giữa động từ và kết quả để nói khả năng.","ex":[["这个字太小，我看不清楚。","Chữ nhỏ quá, tôi nhìn không rõ.","Zhège zì tài xiǎo, wǒ kàn bu qīngchu."],["你听得懂上海话吗？","Bạn nghe hiểu tiếng Thượng Hải không?","Nǐ tīng de dǒng Shànghǎi huà ma?"]]},{"t":"Lượng từ 条 cho tin nhắn, tin tức","b":"一条消息 · 一条新闻 · 一条短信","d":"Tin nhắn, tin tức đếm bằng 条.","ex":[["我收到一条短信。","Tôi nhận được một tin nhắn.","Wǒ shōudào yì tiáo duǎnxìn."],["这条新闻是真的吗？","Tin này có thật không?","Zhè tiáo xīnwén shì zhēn de ma?"]]}],"items":[{"zh":"视频","py":"shìpín","vi":"video","hv":"thị tần","note":"视 (nhìn) + 频 (tần số). Gọi video là 视频通话.","ex":"这个视频已经有一百万人看过了。","exPy":"Zhège shìpín yǐjīng yǒu yìbǎi wàn rén kàn guo le.","exVi":"Video này đã có một triệu người xem.","w":"这个 视频 已经 有 一 百 万 人 看 过 了。"},{"zh":"网页","py":"wǎngyè","vi":"trang web","hv":"võng hiệt","note":"网 (mạng) + 页 (trang).","ex":"这个网页打不开。","exPy":"Zhège wǎngyè dǎ bu kāi.","exVi":"Trang web này không mở được.","w":"这个 网页 打 不 开。"},{"zh":"网友","py":"wǎngyǒu","vi":"bạn trên mạng, cư dân mạng","hv":"võng hữu","note":"网 + 友 (bạn).","ex":"很多网友都在讨论这件事。","exPy":"Hěn duō wǎngyǒu dōu zài tǎolùn zhè jiàn shì.","exVi":"Nhiều cư dân mạng đang bàn về việc này.","w":"很 多 网友 都 在 讨论 这 件 事。"},{"zh":"网址","py":"wǎngzhǐ","vi":"địa chỉ trang web","hv":"võng chỉ","note":"网 + 址 (địa chỉ).","ex":"请把网址发给我。","exPy":"Qǐng bǎ wǎngzhǐ fā gěi wǒ.","exVi":"Xin gửi địa chỉ trang web cho tôi.","w":"请 把 网址 发 给 我。"},{"zh":"转发","py":"zhuǎnfā","vi":"chia sẻ, chuyển tiếp","hv":"chuyển phát","note":"Chia sẻ bài viết, chuyển tiếp email.","ex":"别随便转发没有确认的消息。","exPy":"Bié suíbiàn zhuǎnfā méiyǒu quèrèn de xiāoxi.","exVi":"Đừng tuỳ tiện chia sẻ tin chưa được xác nhận.","w":"别 随便 转发 没有 确认 的 消息。"},{"zh":"发送","py":"fāsòng","vi":"gửi (đi)","hv":"phát tống","note":"Trang trọng hơn 发. Nút \"Gửi\" trên ứng dụng thường ghi 发送.","ex":"写好以后点\"发送\"。","exPy":"Xiě hǎo yǐhòu diǎn \"fāsòng\".","exVi":"Viết xong thì bấm \"Gửi\".","w":"写 好 以后 点\" 发送\"。"},{"zh":"回复","py":"huífù","vi":"trả lời (tin nhắn)","hv":"hồi phục","note":"Chú ý: khác \"hồi phục\" (khỏi bệnh) tiếng Việt; 回复 là trả lời tin nhắn, email.","ex":"他还没回复我的邮件。","exPy":"Tā hái méi huífù wǒ de yóujiàn.","exVi":"Anh ấy vẫn chưa trả lời email của tôi.","w":"他 还 没 回复 我 的 邮件。"},{"zh":"回信","py":"huíxìn","vi":"thư trả lời; viết thư trả lời","hv":"hồi tín","note":"回 + 信.","ex":"收到信以后请马上回信。","exPy":"Shōudào xìn yǐhòu qǐng mǎshàng huíxìn.","exVi":"Nhận được thư xin trả lời ngay.","w":"收到 信 以后 请 马上 回信。"},{"zh":"信号","py":"xìnhào","vi":"tín hiệu, sóng","hv":"tín hiệu","note":"Chính là \"tín hiệu\". Mất sóng là 没信号.","ex":"地下室信号不好。","exPy":"Dìxiàshì xìnhào bù hǎo.","exVi":"Dưới tầng hầm sóng yếu.","w":"地下 室 信号 不 好。"},{"zh":"扫码","py":"sǎomǎ","vi":"quét mã","hv":"tảo mã","note":"扫 (quét) + 码 (mã). Quét mã QR để thanh toán, kết bạn.","ex":"扫码就可以付钱。","exPy":"Sǎomǎ jiù kěyǐ fù qián.","exVi":"Quét mã là trả tiền được.","w":"扫码 就 可以 付 钱。"}],"newChars":["频"],"outro":"很好！Xong bài 169."};
G.ROOMS["zh-l170"] = {"id":"zh-l170","lang":"zh","level":4,"no":170,"teacher":"wang","title":"HSK4 · Bài 170 · 线上和线下 Trực tuyến và trực tiếp","intro":["现在很多课都可以线上上。","Bài 170: Nói về trực tuyến, trực tiếp, phát, nghe đài, xem, hình ảnh, chữ viết, máy in và chuyển phát nhanh. Bấm 1 · Học để bắt đầu."],"introPy":"Xiànzài hěn duō kè dōu kěyǐ xiànshàng shàng.","gram":{"t":"…之一: một trong những","b":"最…的 + danh từ + 之一","d":"Cấu trúc trang trọng nói \"một trong những… nhất\".","ex":[["北京是中国最大的城市之一。","Bắc Kinh là một trong những thành phố lớn nhất Trung Quốc.","Běijīng shì Zhōngguó zuì dà de chéngshì zhī yī."],["这是我最喜欢的电影之一。","Đây là một trong những bộ phim tôi thích nhất.","Zhè shì wǒ zuì xǐhuan de diànyǐng zhī yī."]]},"grams":[{"t":"…之一: một trong những","b":"最…的 + danh từ + 之一","d":"Cấu trúc trang trọng nói \"một trong những… nhất\".","ex":[["北京是中国最大的城市之一。","Bắc Kinh là một trong những thành phố lớn nhất Trung Quốc.","Běijīng shì Zhōngguó zuì dà de chéngshì zhī yī."],["这是我最喜欢的电影之一。","Đây là một trong những bộ phim tôi thích nhất.","Zhè shì wǒ zuì xǐhuan de diànyǐng zhī yī."]]},{"t":"正在 + động từ: đang","b":"正在播放 · 正在开会","d":"Nhấn mạnh việc đang diễn ra đúng lúc nói.","ex":[["他正在打电话。","Anh ấy đang gọi điện.","Tā zhèngzài dǎ diànhuà."],["比赛正在直播。","Trận đấu đang được truyền hình trực tiếp.","Bǐsài zhèngzài zhíbō."]]}],"items":[{"zh":"线上","py":"xiànshàng","vi":"trực tuyến","hv":"tuyến thượng","note":"线 (đường dây) + 上. Học online là 线上学习.","ex":"现在很多课都可以线上上。","exPy":"Xiànzài hěn duō kè dōu kěyǐ xiànshàng shàng.","exVi":"Bây giờ nhiều lớp có thể học trực tuyến.","w":"现在 很 多 课 都 可以 线上 上。"},{"zh":"线下","py":"xiànxià","vi":"trực tiếp (ngoài đời)","hv":"tuyến hạ","note":"Đối lập với 线上. Cửa hàng truyền thống là 线下店.","ex":"线上买东西，线下取货。","exPy":"Xiànshàng mǎi dōngxi, xiànxià qǔ huò.","exVi":"Mua hàng trực tuyến, nhận hàng tại cửa hàng.","w":"线上 买 东西， 线下 取 货。"},{"zh":"播放","py":"bōfàng","vi":"phát (video, nhạc)","hv":"bá phóng","note":"播 = \"bá\" trong \"truyền bá\".","ex":"电视台正在播放新闻。","exPy":"Diànshìtái zhèngzài bōfàng xīnwén.","exVi":"Đài truyền hình đang phát tin tức.","w":"电视台 正在 播放 新闻。"},{"zh":"收听","py":"shōutīng","vi":"nghe (đài)","hv":"thu thính","note":"收 (thu) + 听.","ex":"很多司机喜欢收听广播。","exPy":"Hěn duō sījī xǐhuan shōutīng guǎngbō.","exVi":"Nhiều tài xế thích nghe đài.","w":"很 多 司机 喜欢 收听 广播。"},{"zh":"观看","py":"guānkàn","vi":"xem (trang trọng)","hv":"quan khán","note":"观 (quan sát) + 看.","ex":"欢迎大家观看今天的比赛。","exPy":"Huānyíng dàjiā guānkàn jīntiān de bǐsài.","exVi":"Chào mừng mọi người xem trận đấu hôm nay.","w":"欢迎 大家 观看 今天 的 比赛。"},{"zh":"图片","py":"túpiàn","vi":"hình ảnh","hv":"đồ phiến","note":"图 (hình) + 片 (tấm).","ex":"这本书有很多图片，孩子们很喜欢。","exPy":"Zhè běn shū yǒu hěn duō túpiàn, háizimen hěn xǐhuan.","exVi":"Cuốn sách này có nhiều hình, trẻ con rất thích.","w":"这 本 书 有 很 多 图片， 孩子 们 很 喜欢。"},{"zh":"图","py":"tú","vi":"hình, bản đồ, sơ đồ","hv":"đồ","note":"\"Đồ\" trong \"bản đồ\", \"đồ hoạ\".","ex":"请看下面这张图。","exPy":"Qǐng kàn xiàmian zhè zhāng tú.","exVi":"Mời xem hình dưới đây.","w":"请 看 下面 这 张 图。"},{"zh":"文字","py":"wénzì","vi":"chữ viết","hv":"văn tự","note":"Chính là \"văn tự\".","ex":"汉字是世界上最古老的文字之一。","exPy":"Hànzì shì shìjiè shang zuì gǔlǎo de wénzì zhī yī.","exVi":"Chữ Hán là một trong những chữ viết cổ nhất thế giới.","w":"汉字 是 世界 上 最 古老 的 文字 之 一。"},{"zh":"打印机","py":"dǎyìnjī","vi":"máy in","hv":"đả ấn cơ","note":"打印 (in) + 机.","ex":"打印机没有纸了。","exPy":"Dǎyìnjī méiyǒu zhǐ le.","exVi":"Máy in hết giấy rồi.","w":"打印机 没有 纸 了。"},{"zh":"快递","py":"kuàidì","vi":"chuyển phát nhanh","hv":"khoái đệ","note":"快 (nhanh) + 递 (đưa). Người giao hàng là 快递员.","ex":"快递员把东西送到了门口。","exPy":"Kuàidìyuán bǎ dōngxi sòng dào le ménkǒu.","exVi":"Người giao hàng đã mang đồ tới cửa.","w":"快递 员 把 东西 送 到 了 门口。"}],"newChars":["递"],"outro":"很好！Xong bài 170."};
G.ROOMS["zh-l171"] = {"id":"zh-l171","lang":"zh","level":4,"no":171,"teacher":"wang","title":"HSK4 · Bài 171 · 球队 Đội tuyển và thi đấu","intro":["我们的队长特别会鼓励队员。","Bài 171: Nói về đội, thành viên, đội trưởng, đội bóng, cổ động viên, huấn luyện viên, dự thi, giải đấu lớn, bóng chuyền và đánh bại. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒmen de duìzhǎng tèbié huì gǔlì duìyuán.","gram":{"t":"被 + người + động từ: bị","b":"被打败了 · 被他发现了","d":"Câu bị động dùng 被. Người thực hiện hành động đứng sau 被, có thể lược bỏ.","ex":[["我们被对手打败了。","Chúng tôi bị đối thủ đánh bại.","Wǒmen bèi duìshǒu dǎbài le."],["我的手机被偷了。","Điện thoại của tôi bị trộm rồi.","Wǒ de shǒujī bèi tōu le."]]},"grams":[{"t":"被 + người + động từ: bị","b":"被打败了 · 被他发现了","d":"Câu bị động dùng 被. Người thực hiện hành động đứng sau 被, có thể lược bỏ.","ex":[["我们被对手打败了。","Chúng tôi bị đối thủ đánh bại.","Wǒmen bèi duìshǒu dǎbài le."],["我的手机被偷了。","Điện thoại của tôi bị trộm rồi.","Wǒ de shǒujī bèi tōu le."]]},{"t":"支持 + đội / người","b":"支持哪个队 · 支持你","d":"支持 là ủng hộ; dùng cho đội bóng, ý kiến, người.","ex":[["我永远支持你。","Tôi mãi ủng hộ bạn.","Wǒ yǒngyuǎn zhīchí nǐ."],["大家都支持这个计划。","Mọi người đều ủng hộ kế hoạch này.","Dàjiā dōu zhīchí zhège jìhuà."]]}],"items":[{"zh":"队","py":"duì","vi":"đội; hàng","hv":"đội","note":"Chính là \"đội\". Xếp hàng là 排队.","ex":"我们的队长特别会鼓励队员。","exPy":"Wǒmen de duìzhǎng tèbié huì gǔlì duìyuán.","exVi":"Đội trưởng chúng tôi rất biết động viên đồng đội.","w":"我们 的 队长 特别 会 鼓励 队员。"},{"zh":"队员","py":"duìyuán","vi":"thành viên đội","hv":"đội viên","note":"Chính là \"đội viên\".","ex":"好的教练会看到每个队员的优点。","exPy":"Hǎo de jiàoliàn huì kàndào měi ge duìyuán de yōudiǎn.","exVi":"Huấn luyện viên giỏi sẽ thấy điểm mạnh của từng thành viên.","w":"好 的 教练 会 看 到 每 个 队员 的 优点。"},{"zh":"队长","py":"duìzhǎng","vi":"đội trưởng","hv":"đội trưởng","note":"Chính là \"đội trưởng\".","ex":"他是我们的队长。","exPy":"Tā shì wǒmen de duìzhǎng.","exVi":"Anh ấy là đội trưởng của chúng tôi.","w":"他 是 我们 的 队长。"},{"zh":"球队","py":"qiúduì","vi":"đội bóng","hv":"cầu đội","note":"球 + 队.","ex":"你支持哪个球队？","exPy":"Nǐ zhīchí nǎge qiúduì?","exVi":"Bạn ủng hộ đội bóng nào?","w":"你 支持 哪个 球队？"},{"zh":"球迷","py":"qiúmí","vi":"người hâm mộ bóng đá","hv":"cầu mê","note":"迷 = mê. Người mê điện ảnh là 影迷.","ex":"比赛结束，球迷们都很激动。","exPy":"Bǐsài jiéshù, qiúmímen dōu hěn jīdòng.","exVi":"Trận đấu kết thúc, cổ động viên đều rất xúc động.","w":"比赛 结束， 球迷 们 都 很 激动。"},{"zh":"教练","py":"jiàoliàn","vi":"huấn luyện viên","hv":"giáo luyện","note":"教 (dạy) + 练 (luyện).","ex":"教练让我们每天跑步。","exPy":"Jiàoliàn ràng wǒmen měi tiān pǎobù.","exVi":"Huấn luyện viên bắt chúng tôi chạy bộ mỗi ngày.","w":"教练 让 我们 每 天 跑步。"},{"zh":"参赛","py":"cānsài","vi":"tham gia thi đấu","hv":"tham tái","note":"参 (tham) + 赛 (thi đấu).","ex":"这次比赛有二十个队参赛。","exPy":"Zhè cì bǐsài yǒu èrshí ge duì cānsài.","exVi":"Giải lần này có hai mươi đội tham gia.","w":"这 次 比赛 有 二 十 个 队 参赛。"},{"zh":"大赛","py":"dàsài","vi":"giải đấu lớn","hv":"đại tái","note":"大 + 赛.","ex":"他参加了全国大赛。","exPy":"Tā cānjiā le quánguó dàsài.","exVi":"Anh ấy tham gia giải toàn quốc.","w":"他 参加 了 全 国 大赛。"},{"zh":"排球","py":"páiqiú","vi":"bóng chuyền","hv":"bài cầu","note":"排 (hàng) + 球.","ex":"她排球打得很好。","exPy":"Tā páiqiú dǎ de hěn hǎo.","exVi":"Cô ấy chơi bóng chuyền rất giỏi.","w":"她 排球 打 得 很 好。"},{"zh":"打败","py":"dǎbài","vi":"đánh bại","hv":"đả bại","note":"Chính là \"đả bại\".","ex":"输了不要紧，下次再打败他们。","exPy":"Shū le bú yàojǐn, xià cì zài dǎbài tāmen.","exVi":"Thua không sao, lần sau đánh bại họ.","w":"输 了 不要紧， 下 次 再 打败 他们。"}],"newChars":[],"outro":"很好！Xong bài 171."};
G.ROOMS["zh-l172"] = {"id":"zh-l172","lang":"zh","level":4,"no":172,"teacher":"wang","title":"HSK4 · Bài 172 · 加油！ Mục tiêu và thành tích","intro":["有梦想，才有动力。","Bài 172: Nói về đoạt giải, giải thưởng, giành được, đạt được, mục tiêu, ước mơ, cổ vũ, ủng hộ và tích cực. Bấm 1 · Học để bắt đầu."],"introPy":"Yǒu mèngxiǎng, cái yǒu dònglì.","gram":{"t":"达到 / 取得 / 赢得 — kết hợp cố định","b":"达到目标 · 取得成绩 · 赢得比赛 / 尊重","d":"Ba động từ đều là \"đạt được\" nhưng đi với danh từ khác nhau. Học theo cụm.","ex":[["他赢得了比赛。","Anh ấy thắng trận đấu.","Tā yíngdé le bǐsài."],["公司取得了很大的成功。","Công ty đạt được thành công lớn.","Gōngsī qǔdé le hěn dà de chénggōng."]]},"grams":[{"t":"达到 / 取得 / 赢得 — kết hợp cố định","b":"达到目标 · 取得成绩 · 赢得比赛 / 尊重","d":"Ba động từ đều là \"đạt được\" nhưng đi với danh từ khác nhau. Học theo cụm.","ex":[["他赢得了比赛。","Anh ấy thắng trận đấu.","Tā yíngdé le bǐsài."],["公司取得了很大的成功。","Công ty đạt được thành công lớn.","Gōngsī qǔdé le hěn dà de chénggōng."]]},{"t":"一定 + động từ: nhất định","b":"一定能行 · 一定要来","d":"Khẳng định chắc chắn hoặc nhấn mạnh yêu cầu.","ex":[["明天你一定要来。","Mai bạn nhất định phải đến nhé.","Míngtiān nǐ yídìng yào lái."],["只要努力，你一定能成功。","Chỉ cần cố gắng, bạn nhất định thành công.","Zhǐyào nǔlì, nǐ yídìng néng chénggōng."]]}],"items":[{"zh":"获奖","py":"huòjiǎng","vi":"đoạt giải","hv":"hoạch tưởng","note":"获 (giành được, \"hoạch\") + 奖 (giải thưởng).","ex":"我们队获奖了，大家都很高兴。","exPy":"Wǒmen duì huòjiǎng le, dàjiā dōu hěn gāoxìng.","exVi":"Đội chúng tôi đoạt giải, ai cũng rất vui.","w":"我们 队 获奖 了， 大家 都 很 高兴。"},{"zh":"奖","py":"jiǎng","vi":"giải thưởng","hv":"tưởng","note":"\"Tưởng\" trong \"khen tưởng\". Giải nhất là 一等奖.","ex":"她得了一等奖。","exPy":"Tā dé le yī děng jiǎng.","exVi":"Cô ấy đạt giải nhất.","w":"她 得了 一 等 奖。"},{"zh":"赢得","py":"yíngdé","vi":"giành được","hv":"doanh đắc","note":"赢 (thắng) + 得.","ex":"他赢得了大家的尊重。","exPy":"Tā yíngdé le dàjiā de zūnzhòng.","exVi":"Anh ấy giành được sự tôn trọng của mọi người.","w":"他 赢得 了 大家 的 尊重。"},{"zh":"取得","py":"qǔdé","vi":"đạt được, giành được","hv":"thủ đắc","note":"Hay đi với 成绩 (thành tích), 成功.","ex":"他取得了很好的成绩。","exPy":"Tā qǔdé le hěn hǎo de chéngjì.","exVi":"Anh ấy đạt thành tích rất tốt.","w":"他 取得 了 很 好 的 成绩。"},{"zh":"达到","py":"dádào","vi":"đạt tới","hv":"đạt đáo","note":"\"Đạt\" trong \"đạt được\". Hay đi với 目标, 要求.","ex":"我们终于达到了目标。","exPy":"Wǒmen zhōngyú dádào le mùbiāo.","exVi":"Cuối cùng chúng tôi đã đạt mục tiêu.","w":"我们 终于 达到 了 目标。"},{"zh":"目标","py":"mùbiāo","vi":"mục tiêu","hv":"mục tiêu","note":"Chính là \"mục tiêu\".","ex":"目标要大，但是每一步要小。","exPy":"Mùbiāo yào dà, dànshì měi yí bù yào xiǎo.","exVi":"Mục tiêu phải lớn, nhưng mỗi bước phải nhỏ.","w":"目标 要 大， 但是 每 一 步 要 小。"},{"zh":"梦想","py":"mèngxiǎng","vi":"ước mơ","hv":"mộng tưởng","note":"Khác \"mộng tưởng\" (viển vông) tiếng Việt: 梦想 là ước mơ tích cực.","ex":"有梦想，才有动力。","exPy":"Yǒu mèngxiǎng, cái yǒu dònglì.","exVi":"Có ước mơ mới có động lực.","w":"有 梦想， 才 有 动力。"},{"zh":"加油","py":"jiāyóu","vi":"cố lên; đổ xăng","hv":"gia du","note":"Nghĩa đen \"thêm dầu\". Cổ vũ: 加油！","ex":"加油！你一定能行！","exPy":"Jiāyóu! Nǐ yídìng néng xíng!","exVi":"Cố lên! Bạn nhất định làm được!","w":"加油！ 你 一定 能 行！"},{"zh":"支持","py":"zhīchí","vi":"ủng hộ","hv":"chi trì","note":"\"Chi trì\" (chống đỡ) → ủng hộ.","ex":"谢谢你一直支持我。","exPy":"Xièxie nǐ yìzhí zhīchí wǒ.","exVi":"Cảm ơn bạn luôn ủng hộ tôi.","w":"谢谢 你 一直 支持 我。"},{"zh":"积极","py":"jījí","vi":"tích cực","hv":"tích cực","note":"Chính là \"tích cực\".","ex":"积极的态度很重要。","exPy":"Jījí de tàidu hěn zhòngyào.","exVi":"Thái độ tích cực rất quan trọng.","w":"积极 的 态度 很 重要。"}],"newChars":["达","积"],"outro":"很好！Xong bài 172."};
G.ROOMS["zh-l173"] = {"id":"zh-l173","lang":"zh","level":4,"no":173,"teacher":"wang","title":"HSK4 · Bài 173 · 听音乐会 Âm nhạc và sân khấu","intro":["这部电视剧很受欢迎。","Bài 173: Nói về ca sĩ, tiếng hát, biểu diễn, diễn, kịch nói, nhà hát, phim truyền hình, đàn piano, đàn và chơi đàn. Bấm 1 · Học để bắt đầu."],"introPy":"Zhè bù diànshìjù hěn shòu huānyíng.","gram":{"t":"Chơi nhạc cụ: 弹 / 拉 / 吹","b":"弹钢琴 · 拉小提琴 · 吹笛子","d":"Đàn gảy, đánh phím dùng 弹; đàn kéo dùng 拉; nhạc cụ thổi dùng 吹.","ex":[["他会拉小提琴。","Anh ấy biết kéo vĩ cầm.","Tā huì lā xiǎotíqín."],["她弹得很好。","Cô ấy đàn rất hay.","Tā tán de hěn hǎo."]]},"grams":[{"t":"Chơi nhạc cụ: 弹 / 拉 / 吹","b":"弹钢琴 · 拉小提琴 · 吹笛子","d":"Đàn gảy, đánh phím dùng 弹; đàn kéo dùng 拉; nhạc cụ thổi dùng 吹.","ex":[["他会拉小提琴。","Anh ấy biết kéo vĩ cầm.","Tā huì lā xiǎotíqín."],["她弹得很好。","Cô ấy đàn rất hay.","Tā tán de hěn hǎo."]]},{"t":"从 + tuổi / thời gian + 开始: bắt đầu từ","b":"从五岁开始 · 从明天开始","d":"Nói điểm khởi đầu của một việc.","ex":[["我从去年开始学汉语。","Tôi bắt đầu học tiếng Trung từ năm ngoái.","Wǒ cóng qùnián kāishǐ xué Hànyǔ."],["从今天开始，我每天早起。","Từ hôm nay, ngày nào tôi cũng dậy sớm.","Cóng jīntiān kāishǐ, wǒ měi tiān zǎo qǐ."]]}],"items":[{"zh":"歌手","py":"gēshǒu","vi":"ca sĩ","hv":"ca thủ","note":"歌 + 手 (người giỏi một việc). Giống 歌星 (ngôi sao ca nhạc).","ex":"那个歌手演唱了五首歌。","exPy":"Nàge gēshǒu yǎnchàng le wǔ shǒu gē.","exVi":"Ca sĩ đó đã hát năm bài.","w":"那个 歌手 演唱 了 五 首 歌。"},{"zh":"歌声","py":"gēshēng","vi":"tiếng hát","hv":"ca thanh","note":"歌 + 声 (tiếng).","ex":"剧院里传来美丽的歌声。","exPy":"Jùyuàn lǐ chuán lái měilì de gēshēng.","exVi":"Từ nhà hát vọng ra tiếng hát tuyệt đẹp.","w":"剧院 里 传 来 美丽 的 歌声。"},{"zh":"演唱","py":"yǎnchàng","vi":"biểu diễn (hát)","hv":"diễn xướng","note":"Buổi hoà nhạc là 演唱会.","ex":"明天晚上她要在北京演唱。","exPy":"Míngtiān wǎnshang tā yào zài Běijīng yǎnchàng.","exVi":"Tối mai cô ấy sẽ biểu diễn ở Bắc Kinh.","w":"明天 晚上 她 要 在 北京 演唱。"},{"zh":"演","py":"yǎn","vi":"diễn, đóng (vai)","hv":"diễn","note":"\"Diễn\" trong \"diễn viên\".","ex":"他在电影里演一个老师。","exPy":"Tā zài diànyǐng lǐ yǎn yí ge lǎoshī.","exVi":"Trong phim anh ấy đóng vai một thầy giáo.","w":"他 在 电影 里 演 一 个 老师。"},{"zh":"话剧","py":"huàjù","vi":"kịch nói","hv":"thoại kịch","note":"话 (lời nói) + 剧 (kịch).","ex":"我们去看话剧吧。","exPy":"Wǒmen qù kàn huàjù ba.","exVi":"Mình đi xem kịch nói nhé.","w":"我们 去 看 话剧 吧。"},{"zh":"剧院","py":"jùyuàn","vi":"nhà hát","hv":"kịch viện","note":"剧 + 院.","ex":"剧院门口有很多人。","exPy":"Jùyuàn ménkǒu yǒu hěn duō rén.","exVi":"Trước cửa nhà hát có nhiều người.","w":"剧院 门口 有 很 多 人。"},{"zh":"电视剧","py":"diànshìjù","vi":"phim truyền hình","hv":"điện thị kịch","note":"电视 + 剧.","ex":"这部电视剧很受欢迎。","exPy":"Zhè bù diànshìjù hěn shòu huānyíng.","exVi":"Bộ phim truyền hình này rất được yêu thích.","w":"这 部 电视剧 很 受 欢迎。"},{"zh":"钢琴","py":"gāngqín","vi":"đàn piano","hv":"cương cầm","note":"Chính là \"dương cầm\" (cương cầm).","ex":"我小时候学过钢琴，现在忘了。","exPy":"Wǒ xiǎoshíhou xué guo gāngqín, xiànzài wàng le.","exVi":"Hồi nhỏ tôi học piano, giờ quên rồi.","w":"我 小时候 学 过 钢琴， 现在 忘 了。"},{"zh":"琴","py":"qín","vi":"đàn","hv":"cầm","note":"\"Cầm\" trong \"cầm kỳ thi hoạ\".","ex":"他每天练两个小时琴。","exPy":"Tā měi tiān liàn liǎng ge xiǎoshí qín.","exVi":"Mỗi ngày anh ấy luyện đàn hai tiếng.","w":"他 每 天 练 两 个 小时 琴。"},{"zh":"弹","py":"tán","vi":"chơi (đàn)","hv":"đàn","note":"Đàn bằng ngón tay dùng 弹: 弹钢琴, 弹吉他.","ex":"你会弹钢琴吗？","exPy":"Nǐ huì tán gāngqín ma?","exVi":"Bạn biết chơi piano không?","w":"你 会 弹钢琴 吗？"}],"newChars":[],"outro":"很好！Xong bài 173."};
G.ROOMS["zh-l174"] = {"id":"zh-l174","lang":"zh","level":4,"no":174,"teacher":"wang","title":"HSK4 · Bài 174 · 今天零下五度 Nhiệt độ","intro":["今天的气温比昨天低。","Bài 174: Nói về nhiệt độ không khí, nóng gay gắt, lạnh giá, âm độ, độ C, hạ nhiệt, giá lạnh, mát, thổi và thân nhiệt. Bấm 1 · Học để bắt đầu."],"introPy":"Jīntiān de qìwēn bǐ zuótiān dī.","gram":{"t":"Đọc nhiệt độ","b":"三十五度 · 零下五度 · 三十七度五","d":"Số + 度. Âm độ thêm 零下 phía trước. Số lẻ đặt sau 度: 37,5 độ là 三十七度五.","ex":[["我发烧了，三十八度。","Tôi sốt rồi, ba mươi tám độ.","Wǒ fāshāo le, sānshíbā dù."],["哈尔滨冬天零下二十多度。","Mùa đông Cáp Nhĩ Tân âm hơn hai mươi độ.","Hā'ěrbīn dōngtiān líng xià èrshí duō dù."]]},"grams":[{"t":"Đọc nhiệt độ","b":"三十五度 · 零下五度 · 三十七度五","d":"Số + 度. Âm độ thêm 零下 phía trước. Số lẻ đặt sau 度: 37,5 độ là 三十七度五.","ex":[["我发烧了，三十八度。","Tôi sốt rồi, ba mươi tám độ.","Wǒ fāshāo le, sānshíbā dù."],["哈尔滨冬天零下二十多度。","Mùa đông Cáp Nhĩ Tân âm hơn hai mươi độ.","Hā'ěrbīn dōngtiān líng xià èrshí duō dù."]]},{"t":"要…了: sắp","b":"要降温了 · 要下雨了","d":"Báo hiệu điều sắp xảy ra, giống 快要…了.","ex":[["天要黑了，我们回去吧。","Trời sắp tối rồi, mình về thôi.","Tiān yào hēi le, wǒmen huíqu ba."],["飞机要起飞了。","Máy bay sắp cất cánh.","Fēijī yào qǐfēi le."]]}],"items":[{"zh":"气温","py":"qìwēn","vi":"nhiệt độ không khí","hv":"khí ôn","note":"气 (khí) + 温 (ấm, nhiệt).","ex":"今天的气温比昨天低。","exPy":"Jīntiān de qìwēn bǐ zuótiān dī.","exVi":"Nhiệt độ hôm nay thấp hơn hôm qua.","w":"今天 的 气温 比 昨天 低。"},{"zh":"高温","py":"gāowēn","vi":"nhiệt độ cao, nắng nóng","hv":"cao ôn","note":"高 + 温.","ex":"高温天气不要在外面待太久。","exPy":"Gāowēn tiānqì búyào zài wàimian dāi tài jiǔ.","exVi":"Trời nắng nóng đừng ở ngoài quá lâu.","w":"高温 天气 不要 在 外面 待 太 久。"},{"zh":"低温","py":"dīwēn","vi":"nhiệt độ thấp","hv":"đê ôn","note":"低 + 温.","ex":"这种药要低温保存。","exPy":"Zhè zhǒng yào yào dīwēn bǎocún.","exVi":"Thuốc này phải bảo quản ở nhiệt độ thấp.","w":"这 种 药 要 低温 保存。"},{"zh":"零下","py":"líng xià","vi":"dưới không độ, âm","hv":"linh hạ","note":"零 (không) + 下 (dưới).","ex":"北京冬天常常零下十度。","exPy":"Běijīng dōngtiān chángcháng líng xià shí dù.","exVi":"Mùa đông Bắc Kinh hay âm mười độ.","w":"北京 冬天 常常 零下 十 度。"},{"zh":"摄氏度","py":"shèshìdù","vi":"độ C","hv":"nhiếp thị độ","note":"Phiên âm tên nhà khoa học Celsius. Nói tắt là 度.","ex":"今天最高气温三十五摄氏度。","exPy":"Jīntiān zuì gāo qìwēn sānshíwǔ shèshìdù.","exVi":"Hôm nay nhiệt độ cao nhất 35 độ C.","w":"今天 最 高 气温 三 十 五 摄氏度。"},{"zh":"降温","py":"jiàngwēn","vi":"hạ nhiệt, trời trở lạnh","hv":"giáng ôn","note":"降 (hạ) + 温.","ex":"明天要降温了，多穿点儿衣服。","exPy":"Míngtiān yào jiàngwēn le, duō chuān diǎnr yīfu.","exVi":"Mai trời trở lạnh, mặc thêm áo vào.","w":"明天 要 降温 了， 多 穿 点 儿 衣服。"},{"zh":"寒冷","py":"hánlěng","vi":"giá lạnh","hv":"hàn lãnh","note":"寒 = \"hàn\" trong \"hàn đới\".","ex":"寒冷的冬天快过去了。","exPy":"Hánlěng de dōngtiān kuài guòqu le.","exVi":"Mùa đông giá lạnh sắp qua rồi.","w":"寒冷 的 冬天 快 过去 了。"},{"zh":"凉","py":"liáng","vi":"mát, nguội","hv":"lương","note":"\"Lương\" trong \"thanh lương\" (mát mẻ). 凉快 là mát mẻ.","ex":"晚上很凉快，我们出去走走。","exPy":"Wǎnshang hěn liángkuai, wǒmen chūqu zǒuzou.","exVi":"Buổi tối mát mẻ, mình ra ngoài đi dạo.","w":"晚上 很 凉快， 我们 出去 走 走。"},{"zh":"吹","py":"chuī","vi":"thổi","hv":"xuy","note":"Có bộ 口. Gió thổi, thổi nến: 吹蜡烛.","ex":"海风吹在脸上很舒服。","exPy":"Hǎifēng chuī zài liǎn shang hěn shūfu.","exVi":"Gió biển thổi vào mặt rất dễ chịu.","w":"海 风 吹 在 脸 上 很 舒服。"},{"zh":"体温","py":"tǐwēn","vi":"thân nhiệt","hv":"thể ôn","note":"体 (cơ thể) + 温.","ex":"正常体温是三十七度左右。","exPy":"Zhèngcháng tǐwēn shì sānshíqī dù zuǒyòu.","exVi":"Thân nhiệt bình thường khoảng 37 độ.","w":"正常 体温 是 三 十 七 度 左右。"}],"newChars":["摄","氏","吹"],"outro":"很好！Xong bài 174."};
G.ROOMS["zh-l175"] = {"id":"zh-l175","lang":"zh","level":4,"no":175,"teacher":"wang","title":"HSK4 · Bài 175 · 去健身房 Khám sức khoẻ và tập luyện","intro":["体检以后，医生说我很健康。","Bài 175: Nói về khám sức khoẻ, cân nặng, đau đầu, đau, ho, bị thương, máu, tập thể hình, phòng gym và toàn thân. Bấm 1 · Học để bắt đầu."],"introPy":"Tǐjiǎn yǐhòu, yīshēng shuō wǒ hěn jiànkāng.","gram":{"t":"让 + người + tính từ: khiến ai","b":"让我很头痛 · 让他很高兴","d":"Sự việc làm ai đó có cảm giác thế nào.","ex":[["你的话让我很感动。","Lời bạn nói làm tôi rất cảm động.","Nǐ de huà ràng wǒ hěn gǎndòng."],["这次考试让他很紧张。","Kỳ thi này làm cậu ấy rất căng thẳng.","Zhè cì kǎoshì ràng tā hěn jǐnzhāng."]]},"grams":[{"t":"让 + người + tính từ: khiến ai","b":"让我很头痛 · 让他很高兴","d":"Sự việc làm ai đó có cảm giác thế nào.","ex":[["你的话让我很感动。","Lời bạn nói làm tôi rất cảm động.","Nǐ de huà ràng wǒ hěn gǎndòng."],["这次考试让他很紧张。","Kỳ thi này làm cậu ấy rất căng thẳng.","Zhè cì kǎoshì ràng tā hěn jǐnzhāng."]]},{"t":"Tần suất: 每 + thời gian + số lần","b":"每周三次 · 每天两次 · 每年一次","d":"Số lần đứng sau khoảng thời gian.","ex":[["这种药每天吃三次。","Thuốc này mỗi ngày uống ba lần.","Zhè zhǒng yào měi tiān chī sān cì."],["我每个月去一次健身房。","Mỗi tháng tôi đi gym một lần.","Wǒ měi ge yuè qù yí cì jiànshēnfáng."]]}],"items":[{"zh":"体检","py":"tǐjiǎn","vi":"khám sức khoẻ","hv":"thể kiểm","note":"Viết tắt của 身体检查.","ex":"体检以后，医生说我很健康。","exPy":"Tǐjiǎn yǐhòu, yīshēng shuō wǒ hěn jiànkāng.","exVi":"Khám sức khoẻ xong, bác sĩ nói tôi rất khoẻ.","w":"体检 以后， 医生 说 我 很 健康。"},{"zh":"体重","py":"tǐzhòng","vi":"cân nặng","hv":"thể trọng","note":"Chính là \"thể trọng\".","ex":"我的体重增加了三公斤。","exPy":"Wǒ de tǐzhòng zēngjiā le sān gōngjīn.","exVi":"Cân nặng của tôi tăng ba ký.","w":"我 的 体重 增加 了 三 公斤。"},{"zh":"头痛","py":"tóutòng","vi":"đau đầu","hv":"đầu thống","note":"Giống 头疼. Còn nghĩa bóng: đau đầu vì một chuyện.","ex":"这个问题让我很头痛。","exPy":"Zhège wèntí ràng wǒ hěn tóutòng.","exVi":"Vấn đề này làm tôi rất đau đầu.","w":"这个 问题 让 我 很 头痛。"},{"zh":"痛","py":"tòng","vi":"đau","hv":"thống","note":"\"Thống\" trong \"thống khổ\". Gần nghĩa 疼.","ex":"我的腿很痛。","exPy":"Wǒ de tuǐ hěn tòng.","exVi":"Chân tôi rất đau.","w":"我 的 腿 很 痛。"},{"zh":"咳","py":"ké","vi":"ho","hv":"khái","note":"Ho là 咳嗽.","ex":"他咳得很厉害，应该去医院。","exPy":"Tā ké de hěn lìhai, yīnggāi qù yīyuàn.","exVi":"Anh ấy ho dữ quá, nên đi bệnh viện.","w":"他 咳 得 很 厉害， 应该 去 医院。"},{"zh":"受伤","py":"shòushāng","vi":"bị thương","hv":"thụ thương","note":"Chính là \"thụ thương\".","ex":"运动的时候要小心，别受伤。","exPy":"Yùndòng de shíhou yào xiǎoxīn, bié shòushāng.","exVi":"Lúc tập thể thao phải cẩn thận, đừng để bị thương.","w":"运动 的 时候 要 小心， 别 受伤。"},{"zh":"血","py":"xiě","vi":"máu","hv":"huyết","note":"\"Huyết\" trong \"huyết áp\". Khẩu ngữ đọc xiě, văn viết đọc xuè.","ex":"他的手流血了。","exPy":"Tā de shǒu liú xiě le.","exVi":"Tay anh ấy chảy máu rồi.","w":"他 的 手 流血 了。"},{"zh":"健身","py":"jiànshēn","vi":"tập thể hình, rèn luyện","hv":"kiện thân","note":"健 (khoẻ) + 身 (thân).","ex":"健身不光为了好看，更为了健康。","exPy":"Jiànshēn bùguāng wèile hǎokàn, gèng wèile jiànkāng.","exVi":"Tập thể hình không chỉ để đẹp, mà còn để khoẻ.","w":"健身 不光 为了 好看， 更 为了 健康。"},{"zh":"健身房","py":"jiànshēnfáng","vi":"phòng tập gym","hv":"kiện thân phòng","note":"健身 + 房.","ex":"小区里有一个健身房。","exPy":"Xiǎoqū lǐ yǒu yí ge jiànshēnfáng.","exVi":"Trong khu nhà có một phòng gym.","w":"小区 里 有 一 个 健身房。"},{"zh":"全身","py":"quánshēn","vi":"toàn thân","hv":"toàn thân","note":"Chính là \"toàn thân\".","ex":"跑完步，我全身都是汗。","exPy":"Pǎo wán bù, wǒ quánshēn dōu shì hàn.","exVi":"Chạy bộ xong, tôi ướt đẫm mồ hôi toàn thân.","w":"跑 完 步， 我 全身 都 是 汗。"}],"newChars":["痛","血"],"outro":"很好！Xong bài 175."};
G.ROOMS["zh-l176"] = {"id":"zh-l176","lang":"zh","level":4,"no":176,"teacher":"wang","title":"HSK4 · Bài 176 · 大自然 Thiên nhiên và làng quê","intro":["城市里很少能看到星星。","Bài 176: Nói về thiên nhiên, thực vật, rừng cây, hoa tươi, sao, sông lớn, gấu, đất, làng và nông thôn. Bấm 1 · Học để bắt đầu."],"introPy":"Chéngshì lǐ hěn shǎo néng kàndào xīngxing.","gram":{"t":"Lượng từ cho thiên nhiên","b":"一片树林 · 一束鲜花 · 一颗星星 · 一条江","d":"片 cho vùng rộng, 束 cho bó, 颗 cho vật nhỏ tròn.","ex":[["天上有一颗很亮的星星。","Trên trời có một ngôi sao rất sáng.","Tiān shang yǒu yì kē hěn liàng de xīngxing."],["山下有一片树林。","Dưới núi có một khu rừng.","Shān xià yǒu yí piàn shùlín."]]},"grams":[{"t":"Lượng từ cho thiên nhiên","b":"一片树林 · 一束鲜花 · 一颗星星 · 一条江","d":"片 cho vùng rộng, 束 cho bó, 颗 cho vật nhỏ tròn.","ex":[["天上有一颗很亮的星星。","Trên trời có một ngôi sao rất sáng.","Tiān shang yǒu yì kē hěn liàng de xīngxing."],["山下有一片树林。","Dưới núi có một khu rừng.","Shān xià yǒu yí piàn shùlín."]]},{"t":"通向 / 通到: dẫn tới","b":"Đường + 通向 / 通到 + nơi","d":"通 là thông, dẫn tới.","ex":[["这条路通到火车站。","Con đường này dẫn tới ga tàu.","Zhè tiáo lù tōng dào huǒchēzhàn."],["这扇门通向花园。","Cánh cửa này dẫn ra vườn.","Zhè shàn mén tōng xiàng huāyuán."]]}],"items":[{"zh":"大自然","py":"dàzìrán","vi":"thiên nhiên","hv":"đại tự nhiên","note":"大 + 自然 (tự nhiên).","ex":"大自然是最好的老师。","exPy":"Dàzìrán shì zuì hǎo de lǎoshī.","exVi":"Thiên nhiên là người thầy tốt nhất.","w":"大自然 是 最好 的 老师。"},{"zh":"植物","py":"zhíwù","vi":"thực vật, cây cỏ","hv":"thực vật","note":"Chính là \"thực vật\" tiếng Việt. Đừng nhầm với 食物 (đồ ăn).","ex":"这种植物不需要很多水。","exPy":"Zhè zhǒng zhíwù bù xūyào hěn duō shuǐ.","exVi":"Loại cây này không cần nhiều nước.","w":"这 种植 物 不 需要 很 多 水。"},{"zh":"树林","py":"shùlín","vi":"rừng cây","hv":"thụ lâm","note":"树 (cây) + 林 (rừng, \"lâm\").","ex":"小路通向一片树林。","exPy":"Xiǎo lù tōng xiàng yí piàn shùlín.","exVi":"Con đường nhỏ dẫn tới một khu rừng.","w":"小 路 通 向 一 片 树林。"},{"zh":"鲜花","py":"xiānhuā","vi":"hoa tươi","hv":"tiên hoa","note":"鲜 (tươi) + 花.","ex":"他送了我一束鲜花。","exPy":"Tā sòng le wǒ yí shù xiānhuā.","exVi":"Anh ấy tặng tôi một bó hoa tươi.","w":"他 送 了 我 一 束 鲜花。"},{"zh":"星星","py":"xīngxing","vi":"ngôi sao","hv":"tinh tinh","note":"星 = \"tinh\" trong \"hành tinh\".","ex":"城市里很少能看到星星。","exPy":"Chéngshì lǐ hěn shǎo néng kàndào xīngxing.","exVi":"Ở thành phố hiếm khi nhìn thấy sao.","w":"城市 里 很 少 能 看 到 星星。"},{"zh":"江","py":"jiāng","vi":"sông lớn","hv":"giang","note":"\"Giang\" trong \"giang sơn\". Sông Trường Giang là 长江.","ex":"长江是中国最长的河。","exPy":"Chángjiāng shì Zhōngguó zuì cháng de hé.","exVi":"Trường Giang là con sông dài nhất Trung Quốc.","w":"长江 是 中国 最 长 的 河。"},{"zh":"熊","py":"xióng","vi":"con gấu","hv":"hùng","note":"Gấu trúc 熊猫 có chữ này.","ex":"动物园里有一只大熊。","exPy":"Dòngwùyuán lǐ yǒu yì zhī dà xióng.","exVi":"Trong sở thú có một con gấu lớn.","w":"动物园 里 有 一 只 大 熊。"},{"zh":"土","py":"tǔ","vi":"đất","hv":"thổ","note":"\"Thổ\" trong \"thổ địa\", \"lãnh thổ\".","ex":"植物需要土和水。","exPy":"Zhíwù xūyào tǔ hé shuǐ.","exVi":"Cây cần đất và nước.","w":"植物 需要 土 和 水。"},{"zh":"村","py":"cūn","vi":"làng","hv":"thôn","note":"Chính là \"thôn\" (làng).","ex":"我喜欢周末去农村走走。","exPy":"Wǒ xǐhuan zhōumò qù nóngcūn zǒuzou.","exVi":"Tôi thích cuối tuần về nông thôn đi dạo.","w":"我 喜欢 周末 去 农村 走 走。"},{"zh":"农村","py":"nóngcūn","vi":"nông thôn","hv":"nông thôn","note":"Chính là \"nông thôn\".","ex":"现在农村的生活越来越好了。","exPy":"Xiànzài nóngcūn de shēnghuó yuèláiyuè hǎo le.","exVi":"Bây giờ cuộc sống ở nông thôn ngày càng tốt.","w":"现在 农村 的 生活 越 来 越 好 了。"}],"newChars":["植","土","村","农"],"outro":"很好！Xong bài 176."};
G.ROOMS["zh-l177"] = {"id":"zh-l177","lang":"zh","level":4,"no":177,"teacher":"wang","title":"HSK4 · Bài 177 · 我的家乡 Quê hương và vùng miền","intro":["我的家乡有很多好吃的东西。","Bài 177: Nói về quê hương, quê nhà, thành, nội thành, chợ, khu vực, các nơi, và miền đông, tây, nam. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ de jiāxiāng yǒu hěn duō hǎochī de dōngxi.","gram":{"t":"在 + nơi + 长大: lớn lên ở","b":"在农村长大 · 在城里长大","d":"长大 (zhǎngdà) là lớn lên.","ex":[["我在河内长大。","Tôi lớn lên ở Hà Nội.","Wǒ zài Hénèi zhǎngdà."],["你是在哪儿长大的？","Bạn lớn lên ở đâu?","Nǐ shì zài nǎr zhǎngdà de?"]]},"grams":[{"t":"在 + nơi + 长大: lớn lên ở","b":"在农村长大 · 在城里长大","d":"长大 (zhǎngdà) là lớn lên.","ex":[["我在河内长大。","Tôi lớn lên ở Hà Nội.","Wǒ zài Hénèi zhǎngdà."],["你是在哪儿长大的？","Bạn lớn lên ở đâu?","Nǐ shì zài nǎr zhǎngdà de?"]]},{"t":"各 + danh từ / lượng từ: các, mỗi","b":"各地 · 各国 · 各位 · 各种","d":"各 nhấn mạnh từng thành phần trong một tập hợp.","ex":[["各国的代表都来了。","Đại biểu các nước đều đến.","Gè guó de dàibiǎo dōu lái le."],["各位，请安静。","Thưa quý vị, xin giữ trật tự.","Gèwèi, qǐng ānjìng."]]}],"items":[{"zh":"家乡","py":"jiāxiāng","vi":"quê hương","hv":"gia hương","note":"Chính là \"gia hương\".","ex":"我的家乡有很多好吃的东西。","exPy":"Wǒ de jiāxiāng yǒu hěn duō hǎochī de dōngxi.","exVi":"Quê tôi có nhiều món ngon.","w":"我 的 家乡 有 很 多 好吃 的 东西。"},{"zh":"老家","py":"lǎojiā","vi":"quê nhà, quê gốc","hv":"lão gia","note":"Khác \"lão gia\" (ông chủ) trong phim: 老家 là quê gốc.","ex":"每年春节我都回老家看父母。","exPy":"Měi nián Chūnjié wǒ dōu huí lǎojiā kàn fùmǔ.","exVi":"Tết năm nào tôi cũng về quê thăm bố mẹ.","w":"每 年 春 节 我 都 回 老家 看 父母。"},{"zh":"城","py":"chéng","vi":"thành, thành phố","hv":"thành","note":"\"Thành\" trong \"thành phố\". Vạn Lý Trường Thành là 长城.","ex":"他从小在城里长大。","exPy":"Tā cóngxiǎo zài chéng lǐ zhǎngdà.","exVi":"Anh ấy lớn lên ở thành phố từ nhỏ.","w":"他 从小 在 城 里 长 大。"},{"zh":"市区","py":"shìqū","vi":"nội thành","hv":"thị khu","note":"市 + 区.","ex":"市区的房子比郊区贵。","exPy":"Shìqū de fángzi bǐ jiāoqū guì.","exVi":"Nhà trong nội thành đắt hơn ngoại ô.","w":"市区 的 房子 比 郊区 贵。"},{"zh":"市场","py":"shìchǎng","vi":"chợ; thị trường","hv":"thị trường","note":"Chính là \"thị trường\", cũng là chợ.","ex":"早上的市场非常热闹。","exPy":"Zǎoshang de shìchǎng fēicháng rènao.","exVi":"Chợ buổi sáng rất náo nhiệt.","w":"早上 的 市场 非常 热闹。"},{"zh":"区","py":"qū","vi":"khu, quận","hv":"khu","note":"\"Khu\" trong \"khu vực\". Quận ở thành phố cũng là 区.","ex":"他住在海淀区。","exPy":"Tā zhù zài Hǎidiàn Qū.","exVi":"Anh ấy sống ở quận Hải Điến.","w":"他 住 在 海 淀 区。"},{"zh":"各地","py":"gèdì","vi":"các nơi","hv":"các địa","note":"各 (các) + 地.","ex":"世界各地的游客都来这里。","exPy":"Shìjiè gèdì de yóukè dōu lái zhèlǐ.","exVi":"Du khách khắp nơi trên thế giới đều đến đây.","w":"世界 各地 的 游客 都 来 这里。"},{"zh":"东部","py":"dōngbù","vi":"miền đông","hv":"đông bộ","note":"东 + 部 (phần). Chú ý: 北部 là miền Bắc.","ex":"中国东部经济很发达。","exPy":"Zhōngguó dōngbù jīngjì hěn fādá.","exVi":"Kinh tế miền đông Trung Quốc rất phát triển.","w":"中国 东部 经济 很 发达。"},{"zh":"西部","py":"xībù","vi":"miền tây","hv":"tây bộ","note":"西 + 部.","ex":"西部有很多高山。","exPy":"Xībù yǒu hěn duō gāo shān.","exVi":"Miền tây có nhiều núi cao.","w":"西部 有 很 多 高 山。"},{"zh":"南部","py":"nánbù","vi":"miền nam","hv":"nam bộ","note":"Chính là \"Nam Bộ\".","ex":"越南南部的天气很热。","exPy":"Yuènán nánbù de tiānqì hěn rè.","exVi":"Thời tiết miền Nam Việt Nam rất nóng.","w":"越 南 南部 的 天气 很 热。"}],"newChars":["乡"],"outro":"很好！Xong bài 177."};
G.ROOMS["zh-l178"] = {"id":"zh-l178","lang":"zh","level":4,"no":178,"teacher":"wang","title":"HSK4 · Bài 178 · 保护环境 Môi trường và vệ sinh","intro":["垃圾要分类。","Bài 178: Nói về bảo vệ môi trường, rác, nhựa, túi, thùng, khăn giấy, vệ sinh, nhà vệ sinh, khói và hút. Bấm 1 · Học để bắt đầu."],"introPy":"Lājī yào fēnlèi.","gram":{"t":"把 + vật + 扔进 / 放进 + nơi","b":"把垃圾扔进垃圾桶","d":"Động từ + 进 chỉ hướng đi vào bên trong.","ex":[["把衣服放进洗衣机。","Bỏ quần áo vào máy giặt.","Bǎ yīfu fàng jìn xǐyījī."],["他把书放进了书包。","Cậu ấy cho sách vào cặp.","Tā bǎ shū fàng jìn le shūbāo."]]},"grams":[{"t":"把 + vật + 扔进 / 放进 + nơi","b":"把垃圾扔进垃圾桶","d":"Động từ + 进 chỉ hướng đi vào bên trong.","ex":[["把衣服放进洗衣机。","Bỏ quần áo vào máy giặt.","Bǎ yīfu fàng jìn xǐyījī."],["他把书放进了书包。","Cậu ấy cho sách vào cặp.","Tā bǎ shū fàng jìn le shūbāo."]]},{"t":"不能 + động từ: không được phép","b":"不能吸烟 · 不能停车","d":"Dùng trên biển cấm và lời nhắc nhở.","ex":[["上课不能玩手机。","Trong giờ học không được chơi điện thoại.","Shàngkè bù néng wán shǒujī."],["这里不能拍照。","Ở đây không được chụp ảnh.","Zhèlǐ bù néng pāizhào."]]}],"items":[{"zh":"环保","py":"huánbǎo","vi":"bảo vệ môi trường","hv":"hoàn bảo","note":"Viết tắt của 环境保护. Cũng là tính từ: 环保袋 (túi thân thiện môi trường).","ex":"我们要有环保意识。","exPy":"Wǒmen yào yǒu huánbǎo yìshi.","exVi":"Chúng ta phải có ý thức bảo vệ môi trường.","w":"我们 要 有 环保 意识。"},{"zh":"垃圾","py":"lājī","vi":"rác","hv":"lạp cấp","note":"Thùng rác là 垃圾桶.","ex":"垃圾要分类。","exPy":"Lājī yào fēnlèi.","exVi":"Rác phải phân loại.","w":"垃圾 要 分类。"},{"zh":"塑料","py":"sùliào","vi":"nhựa","hv":"tố liệu","note":"Túi nhựa là 塑料袋.","ex":"少用塑料袋。","exPy":"Shǎo yòng sùliàodài.","exVi":"Dùng ít túi nhựa thôi.","w":"少 用 塑料袋。"},{"zh":"袋子","py":"dàizi","vi":"cái túi","hv":"đại tử","note":"袋 = túi. Làm lượng từ: 一袋米.","ex":"去超市买东西，我带自己的袋子。","exPy":"Qù chāoshì mǎi dōngxi, wǒ dài zìjǐ de dàizi.","exVi":"Đi siêu thị mua đồ, tôi mang túi riêng.","w":"去 超市 买 东西， 我 带 自己 的 袋子。"},{"zh":"桶","py":"tǒng","vi":"cái thùng, xô","hv":"dũng","note":"Thùng rác 垃圾桶, xô nước 水桶.","ex":"门口有一个大桶。","exPy":"Ménkǒu yǒu yí ge dà tǒng.","exVi":"Trước cửa có một cái thùng lớn.","w":"门口 有 一 个 大 桶。"},{"zh":"纸巾","py":"zhǐjīn","vi":"khăn giấy","hv":"chỉ cân","note":"纸 + 巾 (khăn).","ex":"你有纸巾吗？","exPy":"Nǐ yǒu zhǐjīn ma?","exVi":"Bạn có khăn giấy không?","w":"你 有 纸巾 吗？"},{"zh":"卫生","py":"wèishēng","vi":"vệ sinh, sạch sẽ","hv":"vệ sinh","note":"Chính là \"vệ sinh\".","ex":"饭前要洗手，注意卫生。","exPy":"Fàn qián yào xǐ shǒu, zhùyì wèishēng.","exVi":"Trước bữa ăn phải rửa tay, giữ vệ sinh.","w":"饭 前 要 洗 手， 注意 卫生。"},{"zh":"厕所","py":"cèsuǒ","vi":"nhà vệ sinh","hv":"xí sở","note":"Từ thông thường; lịch sự hơn là 洗手间, 卫生间.","ex":"请问厕所在哪儿？","exPy":"Qǐngwèn cèsuǒ zài nǎr?","exVi":"Cho hỏi nhà vệ sinh ở đâu?","w":"请问 厕所 在 哪儿？"},{"zh":"烟","py":"yān","vi":"khói; thuốc lá","hv":"yên","note":"\"Yên\" trong \"yên vụ\" (khói sương). Hút thuốc là 抽烟 / 吸烟.","ex":"吸烟对身体不好。","exPy":"Xīyān duì shēntǐ bù hǎo.","exVi":"Hút thuốc không tốt cho sức khoẻ.","w":"吸 烟 对 身体 不 好。"},{"zh":"吸","py":"xī","vi":"hút, hít","hv":"hấp","note":"\"Hấp\" trong \"hô hấp\", \"hấp thụ\".","ex":"深吸一口气。","exPy":"Shēn xī yì kǒu qì.","exVi":"Hít một hơi thật sâu.","w":"深 吸 一口气。"}],"newChars":["厕"],"outro":"很好！Xong bài 178."};
G.ROOMS["zh-l179"] = {"id":"zh-l179","lang":"zh","level":4,"no":179,"teacher":"wang","title":"HSK4 · Bài 179 · 租房子 Thuê nhà và sửa nhà","intro":["我想租一套离公司近的房子。","Bài 179: Nói về tiền thuê nhà, cho thuê, sân, cửa sổ, gương, treo, sáng, lắp, sửa và đến tận nhà. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xiǎng zū yí tào lí gōngsī jìn de fángzi.","gram":{"t":"Nơi + động từ + 着 + vật: tả sự tồn tại","b":"墙上挂着画 · 桌子上放着书","d":"Câu tồn tại: nơi chốn đứng đầu, động từ + 着, rồi đến vật.","ex":[["门口站着一个人。","Trước cửa có một người đứng.","Ménkǒu zhàn zhe yí ge rén."],["桌子上放着一杯水。","Trên bàn có một cốc nước.","Zhuōzi shang fàng zhe yì bēi shuǐ."]]},"grams":[{"t":"Nơi + động từ + 着 + vật: tả sự tồn tại","b":"墙上挂着画 · 桌子上放着书","d":"Câu tồn tại: nơi chốn đứng đầu, động từ + 着, rồi đến vật.","ex":[["门口站着一个人。","Trước cửa có một người đứng.","Ménkǒu zhàn zhe yí ge rén."],["桌子上放着一杯水。","Trên bàn có một cốc nước.","Zhuōzi shang fàng zhe yì bēi shuǐ."]]},{"t":"Lượng từ 套 cho căn hộ, bộ","b":"一套房子 · 一套衣服 · 一套书","d":"套 dùng cho thứ đi thành bộ hoàn chỉnh.","ex":[["他们买了一套新房子。","Họ mua một căn nhà mới.","Tāmen mǎi le yí tào xīn fángzi."],["我买了一套茶具。","Tôi mua một bộ ấm chén.","Wǒ mǎi le yí tào chájù."]]}],"items":[{"zh":"房租","py":"fángzū","vi":"tiền thuê nhà","hv":"phòng tô","note":"房 + 租 (thuê).","ex":"房租每个月三千块。","exPy":"Fángzū měi ge yuè sānqiān kuài.","exVi":"Tiền thuê nhà mỗi tháng ba nghìn tệ.","w":"房租 每 个 月 三 千 块。"},{"zh":"出租","py":"chūzū","vi":"cho thuê","hv":"xuất tô","note":"Taxi là 出租车 (xe cho thuê).","ex":"这套房子出租。","exPy":"Zhè tào fángzi chūzū.","exVi":"Căn nhà này cho thuê.","w":"这 套 房子 出租。"},{"zh":"院子","py":"yuànzi","vi":"sân","hv":"viện tử","note":"院 = sân, viện.","ex":"院子里种了很多花。","exPy":"Yuànzi lǐ zhòng le hěn duō huā.","exVi":"Trong sân trồng nhiều hoa.","w":"院子 里 种 了 很 多 花。"},{"zh":"窗","py":"chuāng","vi":"cửa sổ","hv":"song","note":"Hay dùng 窗户 hoặc 窗子.","ex":"打开窗，让空气进来。","exPy":"Dǎkāi chuāng, ràng kōngqì jìnlai.","exVi":"Mở cửa sổ cho không khí vào.","w":"打开 窗， 让 空气 进来。"},{"zh":"镜子","py":"jìngzi","vi":"cái gương","hv":"kính tử","note":"镜 = \"kính\" (gương, kính). Kính mắt là 眼镜.","ex":"她站在镜子前面。","exPy":"Tā zhàn zài jìngzi qiánmian.","exVi":"Cô ấy đứng trước gương.","w":"她 站 在 镜子 前面。"},{"zh":"挂","py":"guà","vi":"treo","hv":"quải","note":"Treo tranh, treo áo. Cúp máy điện thoại cũng là 挂.","ex":"墙上挂着一张地图。","exPy":"Qiáng shang guà zhe yì zhāng dìtú.","exVi":"Trên tường treo một tấm bản đồ.","w":"墙 上 挂 着 一 张 地图。"},{"zh":"亮","py":"liàng","vi":"sáng","hv":"lượng","note":"\"Lượng\" trong \"minh lượng\". Đèn sáng: 灯亮了.","ex":"灯坏了，房间一点儿也不亮。","exPy":"Dēng huài le, fángjiān yìdiǎnr yě bú liàng.","exVi":"Đèn hỏng rồi, phòng chẳng sáng chút nào.","w":"灯 坏 了， 房间 一点儿 也 不 亮。"},{"zh":"装","py":"zhuāng","vi":"lắp; đựng; giả vờ","hv":"trang","note":"\"Trang\" trong \"trang bị\". 装空调 (lắp điều hoà), 装傻 (giả ngốc).","ex":"我们家装了新空调。","exPy":"Wǒmen jiā zhuāng le xīn kōngtiáo.","exVi":"Nhà chúng tôi lắp điều hoà mới.","w":"我们 家 装 了 新 空调。"},{"zh":"修","py":"xiū","vi":"sửa","hv":"tu","note":"\"Tu\" trong \"tu sửa\". Sửa xe là 修车.","ex":"你能帮我修一下电脑吗？","exPy":"Nǐ néng bāng wǒ xiū yíxià diànnǎo ma?","exVi":"Bạn sửa giúp tôi máy tính được không?","w":"你 能 帮 我 修 一下 电脑 吗？"},{"zh":"上门","py":"shàngmén","vi":"đến tận nhà","hv":"thượng môn","note":"Dịch vụ tận nhà: 上门服务.","ex":"现在很多服务都可以上门。","exPy":"Xiànzài hěn duō fúwù dōu kěyǐ shàngmén.","exVi":"Bây giờ nhiều dịch vụ có thể đến tận nhà.","w":"现在 很 多 服务 都 可以 上门。"}],"newChars":["挂","装"],"outro":"很好！Xong bài 179."};
G.ROOMS["zh-l180"] = {"id":"zh-l180","lang":"zh","level":4,"no":180,"teacher":"wang","title":"HSK4 · Bài 180 · 发红包 Tiền bạc và buôn bán","intro":["上大学的费用越来越高。","Bài 180: Nói về phí, chi phí, thu phí, tiền lẻ, tiền tiêu vặt, lì xì, việc buôn bán, hàng hoá, gam và ký. Bấm 1 · Học để bắt đầu."],"introPy":"Shàng dàxué de fèiyong yuèláiyuè gāo.","gram":{"t":"一共: tổng cộng","b":"一共 + số lượng","d":"Đứng trước con số tổng.","ex":[["一共多少钱？","Tổng cộng bao nhiêu tiền?","Yígòng duōshao qián?"],["我们班一共有三十个学生。","Lớp chúng tôi tổng cộng ba mươi học sinh.","Wǒmen bān yígòng yǒu sānshí ge xuésheng."]]},"grams":[{"t":"一共: tổng cộng","b":"一共 + số lượng","d":"Đứng trước con số tổng.","ex":[["一共多少钱？","Tổng cộng bao nhiêu tiền?","Yígòng duōshao qián?"],["我们班一共有三十个学生。","Lớp chúng tôi tổng cộng ba mươi học sinh.","Wǒmen bān yígòng yǒu sānshí ge xuésheng."]]},{"t":"Đơn vị đo lường","b":"克 · 千克 / 公斤 · 斤 · 米 · 公里","d":"1 公斤 = 2 斤 = 1000 克. Ở chợ Trung Quốc người ta hay tính bằng 斤.","ex":[["我体重六十公斤。","Tôi nặng sáu mươi ký.","Wǒ tǐzhòng liùshí gōngjīn."],["一公斤等于两斤。","Một ký bằng hai cân.","Yì gōngjīn děngyú liǎng jīn."]]}],"items":[{"zh":"费","py":"fèi","vi":"phí, tiền","hv":"phí","note":"Chính là \"phí\". Ghép: 学费, 电费, 水费.","ex":"上大学的费用越来越高。","exPy":"Shàng dàxué de fèiyong yuèláiyuè gāo.","exVi":"Chi phí học đại học ngày càng cao.","w":"上 大学 的 费用 越 来 越 高。"},{"zh":"费用","py":"fèiyong","vi":"chi phí","hv":"phí dụng","note":"Chính là \"phí dụng\".","ex":"旅行的费用一共五千块。","exPy":"Lǚxíng de fèiyong yígòng wǔqiān kuài.","exVi":"Chi phí chuyến đi tổng cộng năm nghìn tệ.","w":"旅行 的 费用 一共 五 千 块。"},{"zh":"收费","py":"shōufèi","vi":"thu phí","hv":"thu phí","note":"Chính là \"thu phí\".","ex":"这个停车场收费吗？","exPy":"Zhège tíngchēchǎng shōufèi ma?","exVi":"Bãi đỗ xe này có thu phí không?","w":"这个 停车场 收费 吗？"},{"zh":"零钱","py":"língqián","vi":"tiền lẻ","hv":"linh tiền","note":"零 (lẻ) + 钱.","ex":"你有零钱吗？","exPy":"Nǐ yǒu língqián ma?","exVi":"Bạn có tiền lẻ không?","w":"你 有 零钱 吗？"},{"zh":"零花钱","py":"línghuāqián","vi":"tiền tiêu vặt","hv":"linh hoa tiền","note":"零 + 花 (tiêu) + 钱.","ex":"妈妈每周给我一百块零花钱。","exPy":"Māma měi zhōu gěi wǒ yìbǎi kuài línghuāqián.","exVi":"Mẹ mỗi tuần cho tôi một trăm tệ tiêu vặt.","w":"妈妈 每 周 给 我 一 百 块 零花钱。"},{"zh":"红包","py":"hóngbāo","vi":"bao lì xì","hv":"hồng bao","note":"Phong bao đỏ đựng tiền. Ngày nay có cả lì xì qua điện thoại.","ex":"现在很多人用手机发红包。","exPy":"Xiànzài hěn duō rén yòng shǒujī fā hóngbāo.","exVi":"Bây giờ nhiều người lì xì qua điện thoại.","w":"现在 很 多 人 用 手机 发 红包。"},{"zh":"生意","py":"shēngyi","vi":"việc buôn bán, làm ăn","hv":"sinh ý","note":"Làm ăn là 做生意.","ex":"他的生意做得很大。","exPy":"Tā de shēngyi zuò de hěn dà.","exVi":"Anh ấy làm ăn rất lớn.","w":"他 的 生意 做 得 很 大。"},{"zh":"货","py":"huò","vi":"hàng hoá","hv":"hoá","note":"\"Hoá\" trong \"hàng hoá\". Giao hàng là 送货.","ex":"这批货明天到。","exPy":"Zhè pī huò míngtiān dào.","exVi":"Lô hàng này mai đến.","w":"这 批 货 明天 到。"},{"zh":"克","py":"kè","vi":"gam","hv":"khắc","note":"Phiên âm từ \"gram\". 一百克 = 100 gam.","ex":"坐飞机行李不能超过二十千克。","exPy":"Zuò fēijī xíngli bù néng chāoguò èrshí qiānkè.","exVi":"Đi máy bay hành lý không được quá hai mươi ký.","w":"坐 飞机 行李 不 能 超过 二 十 千克。"},{"zh":"千克","py":"qiānkè","vi":"ki-lô-gam","hv":"thiên khắc","note":"千 (nghìn) + 克. Khẩu ngữ hay nói 公斤.","ex":"这个箱子二十千克。","exPy":"Zhège xiāngzi èrshí qiānkè.","exVi":"Cái vali này hai mươi ký.","w":"这个 箱子 二 十 千克。"}],"newChars":[],"outro":"很好！Xong bài 180."};
G.ROOMS["zh-l181"] = {"id":"zh-l181","lang":"zh","level":4,"no":181,"teacher":"wang","title":"HSK4 · Bài 181 · 年底 Ngày tháng và thời điểm","intro":["合同上的日期写错了。","Bài 181: Nói về ngày tháng, ngày sống, tháng, cuối năm, cuối (kỳ), ngày lễ, ngày nghỉ, đêm, ban đêm và sáng sớm. Bấm 1 · Học để bắt đầu."],"introPy":"Hétong shang de rìqī xiě cuò le.","gram":{"t":"Thứ tự ngày tháng: lớn trước, nhỏ sau","b":"年 → 月 → 日 → 星期","d":"Tiếng Trung viết năm trước, rồi tháng, ngày, ngược với tiếng Việt.","ex":[["今天是二零二六年十一月三日。","Hôm nay là ngày 3 tháng 11 năm 2026.","Jīntiān shì èr líng èr liù nián shíyī yuè sān rì."],["我的生日是五月二十号。","Sinh nhật tôi là ngày 20 tháng 5.","Wǒ de shēngrì shì wǔ yuè èrshí hào."]]},"grams":[{"t":"Thứ tự ngày tháng: lớn trước, nhỏ sau","b":"年 → 月 → 日 → 星期","d":"Tiếng Trung viết năm trước, rồi tháng, ngày, ngược với tiếng Việt.","ex":[["今天是二零二六年十一月三日。","Hôm nay là ngày 3 tháng 11 năm 2026.","Jīntiān shì èr líng èr liù nián shíyī yuè sān rì."],["我的生日是五月二十号。","Sinh nhật tôi là ngày 20 tháng 5.","Wǒ de shēngrì shì wǔ yuè èrshí hào."]]},{"t":"过日子: sống, sinh hoạt","b":"过 + 日子 / 生活 / 年 / 节","d":"过 nghĩa \"trải qua\": 过年, 过节, 过日子.","ex":[["他们一家人过着简单的日子。","Cả nhà họ sống một cuộc sống giản dị.","Tāmen yì jiā rén guò zhe jiǎndān de rìzi."],["你们怎么过周末？","Các bạn trải qua cuối tuần thế nào?","Nǐmen zěnme guò zhōumò?"]]}],"items":[{"zh":"日期","py":"rìqī","vi":"ngày tháng","hv":"nhật kỳ","note":"Ngày cụ thể trên lịch, trên giấy tờ.","ex":"合同上的日期写错了。","exPy":"Hétong shang de rìqī xiě cuò le.","exVi":"Ngày tháng trên hợp đồng viết sai rồi.","w":"合同 上 的 日期 写 错 了。"},{"zh":"日子","py":"rìzi","vi":"ngày; cuộc sống","hv":"nhật tử","note":"Ngày đặc biệt, hoặc cuộc sống: 过日子.","ex":"今天是个好日子。","exPy":"Jīntiān shì ge hǎo rìzi.","exVi":"Hôm nay là một ngày đẹp.","w":"今天 是 个 好 日子。"},{"zh":"月份","py":"yuèfèn","vi":"tháng","hv":"nguyệt phần","note":"Dùng khi nói về tháng nói chung: 哪个月份.","ex":"几月份去旅行最好？","exPy":"Jǐ yuèfèn qù lǚxíng zuì hǎo?","exVi":"Tháng mấy đi du lịch là tốt nhất?","w":"几 月份 去 旅行 最好？"},{"zh":"年底","py":"niándǐ","vi":"cuối năm","hv":"niên để","note":"年 + 底 (đáy, cuối).","ex":"年底我要回国。","exPy":"Niándǐ wǒ yào huí guó.","exVi":"Cuối năm tôi sẽ về nước.","w":"年底 我 要 回 国。"},{"zh":"末","py":"mò","vi":"cuối","hv":"mạt","note":"\"Mạt\" trong \"mạt vận\". Ghép: 周末, 月末, 期末.","ex":"我们月末见面吧。","exPy":"Wǒmen yuèmò jiànmiàn ba.","exVi":"Cuối tháng mình gặp nhau nhé.","w":"我们 月 末 见面 吧。"},{"zh":"节假日","py":"jiéjiàrì","vi":"ngày lễ, ngày nghỉ","hv":"tiết giả nhật","note":"节日 (lễ) + 假日 (ngày nghỉ).","ex":"节假日最好不要开车出门。","exPy":"Jiéjiàrì zuì hǎo búyào kāichē chūmén.","exVi":"Ngày lễ tốt nhất đừng lái xe ra ngoài.","w":"节假日 最好 不要 开车 出门。"},{"zh":"假日","py":"jiàrì","vi":"ngày nghỉ","hv":"giả nhật","note":"假 + 日.","ex":"假日我喜欢在家看书。","exPy":"Jiàrì wǒ xǐhuan zài jiā kàn shū.","exVi":"Ngày nghỉ tôi thích ở nhà đọc sách.","w":"假日 我 喜欢 在 家 看 书。"},{"zh":"夜","py":"yè","vi":"đêm","hv":"dạ","note":"\"Dạ\" trong \"dạ hội\". Làm lượng từ: 住一夜 (ở một đêm).","ex":"我们在那儿住了一夜。","exPy":"Wǒmen zài nàr zhù le yí yè.","exVi":"Chúng tôi ở đó một đêm.","w":"我们 在 那儿 住 了 一 夜。"},{"zh":"夜晚","py":"yèwǎn","vi":"ban đêm","hv":"dạ vãn","note":"Văn chương hơn 晚上.","ex":"夏天的夜晚很美。","exPy":"Xiàtiān de yèwǎn hěn měi.","exVi":"Đêm mùa hè rất đẹp.","w":"夏天 的 夜晚 很 美。"},{"zh":"早晨","py":"zǎochen","vi":"sáng sớm","hv":"tảo thần","note":"晨 = \"thần\" (buổi sớm). Giống 早上.","ex":"早晨六点，公园里已经有很多人了。","exPy":"Zǎochen liù diǎn, gōngyuán lǐ yǐjīng yǒu hěn duō rén le.","exVi":"Sáu giờ sáng, công viên đã có nhiều người.","w":"早晨 六 点， 公园 里 已经 有 很 多 人 了。"}],"newChars":["夜","晨"],"outro":"很好！Xong bài 181."};
G.ROOMS["zh-l182"] = {"id":"zh-l182","lang":"zh","level":4,"no":182,"teacher":"wang","title":"HSK4 · Bài 182 · 之前和之后 Trước, sau và trong khoảng","intro":["春节前后火车票很难买。","Bài 182: Dùng 之前 / 之后 / 之间 / 之中 / 之, 前后, 今后, 目前, 将 / 将要 để nói thời gian và quan hệ. Bấm 1 · Học để bắt đầu."],"introPy":"Chūnjié qiánhòu huǒchēpiào hěn nán mǎi.","gram":{"t":"之前 / 之后 và 以前 / 以后","b":"việc + 之前 / 之后","d":"Nghĩa gần như nhau, 之 trang trọng hơn. Đứng một mình đầu câu thường dùng 以前, 以后.","ex":[["吃饭以前要洗手。","Trước khi ăn phải rửa tay.","Chīfàn yǐqián yào xǐ shǒu."],["下课之后我去找你。","Tan học tôi đi tìm bạn.","Xiàkè zhīhòu wǒ qù zhǎo nǐ."]]},"grams":[{"t":"之前 / 之后 và 以前 / 以后","b":"việc + 之前 / 之后","d":"Nghĩa gần như nhau, 之 trang trọng hơn. Đứng một mình đầu câu thường dùng 以前, 以后.","ex":[["吃饭以前要洗手。","Trước khi ăn phải rửa tay.","Chīfàn yǐqián yào xǐ shǒu."],["下课之后我去找你。","Tan học tôi đi tìm bạn.","Xiàkè zhīhòu wǒ qù zhǎo nǐ."]]},{"t":"A 和 B 之间","b":"北京和上海之间 · 朋友之间","d":"Diễn tả khoảng giữa hai điểm hoặc quan hệ giữa các bên.","ex":[["北京和天津之间只要半个小时。","Giữa Bắc Kinh và Thiên Tân chỉ mất nửa tiếng.","Běijīng hé Tiānjīn zhījiān zhǐ yào bàn ge xiǎoshí."],["朋友之间要互相帮助。","Bạn bè phải giúp đỡ lẫn nhau.","Péngyou zhījiān yào hùxiāng bāngzhù."]]}],"items":[{"zh":"之前","py":"zhīqián","vi":"trước, trước khi","hv":"chi tiền","note":"Trang trọng hơn 以前. Sau một việc: 吃饭之前.","ex":"睡觉之前不要喝咖啡。","exPy":"Shuìjiào zhīqián búyào hē kāfēi.","exVi":"Trước khi ngủ đừng uống cà phê.","w":"睡觉 之前 不要 喝 咖啡。"},{"zh":"之后","py":"zhīhòu","vi":"sau, sau khi","hv":"chi hậu","note":"Trang trọng hơn 以后.","ex":"毕业之后他去了上海。","exPy":"Bìyè zhīhòu tā qù le Shànghǎi.","exVi":"Sau khi tốt nghiệp anh ấy đi Thượng Hải.","w":"毕业 之后 他 去 了 上 海。"},{"zh":"之间","py":"zhījiān","vi":"giữa (hai bên)","hv":"chi gian","note":"A 和 B 之间: giữa A và B.","ex":"我们之间没有秘密。","exPy":"Wǒmen zhījiān méiyǒu mìmì.","exVi":"Giữa chúng ta không có bí mật.","w":"我们 之间 没有 秘密。"},{"zh":"之中","py":"zhīzhōng","vi":"trong số, trong khi","hv":"chi trung","note":"Trang trọng hơn 中.","ex":"在这些学生之中，他最努力。","exPy":"Zài zhèxiē xuésheng zhīzhōng, tā zuì nǔlì.","exVi":"Trong số học sinh này, cậu ấy chăm nhất.","w":"在 这些 学生 之中， 他 最 努力。"},{"zh":"之","py":"zhī","vi":"của (văn viết)","hv":"chi","note":"Giống 的 nhưng dùng trong văn viết, thành ngữ: 之一, 百分之十.","ex":"百分之八十的人同意这个计划。","exPy":"Bǎi fēn zhī bāshí de rén tóngyì zhège jìhuà.","exVi":"Tám mươi phần trăm người đồng ý kế hoạch này.","w":"百分之 八 十 的 人 同意 这个 计划。"},{"zh":"前后","py":"qiánhòu","vi":"khoảng, trước sau","hv":"tiền hậu","note":"Mốc thời gian + 前后: khoảng lúc đó.","ex":"春节前后火车票很难买。","exPy":"Chūnjié qiánhòu huǒchēpiào hěn nán mǎi.","exVi":"Quanh dịp Tết vé tàu rất khó mua.","w":"春 节 前后 火车 票 很 难 买。"},{"zh":"今后","py":"jīnhòu","vi":"từ nay về sau","hv":"kim hậu","note":"今 (nay) + 后.","ex":"今后我会更加努力。","exPy":"Jīnhòu wǒ huì gèngjiā nǔlì.","exVi":"Từ nay về sau tôi sẽ cố gắng hơn.","w":"今后 我 会 更加 努力。"},{"zh":"目前","py":"mùqián","vi":"hiện nay, trước mắt","hv":"mục tiền","note":"Trang trọng, hay gặp trong tin tức.","ex":"目前我还在找工作。","exPy":"Mùqián wǒ hái zài zhǎo gōngzuò.","exVi":"Hiện tôi vẫn đang tìm việc.","w":"目前 我 还 在 找 工作。"},{"zh":"将","py":"jiāng","vi":"sẽ (văn viết)","hv":"tương","note":"Văn viết của 会 / 要. Hay gặp trong thông báo.","ex":"比赛将在明天举行。","exPy":"Bǐsài jiāng zài míngtiān jǔxíng.","exVi":"Trận đấu sẽ diễn ra vào ngày mai.","w":"比赛 将 在 明天 举行。"},{"zh":"将要","py":"jiāngyào","vi":"sắp sẽ","hv":"tương yếu","note":"Văn viết của 快要.","ex":"新学期将要开始了。","exPy":"Xīn xuéqī jiāngyào kāishǐ le.","exVi":"Học kỳ mới sắp bắt đầu.","w":"新 学期 将要 开始 了。"}],"newChars":[],"outro":"很好！Xong bài 182."};
G.ROOMS["zh-l183"] = {"id":"zh-l183","lang":"zh","level":4,"no":183,"teacher":"wang","title":"HSK4 · Bài 183 · 难忘的友情 Cảm xúc và tình cảm","intro":["我们的友情已经十年了。","Bài 183: Nói về cảm động, cảm nhận, nội tâm, khó quên, tốt đẹp, tình bạn, lòng nhân ái, phiền, bất mãn và buồn cười. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒmen de yǒuqíng yǐjīng shí nián le.","gram":{"t":"感人 và 感动","b":"感人 = khiến người khác cảm động (tả sự việc) · 感动 = bị cảm động (tả người)","d":"这个电影很感人 / 我很感动.","ex":[["他的话让我很感动。","Lời anh ấy làm tôi rất cảm động.","Tā de huà ràng wǒ hěn gǎndòng."],["这首歌很感人。","Bài hát này rất cảm động.","Zhè shǒu gē hěn gǎnrén."]]},"grams":[{"t":"感人 và 感动","b":"感人 = khiến người khác cảm động (tả sự việc) · 感动 = bị cảm động (tả người)","d":"这个电影很感人 / 我很感动.","ex":[["他的话让我很感动。","Lời anh ấy làm tôi rất cảm động.","Tā de huà ràng wǒ hěn gǎndòng."],["这首歌很感人。","Bài hát này rất cảm động.","Zhè shǒu gē hěn gǎnrén."]]},{"t":"祝 + người + lời chúc","b":"祝你生日快乐 · 祝你一路平安","d":"Câu chúc mở đầu bằng 祝.","ex":[["祝你考试顺利！","Chúc bạn thi tốt!","Zhù nǐ kǎoshì shùnlì!"],["祝大家新年快乐！","Chúc mọi người năm mới vui vẻ!","Zhù dàjiā xīnnián kuàilè!"]]}],"items":[{"zh":"感人","py":"gǎnrén","vi":"cảm động","hv":"cảm nhân","note":"Khiến người ta xúc động. Chính mình xúc động là 感动.","ex":"这是一个很感人的故事。","exPy":"Zhè shì yí ge hěn gǎnrén de gùshi.","exVi":"Đây là một câu chuyện rất cảm động.","w":"这 是 一 个 很 感人 的 故事。"},{"zh":"感受","py":"gǎnshòu","vi":"cảm nhận","hv":"cảm thụ","note":"Chính là \"cảm thụ\".","ex":"说说你的感受吧。","exPy":"Shuōshuo nǐ de gǎnshòu ba.","exVi":"Nói cảm nhận của bạn đi.","w":"说 说 你 的 感受 吧。"},{"zh":"内心","py":"nèixīn","vi":"nội tâm, trong lòng","hv":"nội tâm","note":"Chính là \"nội tâm\".","ex":"他的内心很孤独。","exPy":"Tā de nèixīn hěn gūdú.","exVi":"Trong lòng anh ấy rất cô đơn.","w":"他 的 内心 很 孤独。"},{"zh":"难忘","py":"nánwàng","vi":"khó quên","hv":"nan vong","note":"难 (khó) + 忘 (quên).","ex":"这件事让我很难忘。","exPy":"Zhè jiàn shì ràng wǒ hěn nánwàng.","exVi":"Chuyện này làm tôi khó quên.","w":"这 件 事 让 我 很 难忘。"},{"zh":"美好","py":"měihǎo","vi":"tốt đẹp","hv":"mỹ hảo","note":"Chính là \"mỹ hảo\".","ex":"大学生活是我一生中最美好的时光。","exPy":"Dàxué shēnghuó shì wǒ yìshēng zhōng zuì měihǎo de shíguāng.","exVi":"Đời sinh viên là quãng thời gian đẹp nhất đời tôi.","w":"大学生 活 是 我 一生 中 最 美好 的 时光。"},{"zh":"友情","py":"yǒuqíng","vi":"tình bạn","hv":"hữu tình","note":"Khác \"hữu tình\" (đẹp, nên thơ) tiếng Việt: 友情 là tình bạn.","ex":"我们的友情已经十年了。","exPy":"Wǒmen de yǒuqíng yǐjīng shí nián le.","exVi":"Tình bạn của chúng tôi đã mười năm.","w":"我们 的 友情 已经 十 年 了。"},{"zh":"爱心","py":"àixīn","vi":"lòng nhân ái","hv":"ái tâm","note":"爱 + 心 (lòng).","ex":"她是一个很有爱心的人。","exPy":"Tā shì yí ge hěn yǒu àixīn de rén.","exVi":"Cô ấy là người rất có lòng nhân ái.","w":"她 是 一 个 很 有 爱心 的 人。"},{"zh":"烦","py":"fán","vi":"phiền, bực","hv":"phiền","note":"\"Phiền\" trong \"phiền phức\". 烦死了 (bực chết đi được).","ex":"别烦我，我在学习。","exPy":"Bié fán wǒ, wǒ zài xuéxí.","exVi":"Đừng làm phiền tôi, tôi đang học.","w":"别 烦 我， 我 在 学习。"},{"zh":"不满","py":"bùmǎn","vi":"bất mãn, không hài lòng","hv":"bất mãn","note":"Chính là \"bất mãn\".","ex":"每天加班，他心里很不满。","exPy":"Měi tiān jiābān, tā xīnlǐ hěn bùmǎn.","exVi":"Ngày nào cũng tăng ca, trong lòng anh ấy rất bất mãn.","w":"每 天 加班， 他 心里 很 不满。"},{"zh":"好笑","py":"hǎoxiào","vi":"buồn cười","hv":"hảo tiếu","note":"好 + 笑 (cười).","ex":"这个笑话太好笑了。","exPy":"Zhège xiàohua tài hǎoxiào le.","exVi":"Câu chuyện cười này buồn cười quá.","w":"这个 笑话 太 好笑 了。"}],"newChars":[],"outro":"很好！Xong bài 183."};
G.ROOMS["zh-l184"] = {"id":"zh-l184","lang":"zh","level":4,"no":184,"teacher":"wang","title":"HSK4 · Bài 184 · 抬头看 Động tác cơ thể","intro":["听到有人喊他，他马上抬头。","Bài 184: Nói về ngẩng đầu, gật đầu, hét, đeo trên lưng, ba lô, đè, ngửi, đo, rơi và chảy. Bấm 1 · Học để bắt đầu."],"introPy":"Tīngdào yǒu rén hǎn tā, tā mǎshàng táitóu.","gram":{"t":"Động từ lặp lại: làm thử, làm một chút","b":"看看 · 闻闻 · 点了点头","d":"Lặp động từ cho nhẹ nhàng; việc đã xong thì chèn 了 vào giữa.","ex":[["你尝尝这个菜。","Bạn nếm thử món này.","Nǐ chángchang zhège cài."],["他想了想，说\"好\"。","Anh ấy nghĩ một lúc rồi nói \"được\".","Tā xiǎng le xiǎng, shuō \"hǎo\"."]]},"grams":[{"t":"Động từ lặp lại: làm thử, làm một chút","b":"看看 · 闻闻 · 点了点头","d":"Lặp động từ cho nhẹ nhàng; việc đã xong thì chèn 了 vào giữa.","ex":[["你尝尝这个菜。","Bạn nếm thử món này.","Nǐ chángchang zhège cài."],["他想了想，说\"好\"。","Anh ấy nghĩ một lúc rồi nói \"được\".","Tā xiǎng le xiǎng, shuō \"hǎo\"."]]},{"t":"Một chữ, hai cách đọc","b":"背 bēi (đeo) / bèi (lưng, học thuộc) · 量 liáng (đo) / liàng (lượng)","d":"Nhiều chữ đổi nghĩa theo thanh điệu, phải học theo từ.","ex":[["我在背生词。","Tôi đang học thuộc từ mới.","Wǒ zài bèi shēngcí."],["工作量太大了。","Khối lượng công việc lớn quá.","Gōngzuòliàng tài dà le."]]}],"items":[{"zh":"抬头","py":"táitóu","vi":"ngẩng đầu","hv":"đài đầu","note":"抬 (nâng) + 头. Cúi đầu là 低头.","ex":"听到有人喊他，他马上抬头。","exPy":"Tīngdào yǒu rén hǎn tā, tā mǎshàng táitóu.","exVi":"Nghe có người gọi, anh ấy lập tức ngẩng đầu.","w":"听 到 有 人 喊 他， 他 马上 抬头。"},{"zh":"点头","py":"diǎntóu","vi":"gật đầu","hv":"điểm đầu","note":"Lắc đầu là 摇头.","ex":"他同意了，点了点头。","exPy":"Tā tóngyì le, diǎn le diǎn tóu.","exVi":"Anh ấy đồng ý, gật gật đầu.","w":"他 同意 了， 点 了 点头。"},{"zh":"喊","py":"hǎn","vi":"hét, gọi to","hv":"hảm","note":"Có bộ 口. Gọi to tên ai: 喊他的名字.","ex":"有人在外面喊你。","exPy":"Yǒu rén zài wàimian hǎn nǐ.","exVi":"Có người đang gọi bạn ngoài kia.","w":"有 人 在 外面 喊 你。"},{"zh":"背","py":"bēi","vi":"đeo (trên lưng), cõng","hv":"bối","note":"Đọc bēi khi là đeo, cõng; đọc bèi khi là lưng hoặc học thuộc.","ex":"学生们背着书包去学校。","exPy":"Xuéshengmen bēi zhe shūbāo qù xuéxiào.","exVi":"Học sinh đeo cặp đến trường.","w":"学生 们 背 着 书包 去 学校。"},{"zh":"背包","py":"bēibāo","vi":"ba lô","hv":"bối bao","note":"背 + 包.","ex":"我的背包里有水和面包。","exPy":"Wǒ de bēibāo lǐ yǒu shuǐ hé miànbāo.","exVi":"Trong ba lô tôi có nước và bánh mì.","w":"我 的 背包 里 有 水 和 面包。"},{"zh":"压","py":"yā","vi":"đè, ép","hv":"áp","note":"\"Áp\" trong \"áp lực\", \"huyết áp\". Áp lực là 压力.","ex":"别压着我的书。","exPy":"Bié yā zhe wǒ de shū.","exVi":"Đừng đè lên sách của tôi.","w":"别 压 着 我 的 书。"},{"zh":"闻","py":"wén","vi":"ngửi","hv":"văn","note":"Nghĩa gốc \"nghe\" (新闻 tin tức), nay chủ yếu là ngửi.","ex":"你闻闻，这是什么味道？","exPy":"Nǐ wénwen, zhè shì shénme wèidao?","exVi":"Bạn ngửi thử xem, mùi gì đây?","w":"你 闻 闻， 这 是 什么 味道？"},{"zh":"量","py":"liáng","vi":"đo","hv":"lượng","note":"Đo nhiệt độ, chiều cao. Đọc liàng thì là \"lượng\" (số lượng).","ex":"护士给我量了体温。","exPy":"Hùshi gěi wǒ liáng le tǐwēn.","exVi":"Y tá đo thân nhiệt cho tôi.","w":"护士 给 我 量 了 体温。"},{"zh":"落","py":"luò","vi":"rơi, rụng","hv":"lạc","note":"\"Lạc\" trong \"toạ lạc\", \"lưu lạc\", nghĩa gốc là rơi xuống. Lá rụng: 叶子落了.","ex":"秋天树叶都落了。","exPy":"Qiūtiān shùyè dōu luò le.","exVi":"Mùa thu lá cây rụng hết.","w":"秋天 树 叶 都 落 了。"},{"zh":"流","py":"liú","vi":"chảy","hv":"lưu","note":"\"Lưu\" trong \"lưu lượng\", \"giao lưu\".","ex":"她感动得流下了眼泪。","exPy":"Tā gǎndòng de liú xià le yǎnlèi.","exVi":"Cô ấy cảm động đến rơi nước mắt.","w":"她 感动 得 流 下 了 眼泪。"}],"newChars":["喊","背"],"outro":"很好！Xong bài 184."};
G.ROOMS["zh-l185"] = {"id":"zh-l185","lang":"zh","level":4,"no":185,"teacher":"wang","title":"HSK4 · Bài 185 · 忽然下雨了 Phó từ chỉ thời gian và bất ngờ","intro":["他忽然站起来走了。","Bài 185: Dùng các phó từ: đột nhiên, không ngờ, mau, nhanh lên, suýt nữa, đã, vẫn, lại lần nữa, từ đó, cứ mãi. Bấm 1 · Học để bắt đầu."],"introPy":"Tā hūrán zhàn qǐlai zǒu le.","gram":{"t":"差点儿: suýt","b":"差点儿 + động từ + 了","d":"Câu khẳng định với 差点儿 nghĩa là việc đó KHÔNG xảy ra (may quá).","ex":[["我差点儿没赶上火车。","Tôi suýt nữa thì lỡ tàu.","Wǒ chàdiǎnr méi gǎnshàng huǒchē."],["他差点儿摔倒了。","Anh ấy suýt ngã.","Tā chàdiǎnr shuāi dǎo le."]]},"grams":[{"t":"差点儿: suýt","b":"差点儿 + động từ + 了","d":"Câu khẳng định với 差点儿 nghĩa là việc đó KHÔNG xảy ra (may quá).","ex":[["我差点儿没赶上火车。","Tôi suýt nữa thì lỡ tàu.","Wǒ chàdiǎnr méi gǎnshàng huǒchē."],["他差点儿摔倒了。","Anh ấy suýt ngã.","Tā chàdiǎnr shuāi dǎo le."]]},{"t":"竟然: thể hiện bất ngờ","b":"Chủ ngữ + 竟然 + động từ","d":"Đứng trước động từ, người nói không ngờ tới điều đó.","ex":[["这么难的题，他竟然做对了。","Bài khó vậy mà cậu ấy làm đúng.","Zhème nán de tí, tā jìngrán zuò duì le."],["我竟然在这儿遇见了你！","Không ngờ lại gặp bạn ở đây!","Wǒ jìngrán zài zhèr yùjiàn le nǐ!"]]}],"items":[{"zh":"忽然","py":"hūrán","vi":"bỗng nhiên","hv":"hốt nhiên","note":"Chính là \"hốt nhiên\". Gần nghĩa 突然.","ex":"他忽然站起来走了。","exPy":"Tā hūrán zhàn qǐlai zǒu le.","exVi":"Anh ấy bỗng đứng dậy bỏ đi.","w":"他 忽然 站 起来 走 了。"},{"zh":"竟然","py":"jìngrán","vi":"không ngờ, vậy mà","hv":"cánh nhiên","note":"Thể hiện ngạc nhiên vì điều trái dự đoán.","ex":"他竟然忘了我的生日。","exPy":"Tā jìngrán wàng le wǒ de shēngrì.","exVi":"Không ngờ anh ấy quên sinh nhật tôi.","w":"他 竟然 忘 了 我 的 生日。"},{"zh":"赶紧","py":"gǎnjǐn","vi":"vội, mau chóng","hv":"cản khẩn","note":"Làm ngay vì thời gian gấp.","ex":"快下雨了，赶紧回家吧。","exPy":"Kuài xià yǔ le, gǎnjǐn huí jiā ba.","exVi":"Sắp mưa rồi, mau về nhà thôi.","w":"快 下雨 了， 赶紧 回 家 吧。"},{"zh":"赶快","py":"gǎnkuài","vi":"nhanh lên","hv":"cản khoái","note":"Hay dùng trong câu giục.","ex":"天黑了，我们赶快回去吧。","exPy":"Tiān hēi le, wǒmen gǎnkuài huíqu ba.","exVi":"Trời tối rồi, mình về nhanh thôi.","w":"天 黑 了， 我们 赶快 回去 吧。"},{"zh":"差点儿","py":"chàdiǎnr","vi":"suýt nữa","hv":"sai điểm nhi","note":"Việc suýt xảy ra nhưng không xảy ra.","ex":"我差点儿忘了。","exPy":"Wǒ chàdiǎnr wàng le.","exVi":"Tôi suýt nữa thì quên.","w":"我 差点儿 忘 了。"},{"zh":"已","py":"yǐ","vi":"đã","hv":"dĩ","note":"Văn viết của 已经.","ex":"比赛已结束。","exPy":"Bǐsài yǐ jiéshù.","exVi":"Trận đấu đã kết thúc.","w":"比赛 已 结束。"},{"zh":"仍","py":"réng","vi":"vẫn","hv":"nhưng","note":"Văn viết của 仍然, 还.","ex":"时间过去很久了，我仍记得那一天。","exPy":"Shíjiān guòqu hěn jiǔ le, wǒ réng jìde nà yì tiān.","exVi":"Đã lâu lắm rồi, tôi vẫn nhớ ngày hôm đó.","w":"时间 过去 很 久 了， 我 仍 记得 那 一 天。"},{"zh":"再次","py":"zàicì","vi":"lần nữa","hv":"tái thứ","note":"Chính là \"tái thứ\" (lần thứ hai).","ex":"欢迎您再次光临。","exPy":"Huānyíng nín zàicì guānglín.","exVi":"Hân hạnh đón quý khách lần sau.","w":"欢迎 您 再次 光临。"},{"zh":"从此","py":"cóngcǐ","vi":"từ đó","hv":"tòng thử","note":"从 (từ) + 此 (đây, đó).","ex":"从此以后，他再也不抽烟了。","exPy":"Cóngcǐ yǐhòu, tā zài yě bù chōuyān le.","exVi":"Từ đó về sau, anh ấy không hút thuốc nữa.","w":"从此 以后， 他 再 也 不 抽烟 了。"},{"zh":"老是","py":"lǎoshì","vi":"cứ mãi, lúc nào cũng","hv":"lão thị","note":"Khẩu ngữ, mang ý phàn nàn, như 总是.","ex":"你老是玩手机，眼睛会坏的。","exPy":"Nǐ lǎoshì wán shǒujī, yǎnjing huì huài de.","exVi":"Bạn cứ chơi điện thoại mãi, mắt sẽ hỏng đấy.","w":"你 老是 玩 手机， 眼睛 会 坏 的。"}],"newChars":["忽"],"outro":"很好！Xong bài 185."};
G.ROOMS["zh-l186"] = {"id":"zh-l186","lang":"zh","level":4,"no":186,"teacher":"wang","title":"HSK4 · Bài 186 · 一顿饭 Lượng từ thường gặp","intro":["中午我们好好吃一顿吧。","Bài 186: Dùng đúng các lượng từ: bữa, món / đề, bức, bài hát, hạng mục, đoàn tàu, hàng, miếng / vùng, kỳ, bộ. Bấm 1 · Học để bắt đầu."],"introPy":"Zhōngwǔ wǒmen hǎohǎo chī yí dùn ba.","gram":{"t":"Chọn lượng từ theo danh từ","b":"一顿饭 · 一道菜 · 一首歌 · 一幅画 · 一部电影","d":"Mỗi danh từ có lượng từ quen dùng. Học danh từ thì học kèm lượng từ.","ex":[["他写了一首诗。","Anh ấy viết một bài thơ.","Tā xiě le yì shǒu shī."],["我们点了五道菜。","Chúng tôi gọi năm món.","Wǒmen diǎn le wǔ dào cài."]]},"grams":[{"t":"Chọn lượng từ theo danh từ","b":"一顿饭 · 一道菜 · 一首歌 · 一幅画 · 一部电影","d":"Mỗi danh từ có lượng từ quen dùng. Học danh từ thì học kèm lượng từ.","ex":[["他写了一首诗。","Anh ấy viết một bài thơ.","Tā xiě le yì shǒu shī."],["我们点了五道菜。","Chúng tôi gọi năm món.","Wǒmen diǎn le wǔ dào cài."]]},{"t":"遍 và 次: số lần","b":"看了三遍 (từ đầu đến cuối) · 去了三次 (số lần)","d":"遍 nhấn mạnh làm trọn vẹn từ đầu đến cuối, 次 chỉ đếm số lần.","ex":[["请再说一遍。","Xin nói lại một lần nữa.","Qǐng zài shuō yí biàn."],["我去过北京两次。","Tôi đã đến Bắc Kinh hai lần.","Wǒ qù guo Běijīng liǎng cì."]]}],"items":[{"zh":"顿","py":"dùn","vi":"bữa, trận (lượng từ)","hv":"đốn","note":"Đếm bữa ăn: 一顿饭. Cũng dùng cho trận mắng: 骂了一顿.","ex":"中午我们好好吃一顿吧。","exPy":"Zhōngwǔ wǒmen hǎohǎo chī yí dùn ba.","exVi":"Trưa nay mình ăn một bữa thật ngon nhé.","w":"中午 我们 好好 吃 一 顿 吧。"},{"zh":"道","py":"dào","vi":"món ăn; câu (đề); đường (lượng từ)","hv":"đạo","note":"Đếm món ăn, câu hỏi bài thi: 一道菜, 一道题.","ex":"考试一共有五十道题。","exPy":"Kǎoshì yígòng yǒu wǔshí dào tí.","exVi":"Bài thi tổng cộng có năm mươi câu.","w":"考试 一共 有 五 十 道 题。"},{"zh":"幅","py":"fú","vi":"bức (tranh)","hv":"bức","note":"Chính là \"bức\". 一幅画.","ex":"这幅画是我爷爷画的。","exPy":"Zhè fú huà shì wǒ yéye huà de.","exVi":"Bức tranh này do ông tôi vẽ.","w":"这 幅 画 是 我 爷爷 画 的。"},{"zh":"首","py":"shǒu","vi":"bài (thơ, hát)","hv":"thủ","note":"\"Thủ\" trong \"thủ đô\" là nghĩa khác; ở đây là lượng từ cho bài hát, bài thơ.","ex":"我给你唱一首歌。","exPy":"Wǒ gěi nǐ chàng yì shǒu gē.","exVi":"Tôi hát tặng bạn một bài.","w":"我 给 你 唱 一 首 歌。"},{"zh":"项","py":"xiàng","vi":"hạng mục, điều","hv":"hạng","note":"\"Hạng\" trong \"hạng mục\". 一项工作, 一项比赛.","ex":"这是一项重要的工作。","exPy":"Zhè shì yí xiàng zhòngyào de gōngzuò.","exVi":"Đây là một công việc quan trọng.","w":"这 是 一 项 重要 的 工作。"},{"zh":"列","py":"liè","vi":"đoàn (tàu), hàng","hv":"liệt","note":"一列火车 (một đoàn tàu). Còn là động từ \"liệt kê\": 列出.","ex":"一列火车开过来了。","exPy":"Yí liè huǒchē kāi guòlai le.","exVi":"Một đoàn tàu đang chạy tới.","w":"一 列 火车 开 过来 了。"},{"zh":"排","py":"pái","vi":"hàng, dãy; xếp","hv":"bài","note":"一排椅子 (một dãy ghế). Xếp hàng là 排队.","ex":"我坐在第一排。","exPy":"Wǒ zuò zài dì yī pái.","exVi":"Tôi ngồi ở hàng đầu.","w":"我 坐 在 第一 排。"},{"zh":"片","py":"piàn","vi":"miếng, lát; vùng","hv":"phiến","note":"Vật mỏng: 一片面包. Vùng rộng: 一片树林.","ex":"我吃了两片面包。","exPy":"Wǒ chī le liǎng piàn miànbāo.","exVi":"Tôi ăn hai lát bánh mì.","w":"我 吃 了 两 片面 包。"},{"zh":"期","py":"qī","vi":"kỳ, số (báo, khoá)","hv":"kỳ","note":"\"Kỳ\" trong \"học kỳ\". 第一期 (số đầu, khoá đầu).","ex":"这本杂志每月出一期。","exPy":"Zhè běn zázhì měi yuè chū yì qī.","exVi":"Tạp chí này mỗi tháng ra một số.","w":"这 本 杂志 每 月 出 一 期。"},{"zh":"部","py":"bù","vi":"bộ (phim, sách); phần","hv":"bộ","note":"一部电影, 一部小说. Còn là danh từ \"phần\": 北部, 东部.","ex":"他最喜欢那部电视剧。","exPy":"Tā zuì xǐhuan nà bù diànshìjù.","exVi":"Anh ấy thích nhất bộ phim truyền hình đó.","w":"他 最 喜欢 那 部 电视剧。"}],"newChars":["顿","幅","项"],"outro":"很好！Xong bài 186."};
G.ROOMS["zh-l187"] = {"id":"zh-l187","lang":"zh","level":4,"no":187,"teacher":"wang","title":"HSK4 · Bài 187 · 大多数人 Số lượng","intro":["大多数学生喜欢上体育课。","Bài 187: Nói về đa số, thiểu số, số lượng lớn, số lượng nhỏ, số người, toàn bộ, tất cả, tổng cộng, chỉ và chỉ có. Bấm 1 · Học để bắt đầu."],"introPy":"Dàduōshù xuésheng xǐhuan shàng tǐyù kè.","gram":{"t":"全 / 全都 / 都: tất cả","b":"全 + danh từ · 全都 + động từ","d":"全 đứng trước danh từ (全家, 全国), 全都 đứng trước động từ.","ex":[["全国人民都在看这场比赛。","Nhân dân cả nước đều đang xem trận đấu này.","Quán guó rénmín dōu zài kàn zhè chǎng bǐsài."],["他们全都来了。","Họ đến đủ cả rồi.","Tāmen quándōu lái le."]]},"grams":[{"t":"全 / 全都 / 都: tất cả","b":"全 + danh từ · 全都 + động từ","d":"全 đứng trước danh từ (全家, 全国), 全都 đứng trước động từ.","ex":[["全国人民都在看这场比赛。","Nhân dân cả nước đều đang xem trận đấu này.","Quán guó rénmín dōu zài kàn zhè chǎng bǐsài."],["他们全都来了。","Họ đến đủ cả rồi.","Tāmen quándōu lái le."]]},{"t":"仅仅 / 只…就…: chỉ… đã…","b":"仅仅 + thời gian + 就 + kết quả","d":"Nhấn mạnh làm được nhanh hoặc ít.","ex":[["他只用了十分钟就做完了。","Anh ấy chỉ mất mười phút đã làm xong.","Tā zhǐ yòng le shí fēnzhōng jiù zuò wán le."],["仅仅一个月，他就瘦了五公斤。","Chỉ một tháng, anh ấy đã giảm năm ký.","Jǐnjǐn yí ge yuè, tā jiù shòu le wǔ gōngjīn."]]}],"items":[{"zh":"多数","py":"duōshù","vi":"đa số","hv":"đa số","note":"Chính là \"đa số\". 大多数 là đại đa số.","ex":"大多数学生喜欢上体育课。","exPy":"Dàduōshù xuésheng xǐhuan shàng tǐyù kè.","exVi":"Đa số học sinh thích giờ thể dục.","w":"大多 数学 生 喜欢 上 体育 课。"},{"zh":"少数","py":"shǎoshù","vi":"thiểu số","hv":"thiểu số","note":"Chính là \"thiểu số\". Dân tộc thiểu số là 少数民族.","ex":"只有少数人反对。","exPy":"Zhǐyǒu shǎoshù rén fǎnduì.","exVi":"Chỉ có số ít người phản đối.","w":"只有 少数 人 反对。"},{"zh":"大量","py":"dàliàng","vi":"số lượng lớn","hv":"đại lượng","note":"大 + 量.","ex":"学外语需要大量练习。","exPy":"Xué wàiyǔ xūyào dàliàng liànxí.","exVi":"Học ngoại ngữ cần luyện tập rất nhiều.","w":"学 外语 需要 大量 练习。"},{"zh":"少量","py":"shǎoliàng","vi":"số lượng nhỏ","hv":"thiểu lượng","note":"少 + 量.","ex":"菜里放少量的盐。","exPy":"Cài lǐ fàng shǎoliàng de yán.","exVi":"Cho một ít muối vào món ăn.","w":"菜 里 放 少量 的 盐。"},{"zh":"人数","py":"rénshù","vi":"số người","hv":"nhân số","note":"人 + 数.","ex":"今年报名的人数增加了很多。","exPy":"Jīnnián bàomíng de rénshù zēngjiā le hěn duō.","exVi":"Năm nay số người đăng ký tăng nhiều.","w":"今年 报名 的 人数 增加 了 很 多。"},{"zh":"全","py":"quán","vi":"toàn bộ, đủ","hv":"toàn","note":"\"Toàn\" trong \"toàn bộ\". Đứng trước danh từ: 全家, 全国.","ex":"你说的我全都明白了。","exPy":"Nǐ shuō de wǒ quándōu míngbai le.","exVi":"Những gì bạn nói tôi hiểu hết rồi.","w":"你 说 的 我 全都 明白 了。"},{"zh":"全都","py":"quándōu","vi":"tất cả đều","hv":"toàn đô","note":"全 + 都, nhấn mạnh hơn 都.","ex":"作业我全都做完了。","exPy":"Zuòyè wǒ quándōu zuò wán le.","exVi":"Bài tập tôi làm xong hết rồi.","w":"作业 我 全都 做 完 了。"},{"zh":"共","py":"gòng","vi":"tổng cộng","hv":"cộng","note":"Văn viết của 一共.","ex":"全班共有四十人。","exPy":"Quán bān gòng yǒu sìshí rén.","exVi":"Cả lớp tổng cộng bốn mươi người.","w":"全 班 共 有 四 十 人。"},{"zh":"仅","py":"jǐn","vi":"chỉ","hv":"cận","note":"Văn viết của 只.","ex":"这个房间仅能住两个人。","exPy":"Zhège fángjiān jǐn néng zhù liǎng ge rén.","exVi":"Phòng này chỉ ở được hai người.","w":"这个 房间 仅 能 住 两 个人。"},{"zh":"仅仅","py":"jǐnjǐn","vi":"chỉ vẻn vẹn","hv":"cận cận","note":"Nhấn mạnh số lượng rất ít.","ex":"他仅仅用了一年就学会了汉语。","exPy":"Tā jǐnjǐn yòng le yì nián jiù xuéhuì le Hànyǔ.","exVi":"Anh ấy chỉ mất vẻn vẹn một năm đã học được tiếng Trung.","w":"他 仅仅 用 了 一 年 就 学会 了 汉语。"}],"newChars":[],"outro":"很好！Xong bài 187."};
G.ROOMS["zh-l188"] = {"id":"zh-l188","lang":"zh","level":4,"no":188,"teacher":"wang","title":"HSK4 · Bài 188 · 比较 So sánh","intro":["这个月的销量高于上个月。","Bài 188: So sánh bằng 高于 / 低于, 相比, 不如, 同样, 更加, 大大, 稍, 基本, 基本上. Bấm 1 · Học để bắt đầu."],"introPy":"Zhège yuè de xiāoliàng gāoyú shàng ge yuè.","gram":{"t":"A 不如 B (+ tính từ)","b":"我不如他高 · 坐车不如走路","d":"A không bằng B; có thể bỏ tính từ khi ý đã rõ.","ex":[["坐公交车不如骑车快。","Đi xe buýt không nhanh bằng đạp xe.","Zuò gōngjiāochē bùrú qí chē kuài."],["看电视不如看书。","Xem TV không bằng đọc sách.","Kàn diànshì bùrú kàn shū."]]},"grams":[{"t":"A 不如 B (+ tính từ)","b":"我不如他高 · 坐车不如走路","d":"A không bằng B; có thể bỏ tính từ khi ý đã rõ.","ex":[["坐公交车不如骑车快。","Đi xe buýt không nhanh bằng đạp xe.","Zuò gōngjiāochē bùrú qí chē kuài."],["看电视不如看书。","Xem TV không bằng đọc sách.","Kàn diànshì bùrú kàn shū."]]},{"t":"和 / 跟 + A + 相比","b":"和去年相比 · 跟别人相比","d":"Đặt đầu câu để so sánh, vế sau nêu kết luận.","ex":[["和去年相比，今年的游客多了很多。","So với năm ngoái, năm nay du khách đông hơn nhiều.","Hé qùnián xiāngbǐ, jīnnián de yóukè duō le hěn duō."],["跟别人相比，他更加努力。","So với người khác, anh ấy cố gắng hơn.","Gēn biérén xiāngbǐ, tā gèngjiā nǔlì."]]}],"items":[{"zh":"高于","py":"gāoyú","vi":"cao hơn","hv":"cao vu","note":"Văn viết: A 高于 B.","ex":"这个月的销量高于上个月。","exPy":"Zhège yuè de xiāoliàng gāoyú shàng ge yuè.","exVi":"Doanh số tháng này cao hơn tháng trước.","w":"这个 月 的 销量 高于 上 个 月。"},{"zh":"低于","py":"dīyú","vi":"thấp hơn","hv":"đê vu","note":"Văn viết: A 低于 B.","ex":"气温低于零度会结冰。","exPy":"Qìwēn dīyú líng dù huì jiébīng.","exVi":"Nhiệt độ dưới không độ sẽ đóng băng.","w":"气温 低于 零 度 会 结 冰。"},{"zh":"相比","py":"xiāngbǐ","vi":"so với","hv":"tương tỷ","note":"和…相比 (so với…).","ex":"和北京相比，上海更暖和。","exPy":"Hé Běijīng xiāngbǐ, Shànghǎi gèng nuǎnhuo.","exVi":"So với Bắc Kinh, Thượng Hải ấm hơn.","w":"和 北京 相比， 上 海 更 暖和。"},{"zh":"不如","py":"bùrú","vi":"không bằng","hv":"bất như","note":"A 不如 B: A không bằng B.","ex":"我的汉语不如他好。","exPy":"Wǒ de Hànyǔ bùrú tā hǎo.","exVi":"Tiếng Trung của tôi không giỏi bằng anh ấy.","w":"我 的 汉语 不如 他 好。"},{"zh":"同样","py":"tóngyàng","vi":"giống như vậy, cũng","hv":"đồng dạng","note":"同 (cùng) + 样.","ex":"我也遇到了同样的问题。","exPy":"Wǒ yě yùdào le tóngyàng de wèntí.","exVi":"Tôi cũng gặp vấn đề tương tự.","w":"我 也 遇到 了 同样 的 问题。"},{"zh":"更加","py":"gèngjiā","vi":"càng thêm","hv":"cánh gia","note":"Mạnh hơn 更.","ex":"下雨以后，空气更加新鲜了。","exPy":"Xià yǔ yǐhòu, kōngqì gèngjiā xīnxiān le.","exVi":"Mưa xong, không khí càng trong lành hơn.","w":"下雨 以后， 空气 更加 新鲜 了。"},{"zh":"大大","py":"dàdà","vi":"rất nhiều, đáng kể","hv":"đại đại","note":"Đứng trước động từ: 大大提高 (nâng cao đáng kể).","ex":"网上买东西大大方便了我们的生活。","exPy":"Wǎngshang mǎi dōngxi dàdà fāngbiàn le wǒmen de shēnghuó.","exVi":"Mua sắm trên mạng làm cuộc sống của chúng ta tiện lợi hơn nhiều.","w":"网上 买 东西 大大 方便 了 我们 的 生活。"},{"zh":"稍","py":"shāo","vi":"hơi, một chút","hv":"sảo","note":"Trang trọng. 稍等 (xin đợi chút).","ex":"稍等，我马上回来。","exPy":"Shāo děng, wǒ mǎshàng huílai.","exVi":"Đợi chút, tôi quay lại ngay.","w":"稍 等， 我 马上 回来。"},{"zh":"基本","py":"jīběn","vi":"cơ bản","hv":"cơ bản","note":"Chính là \"cơ bản\".","ex":"我基本上每天都跑步。","exPy":"Wǒ jīběnshàng měi tiān dōu pǎobù.","exVi":"Về cơ bản ngày nào tôi cũng chạy bộ.","w":"我 基本上 每 天 都 跑步。"},{"zh":"基本上","py":"jīběnshàng","vi":"về cơ bản","hv":"cơ bản thượng","note":"基本 + 上.","ex":"工作基本上完成了。","exPy":"Gōngzuò jīběnshàng wánchéng le.","exVi":"Công việc về cơ bản đã xong.","w":"工作 基本上 完成 了。"}],"newChars":[],"outro":"很好！Xong bài 188."};
G.ROOMS["zh-l189"] = {"id":"zh-l189","lang":"zh","level":4,"no":189,"teacher":"wang","title":"HSK4 · Bài 189 · 增长和下降 Tăng giảm và thay đổi","intro":["网上购物的人数每年都在增长。","Bài 189: Nói về tăng trưởng, giảm xuống, hạ, trừ bớt, giảm nhẹ, đẩy nhanh, tăng cường, nảy sinh, mất đi và dừng lại. Bấm 1 · Học để bắt đầu."],"introPy":"Wǎngshang gòuwù de rénshù měi nián dōu zài zēngzhǎng.","gram":{"t":"Kết hợp cố định","b":"加快速度 · 加强管理 · 减轻压力 · 产生兴趣 · 失去信心","d":"Học theo cụm, vì mỗi động từ đi với những danh từ nhất định.","ex":[["别失去信心！","Đừng mất niềm tin!","Bié shīqù xìnxīn!"],["公司要加强管理。","Công ty phải tăng cường quản lý.","Gōngsī yào jiāqiáng guǎnlǐ."]]},"grams":[{"t":"Kết hợp cố định","b":"加快速度 · 加强管理 · 减轻压力 · 产生兴趣 · 失去信心","d":"Học theo cụm, vì mỗi động từ đi với những danh từ nhất định.","ex":[["别失去信心！","Đừng mất niềm tin!","Bié shīqù xìnxīn!"],["公司要加强管理。","Công ty phải tăng cường quản lý.","Gōngsī yào jiāqiáng guǎnlǐ."]]},{"t":"Phép tính","b":"加 cộng · 减 trừ · 乘 nhân · 除 chia · 等于 bằng","d":"Đọc phép tính bằng tiếng Trung.","ex":[["五加五等于十。","Năm cộng năm bằng mười.","Wǔ jiā wǔ děngyú shí."],["二乘三等于六。","Hai nhân ba bằng sáu.","Èr chéng sān děngyú liù."]]}],"items":[{"zh":"增长","py":"zēngzhǎng","vi":"tăng trưởng","hv":"tăng trưởng","note":"Chính là \"tăng trưởng\".","ex":"网上购物的人数每年都在增长。","exPy":"Wǎngshang gòuwù de rénshù měi nián dōu zài zēngzhǎng.","exVi":"Số người mua sắm trên mạng năm nào cũng tăng.","w":"网上 购物 的 人数 每 年 都 在 增长。"},{"zh":"下降","py":"xiàjiàng","vi":"giảm xuống","hv":"hạ giáng","note":"下 + 降.","ex":"晚上气温会下降。","exPy":"Wǎnshang qìwēn huì xiàjiàng.","exVi":"Buổi tối nhiệt độ sẽ giảm.","w":"晚上 气温 会 下降。"},{"zh":"降","py":"jiàng","vi":"hạ, giảm","hv":"giáng","note":"\"Giáng\" trong \"giáng cấp\". 降价 (giảm giá), 降温.","ex":"价格降了一半。","exPy":"Jiàgé jiàng le yíbàn.","exVi":"Giá giảm một nửa.","w":"价格 降 了 一半。"},{"zh":"减","py":"jiǎn","vi":"trừ, bớt","hv":"giảm","note":"Chính là \"giảm\". Giảm cân là 减肥.","ex":"听音乐能减轻我的压力。","exPy":"Tīng yīnyuè néng jiǎnqīng wǒ de yālì.","exVi":"Nghe nhạc giúp tôi giảm căng thẳng.","w":"听 音乐 能 减轻 我 的 压力。"},{"zh":"减轻","py":"jiǎnqīng","vi":"giảm nhẹ","hv":"giảm khinh","note":"减 + 轻 (nhẹ).","ex":"运动可以减轻压力。","exPy":"Yùndòng kěyǐ jiǎnqīng yālì.","exVi":"Vận động có thể giảm áp lực.","w":"运动 可以 减轻 压力。"},{"zh":"加快","py":"jiākuài","vi":"đẩy nhanh","hv":"gia khoái","note":"加 + 快.","ex":"我们要加快速度。","exPy":"Wǒmen yào jiākuài sùdù.","exVi":"Chúng ta phải đẩy nhanh tốc độ.","w":"我们 要 加快 速度。"},{"zh":"加强","py":"jiāqiáng","vi":"tăng cường","hv":"gia cường","note":"Chính là \"gia cường\".","ex":"我们要加强锻炼。","exPy":"Wǒmen yào jiāqiáng duànliàn.","exVi":"Chúng ta phải tăng cường rèn luyện.","w":"我们 要 加强 锻炼。"},{"zh":"产生","py":"chǎnshēng","vi":"nảy sinh, sinh ra","hv":"sản sinh","note":"Chính là \"sản sinh\".","ex":"他对中国文化产生了兴趣。","exPy":"Tā duì Zhōngguó wénhuà chǎnshēng le xìngqù.","exVi":"Anh ấy nảy sinh hứng thú với văn hoá Trung Quốc.","w":"他 对 中国 文化 产生 了 兴趣。"},{"zh":"失去","py":"shīqù","vi":"mất đi","hv":"thất khứ","note":"失 = \"thất\" trong \"thất bại\".","ex":"他失去了工作。","exPy":"Tā shīqù le gōngzuò.","exVi":"Anh ấy mất việc.","w":"他 失去 了 工作。"},{"zh":"停止","py":"tíngzhǐ","vi":"dừng lại","hv":"đình chỉ","note":"Chính là \"đình chỉ\".","ex":"比赛因为下雨停止了。","exPy":"Bǐsài yīnwèi xià yǔ tíngzhǐ le.","exVi":"Trận đấu dừng lại vì trời mưa.","w":"比赛 因为 下雨 停止 了。"}],"newChars":["强","产"],"outro":"很好！Xong bài 189."};
G.ROOMS["zh-l190"] = {"id":"zh-l190","lang":"zh","level":4,"no":190,"teacher":"wang","title":"HSK4 · Bài 190 · 提出想法 Nói và trao đổi ý kiến","intro":["大家对这个计划有什么想法？","Bài 190: Nói về đồng ý, trả lời, đưa ra, nhắc đến, chỉ ra, lấy ví dụ, ví dụ, cách nói, suy nghĩ và cách làm. Bấm 1 · Học để bắt đầu."],"introPy":"Dàjiā duì zhège jìhuà yǒu shénme xiǎngfǎ?","gram":{"t":"Động từ + 出: đưa ra, làm lộ ra","b":"提出 · 指出 · 说出 · 想出","d":"出 sau động từ cho biết điều gì đó được đưa ra ngoài.","ex":[["他想出了一个好办法。","Anh ấy nghĩ ra một cách hay.","Tā xiǎng chū le yí ge hǎo bànfǎ."],["你说出你的想法吧。","Bạn nói ra suy nghĩ của mình đi.","Nǐ shuō chū nǐ de xiǎngfǎ ba."]]},"grams":[{"t":"Động từ + 出: đưa ra, làm lộ ra","b":"提出 · 指出 · 说出 · 想出","d":"出 sau động từ cho biết điều gì đó được đưa ra ngoài.","ex":[["他想出了一个好办法。","Anh ấy nghĩ ra một cách hay.","Tā xiǎng chū le yí ge hǎo bànfǎ."],["你说出你的想法吧。","Bạn nói ra suy nghĩ của mình đi.","Nǐ shuō chū nǐ de xiǎngfǎ ba."]]},{"t":"比如 / 例如: ví dụ như","b":"…，比如 + ví dụ","d":"Đưa ví dụ cụ thể sau một nhận định chung.","ex":[["我喜欢运动，比如游泳和跑步。","Tôi thích thể thao, ví dụ như bơi và chạy.","Wǒ xǐhuan yùndòng, bǐrú yóuyǒng hé pǎobù."],["很多水果对身体好，例如苹果。","Nhiều loại quả tốt cho sức khoẻ, ví dụ táo.","Hěn duō shuǐguǒ duì shēntǐ hǎo, lìrú píngguǒ."]]}],"items":[{"zh":"答应","py":"dāying","vi":"đồng ý, nhận lời","hv":"đáp ứng","note":"Chính là \"đáp ứng\".","ex":"他答应了我的要求。","exPy":"Tā dāying le wǒ de yāoqiú.","exVi":"Anh ấy đồng ý yêu cầu của tôi.","w":"他 答应 了 我 的 要求。"},{"zh":"答","py":"dá","vi":"trả lời","hv":"đáp","note":"Chính là \"đáp\" trong \"đáp án\". 回答 là trả lời.","ex":"这个问题我答不上来。","exPy":"Zhège wèntí wǒ dá bu shànglái.","exVi":"Câu hỏi này tôi không trả lời được.","w":"这个 问题 我 答 不 上来。"},{"zh":"提出","py":"tíchū","vi":"đưa ra, đề xuất","hv":"đề xuất","note":"Chính là \"đề xuất\".","ex":"他提出了一个好建议。","exPy":"Tā tíchū le yí ge hǎo jiànyì.","exVi":"Anh ấy đưa ra một đề xuất hay.","w":"他 提出 了 一 个 好 建议。"},{"zh":"提到","py":"tídào","vi":"nhắc đến","hv":"đề đáo","note":"提 + 到.","ex":"他在信里提到了你。","exPy":"Tā zài xìn lǐ tídào le nǐ.","exVi":"Anh ấy có nhắc đến bạn trong thư.","w":"他 在 信 里 提到 了 你。"},{"zh":"指出","py":"zhǐchū","vi":"chỉ ra","hv":"chỉ xuất","note":"指 (chỉ) + 出.","ex":"老师指出了我的错误。","exPy":"Lǎoshī zhǐchū le wǒ de cuòwù.","exVi":"Thầy chỉ ra lỗi sai của tôi.","w":"老师 指出 了 我 的 错误。"},{"zh":"举例","py":"jǔlì","vi":"nêu ví dụ","hv":"cử lệ","note":"举 (nêu) + 例 (lệ, ví dụ).","ex":"请举例说明。","exPy":"Qǐng jǔlì shuōmíng.","exVi":"Xin nêu ví dụ để giải thích.","w":"请 举例 说明。"},{"zh":"例子","py":"lìzi","vi":"ví dụ","hv":"lệ tử","note":"例 + 子.","ex":"好的例子能帮助学生理解。","exPy":"Hǎo de lìzi néng bāngzhù xuésheng lǐjiě.","exVi":"Ví dụ hay giúp học sinh hiểu bài.","w":"好 的 例子 能 帮助 学生 理解。"},{"zh":"说法","py":"shuōfǎ","vi":"cách nói; ý kiến","hv":"thuyết pháp","note":"Khác \"thuyết pháp\" (giảng đạo) tiếng Việt: 说法 là cách nói, quan điểm.","ex":"这种说法不对。","exPy":"Zhè zhǒng shuōfǎ bú duì.","exVi":"Cách nói này không đúng.","w":"这 种 说法 不 对。"},{"zh":"想法","py":"xiǎngfǎ","vi":"suy nghĩ, ý tưởng","hv":"tưởng pháp","note":"想 + 法.","ex":"大家对这个计划有什么想法？","exPy":"Dàjiā duì zhège jìhuà yǒu shénme xiǎngfǎ?","exVi":"Mọi người có ý kiến gì về kế hoạch này?","w":"大家 对 这个 计划 有 什么 想法？"},{"zh":"做法","py":"zuòfǎ","vi":"cách làm","hv":"tố pháp","note":"做 + 法.","ex":"每个人的做法都不一样。","exPy":"Měi ge rén de zuòfǎ dōu bù yíyàng.","exVi":"Cách làm của mỗi người đều khác nhau.","w":"每 个人 的 做法 都 不 一样。"}],"newChars":[],"outro":"很好！Xong bài 190."};
G.ROOMS["zh-l191"] = {"id":"zh-l191","lang":"zh","level":4,"no":191,"teacher":"wang","title":"HSK4 · Bài 191 · 不光…而且… Liên từ nối ý","intro":["学汉语并不像你想的那么难。","Bài 191: Nối câu bằng 并, 既, 此外, 加上, 不论, 不光, 再说, 就是, 实际上, 是否. Bấm 1 · Học để bắt đầu."],"introPy":"Xué Hànyǔ bìng bú xiàng nǐ xiǎng de nàme nán.","gram":{"t":"不论 / 不管…都…: dù… cũng","b":"不论 + câu hỏi / lựa chọn，都 + kết quả","d":"Sau 不论 thường là từ để hỏi (多, 什么, 谁) hoặc lựa chọn (A 还是 B).","ex":[["不论你去不去，我都去。","Dù bạn có đi hay không, tôi vẫn đi.","Búlùn nǐ qù bu qù, wǒ dōu qù."],["不论是谁，都要遵守规定。","Bất kể là ai cũng phải tuân thủ quy định.","Búlùn shì shéi, dōu yào zūnshǒu guīdìng."]]},"grams":[{"t":"不论 / 不管…都…: dù… cũng","b":"不论 + câu hỏi / lựa chọn，都 + kết quả","d":"Sau 不论 thường là từ để hỏi (多, 什么, 谁) hoặc lựa chọn (A 还是 B).","ex":[["不论你去不去，我都去。","Dù bạn có đi hay không, tôi vẫn đi.","Búlùn nǐ qù bu qù, wǒ dōu qù."],["不论是谁，都要遵守规定。","Bất kể là ai cũng phải tuân thủ quy định.","Búlùn shì shéi, dōu yào zūnshǒu guīdìng."]]},{"t":"既…又…: vừa… vừa…","b":"既 + tính từ / động từ + 又 + tính từ / động từ","d":"Hai đặc điểm cùng tồn tại.","ex":[["这个办法既简单又有效。","Cách này vừa đơn giản vừa hiệu quả.","Zhège bànfǎ jì jiǎndān yòu yǒuxiào."],["他既会唱歌又会跳舞。","Anh ấy vừa biết hát vừa biết nhảy.","Tā jì huì chànggē yòu huì tiàowǔ."]]}],"items":[{"zh":"并","py":"bìng","vi":"và; hoàn toàn (không)","hv":"tịnh","note":"Nối hai động từ: 讨论并通过. Trước 不 / 没 để nhấn mạnh: 并不难.","ex":"学汉语并不像你想的那么难。","exPy":"Xué Hànyǔ bìng bú xiàng nǐ xiǎng de nàme nán.","exVi":"Học tiếng Trung không khó như bạn nghĩ đâu.","w":"学 汉语 并 不 像 你 想 的 那么 难。"},{"zh":"既","py":"jì","vi":"đã… lại…","hv":"ký","note":"既…又…: vừa… vừa….","ex":"她既聪明又漂亮。","exPy":"Tā jì cōngming yòu piàoliang.","exVi":"Cô ấy vừa thông minh vừa xinh đẹp.","w":"她 既 聪明 又 漂亮。"},{"zh":"此外","py":"cǐwài","vi":"ngoài ra","hv":"thử ngoại","note":"此 (này) + 外.","ex":"这里环境好，此外交通也很方便。","exPy":"Zhèlǐ huánjìng hǎo, cǐwài jiāotōng yě hěn fāngbiàn.","exVi":"Ở đây môi trường tốt, ngoài ra giao thông cũng tiện.","w":"这里 环境 好， 此外 交通 也 很 方便。"},{"zh":"加上","py":"jiāshàng","vi":"thêm vào đó","hv":"gia thượng","note":"Nêu thêm một lý do.","ex":"天气不好，加上身体不舒服，我就没去。","exPy":"Tiānqì bù hǎo, jiāshàng shēntǐ bù shūfu, wǒ jiù méi qù.","exVi":"Thời tiết xấu, thêm nữa người không khoẻ, nên tôi không đi.","w":"天气 不 好， 加上 身体 不 舒服， 我 就 没 去。"},{"zh":"不论","py":"búlùn","vi":"bất luận, dù","hv":"bất luận","note":"Chính là \"bất luận\". Hay đi với 都.","ex":"不论多忙，他都每天跑步。","exPy":"Búlùn duō máng, tā dōu měi tiān pǎobù.","exVi":"Dù bận đến mấy, ngày nào anh ấy cũng chạy bộ.","w":"不论 多 忙， 他 都 每 天 跑步。"},{"zh":"不光","py":"bùguāng","vi":"không chỉ","hv":"bất quang","note":"Khẩu ngữ của 不但. Vế sau có 还 / 也.","ex":"他不光会说汉语，还会说日语。","exPy":"Tā bùguāng huì shuō Hànyǔ, hái huì shuō Rìyǔ.","exVi":"Anh ấy không chỉ nói được tiếng Trung, còn nói được tiếng Nhật.","w":"他 不光 会 说 汉语， 还 会 说 日 语。"},{"zh":"再说","py":"zàishuō","vi":"hơn nữa; để sau hãy tính","hv":"tái thuyết","note":"Hai nghĩa: \"hơn nữa\" (thêm lý do) và \"để sau tính\".","ex":"我们先吃饭，别的事再说。","exPy":"Wǒmen xiān chīfàn, bié de shì zàishuō.","exVi":"Chúng ta ăn cơm trước, việc khác để sau tính.","w":"我们 先 吃 饭， 别的 事 再说。"},{"zh":"就是","py":"jiùshì","vi":"chính là; chỉ là","hv":"tựu thị","note":"Nhấn mạnh: 就是他 (chính là anh ấy). Còn là \"chỉ có điều\".","ex":"这件衣服很好，就是有点儿贵。","exPy":"Zhè jiàn yīfu hěn hǎo, jiùshì yǒudiǎnr guì.","exVi":"Bộ đồ này đẹp, chỉ có điều hơi đắt.","w":"这 件 衣服 很 好， 就是 有点儿 贵。"},{"zh":"实际上","py":"shíjìshàng","vi":"thực ra","hv":"thực tế thượng","note":"Chính là \"trên thực tế\".","ex":"他看起来很冷，实际上很热情。","exPy":"Tā kàn qǐlai hěn lěng, shíjìshàng hěn rèqíng.","exVi":"Trông anh ấy lạnh lùng, thực ra rất nhiệt tình.","w":"他 看 起来 很 冷， 实际上 很 热情。"},{"zh":"是否","py":"shìfǒu","vi":"có… hay không","hv":"thị phủ","note":"Văn viết của 是不是.","ex":"请告诉我你是否能参加。","exPy":"Qǐng gàosu wǒ nǐ shìfǒu néng cānjiā.","exVi":"Xin cho tôi biết bạn có thể tham gia hay không.","w":"请 告诉 我 你 是否 能 参加。"}],"newChars":[],"outro":"很好！Xong bài 191."};
G.ROOMS["zh-l192"] = {"id":"zh-l192","lang":"zh","level":4,"no":192,"teacher":"wang","title":"HSK4 · Bài 192 · 普遍和少见 Đánh giá mức độ","intro":["现在用手机付钱已经很普遍了。","Bài 192: Nói về phổ biến, bình thường, thường ngày, hằng ngày, hiếm gặp, đa dạng, trực tiếp, phù hợp, thích nghi và hiệu quả. Bấm 1 · Học để bắt đầu."],"introPy":"Xiànzài yòng shǒujī fù qián yǐjīng hěn pǔbiàn le.","gram":{"t":"适合 và 合适","b":"适合 + tân ngữ (động từ) · 合适 (tính từ)","d":"这件衣服适合你 / 这件衣服很合适. Không nói 很适合 mà không có tân ngữ.","ex":[["这个工作很适合他。","Công việc này rất hợp với anh ấy.","Zhège gōngzuò hěn shìhé tā."],["大小很合适。","Kích cỡ rất vừa.","Dàxiǎo hěn héshì."]]},"grams":[{"t":"适合 và 合适","b":"适合 + tân ngữ (động từ) · 合适 (tính từ)","d":"这件衣服适合你 / 这件衣服很合适. Không nói 很适合 mà không có tân ngữ.","ex":[["这个工作很适合他。","Công việc này rất hợp với anh ấy.","Zhège gōngzuò hěn shìhé tā."],["大小很合适。","Kích cỡ rất vừa.","Dàxiǎo hěn héshì."]]},{"t":"在…内: trong vòng","b":"三天内 · 一小时内 · 公司内","d":"Giới hạn thời gian hoặc phạm vi.","ex":[["请在一周内回复。","Xin trả lời trong vòng một tuần.","Qǐng zài yì zhōu nèi huífù."],["会议室内不能吸烟。","Trong phòng họp không được hút thuốc.","Huìyìshì nèi bù néng xīyān."]]}],"items":[{"zh":"普遍","py":"pǔbiàn","vi":"phổ biến","hv":"phổ biến","note":"Chính là \"phổ biến\".","ex":"现在用手机付钱已经很普遍了。","exPy":"Xiànzài yòng shǒujī fù qián yǐjīng hěn pǔbiàn le.","exVi":"Bây giờ trả tiền bằng điện thoại đã rất phổ biến.","w":"现在 用 手机 付 钱 已经 很 普遍 了。"},{"zh":"普通","py":"pǔtōng","vi":"bình thường","hv":"phổ thông","note":"Chính là \"phổ thông\". Tiếng phổ thông là 普通话.","ex":"我只是一个普通人。","exPy":"Wǒ zhǐshì yí ge pǔtōng rén.","exVi":"Tôi chỉ là một người bình thường.","w":"我 只是 一 个 普通 人。"},{"zh":"平常","py":"píngcháng","vi":"thường ngày; bình thường","hv":"bình thường","note":"Chính là \"bình thường\". Còn nghĩa \"ngày thường\".","ex":"我平常七点起床。","exPy":"Wǒ píngcháng qī diǎn qǐchuáng.","exVi":"Ngày thường tôi dậy lúc bảy giờ.","w":"我 平常 七 点 起床。"},{"zh":"日常","py":"rìcháng","vi":"hằng ngày","hv":"nhật thường","note":"Chính là \"nhật thường\". 日常生活 (cuộc sống hằng ngày).","ex":"学外语要从日常对话开始。","exPy":"Xué wàiyǔ yào cóng rìcháng duìhuà kāishǐ.","exVi":"Học ngoại ngữ nên bắt đầu từ hội thoại hằng ngày.","w":"学 外语 要 从 日常 对话 开始。"},{"zh":"少见","py":"shǎojiàn","vi":"hiếm gặp","hv":"thiểu kiến","note":"少 + 见.","ex":"这种鸟很少见。","exPy":"Zhè zhǒng niǎo hěn shǎojiàn.","exVi":"Loài chim này rất hiếm gặp.","w":"这 种 鸟 很 少见。"},{"zh":"多样","py":"duōyàng","vi":"đa dạng","hv":"đa dạng","note":"Chính là \"đa dạng\".","ex":"越南的食物很多样。","exPy":"Yuènán de shíwù hěn duōyàng.","exVi":"Đồ ăn Việt Nam rất đa dạng.","w":"越 南 的 食物 很 多样。"},{"zh":"直接","py":"zhíjiē","vi":"trực tiếp","hv":"trực tiếp","note":"Chính là \"trực tiếp\".","ex":"有问题可以直接问我。","exPy":"Yǒu wèntí kěyǐ zhíjiē wèn wǒ.","exVi":"Có vấn đề có thể hỏi thẳng tôi.","w":"有 问题 可以 直接 问 我。"},{"zh":"适合","py":"shìhé","vi":"phù hợp","hv":"thích hợp","note":"Chính là \"thích hợp\". Sau 适合 là tân ngữ trực tiếp: 适合你.","ex":"这件衣服很适合你。","exPy":"Zhè jiàn yīfu hěn shìhé nǐ.","exVi":"Bộ đồ này rất hợp với bạn.","w":"这 件 衣服 很 适合 你。"},{"zh":"适应","py":"shìyìng","vi":"thích nghi","hv":"thích ứng","note":"Chính là \"thích ứng\".","ex":"刚来的时候，我不太适应这里的天气。","exPy":"Gāng lái de shíhou, wǒ bú tài shìyìng zhèlǐ de tiānqì.","exVi":"Mới đến, tôi chưa quen lắm với thời tiết ở đây.","w":"刚 来 的 时候， 我 不 太 适应 这里 的 天气。"},{"zh":"有效","py":"yǒuxiào","vi":"có hiệu quả; có hiệu lực","hv":"hữu hiệu","note":"Chính là \"hữu hiệu\". Vé còn hạn: 有效.","ex":"这个方法简单有效。","exPy":"Zhège fāngfǎ jiǎndān yǒuxiào.","exVi":"Phương pháp này đơn giản mà hiệu quả.","w":"这个 方法 简单 有效。"}],"newChars":[],"outro":"很好！Xong bài 192."};
G.ROOMS["zh-l193"] = {"id":"zh-l193","lang":"zh","level":4,"no":193,"teacher":"wang","title":"HSK4 · Bài 193 · 庆祝生日 Sự kiện và gặp gỡ","intro":["我们去饭店庆祝一下吧。","Bài 193: Nói về ăn mừng, tụ họp, liên hoan, đến, chúc, chúc ngủ ngon, để lại, đi ngang qua, bỏ lỡ và kịp. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒmen qù fàndiàn qìngzhù yíxià ba.","gram":{"t":"给 + người + 留下 + ấn tượng","b":"给我留下了好印象","d":"Ai để lại ấn tượng cho ai.","ex":[["这次旅行给我留下了美好的回忆。","Chuyến đi này để lại cho tôi kỷ niệm đẹp.","Zhè cì lǚxíng gěi wǒ liúxia le měihǎo de huíyì."],["你给老师留下了好印象。","Bạn để lại ấn tượng tốt cho thầy.","Nǐ gěi lǎoshī liúxia le hǎo yìnxiàng."]]},"grams":[{"t":"给 + người + 留下 + ấn tượng","b":"给我留下了好印象","d":"Ai để lại ấn tượng cho ai.","ex":[["这次旅行给我留下了美好的回忆。","Chuyến đi này để lại cho tôi kỷ niệm đẹp.","Zhè cì lǚxíng gěi wǒ liúxia le měihǎo de huíyì."],["你给老师留下了好印象。","Bạn để lại ấn tượng tốt cho thầy.","Nǐ gěi lǎoshī liúxia le hǎo yìnxiàng."]]},{"t":"赶上 và 错过","b":"赶上 + chuyến xe / cơ hội (kịp) · 错过 + chuyến xe / cơ hội (lỡ)","d":"Hai động từ đối lập, đi với cùng loại danh từ.","ex":[["如果不快点儿，就赶不上飞机了。","Nếu không nhanh lên thì không kịp máy bay.","Rúguǒ bú kuài diǎnr, jiù gǎn bu shàng fēijī le."],["我错过了他的电话。","Tôi bỏ lỡ cuộc gọi của anh ấy.","Wǒ cuòguò le tā de diànhuà."]]}],"items":[{"zh":"庆祝","py":"qìngzhù","vi":"ăn mừng, chúc mừng","hv":"khánh chúc","note":"Chính là \"khánh chúc\".","ex":"我们去饭店庆祝一下吧。","exPy":"Wǒmen qù fàndiàn qìngzhù yíxià ba.","exVi":"Chúng ta ra nhà hàng ăn mừng chút nhé.","w":"我们 去 饭店 庆祝 一下 吧。"},{"zh":"聚","py":"jù","vi":"tụ họp","hv":"tụ","note":"\"Tụ\" trong \"hội tụ\". 聚会 là buổi tụ họp.","ex":"毕业以后，同学们很少聚在一起了。","exPy":"Bìyè yǐhòu, tóngxuémen hěn shǎo jù zài yìqǐ le.","exVi":"Tốt nghiệp rồi, bạn học ít khi tụ tập.","w":"毕业 以后， 同学 们 很 少 聚 在 一起 了。"},{"zh":"聚餐","py":"jùcān","vi":"liên hoan, ăn chung","hv":"tụ xan","note":"聚 + 餐.","ex":"周五晚上公司聚餐。","exPy":"Zhōuwǔ wǎnshang gōngsī jùcān.","exVi":"Tối thứ Sáu công ty liên hoan.","w":"周 五 晚上 公司 聚餐。"},{"zh":"到来","py":"dàolái","vi":"đến, sự đến","hv":"đáo lai","note":"Trang trọng. 春天的到来 (mùa xuân đến).","ex":"欢迎您的到来。","exPy":"Huānyíng nín de dàolái.","exVi":"Hoan nghênh ngài đã đến.","w":"欢迎 您 的 到来。"},{"zh":"祝","py":"zhù","vi":"chúc","hv":"chúc","note":"Chính là \"chúc\".","ex":"祝你一路平安！","exPy":"Zhù nǐ yí lù píng'ān!","exVi":"Chúc bạn thượng lộ bình an!","w":"祝 你 一路 平安！"},{"zh":"晚安","py":"wǎn'ān","vi":"chúc ngủ ngon","hv":"vãn an","note":"晚 + 安 (yên).","ex":"晚安，明天见。","exPy":"Wǎn'ān, míngtiān jiàn.","exVi":"Ngủ ngon nhé, mai gặp.","w":"晚安， 明天 见。"},{"zh":"留下","py":"liúxia","vi":"để lại, ở lại","hv":"lưu hạ","note":"留 = \"lưu\" trong \"lưu giữ\".","ex":"他给我留下了很深的印象。","exPy":"Tā gěi wǒ liúxia le hěn shēn de yìnxiàng.","exVi":"Anh ấy để lại cho tôi ấn tượng sâu sắc.","w":"他 给 我 留下 了 很 深 的 印象。"},{"zh":"路过","py":"lùguò","vi":"đi ngang qua","hv":"lộ quá","note":"路 + 过.","ex":"路过的时候进来坐坐吧。","exPy":"Lùguò de shíhou jìnlai zuòzuo ba.","exVi":"Khi đi ngang qua thì vào ngồi chơi nhé.","w":"路过 的 时候 进来 坐 坐 吧。"},{"zh":"错过","py":"cuòguò","vi":"bỏ lỡ","hv":"thác quá","note":"错 (sai) + 过.","ex":"别错过这次机会。","exPy":"Bié cuòguò zhè cì jīhuì.","exVi":"Đừng bỏ lỡ cơ hội này.","w":"别 错过 这 次 机会。"},{"zh":"赶上","py":"gǎnshàng","vi":"kịp, đuổi kịp","hv":"cản thượng","note":"赶 (đuổi) + 上.","ex":"我们赶上了最后一班车。","exPy":"Wǒmen gǎnshàng le zuìhòu yì bān chē.","exVi":"Chúng tôi kịp chuyến xe cuối cùng.","w":"我们 赶上 了 最后 一 班 车。"}],"newChars":["庆"],"outro":"很好！Xong bài 193."};
G.ROOMS["zh-l194"] = {"id":"zh-l194","lang":"zh","level":4,"no":194,"teacher":"wang","title":"HSK4 · Bài 194 · 换个牌子 Đồ dùng và quần áo","intro":["我喜欢这个牌子的运动鞋。","Bài 194: Nói về nhãn hiệu, biển, áo khoác, áo len, giày da, đồng hồ, thời gian biểu, dầu, thô và mảnh. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xǐhuan zhège páizi de yùndòngxié.","gram":{"t":"Câu hỏi 什么牌子的 / 什么颜色的","b":"Danh từ + 是 + 什么 + … + 的？","d":"Hỏi đặc điểm bằng 什么 + danh từ + 的.","ex":[["你的车是什么颜色的？","Xe bạn màu gì?","Nǐ de chē shì shénme yánsè de?"],["这件毛衣是什么牌子的？","Áo len này hãng gì?","Zhè jiàn máoyī shì shénme páizi de?"]]},"grams":[{"t":"Câu hỏi 什么牌子的 / 什么颜色的","b":"Danh từ + 是 + 什么 + … + 的？","d":"Hỏi đặc điểm bằng 什么 + danh từ + 的.","ex":[["你的车是什么颜色的？","Xe bạn màu gì?","Nǐ de chē shì shénme yánsè de?"],["这件毛衣是什么牌子的？","Áo len này hãng gì?","Zhè jiàn máoyī shì shénme páizi de?"]]},{"t":"又…又…: vừa… vừa… (khẩu ngữ)","b":"又 + tính từ + 又 + tính từ","d":"Hai đặc điểm cùng chiều (cùng tốt hoặc cùng xấu).","ex":[["这个苹果又大又甜。","Quả táo này vừa to vừa ngọt.","Zhège píngguǒ yòu dà yòu tián."],["外面又冷又黑。","Bên ngoài vừa lạnh vừa tối.","Wàimian yòu lěng yòu hēi."]]}],"items":[{"zh":"牌子","py":"páizi","vi":"nhãn hiệu; biển","hv":"bài tử","note":"Thương hiệu: 什么牌子? Còn là tấm biển.","ex":"我喜欢这个牌子的运动鞋。","exPy":"Wǒ xǐhuan zhège páizi de yùndòngxié.","exVi":"Tôi thích giày thể thao hãng này.","w":"我 喜欢 这个 牌子 的 运动 鞋。"},{"zh":"牌","py":"pái","vi":"biển; thẻ; nhãn","hv":"bài","note":"Biển số xe 车牌, bài lá 扑克牌.","ex":"门口挂着一块牌。","exPy":"Ménkǒu guà zhe yí kuài pái.","exVi":"Trước cửa treo một tấm biển.","w":"门口 挂 着 一 块 牌。"},{"zh":"外套","py":"wàitào","vi":"áo khoác ngoài","hv":"ngoại sáo","note":"外 + 套 (bao ngoài).","ex":"冬天我常穿毛衣和外套。","exPy":"Dōngtiān wǒ cháng chuān máoyī hé wàitào.","exVi":"Mùa đông tôi hay mặc áo len và áo khoác.","w":"冬天 我 常 穿 毛衣 和 外套。"},{"zh":"毛衣","py":"máoyī","vi":"áo len","hv":"mao y","note":"毛 (lông) + 衣.","ex":"妈妈给我织了一件毛衣。","exPy":"Māma gěi wǒ zhī le yí jiàn máoyī.","exVi":"Mẹ đan cho tôi một chiếc áo len.","w":"妈妈 给 我 织 了 一 件 毛衣。"},{"zh":"皮鞋","py":"píxié","vi":"giày da","hv":"bì hài","note":"皮 (da) + 鞋 (giày).","ex":"面试要穿皮鞋。","exPy":"Miànshì yào chuān píxié.","exVi":"Đi phỏng vấn phải đi giày da.","w":"面试 要 穿 皮鞋。"},{"zh":"表","py":"biǎo","vi":"đồng hồ đeo tay; bảng","hv":"biểu","note":"\"Biểu\" trong \"biểu đồ\". Đồng hồ đeo tay là 手表.","ex":"按照时间表，我们三点出发。","exPy":"Ànzhào shíjiānbiǎo, wǒmen sān diǎn chūfā.","exVi":"Theo thời gian biểu, ba giờ chúng ta xuất phát.","w":"按照 时间表， 我们 三 点 出发。"},{"zh":"时间表","py":"shíjiānbiǎo","vi":"thời gian biểu, lịch","hv":"thời gian biểu","note":"Chính là \"thời gian biểu\".","ex":"我做了一个学习时间表。","exPy":"Wǒ zuò le yí ge xuéxí shíjiānbiǎo.","exVi":"Tôi lập một thời gian biểu học tập.","w":"我 做 了 一 个 学习 时间表。"},{"zh":"油","py":"yóu","vi":"dầu; xăng","hv":"du","note":"Dầu ăn 油, xăng 汽油. Đổ xăng là 加油.","ex":"菜里油太多了。","exPy":"Cài lǐ yóu tài duō le.","exVi":"Món ăn nhiều dầu quá.","w":"菜 里 油 太 多 了。"},{"zh":"粗","py":"cū","vi":"thô, to (sợi); cẩu thả","hv":"thô","note":"Chính là \"thô\". Đối lập với 细.","ex":"做事不能太粗，要细心一点儿。","exPy":"Zuò shì bù néng tài cū, yào xìxīn yìdiǎnr.","exVi":"Làm việc không được cẩu thả, phải cẩn thận hơn.","w":"做 事 不 能 太 粗， 要 细心 一点儿。"},{"zh":"细","py":"xì","vi":"mảnh, nhỏ; tỉ mỉ","hv":"tế","note":"\"Tế\" trong \"tế bào\", \"tinh tế\".","ex":"她的手指又细又长。","exPy":"Tā de shǒuzhǐ yòu xì yòu cháng.","exVi":"Ngón tay cô ấy vừa thon vừa dài.","w":"她 的 手指 又 细 又 长。"}],"newChars":["套"],"outro":"很好！Xong bài 194."};
G.ROOMS["zh-l195"] = {"id":"zh-l195","lang":"zh","level":4,"no":195,"teacher":"wang","title":"HSK4 · Bài 195 · 说得很流利 Kỹ năng và khả năng","intro":["只要每天积累，你的汉语一定会越来越流利。","Bài 195: Nói về cẩn thận, thành thạo, khéo / trùng hợp, mạnh, chính xác, lưu loát, tích luỹ, có thể, có thể hay không, không thể. Bấm 1 · Học để bắt đầu."],"introPy":"Zhǐyào měi tiān jīlěi, nǐ de Hànyǔ yídìng huì yuèláiyuè liúlì.","gram":{"t":"Động từ + 得 + 很 + tính từ: nhận xét kỹ năng","b":"说得很流利 · 写得很好","d":"Có tân ngữ thì lặp động từ: 说汉语说得很流利, hoặc đưa tân ngữ lên trước: 汉语说得很流利.","ex":[["他开车开得很稳。","Anh ấy lái xe rất vững.","Tā kāichē kāi de hěn wěn."],["她字写得很漂亮。","Cô ấy viết chữ rất đẹp.","Tā zì xiě de hěn piàoliang."]]},"grams":[{"t":"Động từ + 得 + 很 + tính từ: nhận xét kỹ năng","b":"说得很流利 · 写得很好","d":"Có tân ngữ thì lặp động từ: 说汉语说得很流利, hoặc đưa tân ngữ lên trước: 汉语说得很流利.","ex":[["他开车开得很稳。","Anh ấy lái xe rất vững.","Tā kāichē kāi de hěn wěn."],["她字写得很漂亮。","Cô ấy viết chữ rất đẹp.","Tā zì xiě de hěn piàoliang."]]},{"t":"无法 / 不能: không thể","b":"无法 + động từ (văn viết) · 不能 + động từ (khẩu ngữ)","d":"无法 trang trọng, hay gặp trong văn bản, tin tức.","ex":[["因为下雨，比赛无法进行。","Vì mưa, trận đấu không thể diễn ra.","Yīnwèi xià yǔ, bǐsài wúfǎ jìnxíng."],["我今天不能去。","Hôm nay tôi không đi được.","Wǒ jīntiān bù néng qù."]]}],"items":[{"zh":"细心","py":"xìxīn","vi":"cẩn thận, chu đáo","hv":"tế tâm","note":"细 (tỉ mỉ) + 心.","ex":"细心的人很少犯错。","exPy":"Xìxīn de rén hěn shǎo fàncuò.","exVi":"Người cẩn thận ít khi mắc lỗi.","w":"细心 的 人 很 少 犯 错。"},{"zh":"熟","py":"shú","vi":"chín; quen; thạo","hv":"thục","note":"\"Thục\" trong \"thành thục\". Cơm chín: 饭熟了; quen thuộc: 很熟.","ex":"我们俩很熟，是老朋友了。","exPy":"Wǒmen liǎ hěn shú, shì lǎo péngyou le.","exVi":"Hai chúng tôi rất thân, là bạn cũ rồi.","w":"我们 俩 很 熟， 是 老 朋友 了。"},{"zh":"巧","py":"qiǎo","vi":"khéo; trùng hợp","hv":"xảo","note":"\"Xảo\" trong \"khéo xảo\". 真巧! (thật trùng hợp!).","ex":"真巧，我也要去那儿。","exPy":"Zhēn qiǎo, wǒ yě yào qù nàr.","exVi":"Thật trùng hợp, tôi cũng định đi đó.","w":"真 巧， 我 也 要 去 那儿。"},{"zh":"强","py":"qiáng","vi":"mạnh, giỏi","hv":"cường","note":"\"Cường\" trong \"cường quốc\".","ex":"他的学习能力很强。","exPy":"Tā de xuéxí nénglì hěn qiáng.","exVi":"Khả năng học tập của anh ấy rất mạnh.","w":"他 的 学习 能力 很 强。"},{"zh":"准","py":"zhǔn","vi":"chính xác, đúng","hv":"chuẩn","note":"Chính là \"chuẩn\".","ex":"他的发音很准。","exPy":"Tā de fāyīn hěn zhǔn.","exVi":"Phát âm của anh ấy rất chuẩn.","w":"他 的 发音 很 准。"},{"zh":"流利","py":"liúlì","vi":"lưu loát","hv":"lưu lợi","note":"Chính là \"lưu loát\".","ex":"只要每天积累，你的汉语一定会越来越流利。","exPy":"Zhǐyào měi tiān jīlěi, nǐ de Hànyǔ yídìng huì yuèláiyuè liúlì.","exVi":"Chỉ cần tích luỹ mỗi ngày, tiếng Trung của bạn nhất định ngày càng lưu loát.","w":"只要 每 天 积累， 你 的 汉语 一定 会 越 来 越 流利。"},{"zh":"积累","py":"jīlěi","vi":"tích luỹ","hv":"tích luỹ","note":"Chính là \"tích luỹ\".","ex":"学外语要每天积累生词。","exPy":"Xué wàiyǔ yào měi tiān jīlěi shēngcí.","exVi":"Học ngoại ngữ phải tích luỹ từ mới mỗi ngày.","w":"学 外语 要 每 天 积累 生 词。"},{"zh":"能够","py":"nénggòu","vi":"có thể","hv":"năng cấu","note":"Trang trọng hơn 能.","ex":"我希望能够帮助你。","exPy":"Wǒ xīwàng nénggòu bāngzhù nǐ.","exVi":"Tôi hy vọng có thể giúp bạn.","w":"我 希望 能够 帮助 你。"},{"zh":"能否","py":"néng fǒu","vi":"có thể hay không","hv":"năng phủ","note":"Văn viết của 能不能.","ex":"你能否明天来一下？","exPy":"Nǐ néng fǒu míngtiān lái yíxià?","exVi":"Mai bạn có thể đến một chút không?","w":"你 能否 明天 来 一下？"},{"zh":"无法","py":"wúfǎ","vi":"không thể","hv":"vô pháp","note":"无 (không) + 法 (cách).","ex":"我无法相信这是真的。","exPy":"Wǒ wúfǎ xiāngxìn zhè shì zhēn de.","exVi":"Tôi không thể tin đây là thật.","w":"我 无法 相信 这 是 真 的。"}],"newChars":[],"outro":"很好！Xong bài 195."};
G.ROOMS["zh-l196"] = {"id":"zh-l196","lang":"zh","level":4,"no":196,"teacher":"wang","title":"HSK4 · Bài 196 · 前方路口 Vị trí và cách thức","intro":["前方到站是北京西站。","Bài 196: Nói về phía trước, trước mắt, bên dưới, trong vòng, miền Bắc, cách thức, đối phương, khác, này và lần này. Bấm 1 · Học để bắt đầu."],"introPy":"Qiánfāng dào zhàn shì Běijīng Xī Zhàn.","gram":{"t":"以内 / 以上 / 以下","b":"số + 以内 (trong vòng) · 以上 (trở lên) · 以下 (trở xuống)","d":"Ba từ đi sau con số để giới hạn phạm vi.","ex":[["一千块以内的手机有很多。","Điện thoại dưới một nghìn tệ có rất nhiều.","Yìqiān kuài yǐnèi de shǒujī yǒu hěn duō."],["十八岁以上才能参加。","Từ mười tám tuổi trở lên mới được tham gia.","Shíbā suì yǐshàng cái néng cānjiā."]]},"grams":[{"t":"以内 / 以上 / 以下","b":"số + 以内 (trong vòng) · 以上 (trở lên) · 以下 (trở xuống)","d":"Ba từ đi sau con số để giới hạn phạm vi.","ex":[["一千块以内的手机有很多。","Điện thoại dưới một nghìn tệ có rất nhiều.","Yìqiān kuài yǐnèi de shǒujī yǒu hěn duō."],["十八岁以上才能参加。","Từ mười tám tuổi trở lên mới được tham gia.","Shíbā suì yǐshàng cái néng cānjiā."]]},{"t":"另 + 一 + lượng từ: một cái khác","b":"另一个人 · 另一件事","d":"另 đứng trước số từ.","ex":[["这是另一个问题。","Đó là một vấn đề khác.","Zhè shì lìng yí ge wèntí."],["我还有另一件事要说。","Tôi còn một việc khác muốn nói.","Wǒ hái yǒu lìng yí jiàn shì yào shuō."]]}],"items":[{"zh":"前方","py":"qiánfāng","vi":"phía trước","hv":"tiền phương","note":"Hay gặp trong thông báo giao thông: 前方到站 (ga sắp tới).","ex":"前方到站是北京西站。","exPy":"Qiánfāng dào zhàn shì Běijīng Xī Zhàn.","exVi":"Ga sắp tới là ga Bắc Kinh Tây.","w":"前方 到 站 是 北京 西 站。"},{"zh":"眼前","py":"yǎnqián","vi":"trước mắt","hv":"nhãn tiền","note":"Chính là \"nhãn tiền\".","ex":"美丽的大海出现在眼前。","exPy":"Měilì de dàhǎi chūxiàn zài yǎnqián.","exVi":"Biển đẹp hiện ra trước mắt.","w":"美丽 的 大 海 出现 在 眼前。"},{"zh":"底下","py":"dǐxia","vi":"bên dưới","hv":"để hạ","note":"Khẩu ngữ của 下面.","ex":"猫在床底下。","exPy":"Māo zài chuáng dǐxia.","exVi":"Con mèo ở dưới gầm giường.","w":"猫 在 床 底下。"},{"zh":"以内","py":"yǐnèi","vi":"trong vòng","hv":"dĩ nội","note":"Số + 以内: 一百块以内 (trong vòng một trăm tệ).","ex":"请在三天以内完成。","exPy":"Qǐng zài sān tiān yǐnèi wánchéng.","exVi":"Xin hoàn thành trong vòng ba ngày.","w":"请 在 三 天 以内 完成。"},{"zh":"北部","py":"běibù","vi":"miền bắc","hv":"bắc bộ","note":"Chính là \"Bắc Bộ\".","ex":"河内在越南北部。","exPy":"Hénèi zài Yuènán běibù.","exVi":"Hà Nội ở miền Bắc Việt Nam.","w":"河 内在 越 南 北部。"},{"zh":"方式","py":"fāngshì","vi":"cách thức","hv":"phương thức","note":"Chính là \"phương thức\".","ex":"每个人都有自己的生活方式。","exPy":"Měi ge rén dōu yǒu zìjǐ de shēnghuó fāngshì.","exVi":"Ai cũng có lối sống riêng.","w":"每 个人 都 有 自己 的 生活 方式。"},{"zh":"对方","py":"duìfāng","vi":"phía bên kia, đối phương","hv":"đối phương","note":"Chính là \"đối phương\". Cũng chỉ người đang nói chuyện với mình.","ex":"说话的时候要尊重对方。","exPy":"Shuōhuà de shíhou yào zūnzhòng duìfāng.","exVi":"Khi nói chuyện phải tôn trọng người đối diện.","w":"说话 的 时候 要 尊重 对方。"},{"zh":"另","py":"lìng","vi":"khác","hv":"lánh","note":"Hay gặp trong 另一个, 另外.","ex":"我们换另一家饭店吧。","exPy":"Wǒmen huàn lìng yì jiā fàndiàn ba.","exVi":"Mình đổi sang nhà hàng khác nhé.","w":"我们 换 另 一 家 饭店 吧。"},{"zh":"此","py":"cǐ","vi":"này, đây (văn viết)","hv":"thử","note":"Văn viết của 这. Ghép: 因此, 从此, 此外.","ex":"此次比赛共有三十个国家参加。","exPy":"Cǐ cì bǐsài gòng yǒu sānshí ge guójiā cānjiā.","exVi":"Giải đấu lần này có ba mươi quốc gia tham gia.","w":"此次 比赛 共 有 三 十 个 国家 参加。"},{"zh":"此次","py":"cǐ cì","vi":"lần này","hv":"thử thứ","note":"Văn viết của 这次.","ex":"此次会议非常重要。","exPy":"Cǐ cì huìyì fēicháng zhòngyào.","exVi":"Cuộc họp lần này rất quan trọng.","w":"此次 会议 非常 重要。"}],"newChars":[],"outro":"很好！Xong bài 196."};
G.ROOMS["zh-l197"] = {"id":"zh-l197","lang":"zh","level":4,"no":197,"teacher":"wang","title":"HSK4 · Bài 197 · 取消订单 Thao tác và đặt chỗ","intro":["订单已经取消了。","Bài 197: Nói về xem, tìm kiếm, lấy (thông tin), vào, tung ra, tạm dừng, huỷ, đặt trước, quyết định và hẹn. Bấm 1 · Học để bắt đầu."],"introPy":"Dìngdān yǐjīng qǔxiāo le.","gram":{"t":"订 và 定","b":"订 = đặt trước (vé, phòng) · 定 = quyết định, chốt","d":"Hai chữ đọc giống nhau, nghĩa khác. Đặt chỗ dùng 订, chốt kế hoạch dùng 定.","ex":[["我订了两张电影票。","Tôi đặt hai vé xem phim.","Wǒ dìng le liǎng zhāng diànyǐngpiào."],["我们定在周六见面。","Chúng ta chốt gặp nhau thứ Bảy.","Wǒmen dìng zài zhōuliù jiànmiàn."]]},"grams":[{"t":"订 và 定","b":"订 = đặt trước (vé, phòng) · 定 = quyết định, chốt","d":"Hai chữ đọc giống nhau, nghĩa khác. Đặt chỗ dùng 订, chốt kế hoạch dùng 定.","ex":[["我订了两张电影票。","Tôi đặt hai vé xem phim.","Wǒ dìng le liǎng zhāng diànyǐngpiào."],["我们定在周六见面。","Chúng ta chốt gặp nhau thứ Bảy.","Wǒmen dìng zài zhōuliù jiànmiàn."]]},{"t":"因为…，…: vì… nên…","b":"因为 + lý do，(所以) + kết quả","d":"Có thể bỏ 所以 ở vế sau.","ex":[["因为生病，他没来上课。","Vì ốm, cậu ấy không đến lớp.","Yīnwèi shēngbìng, tā méi lái shàngkè."],["因为太忙，所以我取消了旅行。","Vì quá bận nên tôi huỷ chuyến đi.","Yīnwèi tài máng, suǒyǐ wǒ qǔxiāo le lǚxíng."]]}],"items":[{"zh":"查看","py":"chákàn","vi":"xem, kiểm tra","hv":"tra khán","note":"查 + 看. Xem chi tiết trên ứng dụng: 查看详情.","ex":"你可以在手机上查看成绩。","exPy":"Nǐ kěyǐ zài shǒujī shang chákàn chéngjì.","exVi":"Bạn có thể xem điểm trên điện thoại.","w":"你 可以 在 手机 上 查看 成绩。"},{"zh":"查找","py":"cházhǎo","vi":"tìm kiếm, tra tìm","hv":"tra trảo","note":"查 + 找.","ex":"我在网上查找资料。","exPy":"Wǒ zài wǎngshang cházhǎo zīliào.","exVi":"Tôi tìm tài liệu trên mạng.","w":"我 在 网上 查找 资料。"},{"zh":"获取","py":"huòqǔ","vi":"thu được, lấy được","hv":"hoạch thủ","note":"Trang trọng. 获取信息 (thu thập thông tin).","ex":"我们从网上获取信息。","exPy":"Wǒmen cóng wǎngshang huòqǔ xìnxī.","exVi":"Chúng ta lấy thông tin từ mạng.","w":"我们 从 网上 获取 信息。"},{"zh":"进入","py":"jìnrù","vi":"đi vào","hv":"tiến nhập","note":"Trang trọng hơn 进.","ex":"比赛进入了最后一分钟。","exPy":"Bǐsài jìnrù le zuìhòu yì fēnzhōng.","exVi":"Trận đấu bước vào phút cuối cùng.","w":"比赛 进入 了 最后 一 分钟。"},{"zh":"推出","py":"tuīchū","vi":"tung ra, ra mắt","hv":"suy xuất","note":"推 (đẩy) + 出. Ra mắt sản phẩm mới.","ex":"这家店每个月都推出新菜。","exPy":"Zhè jiā diàn měi ge yuè dōu tuīchū xīn cài.","exVi":"Quán này tháng nào cũng ra món mới.","w":"这 家 店 每 个 月 都 推出 新 菜。"},{"zh":"暂停","py":"zàntíng","vi":"tạm dừng","hv":"tạm đình","note":"Chính là \"tạm đình\".","ex":"视频可以暂停一下吗？","exPy":"Shìpín kěyǐ zàntíng yíxià ma?","exVi":"Có thể tạm dừng video một chút không?","w":"视频 可以 暂停 一下 吗？"},{"zh":"取消","py":"qǔxiāo","vi":"huỷ bỏ","hv":"thủ tiêu","note":"Khác \"thủ tiêu\" (giết) tiếng Việt: 取消 là huỷ (đơn, chuyến bay).","ex":"订单已经取消了。","exPy":"Dìngdān yǐjīng qǔxiāo le.","exVi":"Đơn hàng đã bị huỷ.","w":"订单 已经 取消 了。"},{"zh":"订","py":"dìng","vi":"đặt trước","hv":"đính","note":"Đặt phòng 订房间, đặt vé 订票.","ex":"我已经订好了酒店。","exPy":"Wǒ yǐjīng dìng hǎo le jiǔdiàn.","exVi":"Tôi đã đặt xong khách sạn.","w":"我 已经 订 好 了 酒店。"},{"zh":"定","py":"dìng","vi":"quyết định, định","hv":"định","note":"\"Định\" trong \"quyết định\". 定了 (đã chốt).","ex":"时间定了吗？","exPy":"Shíjiān dìng le ma?","exVi":"Đã chốt thời gian chưa?","w":"时间 定 了 吗？"},{"zh":"约","py":"yuē","vi":"hẹn","hv":"ước","note":"\"Ước\" trong \"ước hẹn\". Hẹn gặp: 约好了.","ex":"我们约好下午三点见面。","exPy":"Wǒmen yuē hǎo xiàwǔ sān diǎn jiànmiàn.","exVi":"Chúng ta hẹn ba giờ chiều gặp nhau.","w":"我们 约 好 下午 三 点 见面。"}],"newChars":["订"],"outro":"很好！Xong bài 197."};
G.ROOMS["zh-l198"] = {"id":"zh-l198","lang":"zh","level":4,"no":198,"teacher":"wang","title":"HSK4 · Bài 198 · 各种职业 Nghề nghiệp và vai trò","intro":["他从小的梦想就是当警察。","Bài 198: Nói về đầu bếp, cảnh sát, khách hàng, độc giả, thính giả, hội viên, nhân viên bán vé, nghề nghiệp, nhóm và tổ. Bấm 1 · Học để bắt đầu."],"introPy":"Tā cóngxiǎo de mèngxiǎng jiù shì dāng jǐngchá.","gram":{"t":"打折: giảm giá kiểu Trung Quốc","b":"打九折 = giảm 10% · 打八折 = giảm 20%","d":"Con số là phần trăm phải trả (90%, 80%), ngược với cách nói \"giảm…\" của người Việt.","ex":[["这件衣服打七折。","Bộ đồ này giảm 30%.","Zhè jiàn yīfu dǎ qī zhé."],["周末所有商品打八折。","Cuối tuần mọi mặt hàng giảm 20%.","Zhōumò suǒyǒu shāngpǐn dǎ bā zhé."]]},"grams":[{"t":"打折: giảm giá kiểu Trung Quốc","b":"打九折 = giảm 10% · 打八折 = giảm 20%","d":"Con số là phần trăm phải trả (90%, 80%), ngược với cách nói \"giảm…\" của người Việt.","ex":[["这件衣服打七折。","Bộ đồ này giảm 30%.","Zhè jiàn yīfu dǎ qī zhé."],["周末所有商品打八折。","Cuối tuần mọi mặt hàng giảm 20%.","Zhōumò suǒyǒu shāngpǐn dǎ bā zhé."]]},{"t":"受到 + sự yêu thích / giúp đỡ","b":"受到欢迎 · 受到喜爱 · 受到帮助","d":"Nhận được (thái độ, sự đối xử) từ người khác.","ex":[["这个节目很受观众欢迎。","Chương trình này rất được khán giả yêu thích.","Zhège jiémù hěn shòu guānzhòng huānyíng."],["我受到了很多人的帮助。","Tôi nhận được sự giúp đỡ của rất nhiều người.","Wǒ shòudào le hěn duō rén de bāngzhù."]]}],"items":[{"zh":"厨师","py":"chúshī","vi":"đầu bếp","hv":"trù sư","note":"厨 (bếp, \"trù\") + 师.","ex":"他是一名中餐厨师。","exPy":"Tā shì yì míng zhōngcān chúshī.","exVi":"Anh ấy là đầu bếp món Trung.","w":"他 是 一 名 中餐 厨师。"},{"zh":"警察","py":"jǐngchá","vi":"cảnh sát","hv":"cảnh sát","note":"Chính là \"cảnh sát\".","ex":"他从小的梦想就是当警察。","exPy":"Tā cóngxiǎo de mèngxiǎng jiù shì dāng jǐngchá.","exVi":"Ước mơ từ nhỏ của cậu ấy là làm cảnh sát.","w":"他 从小 的 梦想 就是 当 警察。"},{"zh":"顾客","py":"gùkè","vi":"khách hàng","hv":"cố khách","note":"Khách mua hàng, khách của cửa hàng.","ex":"这家店对顾客很热情。","exPy":"Zhè jiā diàn duì gùkè hěn rèqíng.","exVi":"Cửa hàng này rất nhiệt tình với khách.","w":"这 家 店 对 顾客 很 热情。"},{"zh":"读者","py":"dúzhě","vi":"độc giả","hv":"độc giả","note":"Chính là \"độc giả\".","ex":"这本书受到读者的喜爱。","exPy":"Zhè běn shū shòudào dúzhě de xǐ'ài.","exVi":"Cuốn sách này được độc giả yêu thích.","w":"这 本 书 受到 读者 的 喜爱。"},{"zh":"听众","py":"tīngzhòng","vi":"thính giả","hv":"thính chúng","note":"听 + 众 (đám đông).","ex":"各位听众，晚上好。","exPy":"Gèwèi tīngzhòng, wǎnshang hǎo.","exVi":"Thưa quý thính giả, chào buổi tối.","w":"各位 听众， 晚上 好。"},{"zh":"会员","py":"huìyuán","vi":"hội viên, thành viên","hv":"hội viên","note":"Chính là \"hội viên\". Thẻ hội viên là 会员卡.","ex":"会员可以打九折。","exPy":"Huìyuán kěyǐ dǎ jiǔ zhé.","exVi":"Hội viên được giảm mười phần trăm.","w":"会员 可以 打 九 折。"},{"zh":"售票员","py":"shòupiàoyuán","vi":"nhân viên bán vé","hv":"thụ phiếu viên","note":"售 (bán) + 票 + 员.","ex":"售票员告诉我票已经卖完了。","exPy":"Shòupiàoyuán gàosu wǒ piào yǐjīng mài wán le.","exVi":"Nhân viên bán vé bảo tôi vé đã bán hết.","w":"售票员 告诉 我 票 已经 卖 完 了。"},{"zh":"职业","py":"zhíyè","vi":"nghề nghiệp","hv":"chức nghiệp","note":"Chính là \"chức nghiệp\" (nghề).","ex":"选择职业的时候，要考虑自己的兴趣。","exPy":"Xuǎnzé zhíyè de shíhou, yào kǎolǜ zìjǐ de xìngqù.","exVi":"Khi chọn nghề, phải cân nhắc sở thích của mình.","w":"选择 职业 的 时候， 要 考虑 自己 的 兴趣。"},{"zh":"小组","py":"xiǎozǔ","vi":"nhóm nhỏ","hv":"tiểu tổ","note":"小 + 组 (tổ).","ex":"每个小组选一个代表。","exPy":"Měi ge xiǎozǔ xuǎn yí ge dàibiǎo.","exVi":"Mỗi nhóm chọn một đại diện.","w":"每 个 小组 选 一 个 代表。"},{"zh":"组","py":"zǔ","vi":"tổ, nhóm","hv":"tổ","note":"\"Tổ\" trong \"tổ chức\".","ex":"我们组有五个人。","exPy":"Wǒmen zǔ yǒu wǔ ge rén.","exVi":"Tổ chúng tôi có năm người.","w":"我们 组 有 五 个人。"}],"newChars":["察","职","组"],"outro":"很好！Xong bài 198."};
G.ROOMS["zh-l199"] = {"id":"zh-l199","lang":"zh","level":4,"no":199,"teacher":"wang","title":"HSK4 · Bài 199 · 公共场所 Không gian chung và thế giới","intro":["地铁站的出口很多，别走错了。","Bài 199: Nói về sân vận động, sảnh, lối ra, công cộng, toàn cầu, khoa học công nghệ, tác phẩm, hiện có, có và đối mặt. Bấm 1 · Học để bắt đầu."],"introPy":"Dìtiězhàn de chūkǒu hěn duō, bié zǒu cuò le.","gram":{"t":"在…上 / 在…里: trên mặt, trong lòng","b":"在操场上 · 在大厅里","d":"Sân, mặt bàn dùng 上; phòng, toà nhà dùng 里.","ex":[["孩子们在操场上玩儿。","Bọn trẻ chơi trên sân.","Háizimen zài cāochǎng shang wánr."],["很多人在大厅里等着。","Nhiều người đang đợi trong sảnh.","Hěn duō rén zài dàtīng lǐ děng zhe."]]},"grams":[{"t":"在…上 / 在…里: trên mặt, trong lòng","b":"在操场上 · 在大厅里","d":"Sân, mặt bàn dùng 上; phòng, toà nhà dùng 里.","ex":[["孩子们在操场上玩儿。","Bọn trẻ chơi trên sân.","Háizimen zài cāochǎng shang wánr."],["很多人在大厅里等着。","Nhiều người đang đợi trong sảnh.","Hěn duō rén zài dàtīng lǐ děng zhe."]]},{"t":"Tính từ + 地 + động từ: trạng từ","b":"勇敢地面对 · 认真地学习","d":"地 (de) nối tính từ với động từ để chỉ cách làm.","ex":[["他高兴地笑了。","Anh ấy vui vẻ cười.","Tā gāoxìng de xiào le."],["请慢慢地说。","Xin nói từ từ.","Qǐng mànmàn de shuō."]]}],"items":[{"zh":"操场","py":"cāochǎng","vi":"sân vận động (trường)","hv":"thao trường","note":"Chính là \"thao trường\".","ex":"下课后学生们在操场上跑步。","exPy":"Xiàkè hòu xuéshengmen zài cāochǎng shang pǎobù.","exVi":"Tan học học sinh chạy bộ trên sân trường.","w":"下课 后 学生 们 在 操场 上 跑步。"},{"zh":"大厅","py":"dàtīng","vi":"đại sảnh","hv":"đại sảnh","note":"Chính là \"đại sảnh\".","ex":"我在酒店大厅等你。","exPy":"Wǒ zài jiǔdiàn dàtīng děng nǐ.","exVi":"Tôi đợi bạn ở sảnh khách sạn.","w":"我 在 酒店 大厅 等 你。"},{"zh":"出口","py":"chūkǒu","vi":"lối ra; xuất khẩu","hv":"xuất khẩu","note":"Hai nghĩa: lối ra (ở nhà ga) và \"xuất khẩu\" hàng hoá.","ex":"地铁站的出口很多，别走错了。","exPy":"Dìtiězhàn de chūkǒu hěn duō, bié zǒu cuò le.","exVi":"Ga tàu điện có nhiều lối ra, đừng đi nhầm.","w":"地铁 站 的 出口 很 多， 别 走 错 了。"},{"zh":"公共","py":"gōnggòng","vi":"công cộng","hv":"công cộng","note":"Chính là \"công cộng\".","ex":"公共交通越来越方便。","exPy":"Gōnggòng jiāotōng yuèláiyuè fāngbiàn.","exVi":"Giao thông công cộng ngày càng tiện lợi.","w":"公共 交通 越 来 越 方便。"},{"zh":"全球","py":"quánqiú","vi":"toàn cầu","hv":"toàn cầu","note":"Chính là \"toàn cầu\".","ex":"他的作品在全球都很有名。","exPy":"Tā de zuòpǐn zài quánqiú dōu hěn yǒumíng.","exVi":"Tác phẩm của ông ấy nổi tiếng toàn cầu.","w":"他 的 作品 在 全球 都 很 有名。"},{"zh":"科技","py":"kējì","vi":"khoa học công nghệ","hv":"khoa kỹ","note":"Viết tắt của 科学技术.","ex":"科技改变了我们的生活。","exPy":"Kējì gǎibiàn le wǒmen de shēnghuó.","exVi":"Khoa học công nghệ thay đổi cuộc sống chúng ta.","w":"科技 改变 了 我们 的 生活。"},{"zh":"作品","py":"zuòpǐn","vi":"tác phẩm","hv":"tác phẩm","note":"Chính là \"tác phẩm\".","ex":"这是他最有名的作品。","exPy":"Zhè shì tā zuì yǒumíng de zuòpǐn.","exVi":"Đây là tác phẩm nổi tiếng nhất của ông ấy.","w":"这 是 他 最 有名 的 作品。"},{"zh":"现有","py":"xiànyǒu","vi":"hiện có","hv":"hiện hữu","note":"Chính là \"hiện hữu\".","ex":"现有的问题要马上解决。","exPy":"Xiànyǒu de wèntí yào mǎshàng jiějué.","exVi":"Những vấn đề hiện có phải giải quyết ngay.","w":"现有 的 问题 要 马上 解决。"},{"zh":"有着","py":"yǒuzhe","vi":"có (văn viết)","hv":"hữu trước","note":"Văn viết, nhấn mạnh trạng thái: 有着悠久的历史.","ex":"这座城市有着很长的历史。","exPy":"Zhè zuò chéngshì yǒuzhe hěn cháng de lìshǐ.","exVi":"Thành phố này có lịch sử rất lâu đời.","w":"这 座 城市 有着 很 长 的 历史。"},{"zh":"面对","py":"miànduì","vi":"đối mặt","hv":"diện đối","note":"Chính là \"diện đối\".","ex":"面对问题，不要害怕。","exPy":"Miànduì wèntí, búyào hàipà.","exVi":"Đối mặt vấn đề, đừng sợ hãi.","w":"面对 问题， 不要 害怕。"}],"newChars":["操"],"outro":"很好！Xong bài 199."};
G.ROOMS["zh-l200"] = {"id":"zh-l200","lang":"zh","level":4,"no":200,"teacher":"wang","title":"HSK4 · Bài 200 · 按时完成 Động từ một chữ thường dùng","intro":["文章写完了，再改一改。","Bài 200: Dùng các động từ: ấn / theo, sửa, quản, ở lại, đổ / rót, tính, thông, thiếu, vào và sinh. Bấm 1 · Học để bắt đầu."],"introPy":"Wénzhāng xiě wán le, zài gǎi yi gǎi.","gram":{"t":"按 / 按照 + quy định: theo","b":"按时 · 按照计划","d":"Làm việc theo một tiêu chuẩn có sẵn.","ex":[["请按时完成作业。","Xin hoàn thành bài tập đúng hạn.","Qǐng ànshí wánchéng zuòyè."],["我们按照计划做吧。","Chúng ta làm theo kế hoạch nhé.","Wǒmen ànzhào jìhuà zuò ba."]]},"grams":[{"t":"按 / 按照 + quy định: theo","b":"按时 · 按照计划","d":"Làm việc theo một tiêu chuẩn có sẵn.","ex":[["请按时完成作业。","Xin hoàn thành bài tập đúng hạn.","Qǐng ànshí wánchéng zuòyè."],["我们按照计划做吧。","Chúng ta làm theo kế hoạch nhé.","Wǒmen ànzhào jìhuà zuò ba."]]},{"t":"算了: thôi bỏ đi","b":"算了 · 就算了吧","d":"Dùng khi bỏ qua, không tính toán nữa.","ex":[["他不来就算了。","Anh ấy không đến thì thôi.","Tā bù lái jiù suàn le."],["太贵了，算了吧。","Đắt quá, thôi bỏ đi.","Tài guì le, suàn le ba."]]}],"items":[{"zh":"按","py":"àn","vi":"ấn; theo","hv":"án","note":"Ấn nút: 按电梯. Làm theo: 按时 (đúng giờ), 按照.","ex":"请按一下电梯。","exPy":"Qǐng àn yíxià diàntī.","exVi":"Xin bấm thang máy giúp.","w":"请 按 一下 电梯。"},{"zh":"改","py":"gǎi","vi":"sửa, đổi","hv":"cải","note":"\"Cải\" trong \"cải cách\", \"cải tạo\".","ex":"文章写完了，再改一改。","exPy":"Wénzhāng xiě wán le, zài gǎi yi gǎi.","exVi":"Viết xong bài rồi, sửa lại chút nữa.","w":"文章 写 完 了， 再 改 一 改。"},{"zh":"管","py":"guǎn","vi":"quản lý; lo","hv":"quản","note":"\"Quản\" trong \"quản lý\". 别管我 (đừng lo cho tôi, kệ tôi).","ex":"这件事你别管了。","exPy":"Zhè jiàn shì nǐ bié guǎn le.","exVi":"Chuyện này bạn đừng lo nữa.","w":"这 件 事 你 别 管 了。"},{"zh":"待","py":"dāi","vi":"ở lại","hv":"đãi","note":"Khẩu ngữ, nghĩa như 呆: 在家待着.","ex":"周末我在家待了两天。","exPy":"Zhōumò wǒ zài jiā dāi le liǎng tiān.","exVi":"Cuối tuần tôi ở nhà hai ngày.","w":"周末 我 在 家 待 了 两 天。"},{"zh":"倒","py":"dào","vi":"rót, đổ; ngược","hv":"đảo","note":"Đọc dào: rót nước 倒水, đổ rác 倒垃圾. Đọc dǎo: ngã.","ex":"我给你倒杯茶。","exPy":"Wǒ gěi nǐ dào bēi chá.","exVi":"Tôi rót cho bạn cốc trà.","w":"我 给 你 倒 杯 茶。"},{"zh":"算","py":"suàn","vi":"tính; coi như","hv":"toán","note":"\"Toán\" trong \"tính toán\". 算了 là \"thôi bỏ đi\".","ex":"我们算一下一共多少钱。","exPy":"Wǒmen suàn yíxià yígòng duōshao qián.","exVi":"Mình tính xem tổng cộng bao nhiêu tiền.","w":"我们 算 一下 一共 多少 钱。"},{"zh":"通","py":"tōng","vi":"thông; thông suốt","hv":"thông","note":"Chính là \"thông\". Điện thoại gọi được: 电话通了.","ex":"电话打不通。","exPy":"Diànhuà dǎ bu tōng.","exVi":"Điện thoại gọi không được.","w":"电话 打 不 通。"},{"zh":"缺","py":"quē","vi":"thiếu","hv":"khuyết","note":"\"Khuyết\" trong \"khuyết điểm\". 缺钱 (thiếu tiền).","ex":"这个城市不缺好饭店。","exPy":"Zhège chéngshì bù quē hǎo fàndiàn.","exVi":"Thành phố này không thiếu nhà hàng ngon.","w":"这个 城市 不 缺 好 饭店。"},{"zh":"入","py":"rù","vi":"vào","hv":"nhập","note":"Chính là \"nhập\". Văn viết của 进. 入口 là lối vào.","ex":"入口在左边。","exPy":"Rùkǒu zài zuǒbian.","exVi":"Lối vào ở bên trái.","w":"入口 在 左边。"},{"zh":"生","py":"shēng","vi":"sinh ra; sống","hv":"sinh","note":"Chính là \"sinh\". 生孩子 (sinh con), 生病 (bị bệnh).","ex":"他在北京生活了十年。","exPy":"Tā zài Běijīng shēnghuó le shí nián.","exVi":"Anh ấy sống ở Bắc Kinh mười năm.","w":"他 在 北京 生活 了 十 年。"}],"newChars":["待","倒"],"outro":"很好！Xong bài 200."};
G.ROOMS["zh-l201"] = {"id":"zh-l201","lang":"zh","level":4,"no":201,"teacher":"wang","title":"HSK4 · Bài 201 · 加入我们 Động từ hai chữ thường dùng","intro":["很多年轻人想加入这家公司。","Bài 201: Dùng các động từ: gia nhập, phát ra, mang lại (tác dụng), dùng để, dùng cho, tiện cho, chia thành, gọi là, tránh xa và ra ngoài. Bấm 1 · Học để bắt đầu."],"introPy":"Hěn duō niánqīng rén xiǎng jiārù zhè jiā gōngsī.","gram":{"t":"起到…作用: có tác dụng","b":"起到 + tính từ + 的 + 作用","d":"Cụm cố định nói về hiệu quả của một việc.","ex":[["运动对健康起到重要作用。","Vận động có tác dụng quan trọng với sức khoẻ.","Yùndòng duì jiànkāng qǐdào zhòngyào zuòyòng."],["老师的话起到了作用。","Lời thầy đã có tác dụng.","Lǎoshī de huà qǐdào le zuòyòng."]]},"grams":[{"t":"起到…作用: có tác dụng","b":"起到 + tính từ + 的 + 作用","d":"Cụm cố định nói về hiệu quả của một việc.","ex":[["运动对健康起到重要作用。","Vận động có tác dụng quan trọng với sức khoẻ.","Yùndòng duì jiànkāng qǐdào zhòngyào zuòyòng."],["老师的话起到了作用。","Lời thầy đã có tác dụng.","Lǎoshī de huà qǐdào le zuòyòng."]]},{"t":"用来 / 用于: dùng để","b":"Vật + 用来 + động từ · Vật + 用于 + danh từ / động từ","d":"用来 khẩu ngữ hơn, 用于 văn viết hơn.","ex":[["这个房间用来开会。","Phòng này dùng để họp.","Zhège fángjiān yònglái kāihuì."],["这种药用于治疗感冒。","Thuốc này dùng để chữa cảm.","Zhè zhǒng yào yòngyú zhìliáo gǎnmào."]]}],"items":[{"zh":"加入","py":"jiārù","vi":"gia nhập, tham gia","hv":"gia nhập","note":"Chính là \"gia nhập\".","ex":"很多年轻人想加入这家公司。","exPy":"Hěn duō niánqīng rén xiǎng jiārù zhè jiā gōngsī.","exVi":"Nhiều người trẻ muốn vào công ty này.","w":"很 多 年轻 人 想 加入 这 家 公司。"},{"zh":"发出","py":"fāchū","vi":"phát ra","hv":"phát xuất","note":"发 + 出. Phát ra âm thanh, ánh sáng.","ex":"手机发出了声音。","exPy":"Shǒujī fāchū le shēngyīn.","exVi":"Điện thoại phát ra tiếng.","w":"手机 发出 了 声音。"},{"zh":"起到","py":"qǐdào","vi":"mang lại (tác dụng)","hv":"khởi đáo","note":"Đi với 作用: 起到作用.","ex":"这个办法起到了很好的作用。","exPy":"Zhège bànfǎ qǐdào le hěn hǎo de zuòyòng.","exVi":"Cách này đã mang lại tác dụng tốt.","w":"这个 办法 起到 了 很 好 的 作用。"},{"zh":"用来","py":"yònglái","vi":"dùng để","hv":"dụng lai","note":"Vật + 用来 + làm gì.","ex":"这个盒子用来放笔。","exPy":"Zhège hézi yònglái fàng bǐ.","exVi":"Cái hộp này dùng để đựng bút.","w":"这个 盒子 用来 放 笔。"},{"zh":"用于","py":"yòngyú","vi":"dùng cho, dùng vào","hv":"dụng vu","note":"Văn viết của 用在.","ex":"这笔钱用于买书。","exPy":"Zhè bǐ qián yòngyú mǎi shū.","exVi":"Khoản tiền này dùng để mua sách.","w":"这 笔 钱 用于 买 书。"},{"zh":"便于","py":"biànyú","vi":"tiện cho","hv":"tiện vu","note":"便 (tiện) + 于.","ex":"把东西放好，便于查找。","exPy":"Bǎ dōngxi fàng hǎo, biànyú cházhǎo.","exVi":"Để đồ gọn gàng cho dễ tìm.","w":"把 东西 放 好， 便于 查找。"},{"zh":"分为","py":"fēnwéi","vi":"chia thành","hv":"phân vi","note":"Văn viết của 分成.","ex":"比赛分为上半场和下半场。","exPy":"Bǐsài fēnwéi shàngbànchǎng hé xiàbànchǎng.","exVi":"Trận đấu chia thành hiệp một và hiệp hai.","w":"比赛 分为 上半场 和 下半场。"},{"zh":"叫作","py":"jiàozuò","vi":"gọi là","hv":"khiếu tác","note":"Đặt tên, giải thích tên gọi.","ex":"这种花叫作牡丹。","exPy":"Zhè zhǒng huā jiàozuò mǔdan.","exVi":"Loài hoa này gọi là mẫu đơn.","w":"这 种 花 叫作 牡丹。"},{"zh":"远离","py":"yuǎnlí","vi":"tránh xa","hv":"viễn ly","note":"远 (xa) + 离 (rời).","ex":"远离手机，多陪陪家人。","exPy":"Yuǎnlí shǒujī, duō péipei jiārén.","exVi":"Tránh xa điện thoại, dành thời gian cho gia đình.","w":"远离 手机， 多 陪 陪 家人。"},{"zh":"外出","py":"wàichū","vi":"ra ngoài, đi vắng","hv":"ngoại xuất","note":"Trang trọng hơn 出去.","ex":"外出的时候要注意安全。","exPy":"Wàichū de shíhou yào zhùyì ānquán.","exVi":"Khi ra ngoài phải chú ý an toàn.","w":"外出 的 时候 要 注意 安全。"}],"newChars":[],"outro":"很好！Xong bài 201."};
G.ROOMS["zh-l202"] = {"id":"zh-l202","lang":"zh","level":4,"no":202,"teacher":"wang","title":"HSK4 · Bài 202 · 不必担心 Phó từ chỉ thái độ","intro":["输了不要紧，重要的是从中学到东西。","Bài 202: Dùng: không cần, bất tiện, không ngừng, không đủ, cố ý, cho tốt, lẫn nhau, từ trong đó, cuối cùng và đợi đến khi. Bấm 1 · Học để bắt đầu."],"introPy":"Shū le bú yàojǐn, zhòngyào de shì cóngzhōng xué dào dōngxi.","gram":{"t":"不是故意的: không cố ý","b":"我不是故意的","d":"Câu xin lỗi rất hay dùng khi lỡ làm sai.","ex":[["他不是故意迟到的。","Anh ấy không cố ý đến muộn.","Tā bú shì gùyì chídào de."],["对不起，我不是故意说错的。","Xin lỗi, tôi không cố ý nói sai.","Duìbuqǐ, wǒ bú shì gùyì shuō cuò de."]]},"grams":[{"t":"不是故意的: không cố ý","b":"我不是故意的","d":"Câu xin lỗi rất hay dùng khi lỡ làm sai.","ex":[["他不是故意迟到的。","Anh ấy không cố ý đến muộn.","Tā bú shì gùyì chídào de."],["对不起，我不是故意说错的。","Xin lỗi, tôi không cố ý nói sai.","Duìbuqǐ, wǒ bú shì gùyì shuō cuò de."]]},{"t":"等到…再 / 才…: đợi đến… mới…","b":"等到 + điều kiện，再 / 才 + hành động","d":"再 cho kế hoạch tương lai, 才 cho việc đã xảy ra muộn.","ex":[["等到你回来，我们再吃饭。","Đợi bạn về, chúng ta rồi mới ăn cơm.","Děngdào nǐ huílai, wǒmen zài chīfàn."],["等到天黑，他才回家。","Đợi đến khi trời tối, anh ấy mới về nhà.","Děngdào tiān hēi, tā cái huí jiā."]]}],"items":[{"zh":"不必","py":"búbì","vi":"không cần","hv":"bất tất","note":"Chính là \"bất tất\". Trang trọng hơn 不用.","ex":"你不必担心。","exPy":"Nǐ búbì dānxīn.","exVi":"Bạn không cần lo.","w":"你 不必 担心。"},{"zh":"不便","py":"búbiàn","vi":"bất tiện","hv":"bất tiện","note":"Chính là \"bất tiện\".","ex":"给您带来不便，非常抱歉。","exPy":"Gěi nín dài lái búbiàn, fēicháng bàoqiàn.","exVi":"Gây bất tiện cho quý khách, chúng tôi rất xin lỗi.","w":"给 您 带 来 不便， 非常 抱歉。"},{"zh":"不断","py":"búduàn","vi":"không ngừng","hv":"bất đoạn","note":"Chính là \"bất đoạn\".","ex":"只有不断练习，才能不断进步。","exPy":"Zhǐyǒu búduàn liànxí, cái néng búduàn jìnbù.","exVi":"Chỉ có luyện tập không ngừng mới tiến bộ không ngừng.","w":"只有 不断 练习， 才能 不断 进步。"},{"zh":"不够","py":"búgòu","vi":"không đủ","hv":"bất cấu","note":"不 + 够 (đủ).","ex":"时间不够了，快点儿。","exPy":"Shíjiān búgòu le, kuài diǎnr.","exVi":"Không đủ thời gian rồi, nhanh lên.","w":"时间 不够 了， 快 点 儿。"},{"zh":"故意","py":"gùyì","vi":"cố ý","hv":"cố ý","note":"Chính là \"cố ý\".","ex":"对不起，我不是故意的。","exPy":"Duìbuqǐ, wǒ bú shì gùyì de.","exVi":"Xin lỗi, tôi không cố ý.","w":"对不起， 我 不 是 故意 的。"},{"zh":"好好","py":"hǎohǎo","vi":"cho tốt, đàng hoàng","hv":"hảo hảo","note":"Đứng trước động từ: 好好学习 (học cho tốt).","ex":"你要好好休息。","exPy":"Nǐ yào hǎohǎo xiūxi.","exVi":"Bạn phải nghỉ ngơi cho đàng hoàng.","w":"你 要好 好 休息。"},{"zh":"相互","py":"xiānghù","vi":"lẫn nhau","hv":"tương hỗ","note":"Chính là \"tương hỗ\". Giống 互相.","ex":"队员之间要相互支持。","exPy":"Duìyuán zhījiān yào xiānghù zhīchí.","exVi":"Đồng đội phải hỗ trợ lẫn nhau.","w":"队员 之间 要 相互 支持。"},{"zh":"从中","py":"cóngzhōng","vi":"từ trong đó","hv":"tòng trung","note":"Rút ra bài học từ một việc: 从中学到.","ex":"输了不要紧，重要的是从中学到东西。","exPy":"Shū le bú yàojǐn, zhòngyào de shì cóngzhōng xué dào dōngxi.","exVi":"Thua không sao, quan trọng là học được điều gì từ đó.","w":"输 了 不要紧， 重要 的 是 从中 学 到 东西。"},{"zh":"最终","py":"zuìzhōng","vi":"cuối cùng","hv":"tối chung","note":"Kết quả sau cùng.","ex":"最终的结果还不知道。","exPy":"Zuìzhōng de jiéguǒ hái bù zhīdào.","exVi":"Kết quả cuối cùng vẫn chưa biết.","w":"最终 的 结果 还 不 知道。"},{"zh":"等到","py":"děngdào","vi":"đợi đến khi","hv":"đẳng đáo","note":"等到 + thời điểm / sự việc，再 / 才….","ex":"等到放假，我们去旅行。","exPy":"Děngdào fàngjià, wǒmen qù lǚxíng.","exVi":"Đợi đến kỳ nghỉ, chúng ta đi du lịch.","w":"等到 放假， 我们 去 旅行。"}],"newChars":[],"outro":"很好！Xong bài 202."};
G.ROOMS["zh-l203"] = {"id":"zh-l203","lang":"zh","level":4,"no":203,"teacher":"wang","title":"HSK4 · Bài 203 · 做了一个梦 Thân thể, lòng người và cuộc sống","intro":["学习是活到老学到老的事。","Bài 203: Nói về thân, lòng, hơi / tức giận, mùi vị, đẹp, sống, đời người, nằm mơ, cháy và muộn. Bấm 1 · Học để bắt đầu."],"introPy":"Xuéxí shì huó dào lǎo xué dào lǎo de shì.","gram":{"t":"Động từ ly hợp: 做梦, 生气, 着火","b":"做了一个梦 · 生他的气 · 着了火","d":"Các động từ hai chữ này tách ra được, chèn số lượng, đối tượng vào giữa.","ex":[["你别生我的气。","Bạn đừng giận tôi.","Nǐ bié shēng wǒ de qì."],["我做了一个好梦。","Tôi mơ một giấc mơ đẹp.","Wǒ zuò le yí ge hǎo mèng."]]},"grams":[{"t":"Động từ ly hợp: 做梦, 生气, 着火","b":"做了一个梦 · 生他的气 · 着了火","d":"Các động từ hai chữ này tách ra được, chèn số lượng, đối tượng vào giữa.","ex":[["你别生我的气。","Bạn đừng giận tôi.","Nǐ bié shēng wǒ de qì."],["我做了一个好梦。","Tôi mơ một giấc mơ đẹp.","Wǒ zuò le yí ge hǎo mèng."]]},{"t":"还不迟 / 还来得及: vẫn kịp","b":"现在…还不迟","d":"An ủi, khích lệ rằng chưa muộn.","ex":[["学外语什么时候开始都不迟。","Học ngoại ngữ bắt đầu lúc nào cũng không muộn.","Xué wàiyǔ shénme shíhou kāishǐ dōu bù chí."],["现在走还来得及。","Đi bây giờ vẫn còn kịp.","Xiànzài zǒu hái láidejí."]]}],"items":[{"zh":"身","py":"shēn","vi":"thân, người","hv":"thân","note":"\"Thân\" trong \"thân thể\". Làm lượng từ cho bộ quần áo: 一身衣服.","ex":"他穿了一身新衣服。","exPy":"Tā chuān le yì shēn xīn yīfu.","exVi":"Anh ấy mặc một bộ quần áo mới.","w":"他 穿 了 一身 新 衣服。"},{"zh":"心","py":"xīn","vi":"tim; lòng","hv":"tâm","note":"\"Tâm\" trong \"tâm hồn\". 小心 (cẩn thận), 放心 (yên tâm).","ex":"他的心很好。","exPy":"Tā de xīn hěn hǎo.","exVi":"Anh ấy rất tốt bụng.","w":"他 的 心 很 好。"},{"zh":"气","py":"qì","vi":"hơi, khí; tức giận","hv":"khí","note":"\"Khí\" trong \"không khí\". 生气 là tức giận.","ex":"他气得说不出话来。","exPy":"Tā qì de shuō bu chū huà lái.","exVi":"Anh ấy tức đến không nói nên lời.","w":"他 气 得 说 不 出 话 来。"},{"zh":"味","py":"wèi","vi":"vị, mùi","hv":"vị","note":"\"Vị\" trong \"mùi vị\". 味道 cũng là mùi vị.","ex":"这道菜的味道很特别。","exPy":"Zhè dào cài de wèidao hěn tèbié.","exVi":"Món này mùi vị rất đặc biệt.","w":"这 道 菜 的 味道 很 特别。"},{"zh":"美","py":"měi","vi":"đẹp","hv":"mỹ","note":"Chính là \"mỹ\". 美国 là nước Mỹ.","ex":"这里的风景真美。","exPy":"Zhèlǐ de fēngjǐng zhēn měi.","exVi":"Phong cảnh ở đây đẹp thật.","w":"这里 的 风景 真 美。"},{"zh":"活","py":"huó","vi":"sống","hv":"hoạt","note":"\"Hoạt\" trong \"sinh hoạt\". 活着 (đang sống), 干活儿 (làm việc).","ex":"学习是活到老学到老的事。","exPy":"Xuéxí shì huó dào lǎo xué dào lǎo de shì.","exVi":"Học là việc sống đến già học đến già.","w":"学习 是 活 到 老 学 到 老 的 事。"},{"zh":"人生","py":"rénshēng","vi":"đời người","hv":"nhân sinh","note":"Chính là \"nhân sinh\".","ex":"人生没有太迟的开始。","exPy":"Rénshēng méiyǒu tài chí de kāishǐ.","exVi":"Đời người không có khởi đầu nào là quá muộn.","w":"人生 没有 太 迟 的 开始。"},{"zh":"做梦","py":"zuòmèng","vi":"nằm mơ","hv":"tố mộng","note":"做 + 梦. Mơ thấy là 梦见.","ex":"我昨天晚上做了一个奇怪的梦。","exPy":"Wǒ zuótiān wǎnshang zuò le yí ge qíguài de mèng.","exVi":"Đêm qua tôi mơ một giấc mơ kỳ lạ.","w":"我 昨天 晚上 做 了 一 个 奇怪 的 梦。"},{"zh":"着火","py":"zháohuǒ","vi":"bốc cháy","hv":"trước hoả","note":"着 (zháo, bắt) + 火.","ex":"着火了！快打一一九！","exPy":"Zháohuǒ le! Kuài dǎ yāo yāo jiǔ!","exVi":"Cháy rồi! Gọi 119 ngay!","w":"着火 了！ 快 打 一一 九！"},{"zh":"迟","py":"chí","vi":"muộn","hv":"trì","note":"\"Trì\" trong \"trì hoãn\". 迟到 là đến muộn.","ex":"现在开始还不迟。","exPy":"Xiànzài kāishǐ hái bù chí.","exVi":"Bắt đầu bây giờ vẫn chưa muộn.","w":"现在 开始 还 不 迟。"}],"newChars":[],"outro":"很好！Xong bài 203."};
G.ROOMS["zh-l204"] = {"id":"zh-l204","lang":"zh","level":4,"no":204,"teacher":"wang","title":"HSK4 · Bài 204 · 作为学生 Hậu tố và cách nói trang trọng","intro":["各位乘客请注意。","Bài 204: Dùng 者, 性, 感, 自, 整, 整个, 各个, 各位, 各种 và 作为. Bấm 1 · Học để bắt đầu."],"introPy":"Gèwèi chéngkè qǐng zhùyì.","gram":{"t":"Hậu tố tạo danh từ trừu tượng","b":"tính từ / danh từ + 性 / 感","d":"重要 → 重要性, 安全 → 安全感. Giống \"-tính\", \"-cảm\" trong tiếng Việt.","ex":[["这件事的严重性很大。","Mức độ nghiêm trọng của việc này rất lớn.","Zhè jiàn shì de yánzhòngxìng hěn dà."],["孩子需要安全感。","Trẻ con cần cảm giác an toàn.","Háizi xūyào ānquángǎn."]]},"grams":[{"t":"Hậu tố tạo danh từ trừu tượng","b":"tính từ / danh từ + 性 / 感","d":"重要 → 重要性, 安全 → 安全感. Giống \"-tính\", \"-cảm\" trong tiếng Việt.","ex":[["这件事的严重性很大。","Mức độ nghiêm trọng của việc này rất lớn.","Zhè jiàn shì de yánzhòngxìng hěn dà."],["孩子需要安全感。","Trẻ con cần cảm giác an toàn.","Háizi xūyào ānquángǎn."]]},{"t":"作为 + vai trò，…: với tư cách là","b":"作为 + danh từ chỉ vai trò","d":"Đặt đầu câu để nêu vai trò của chủ ngữ.","ex":[["作为队长，他要负责整个球队。","Là đội trưởng, anh ấy phải chịu trách nhiệm cả đội.","Zuòwéi duìzhǎng, tā yào fùzé zhěnggè qiúduì."],["作为朋友，我必须告诉你真话。","Là bạn, tôi phải nói thật với bạn.","Zuòwéi péngyou, wǒ bìxū gàosu nǐ zhēn huà."]]}],"items":[{"zh":"者","py":"zhě","vi":"người (hậu tố)","hv":"giả","note":"\"Giả\" trong \"tác giả\", \"độc giả\". Gắn sau động từ để chỉ người làm: 记者, 学者.","ex":"记者正在采访运动员。","exPy":"Jìzhě zhèngzài cǎifǎng yùndòngyuán.","exVi":"Phóng viên đang phỏng vấn vận động viên.","w":"记者 正在 采访 运动员。"},{"zh":"性","py":"xìng","vi":"tính (hậu tố)","hv":"tính","note":"\"Tính\" trong \"tính chất\". 重要性 (tầm quan trọng), 可能性 (khả năng).","ex":"大家都知道学习的重要性。","exPy":"Dàjiā dōu zhīdào xuéxí de zhòngyàoxìng.","exVi":"Ai cũng biết tầm quan trọng của việc học.","w":"大家 都 知道 学习 的 重要 性。"},{"zh":"感","py":"gǎn","vi":"cảm giác (hậu tố)","hv":"cảm","note":"幸福感 (cảm giác hạnh phúc), 责任感 (tinh thần trách nhiệm).","ex":"他是一个很有责任感的人。","exPy":"Tā shì yí ge hěn yǒu zérèngǎn de rén.","exVi":"Anh ấy là người rất có tinh thần trách nhiệm.","w":"他 是 一 个 很 有 责任 感 的 人。"},{"zh":"自","py":"zì","vi":"từ (văn viết)","hv":"tự","note":"Văn viết của 从. 来自 (đến từ).","ex":"这些游客来自世界各地。","exPy":"Zhèxiē yóukè láizì shìjiè gèdì.","exVi":"Những du khách này đến từ khắp nơi trên thế giới.","w":"这些 游客 来自 世界 各地。"},{"zh":"整","py":"zhěng","vi":"cả, trọn; đúng (giờ)","hv":"chỉnh","note":"\"Chỉnh\" trong \"chỉnh tề\". 三点整 (đúng ba giờ).","ex":"整个城市都在下雨。","exPy":"Zhěnggè chéngshì dōu zài xià yǔ.","exVi":"Cả thành phố đều đang mưa.","w":"整个 城市 都 在 下雨。"},{"zh":"整个","py":"zhěnggè","vi":"toàn bộ, cả","hv":"chỉnh cá","note":"整 + 个.","ex":"整个下午他都在睡觉。","exPy":"Zhěnggè xiàwǔ tā dōu zài shuìjiào.","exVi":"Cả buổi chiều anh ấy ngủ.","w":"整个 下午 他 都 在 睡觉。"},{"zh":"各个","py":"gègè","vi":"từng, mỗi","hv":"các cá","note":"各 + 个.","ex":"各个国家都有自己的文化。","exPy":"Gègè guójiā dōu yǒu zìjǐ de wénhuà.","exVi":"Mỗi quốc gia đều có văn hoá riêng.","w":"各个 国家 都 有 自己 的 文化。"},{"zh":"各位","py":"gèwèi","vi":"các vị, quý vị","hv":"các vị","note":"Chính là \"các vị\".","ex":"各位乘客请注意。","exPy":"Gèwèi chéngkè qǐng zhùyì.","exVi":"Quý hành khách xin chú ý.","w":"各位 乘客 请 注意。"},{"zh":"各种","py":"gèzhǒng","vi":"các loại","hv":"các chủng","note":"Chính là \"các chủng\".","ex":"各种各样的人都来参加了。","exPy":"Gè zhǒng gè yàng de rén dōu lái cānjiā le.","exVi":"Đủ mọi kiểu người đều đến tham gia.","w":"各种 各 样 的 人 都 来 参加 了。"},{"zh":"作为","py":"zuòwéi","vi":"với tư cách là, là","hv":"tác vi","note":"Khác \"tác vi\" (hành vi) tiếng Việt: 作为 là \"với tư cách\".","ex":"作为学生，我们要好好学习。","exPy":"Zuòwéi xuésheng, wǒmen yào hǎohǎo xuéxí.","exVi":"Là học sinh, chúng ta phải học hành chăm chỉ.","w":"作为 学生， 我们 要好 好学 习。"}],"newChars":[],"outro":"很好！Xong bài 204."};
G.ROOMS["zh-l205"] = {"id":"zh-l205","lang":"zh","level":4,"no":205,"teacher":"wang","title":"HSK4 · Bài 205 · 客气什么 Những từ còn lại của cấp 4","intro":["一步一步来，不要着急。","Bài 205: Học các từ: thể hiện, bước, điểm danh, phép / luật, điểm xấu, khách sáo, nhanh chóng, ừ, số và đáng giá. Bấm 1 · Học để bắt đầu."],"introPy":"Yí bù yí bù lái, búyào zháojí.","gram":{"t":"好处 và 坏处","b":"有好处 / 有坏处 · 对…有好处","d":"Nói mặt lợi và hại của một việc.","ex":[["运动对身体有好处。","Vận động có lợi cho sức khoẻ.","Yùndòng duì shēntǐ yǒu hǎochù."],["玩游戏太多有什么坏处？","Chơi game quá nhiều có tác hại gì?","Wán yóuxì tài duō yǒu shénme huàichù?"]]},"grams":[{"t":"好处 và 坏处","b":"有好处 / 有坏处 · 对…有好处","d":"Nói mặt lợi và hại của một việc.","ex":[["运动对身体有好处。","Vận động có lợi cho sức khoẻ.","Yùndòng duì shēntǐ yǒu hǎochù."],["玩游戏太多有什么坏处？","Chơi game quá nhiều có tác hại gì?","Wán yóuxì tài duō yǒu shénme huàichù?"]]},{"t":"值得 + động từ: đáng để làm","b":"值得看 · 值得去 · 值得学习","d":"Khen một việc đáng bỏ công sức.","ex":[["这个地方值得去一次。","Nơi này đáng để đến một lần.","Zhège dìfang zhíde qù yí cì."],["他的精神值得我们学习。","Tinh thần của anh ấy đáng để chúng ta học tập.","Tā de jīngshén zhíde wǒmen xuéxí."]]}],"items":[{"zh":"表现","py":"biǎoxiàn","vi":"thể hiện; biểu hiện","hv":"biểu hiện","note":"Chính là \"biểu hiện\".","ex":"他在工作中表现得很积极。","exPy":"Tā zài gōngzuò zhōng biǎoxiàn de hěn jījí.","exVi":"Anh ấy thể hiện rất tích cực trong công việc.","w":"他 在 工作 中 表现 得 很 积极。"},{"zh":"步","py":"bù","vi":"bước","hv":"bộ","note":"\"Bộ\" trong \"bộ hành\", \"tiến bộ\". Đi bộ là 散步, 跑步.","ex":"一步一步来，不要着急。","exPy":"Yí bù yí bù lái, búyào zháojí.","exVi":"Từng bước một, đừng vội.","w":"一 步 一 步 来， 不要 着急。"},{"zh":"点名","py":"diǎnmíng","vi":"điểm danh; gọi tên","hv":"điểm danh","note":"Chính là \"điểm danh\".","ex":"上课以前老师先点名。","exPy":"Shàngkè yǐqián lǎoshī xiān diǎnmíng.","exVi":"Trước giờ học thầy điểm danh trước.","w":"上课 以前 老师 先 点名。"},{"zh":"法","py":"fǎ","vi":"luật; cách","hv":"pháp","note":"\"Pháp\" trong \"pháp luật\", \"phương pháp\".","ex":"嗯，这个想法不错，值得试试。","exPy":"Ǹg, zhège xiǎngfǎ búcuò, zhíde shìshi.","exVi":"Ừ, ý này hay đấy, đáng thử.","w":"嗯， 这个 想法 不错， 值得 试 试。"},{"zh":"坏处","py":"huàichù","vi":"điểm xấu, tác hại","hv":"hoại xứ","note":"Đối lập với 好处.","ex":"熬夜有很多坏处。","exPy":"Áoyè yǒu hěn duō huàichù.","exVi":"Thức khuya có nhiều tác hại.","w":"熬夜 有 很 多 坏处。"},{"zh":"客气","py":"kèqi","vi":"khách sáo; lịch sự","hv":"khách khí","note":"Chính là \"khách khí\". 别客气 (đừng khách sáo).","ex":"你帮了我这么多，我不跟你客气了。","exPy":"Nǐ bāng le wǒ zhème duō, wǒ bù gēn nǐ kèqi le.","exVi":"Bạn giúp tôi nhiều vậy, tôi không khách sáo với bạn nữa.","w":"你 帮 了 我 这么 多， 我 不 跟 你 客气 了。"},{"zh":"快速","py":"kuàisù","vi":"nhanh chóng","hv":"khoái tốc","note":"快 + 速.","ex":"经济快速发展。","exPy":"Jīngjì kuàisù fāzhǎn.","exVi":"Kinh tế phát triển nhanh chóng.","w":"经济 快速 发展。"},{"zh":"嗯","py":"ǹg","vi":"ừ, ờ","hv":"ân","note":"Đáp lại tỏ ý đồng ý hay đang nghe.","ex":"嗯，我知道了。","exPy":"Ǹg, wǒ zhīdào le.","exVi":"Ừ, tôi biết rồi.","w":"嗯， 我 知道 了。"},{"zh":"数","py":"shù","vi":"con số; số","hv":"số","note":"Chính là \"số\". Đọc shǔ khi là động từ \"đếm\".","ex":"你最喜欢的数是几？","exPy":"Nǐ zuì xǐhuan de shù shì jǐ?","exVi":"Số bạn thích nhất là số mấy?","w":"你 最 喜欢 的 数 是 几？"},{"zh":"值","py":"zhí","vi":"đáng giá","hv":"trị","note":"\"Trị\" trong \"giá trị\". 值得 (đáng để).","ex":"这本书很值得看。","exPy":"Zhè běn shū hěn zhíde kàn.","exVi":"Cuốn sách này rất đáng đọc.","w":"这 本 书 很 值得 看。"}],"newChars":["嗯"],"outro":"很好！Xong bài 205."};
